INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90650, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示没有把握，不能肯定。", "primary_collocate": null, "pronunciation": "bù yí dìng", "ipa": "pu˥˩ i˧˥ tiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "我不一定能赶上最后一班车。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不一定记得我们的约会。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不一定是他做的。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你问问他，他不一定同意。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天不一定有时间，我先问问。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不一定看见你了，再叫他一声。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，我不一定能考好。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家店周日不一定开门。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太清楚，他不一定在家。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机不一定准时到，别等太久。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "对某事没有把握，不能肯定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79e60a67-5d39-493a-b9c5-106ceed17226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90650, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不一定", "is_correct": true, "explanation": "不一定：表示没有把握，与后句“能赶上”的不确定相合。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰形容词或心理动词，不能修饰“能赶上”，句子不通。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作进行，不能与“能”连用，句子不通。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”修饰形容词，不能修饰“能赶上”。"}], "explanations": {"不一定": "不一定：表示没有把握，与后句“能赶上”的不确定相合。", "非常": "搭配：“非常”修饰形容词或心理动词，不能修饰“能赶上”，句子不通。", "正在": "搭配：“正在”表示动作进行，不能与“能”连用，句子不通。", "太": "搭配：“太”修饰形容词，不能修饰“能赶上”。"}, "sentence_index": 0, "correct_answer": "不一定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事我不一定知道，是我亲手做的。", "explanation": "这里不能用〈不一定〉。事情是我亲手做的，应表示确定，直接用〈确实〉。"}, {"text": "这里不一定停车，请大家遵守。", "explanation": "这里应该用〈不准〉。不一定表示不确定，不能表示禁止；禁止停车要用〈不准〉。"}, {"text": "他不一定迟到了，他早就到了。", "explanation": "这里不能用〈不一定〉。“早就到了”是已经发生的事实，应用〈确实〉而不是表示没有把握的〈不一定〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90650, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不一定", "is_correct": true, "explanation": "不一定：表示没有把握，与“这次考试”的未知结果相合。"}, {"text": "早就", "is_correct": false, "explanation": "语义：“早就”表示已经很久，与尚未发生的“这次考试”矛盾。"}, {"text": "好好", "is_correct": false, "explanation": "搭配：“好好”是修饰动作的副词，与“能考好”搭配不通。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”修饰形容词，不能直接修饰“能考好”，句子不通。"}], "explanations": {"不一定": "不一定：表示没有把握，与“这次考试”的未知结果相合。", "早就": "语义：“早就”表示已经很久，与尚未发生的“这次考试”矛盾。", "好好": "搭配：“好好”是修饰动作的副词，与“能考好”搭配不通。", "太": "搭配：“太”修饰形容词，不能直接修饰“能考好”，句子不通。"}, "sentence_index": 6, "correct_answer": "不一定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试我不一定及格，我已经考了满分。", "explanation": "这里不能用〈不一定〉。考了满分是确定的结果，应直接用〈肯定〉而不是表示没有把握的〈不一定〉。"}, {"text": "快走吧，不一定就要迟到了。", "explanation": "这里应该用〈不然〉。不一定表示不确定，表示“否则”的条件关系要用〈不然〉。"}, {"text": "这么做不一定会出错，错误已经发生了。", "explanation": "这里不能用〈不一定〉。错误已经发生，是确定的结果，应用〈必然〉表示，而不是表示没有把握的〈不一定〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天他没不一定会来，我们再等等。", "corrected_sentence": "明天他不一定会来，我们再等等。", "error_description": "“没”用错：“不一定”本身已含否定，不能与“没”连用，应删去“没”，写作“明天他不一定会来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家饭馆周末没不一定营业。", "corrected_sentence": "这家饭馆周末不一定营业。", "error_description": "“没”用错：“不一定”本身已含否定，不能与“没”连用，应删去“没”，写作“这家饭馆周末不一定营业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
