INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90651, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90651, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "说话的人所在的这个地方。", "primary_collocate": null, "pronunciation": "zhèr", "ipa": "ʈʂɤɻ˥˩", "syllable_count": 1, "sentences": [{"text": "我就住在这儿，离学校很近。", "target_word": "这儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你来这儿坐吧，这儿有空位。", "target_word": "这儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在这儿等了你半个小时。", "target_word": "这儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈，我现在在这儿，你别担心。", "target_word": "这儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他问我：“你为什么不去那儿，要来这儿？”", "target_word": "这儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在这儿工作三年了。", "target_word": "这儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这儿的冬天很冷，你要多穿衣服。", "target_word": "这儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你在这儿等我，我马上回来。", "target_word": "这儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我第一次来这儿，不太认识路。", "target_word": "这儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“从这儿开始读。”", "target_word": "这儿", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "这里", "label": "书面变体"}], "register": "口语", "sense_fingerprint": "指说话人自己所在的地方，常与“那儿”对比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '741a067b-35ee-42ee-a9a5-e70920a0d4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90651, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，问的是人，不指说话人所在的地方。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：“哪儿”是疑问代词，用在“我就住在……”的陈述句里说不通。"}, {"text": "这儿", "is_correct": true, "explanation": "正确：“这儿”指说话人所在的地方，与“我就住在”相符。"}, {"text": "这个", "is_correct": false, "explanation": "搭配：“这个”指事物，不能作“住在”的处所。"}], "explanations": {"谁": "语义：“谁”是疑问代词，问的是人，不指说话人所在的地方。", "哪儿": "语义：“哪儿”是疑问代词，用在“我就住在……”的陈述句里说不通。", "这儿": "正确：“这儿”指说话人所在的地方，与“我就住在”相符。", "这个": "搭配：“这个”指事物，不能作“住在”的处所。"}, "sentence_index": 0, "correct_answer": "这儿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在北京，这儿在上海，离我很远。", "explanation": "这里应该用〈那儿〉。这儿指说话人身边的地方，上海离说话人远，应说“那儿”。"}, {"text": "这儿是三个月前的事情了。", "explanation": "这里应该用〈这件事〉。这儿只指地点，指事情要用“这件事”，不能说“这儿是三个月前的事情了”。"}, {"text": "这儿是我的妈妈，她很温柔。", "explanation": "这里应该用〈这是〉。这儿只指地方，指人要用“这是”，不能说“这儿是我的妈妈”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90651, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这位", "is_correct": false, "explanation": "语义：“这位”指人，不能指冬天所在的地方。"}, {"text": "那位", "is_correct": false, "explanation": "搭配：“那位”指人，不能修饰“冬天”。"}, {"text": "这儿", "is_correct": true, "explanation": "正确：“这儿的冬天”指这个地方的冬天，与后面的“多穿衣服”相符。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”指一群人，不能表示地方，“大家的冬天”说不通。"}], "explanations": {"这位": "语义：“这位”指人，不能指冬天所在的地方。", "那位": "搭配：“那位”指人，不能修饰“冬天”。", "这儿": "正确：“这儿的冬天”指这个地方的冬天，与后面的“多穿衣服”相符。", "大家": "语义：“大家”指一群人，不能表示地方，“大家的冬天”说不通。"}, "sentence_index": 6, "correct_answer": "这儿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跑得这儿快，我们都追不上。", "explanation": "这里应该用〈这么〉。修饰形容词、表示程度要用“这么”，“这儿”只指地点。"}, {"text": "这儿个人走过来了。", "explanation": "这里应该用〈这个〉。指人要用“这个人”，不能说“这儿个人”。"}, {"text": "这儿位老师很和蔼。", "explanation": "这里应该用〈这位〉。指人要用“这位”，不能说“这儿位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90651, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你到这儿去一下。", "corrected_sentence": "请你到这儿来一下。", "error_description": "说话人在「这儿」，请对方到说话人这里应说「来」，「去」指离开说话人所在之处。「到这儿去」是错误的，正确为「到这儿来」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90651, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站从这儿很近。", "corrected_sentence": "车站离这儿很近。", "error_description": "表示距离要用介词「离」，「从」表示起点。「从这儿很近」误用了「从」，是错误的；正确为「离这儿很近」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
