INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90652, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90652, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指示近处，这里。", "primary_collocate": null, "pronunciation": "zhèr", "ipa": "ʈʂɤɻ˥˩", "syllable_count": 1, "sentences": [{"text": "书包放在这儿就行。", "target_word": "这儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看，这儿有一只小猫。", "target_word": "这儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这儿是图书馆，请小声说话。", "target_word": "这儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这儿的路很滑，大家走慢一点。", "target_word": "这儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他指着地图说：“我们在这儿。”", "target_word": "这儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把桌子搬到这儿来吧。", "target_word": "这儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的手机在这儿，不在那儿。", "target_word": "这儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这儿离车站不远，走五分钟就到。", "target_word": "这儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这儿有水，你渴了就喝。", "target_word": "这儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在这儿写上你的名字。", "target_word": "这儿", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "这里", "label": "书面变体"}], "register": "口语", "sense_fingerprint": "指示眼前或附近的某个位置，常配合手势、“在”“到”使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '741a067b-35ee-42ee-a9a5-e70920a0d4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90652, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，问的是人，不能表示放置的地方。"}, {"text": "这位", "is_correct": false, "explanation": "搭配：“放在”要接处所，“这位”指人，不能作处所。"}, {"text": "那位", "is_correct": false, "explanation": "搭配：“那位”指人，不能作“放在”的处所。"}, {"text": "这儿", "is_correct": true, "explanation": "正确：“这儿”指说话人眼前或附近的地方，与“放在”搭配，符合句意。"}], "explanations": {"谁": "语义：“谁”是疑问代词，问的是人，不能表示放置的地方。", "这位": "搭配：“放在”要接处所，“这位”指人，不能作处所。", "那位": "搭配：“那位”指人，不能作“放在”的处所。", "这儿": "正确：“这儿”指说话人眼前或附近的地方，与“放在”搭配，符合句意。"}, "sentence_index": 0, "correct_answer": "这儿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我住在上海，这儿是北京，离得很远。", "explanation": "这里应该用〈那儿〉。这儿指说话人身边的地方，北京离说话人远，应说“那儿”。"}, {"text": "这儿是三个月前的事情了。", "explanation": "这里应该用〈这件事〉。这儿只指地点，指事情要用“这件事”，不能说“这儿是三个月前的事情了”。"}, {"text": "这儿是我的爸爸，他很高。", "explanation": "这里应该用〈这是〉。这儿只指地方，指人要用“这是”，不能说“这儿是我的爸爸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90652, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那个", "is_correct": false, "explanation": "搭配：“那个”指事物，不能作“在”的处所，“在那个”说不通。"}, {"text": "这个", "is_correct": false, "explanation": "搭配：“这个”不能指地方，“在这个”说不通。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”指人，不能指手机所在的地方。"}, {"text": "这儿", "is_correct": true, "explanation": "正确：“在这儿”指手机所在的地方，与后面的“不在那儿”相对，符合句意。"}], "explanations": {"那个": "搭配：“那个”指事物，不能作“在”的处所，“在那个”说不通。", "这个": "搭配：“这个”不能指地方，“在这个”说不通。", "大家": "语义：“大家”指人，不能指手机所在的地方。", "这儿": "正确：“在这儿”指手机所在的地方，与后面的“不在那儿”相对，符合句意。"}, "sentence_index": 6, "correct_answer": "这儿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家做得这儿好，就一定没问题。", "explanation": "这里应该用〈这么〉。修饰形容词、表示程度要用“这么”，“这儿”只指地点。"}, {"text": "这儿个学生考了第一名。", "explanation": "这里应该用〈这个〉。指人要用“这个学生”，不能说“这儿个学生”。"}, {"text": "这儿位老师很和蔼。", "explanation": "这里应该用〈这位〉。指人要用“这位”，不能说“这儿位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90652, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这儿本书很好看，你读读。", "corrected_sentence": "这本书很好看，你读读。", "error_description": "错误在指代：“这儿”只指地点，修饰“书”要用“这本”，不能说“这儿本书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90652, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这儿的时候我们很忙，你别打扰。", "corrected_sentence": "这个时候我们很忙，你别打扰。", "error_description": "错误在指代：“这儿”只指地点，指时间要用“这个时候”，不能说“这儿的时候”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90654, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90654, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90654, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，常与“而且”连用，表示意思更进一层。", "primary_collocate": null, "pronunciation": "bú dàn", "ipa": "pu˧˥ tan˥˩", "syllable_count": 2, "sentences": [{"text": "他不但会唱歌，而且会跳舞。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜不但好吃，而且很便宜。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不但聪明，而且很努力。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里不但风景美，而且空气好。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的老师不但很年轻，而且很有耐心。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不但会说汉语，而且写得很好。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家饭馆不但干净，而且服务很好。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑车不但省钱，而且对身体好。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不但帮我做饭，而且帮我洗了衣服。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书不但有意思，而且让我学到很多。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "递进连词，常与“而且”搭配，后面意思更进一层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79e60a67-5d39-493a-b9c5-106ceed17226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90654, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不但", "is_correct": true, "explanation": "不但读作 bú dàn，表示进一层，常与“而且”连用。"}, {"text": "不断", "is_correct": false, "explanation": "dàn 与 duàn 的韵母不同，duàn 多一个 u，不断意思是持续，不是不但。"}, {"text": "不大", "is_correct": false, "explanation": "dàn 与 dà 的韵尾不同，dàn 有 n，dà 没有，不大意思是不是很大。"}, {"text": "不带", "is_correct": false, "explanation": "dàn 与 dài 的韵尾不同，n 变成了 i，不带意思是不携带。"}, {"text": "不当", "is_correct": false, "explanation": "韵尾不同：dàng 是 ng，dàn 是 n；不当意思是不恰当，不是不但。"}], "explanations": {"不但": "不但读作 bú dàn，表示进一层，常与“而且”连用。", "不断": "dàn 与 duàn 的韵母不同，duàn 多一个 u，不断意思是持续，不是不但。", "不大": "dàn 与 dà 的韵尾不同，dàn 有 n，dà 没有，不大意思是不是很大。", "不带": "dàn 与 dài 的韵尾不同，n 变成了 i，不带意思是不携带。", "不当": "韵尾不同：dàng 是 ng，dàn 是 n；不当意思是不恰当，不是不但。"}, "sentence_index": null, "correct_answer": "不但"}, "level_3": {"options": [{"text": "不但", "is_correct": true, "explanation": "不但：表示进一层，与后面的“而且”呼应，填入后句子通顺。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”表示让步，句中并无让步之意，与表递进的“而且”不合，句意不通。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示选择，与表递进的“而且”意思不合，句子不通。"}, {"text": "只要", "is_correct": false, "explanation": "搭配：“只要”引出条件，后面须用“就”呼应，句中没有“就”，句意不通。"}], "explanations": {"不但": "不但：表示进一层，与后面的“而且”呼应，填入后句子通顺。", "虽然": "语义：“虽然”表示让步，句中并无让步之意，与表递进的“而且”不合，句意不通。", "或者": "语义：“或者”表示选择，与表递进的“而且”意思不合，句子不通。", "只要": "搭配：“只要”引出条件，后面须用“就”呼应，句中没有“就”，句意不通。"}, "sentence_index": 0, "correct_answer": "不但"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里风景很美，不但空气不好。", "explanation": "这里应该用〈但是〉。不但表示进一层，前后应是同向补充；这里前后转折，要用“但是”。"}, {"text": "他很努力，不但没有成功。", "explanation": "这里应该用〈却〉。不但表示递进，不表示转折；“很努力”与“没有成功”意思相反，要用“却”。"}, {"text": "他不是老师，不但是医生。", "explanation": "这里应该用〈而是〉。不但不能用来引出对否定内容的更正，“不是……而是……”才是正确的格式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不但", "is_correct": true, "explanation": "不但：表示进一层，与后面的“而且”呼应，填入后句子通顺。"}, {"text": "所以", "is_correct": false, "explanation": "搭配：“所以”表示因果，前面要有“因为”呼应，与表递进的“而且”不合。"}, {"text": "然而", "is_correct": false, "explanation": "搭配：“然而”表示转折，多用于句首，接在主语后不通，与“而且”的递进意思也冲突。"}, {"text": "不然", "is_correct": false, "explanation": "语义：“不然”表示否则，引出不利后果，与“干净”“服务很好”的正面意思相反。"}], "explanations": {"不但": "不但：表示进一层，与后面的“而且”呼应，填入后句子通顺。", "所以": "搭配：“所以”表示因果，前面要有“因为”呼应，与表递进的“而且”不合。", "然而": "搭配：“然而”表示转折，多用于句首，接在主语后不通，与“而且”的递进意思也冲突。", "不然": "语义：“不然”表示否则，引出不利后果，与“干净”“服务很好”的正面意思相反。"}, "sentence_index": 6, "correct_answer": "不但"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没复习，不但考砸了。", "explanation": "这里应该用〈所以〉。不但表示递进，不表示因果；“没复习”与“考砸了”是原因和结果关系。"}, {"text": "不但刮风下雨，我们都要去跑步。", "explanation": "这里应该用〈无论〉。不但表示补充，不表示无论条件如何都要……；“无论……都……”才表示无条件。"}, {"text": "我们走了很久，不但到了目的地。", "explanation": "这里应该用〈终于〉。不但表示递进，不表示经过一段时间后出现的结果，“终于到了”才符合语境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她不但会弹钢琴，但是会唱歌。", "corrected_sentence": "她不但会弹钢琴，而且会唱歌。", "error_description": "连词用错：“但是”表示转折，与“不但”搭配不通，应为“而且”，即“她不但会弹钢琴，而且会唱歌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不但会画画，而是会写诗。", "corrected_sentence": "他不但会画画，还会写诗。", "error_description": "“而是”用错，应为“还”。“而是”表示对否定内容的更正，与表示递进的“不但”不搭，“不但……还……”才通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
