INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90656, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问短语，询问是什么事情。", "primary_collocate": null, "pronunciation": "shén me shì", "ipa": "ʂən˧˥ mɤ ʂʐ̩˥˩", "syllable_count": 3, "sentences": [{"text": "你先告诉我，是什么事？", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没说是什么事，只让我马上过去。", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你到底在担心什么事？", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师叫你去办公室，你知道是什么事吗？", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话里没讲清楚是什么事，我很着急。", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑得这么开心，你猜猜是什么事？", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说的是什么事？我怎么不知道？", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问您今天找我，是为了什么事？", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他这么晚打电话来，会是什么事呢？", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在问，你昨天哭是因为什么事？", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "什麼事", "label": "繁体"}, {"form": "什么事情", "label": "复合"}], "register": "口语", "sense_fingerprint": "疑问短语，问是什么事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '388a63b1-0373-4e8f-9a4b-1f114645e9ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90656, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "什么事", "is_correct": true, "explanation": "“什么事”问的是具体事情，与“你先告诉我”相符。"}, {"text": "马上", "is_correct": false, "explanation": "词性：“马上”是副词，不能单独作“是”的宾语，“是马上？”不成句。"}, {"text": "已经", "is_correct": false, "explanation": "词性：“已经”是副词，“是已经？”不成句，句中要问的是事情。"}, {"text": "知道", "is_correct": false, "explanation": "语义：“是知道？”不成问句，句中要问的是什么事情。"}], "explanations": {"什么事": "“什么事”问的是具体事情，与“你先告诉我”相符。", "马上": "词性：“马上”是副词，不能单独作“是”的宾语，“是马上？”不成句。", "已经": "词性：“已经”是副词，“是已经？”不成句，句中要问的是事情。", "知道": "语义：“是知道？”不成问句，句中要问的是什么事情。"}, "sentence_index": 0, "correct_answer": "什么事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天买了什么事。", "explanation": "这里应该用〈什么东西〉。买的是物品，不能用“什么事”指物品。"}, {"text": "他是什么事？", "explanation": "这里应该用〈什么人〉。问人的身份要用“什么人”，“什么事”只问事情。"}, {"text": "他住在什么事？", "explanation": "这里应该用〈什么地方〉。问住的地点要用“什么地方”，“什么事”不能用来问地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "什么事", "is_correct": true, "explanation": "“什么事”指你所说的事情，与“我怎么不知道”前后呼应。"}, {"text": "怎么样", "is_correct": false, "explanation": "搭配：“你说的是怎么样”不成句，句中要问的是事情。"}, {"text": "已经", "is_correct": false, "explanation": "词性：“已经”是副词，“你说的是已经”不成句。"}, {"text": "什么样", "is_correct": false, "explanation": "语义：“什么样”问的是性质或样子，不是问事情本身。"}], "explanations": {"什么事": "“什么事”指你所说的事情，与“我怎么不知道”前后呼应。", "怎么样": "搭配：“你说的是怎么样”不成句，句中要问的是事情。", "已经": "词性：“已经”是副词，“你说的是已经”不成句。", "什么样": "语义：“什么样”问的是性质或样子，不是问事情本身。"}, "sentence_index": 6, "correct_answer": "什么事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天骑什么事上班？", "explanation": "这里应该用〈什么车〉。骑的是交通工具，不能用“什么事”指车辆。"}, {"text": "她今天穿什么事。", "explanation": "这里应该用〈什么衣服〉。穿的是衣物，不能用“什么事”指衣物。"}, {"text": "我昨天吃了什么事。", "explanation": "这里应该用〈什么菜〉。吃的是食物，不能用“什么事”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他找我有什么的事？", "corrected_sentence": "他找我有什么事？", "error_description": "助词错误：“什么”和“事”之间不能加“的”，应说“有什么事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你昨天做了的什么事？", "corrected_sentence": "你昨天做了什么事？", "error_description": "助词错误：“做了的什么事”多出“的”，“做了”后应直接接“什么事”，应说“做了什么事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
