INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90658, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词，询问性质、形状或状态。", "primary_collocate": null, "pronunciation": "shén me yàng", "ipa": "ʂən˧˥ mə jɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "你喜欢什么样的衣服？", "target_word": "什么样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是什么样的人？", "target_word": "什么样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想找什么样的工作？", "target_word": "什么样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的新同学是什么样的？", "target_word": "什么样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的冬天是什么样的？", "target_word": "什么样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想住什么样的房子？", "target_word": "什么样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "什么样的天气你最喜欢？", "target_word": "什么样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看过什么样的电影？", "target_word": "什么样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的小狗是什么样的？", "target_word": "什么样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想买什么样的手机？", "target_word": "什么样", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "什么样的", "label": "带“的”形式"}], "register": "通用", "sense_fingerprint": "疑问代词，询问人或事物的性质、形状、状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628153f8-23f4-4783-aca5-17ac6551aa7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90658, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "什么样", "is_correct": true, "explanation": "正确。“什么样”询问衣服的样式，与“喜欢”及“衣服”搭配自然。"}, {"text": "怎么", "is_correct": false, "explanation": "语法：“怎么”问方式或原因，不能直接加“的”修饰名词，“怎么的衣服”不成立。"}, {"text": "多少", "is_correct": false, "explanation": "搭配：“多少”问数量，不能修饰“衣服”的样式，“多少的衣服”不成立。"}, {"text": "哪个", "is_correct": false, "explanation": "语义：“哪个”是从已知范围里选一个，这句问的是样式，不是选择。"}], "explanations": {"什么样": "正确。“什么样”询问衣服的样式，与“喜欢”及“衣服”搭配自然。", "怎么": "语法：“怎么”问方式或原因，不能直接加“的”修饰名词，“怎么的衣服”不成立。", "多少": "搭配：“多少”问数量，不能修饰“衣服”的样式，“多少的衣服”不成立。", "哪个": "语义：“哪个”是从已知范围里选一个，这句问的是样式，不是选择。"}, "sentence_index": 0, "correct_answer": "什么样"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你叫什么样？", "explanation": "这里应该用〈什么〉。问名字要用“叫什么”，“什么样”问性质或样子，不能用来问名字。"}, {"text": "他的年龄是什么样的？", "explanation": "这里应该用〈多大〉。年龄是数字，“什么样”问性质，不能用来问年龄。"}, {"text": "他住在什么样？", "explanation": "这里应该用〈哪里〉。问地点要用“哪里”，“什么样”问性质或样子，不能用来问他住的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90658, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "什么样", "is_correct": true, "explanation": "正确。“什么样的天气”询问天气的样子，与“你最喜欢”搭配自然。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”问的是人，天气不是人，“谁的天气”说不通。"}, {"text": "几", "is_correct": false, "explanation": "搭配：“几”问数目，不能修饰“天气”的样子，“几的天气”不成立。"}, {"text": "哪些", "is_correct": false, "explanation": "语义：“哪些”问多个具体对象，这句问的是天气的样子，不成立。"}], "explanations": {"什么样": "正确。“什么样的天气”询问天气的样子，与“你最喜欢”搭配自然。", "谁": "语义：“谁”问的是人，天气不是人，“谁的天气”说不通。", "几": "搭配：“几”问数目，不能修饰“天气”的样子，“几的天气”不成立。", "哪些": "语义：“哪些”问多个具体对象，这句问的是天气的样子，不成立。"}, "sentence_index": 6, "correct_answer": "什么样"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只猫叫什么样？", "explanation": "这里应该用〈什么〉。问名字要用“叫什么”，“什么样”问性质或样子，不能用来问名字。"}, {"text": "这台手机的价钱是什么样的？", "explanation": "这里应该用〈多少钱〉。价钱是数字，应问“多少钱”，不用“什么样”。"}, {"text": "这个班的人数是什么样的？", "explanation": "这里应该用〈多少人〉。人数是数字，应问“多少人”，不用“什么样”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你觉得什么样得衣服最适合我？", "corrected_sentence": "你觉得什么样的衣服最适合我？", "error_description": "错误形式是“什么样得衣服”，正确形式是“什么样的衣服”。“什么样”修饰名词时用结构助词“的”，不用“得”（“得”用在动词后面引出补语）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她想找什么样地工作？", "corrected_sentence": "她想找什么样的工作？", "error_description": "错误形式是“什么样地工作”，正确形式是“什么样的工作”。“什么样”修饰名词时用结构助词“的”，不用“地”（“地”用于修饰动词）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
