INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90659, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示从现在起不会再这样了。", "primary_collocate": null, "pronunciation": "zài yě", "ipa": "tsaɪ̯˥˩ jɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我再也不迟到了。", "target_word": "再也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过这次教训，他再也不敢骗人了。", "target_word": "再也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们吵架以后，她再也没有给我打过电话。", "target_word": "再也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说从今天起再也不抽烟了。", "target_word": "再也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店太贵了，我再也不来了。", "target_word": "再也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子保证再也不玩手机游戏了。", "target_word": "再也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她下定决心，再也不吃甜的了。", "target_word": "再也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我再也不相信他的话了。", "target_word": "再也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摔了一次以后，弟弟再也不敢骑那辆车了。", "target_word": "再也", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师批评以后，他再也没有迟到。", "target_word": "再也", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "再也：从现在起下决心或形成事实，不再重复以前的做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53db9dd3-8e45-4d0b-b8b6-d4711d195280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90659, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再也", "is_correct": true, "explanation": "“再也”与后面的“不”搭配，表示从此不再，正适合表达下定决心不迟到。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：「正在」表示动作进行中，不能直接与「不迟到」这样的否定状态搭配，句子不通。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：「一起」表示共同、一同，不能与「不迟到」搭配，句子不通。"}, {"text": "马上", "is_correct": false, "explanation": "搭配：“马上”表示很快就会发生，不能与表示长期不再的“不迟到了”搭配。"}], "explanations": {"再也": "“再也”与后面的“不”搭配，表示从此不再，正适合表达下定决心不迟到。", "正在": "搭配：「正在」表示动作进行中，不能直接与「不迟到」这样的否定状态搭配，句子不通。", "一起": "搭配：「一起」表示共同、一同，不能与「不迟到」搭配，句子不通。", "马上": "搭配：“马上”表示很快就会发生，不能与表示长期不再的“不迟到了”搭配。"}, "sentence_index": 0, "correct_answer": "再也"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说从今天起再也抽烟了。", "explanation": "这里应该用〈不再〉。“再也”后面必须接否定词（不、没），与肯定的“抽烟了”搭配不当。"}, {"text": "他说，他再也抽了一根烟。", "explanation": "这里应该用〈又〉。“再也”表示从此不再，不能用来表示再次发生某事。"}, {"text": "他说从今天起，他再也打算抽烟了。", "explanation": "这里把“再也”用来表示计划将来要做的事，但它只表示从此不再。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90659, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再也", "is_correct": true, "explanation": "“再也”与否定词“不”搭配，表示从此不再，符合“下定决心”的语境。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示间或发生，与“下定决心”的一贯态度不符。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与“下定决心”这种有意识的决定相矛盾。"}, {"text": "经常", "is_correct": false, "explanation": "搭配：“经常”表示反复发生，与“不吃甜的了”这种决定性的状态搭配不当。"}], "explanations": {"再也": "“再也”与否定词“不”搭配，表示从此不再，符合“下定决心”的语境。", "偶尔": "语义：“偶尔”表示间或发生，与“下定决心”的一贯态度不符。", "忽然": "语义：“忽然”表示突然发生，与“下定决心”这种有意识的决定相矛盾。", "经常": "搭配：“经常”表示反复发生，与“不吃甜的了”这种决定性的状态搭配不当。"}, "sentence_index": 6, "correct_answer": "再也"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师批评以后，他再也迟到了吗？", "explanation": "「再也」要与否定词（不、没）搭配，肯定的「迟到了吗」不成立。"}, {"text": "老师批评以后，他再也很高兴。", "explanation": "这里把“再也”当作表示程度的用法，但它只表示从此不再。"}, {"text": "老师批评以后，他再也去了学校。", "explanation": "这里把“再也”当作表示“再次”的用法，但它只用于否定句，表示从此不再，不能用于肯定句“去了学校”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90659, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我再也喝可乐了。", "corrected_sentence": "我再也不喝可乐了。", "error_description": "错误：“再也”后面漏了否定词“不”。正确：“再也”要与否定词搭配，应说“我再也不喝可乐了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90659, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我再也不了去那家店了。", "corrected_sentence": "我再也不去那家店了。", "error_description": "错误：“再也不”中间多加了“了”，成了“再也不了去”。正确：“再也不”是固定搭配，中间不能插入“了”，应说“我再也不去那家店了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
