INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90661, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "再就是表示说完一件事，还要接着说另一件事。", "primary_collocate": null, "pronunciation": "zài jiù shì", "ipa": "tsai˥˩ tɕjou˥˩ ʂɨ˥˩", "syllable_count": 3, "sentences": [{"text": "今天先说这些，再就是明天的安排。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说完了工作，再就是说家里的事。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说了价钱，再就是送货的时间。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱已经准备好了，再就是找人帮忙。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先说好价钱，再就是说什么时候送来。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要早点睡，再就是别忘了带伞。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说了作业，再就是考试的时间。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上要小心，再就是到了给我打电话。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地方找好了，再就是请哪些客人。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先说天气，再就是说吃的东西。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "说完一件事后接着说另一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab11b7c9-d5a8-4a17-9c0b-0279c3fa91db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90661, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再就是", "is_correct": true, "explanation": "正确：说完“先说这些”之后，接着说“明天的安排”，符合语境。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，这里只是接着说另一件事，前后不构成转折。"}, {"text": "因为", "is_correct": false, "explanation": "配价：“因为”后需接原因分句，不能直接接名词短语“明天的安排”。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，“先说这些”推不出“明天的安排”，语义不通。"}], "explanations": {"再就是": "正确：说完“先说这些”之后，接着说“明天的安排”，符合语境。", "然而": "语义：“然而”表示转折，这里只是接着说另一件事，前后不构成转折。", "因为": "配价：“因为”后需接原因分句，不能直接接名词短语“明天的安排”。", "所以": "语义：“所以”表示结果，“先说这些”推不出“明天的安排”，语义不通。"}, "sentence_index": 0, "correct_answer": "再就是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不是学生，再就是老师。", "explanation": "这里应该用〈而是〉。“不是A，而是B”表示替换，“再就是”不能用在否定之后表示替换。"}, {"text": "我们只能选一个：坐车，再就是走路。", "explanation": "这里应该用〈或者〉。选择其一要用“或者”，“再就是”只补充另一项，不表示二选一。"}, {"text": "下雨了，再就是我们取消了比赛。", "explanation": "这里应该用〈于是〉。“下雨了，于是我们取消了比赛”表示因果承接，“再就是”不能表示因此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90661, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再就是", "is_correct": true, "explanation": "正确：说完“老师说了作业”之后，接着说“考试的时间”，符合语境。"}, {"text": "可是", "is_correct": false, "explanation": "语义：“可是”表示转折，“作业”与“考试的时间”之间没有对比。"}, {"text": "由于", "is_correct": false, "explanation": "配价：“由于”后需接原因成分，不能直接接“考试的时间”。"}, {"text": "虽然", "is_correct": false, "explanation": "配价：“虽然”需要与后文的转折配合，此句无法成立。"}], "explanations": {"再就是": "正确：说完“老师说了作业”之后，接着说“考试的时间”，符合语境。", "可是": "语义：“可是”表示转折，“作业”与“考试的时间”之间没有对比。", "由于": "配价：“由于”后需接原因成分，不能直接接“考试的时间”。", "虽然": "配价：“虽然”需要与后文的转折配合，此句无法成立。"}, "sentence_index": 6, "correct_answer": "再就是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他既喜欢音乐，再就是喜欢画画。", "explanation": "这里应该用〈也〉。“既……也……”是固定搭配，“再就是”不能与“既”配合。"}, {"text": "我再就是去了一次北京。", "explanation": "这里应该用〈又〉。表示动作重复要用“又”，“再就是”不表示重复。"}, {"text": "他没有生气，再就是笑了。", "explanation": "这里应该用〈反而〉。“反而”表示与预期相反，“再就是”只表示补充，不表示转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90661, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我先说明情况，再就是是说明原因。", "corrected_sentence": "我先说明情况，再就是说明原因。", "error_description": "错误在于多了一个“是”。应说“再就是说明原因”，多余的“是”使句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90661, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们先说吃饭的事，看电影的事再就是。", "corrected_sentence": "我们先说吃饭的事，再就是看电影的事。", "error_description": "语序错误：“再就是”要放在补充的内容前面，不能放在句末。应说“再就是看电影的事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
