INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90662, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示在前面所说之外再补充一项。", "primary_collocate": null, "pronunciation": "zài jiù shì", "ipa": "tsai˥˩ tɕjou˥˩ ʂɨ˥˩", "syllable_count": 3, "sentences": [{"text": "我想买水果，再就是牛奶。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末要洗衣服，再就是打扫房间。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我想去爬山，再就是找朋友吃饭。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "带上书和笔，再就是水。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去北京要看长城，再就是吃烤鸭。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上有苹果，再就是香蕉。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里要买米，再就是买菜。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里需要买盐，再就是买油。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我要谢谢爸爸，再就是妈妈。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校有图书馆，再就是体育馆。", "target_word": "再就是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "列举时在前面各项之外再补充一项", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab11b7c9-d5a8-4a17-9c0b-0279c3fa91db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90662, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再就是", "is_correct": true, "explanation": "正确：在“水果”之外补充“牛奶”，符合“再就是”的用法。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，前后要有对比，这里只是补充一项，不成立。"}, {"text": "因为", "is_correct": false, "explanation": "配价：“因为”后需接原因分句，不能直接接名词“牛奶”。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，“想买水果”推不出“牛奶”，语义不通。"}], "explanations": {"再就是": "正确：在“水果”之外补充“牛奶”，符合“再就是”的用法。", "但是": "语义：“但是”表示转折，前后要有对比，这里只是补充一项，不成立。", "因为": "配价：“因为”后需接原因分句，不能直接接名词“牛奶”。", "所以": "语义：“所以”表示结果，“想买水果”推不出“牛奶”，语义不通。"}, "sentence_index": 0, "correct_answer": "再就是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不是老师，再就是医生。", "explanation": "这里应该用〈而是〉。“不是A，而是B”表示替换，“再就是”只表示在已有事项之外补充，不能用在否定之后表示替换。"}, {"text": "我们只能选一个：喝茶，再就是咖啡。", "explanation": "这里应该用〈或者〉。选择其一要用“或者”，“再就是”只补充另一项，不表示二选一。"}, {"text": "下大雨了，再就是我们回家了。", "explanation": "这里应该用〈于是〉。“下大雨了，于是我们回家了”表示因果承接，“再就是”只补充另一件事，不能表示因此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90662, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再就是", "is_correct": true, "explanation": "正确：在“买米”之外补充“买菜”，符合语境。"}, {"text": "不过", "is_correct": false, "explanation": "语义：“不过”表示转折，“买米”与“买菜”之间没有对比关系。"}, {"text": "由于", "is_correct": false, "explanation": "配价：“由于”后需接原因成分，不能只接动词“买菜”。"}, {"text": "虽然", "is_correct": false, "explanation": "配价：“虽然”需要后文的转折配合，此句无法成立。"}], "explanations": {"再就是": "正确：在“买米”之外补充“买菜”，符合语境。", "不过": "语义：“不过”表示转折，“买米”与“买菜”之间没有对比关系。", "由于": "配价：“由于”后需接原因成分，不能只接动词“买菜”。", "虽然": "配价：“虽然”需要后文的转折配合，此句无法成立。"}, "sentence_index": 6, "correct_answer": "再就是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不但会说英语，再就是会说法语。", "explanation": "这里应该用〈还〉。“不但……还……”是固定搭配，“再就是”不能与“不但”配合。"}, {"text": "他再就是迟到了。", "explanation": "这里应该用〈又〉。表示动作重复要用“又”，“再就是”只用于补充并列的事项，不表示重复。"}, {"text": "大家都很害怕，再就是他很开心。", "explanation": "这里应该用〈反而〉。“反而”表示与预期相反，“再就是”只表示补充，不表示转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要买菜，再就是是做饭。", "corrected_sentence": "我们要买菜，再就是做饭。", "error_description": "错误在于多了一个“是”。应说“再就是做饭”，多余的“是”使句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他要去银行，去药店再就是。", "corrected_sentence": "他要去银行，再就是去药店。", "error_description": "语序错误：“再就是”要放在补充的事项前面，不能放在句末。应说“再就是去药店”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
