INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90665, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "意识到是你忽然知道了、发现了一件事。", "primary_collocate": null, "pronunciation": "yì shí dào", "ipa": "i˥˩ ʂʅ˧˥ taʊ˥˩", "syllable_count": 3, "sentences": [{"text": "走到门口，我才意识到忘了带钥匙。", "target_word": "意识到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看了看表，意识到已经很晚了。", "target_word": "意识到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我忽然意识到今天是妈妈的生日。", "target_word": "意识到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐上地铁后，她意识到自己坐反了方向。", "target_word": "意识到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一打开书包，就意识到作业没带。", "target_word": "意识到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我突然意识到钱包不见了。", "target_word": "意识到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到敲门声，他才意识到有人来了。", "target_word": "意识到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过了很久，我才意识到他是在开玩笑。", "target_word": "意识到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看着窗外，意识到天已经黑了。", "target_word": "意识到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了机场，他意识到护照放在家里了。", "target_word": "意识到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "意识到了", "label": "体标"}, {"form": "意识到过", "label": "体标"}, {"form": "意識到", "label": "繁体"}], "register": "中性", "sense_fingerprint": "忽然想到或发现某件具体的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f4a601-3387-46d6-8878-d4f1e5cccdbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90665, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意识到", "is_correct": true, "explanation": "意识到：走到门口才发觉自己忘了带钥匙，符合“才”表示忽然察觉的语境。"}, {"text": "预料", "is_correct": false, "explanation": "语义：预料是事先估计，与“走到门口”之后才察觉的时间顺序相反。"}, {"text": "提醒", "is_correct": false, "explanation": "配价：提醒后面要带一个被提醒的人，句中没有这样的宾语。"}, {"text": "注意", "is_correct": false, "explanation": "搭配：注意后面接小句通常要用注意到，单用注意不能接这样的内容。"}], "explanations": {"意识到": "意识到：走到门口才发觉自己忘了带钥匙，符合“才”表示忽然察觉的语境。", "预料": "语义：预料是事先估计，与“走到门口”之后才察觉的时间顺序相反。", "提醒": "配价：提醒后面要带一个被提醒的人，句中没有这样的宾语。", "注意": "搭配：注意后面接小句通常要用注意到，单用注意不能接这样的内容。"}, "sentence_index": 0, "correct_answer": "意识到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她意识到了那只猫。", "explanation": "这里应该用〈看见〉。意识到后面接的是某件事或某种情况，不能直接带具体的动物作宾语。"}, {"text": "我意识到了他的电话号码。", "explanation": "这里应该用〈记住〉。意识到表示发觉某件事，不是把号码记在心里。"}, {"text": "他意识到了我的名字。", "explanation": "这里应该用〈知道〉。意识到表示忽然发觉某件事，不能直接以人名作宾语，只能说知道或记得他的名字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90665, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意识到", "is_correct": true, "explanation": "意识到：听到敲门声后才发觉有人来，符合“才”的语境。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：忘记是不记得，与听到敲门声后才察觉的语境相矛盾。"}, {"text": "认可", "is_correct": false, "explanation": "搭配：认可指承认、同意，后面不接有人来了这样的事实陈述。"}, {"text": "预见", "is_correct": false, "explanation": "语义：预见是事先看到，与听到敲门声之后才察觉的顺序相反。"}], "explanations": {"意识到": "意识到：听到敲门声后才发觉有人来，符合“才”的语境。", "忘记": "语义：忘记是不记得，与听到敲门声后才察觉的语境相矛盾。", "认可": "搭配：认可指承认、同意，后面不接有人来了这样的事实陈述。", "预见": "语义：预见是事先看到，与听到敲门声之后才察觉的顺序相反。"}, "sentence_index": 6, "correct_answer": "意识到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飞机降落后，他意识到了机场。", "explanation": "这里应该用〈到达〉。意识到后面接的是事情或情况，不能以地点作宾语，表示抵达某地要用到达。"}, {"text": "他意识到了护照，就走出了门。", "explanation": "这里应该用〈看见〉或〈想起〉。意识到后面接的是事情或情况，不能直接带物品作宾语。"}, {"text": "到了机场，他把护照意识到了。", "explanation": "这里应该用〈想起〉。意识到不能把具体的物品放在把字后面作宾语，这样的说法不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90665, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下了车才把意识到手机落在车上了。", "corrected_sentence": "他下了车才意识到手机落在车上了。", "error_description": "多出了把字。意识到后接小句，不能作把字的宾语，把应删去，写作他下了车才意识到手机落在车上了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90665, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "到了车站，他才把意识到护照忘在车上了。", "corrected_sentence": "到了车站，他才意识到护照忘在车上了。", "error_description": "多出了把字。意识到后接小句，不能作把字的宾语，把应删去，写作到了车站，他才意识到护照忘在车上了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
