INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90666, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "认识到，察觉到。", "primary_collocate": null, "pronunciation": "yì shí dào", "ipa": "i˥˩ ʂʅ˧˥ taʊ˥˩", "syllable_count": 3, "sentences": [{"text": "他慢慢意识到学习很重要。", "target_word": "意识到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人没有意识到睡眠很重要。", "target_word": "意识到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过这件事，他意识到自己错了。", "target_word": "意识到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她意识到问题很严重，马上打了电话。", "target_word": "意识到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子长大后，才意识到父母不容易。", "target_word": "意识到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你有没有意识到自己说话太快？", "target_word": "意识到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来没意识到这样做会伤害朋友。", "target_word": "意识到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司意识到老办法不好用，就换了新的。", "target_word": "意识到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生让他意识到，吃得太多对身体不好。", "target_word": "意识到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要意识到环境问题已经很严重。", "target_word": "意识到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "意识到了", "label": "体标"}, {"form": "意识到过", "label": "体标"}, {"form": "意識到", "label": "繁体"}], "register": "中性", "sense_fingerprint": "逐渐认识到某个道理、问题或自己的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f4a601-3387-46d6-8878-d4f1e5cccdbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90666, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意识到", "is_correct": true, "explanation": "意识到：慢慢认识到学习的重要性，符合“慢慢”的逐渐认识语境。"}, {"text": "看见", "is_correct": false, "explanation": "语义：看见指用眼睛看到具体的东西，学习的重要性不能被看见。"}, {"text": "摸到", "is_correct": false, "explanation": "搭配：摸到指用手触碰具体的物体，不能用来接抽象的道理。"}, {"text": "收到", "is_correct": false, "explanation": "语义：收到指接到信件或物品，不能收到一个道理。"}], "explanations": {"意识到": "意识到：慢慢认识到学习的重要性，符合“慢慢”的逐渐认识语境。", "看见": "语义：看见指用眼睛看到具体的东西，学习的重要性不能被看见。", "摸到": "搭配：摸到指用手触碰具体的物体，不能用来接抽象的道理。", "收到": "语义：收到指接到信件或物品，不能收到一个道理。"}, "sentence_index": 0, "correct_answer": "意识到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我意识到了他的书。", "explanation": "这里应该用〈拿到〉。意识到接的是事实或道理，不能以具体的物品作宾语，表示拿到东西要用拿到。"}, {"text": "我意识到了这盘菜。", "explanation": "这里应该用〈尝到〉。意识到接的是事实或道理，不能以食物作宾语，尝食物要用尝到。"}, {"text": "我意识到了他的电话号码。", "explanation": "这里应该用〈记住〉。意识到表示认识到某件事，不是把号码记在心里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意识到", "is_correct": true, "explanation": "意识到：从来没有认识到这样做的后果，符合“从来没”的语境。"}, {"text": "预告", "is_correct": false, "explanation": "语义：预告是事先告知，与“从来没”之后的事后认识不符。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：摘指从树上等处取下，不能用来接会伤害朋友这样的句子。"}, {"text": "拿", "is_correct": false, "explanation": "搭配：拿指用手取物，不能拿一个因果句作宾语。"}], "explanations": {"意识到": "意识到：从来没有认识到这样做的后果，符合“从来没”的语境。", "预告": "语义：预告是事先告知，与“从来没”之后的事后认识不符。", "摘": "搭配：摘指从树上等处取下，不能用来接会伤害朋友这样的句子。", "拿": "搭配：拿指用手取物，不能拿一个因果句作宾语。"}, "sentence_index": 6, "correct_answer": "意识到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要意识到那只猫。", "explanation": "这里应该用〈看见〉。意识到后面接的是事情或情况，不能直接带动物作宾语。"}, {"text": "我在学校意识到了这位老师。", "explanation": "这里应该用〈认识〉。意识到接的是事实或道理，认识一个人要用认识，不能说意识到某位老师。"}, {"text": "我昨晚意识到了一只小狗。", "explanation": "这里应该用〈梦到〉。意识到接的是事实或道理，不能以动物作宾语，梦中出现某物要用梦到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于很意识到自己的习惯不好。", "corrected_sentence": "他终于意识到自己的习惯不好。", "error_description": "多出了很字。很是程度副词，不能直接修饰意识到，应删去，写作他终于意识到自己的习惯不好。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈看了这封信，把意识到出了大事。", "corrected_sentence": "妈妈看了这封信，意识到出了大事。", "error_description": "多出了把字。意识到后接小句，不能加把字作宾语，把应删去，写作妈妈看了这封信，意识到出了大事。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
