INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90667, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可怜是说谁很不幸，让别人心里难过，想帮他。", "primary_collocate": null, "pronunciation": "kě lián", "ipa": "kʰɤ˨˩˦ li̯ɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这个孩子没有爸爸妈妈，真可怜。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着那只没吃饭的小狗，我觉得它很可怜。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人住在医院里，太可怜了。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个可怜的老人一直在等儿子回来。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别笑他，他已经够可怜的了。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，那个可怜的小女孩没有伞。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都很同情这个可怜的人。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的样子看起来很可怜。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些可怜的孩子需要我们的帮助。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说那只猫很可怜，就把它带回了家。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可怜巴巴", "label": "状态形容词"}, {"form": "可怜兮兮", "label": "状态形容词"}], "register": "中性", "sense_fingerprint": "某人很不幸，让人心疼、想帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b68f76f-19ce-4182-879c-f07998280520') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90667, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可怜", "is_correct": true, "explanation": "正确：「可怜」表示处境不幸、令人同情，与「没有爸爸妈妈」相符。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：孩子没有父母，说「真可爱」与语境冲突。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：没有父母却说「真高兴」，与语境矛盾。"}, {"text": "富有", "is_correct": false, "explanation": "搭配：「真富有」指经济状况，不适合用来描述这个孩子没有父母的处境。"}], "explanations": {"可怜": "正确：「可怜」表示处境不幸、令人同情，与「没有爸爸妈妈」相符。", "可爱": "语义：孩子没有父母，说「真可爱」与语境冲突。", "高兴": "语义：没有父母却说「真高兴」，与语境矛盾。", "富有": "搭配：「真富有」指经济状况，不适合用来描述这个孩子没有父母的处境。"}, "sentence_index": 0, "correct_answer": "可怜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那场雷雨很可怜，房子都在摇。", "explanation": "这里应该用〈可怕〉。可怜表示令人同情，不能用来形容雷雨这类让人害怕的天气。"}, {"text": "他拿到了全班第一名，真可怜。", "explanation": "这里应该用〈厉害〉。可怜表示令人同情，获得第一名应被称赞，不能用「可怜」。"}, {"text": "这位老师待学生很可怜，大家都喜欢她。", "explanation": "这里应该用〈可亲〉。可怜表示令人同情，不能用来形容待人亲切、让人喜欢的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90667, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可怜", "is_correct": true, "explanation": "正确：「可怜」表示令人同情，与「同情」相符。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」说身材，与「同情」的语义不搭配。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：聪明通常不会引起同情，与「同情这个人」的语境冲突。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：漂亮的人通常被赞美，不需要同情，与语境冲突。"}], "explanations": {"可怜": "正确：「可怜」表示令人同情，与「同情」相符。", "高大": "体貌：「高大」说身材，与「同情」的语义不搭配。", "聪明": "语义：聪明通常不会引起同情，与「同情这个人」的语境冲突。", "漂亮": "语义：漂亮的人通常被赞美，不需要同情，与语境冲突。"}, "sentence_index": 6, "correct_answer": "可怜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个老板给员工涨了工资，真可怜。", "explanation": "这里应该用〈慷慨〉。可怜表示令人同情，老板涨工资值得称道，不能用「可怜」。"}, {"text": "这个陌生人的举动很可怜，我们要小心。", "explanation": "这里应该用〈可疑〉。可怜表示令人同情，不能形容举动可疑。"}, {"text": "这么好的机会他抓住了，真可怜。", "explanation": "这里应该用〈幸运〉。可怜表示令人同情，抓住好机会应羡慕而非同情，不能用「可怜」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90667, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一个可怜地老人，一个人住在山里。", "corrected_sentence": "她是一个可怜的老人，一个人住在山里。", "error_description": "错误：助词用错。「可怜」修饰名词「老人」时要用「的」，写作「可怜的老人」，不能用「地」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90667, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只狗饿很可怜，没人喂它。", "corrected_sentence": "那只狗饿得很可怜，没人喂它。", "error_description": "错误：程度补语的助词「得」漏掉。「饿」后应接「得」，写作「饿得很可怜」，不能说「饿很可怜」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90668, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90668, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90668, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "处境不幸，令人同情。", "primary_collocate": null, "pronunciation": "kě lián", "ipa": "kʰɤ˨˩˦ li̯ɛn˧˥", "syllable_count": 2, "sentences": [{"text": "她的生活过得很可怜。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人失去了工作和家，真可怜。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪天还在外面找吃的，流浪猫很可怜。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人在国外生病，没人照顾，太可怜了。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了他的故事，我觉得他可怜极了。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震以后，这些可怜的人没有地方住。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她可怜的样子让大家都很难过。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不想变成一个可怜的人。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家很穷，孩子冬天连鞋都没有，太可怜了。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么冷的天，他还在街上睡觉，真可怜。", "target_word": "可怜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可怜巴巴", "label": "状态形容词"}, {"form": "可怜兮兮", "label": "状态形容词"}], "register": "中性", "sense_fingerprint": "处境不好、生活困难，令人同情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b68f76f-19ce-4182-879c-f07998280520') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90668, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可怜", "is_correct": true, "explanation": "正确：「可怜」表示处境不好、令人同情，与「生活过得很」相符。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：「生活过得很可爱」说不通，与生活状况的描述不符。"}, {"text": "高", "is_correct": false, "explanation": "搭配：「过得很高」不用于描述生活状况，搭配不当。"}, {"text": "快速", "is_correct": false, "explanation": "搭配：「过得很快速」不符合描述生活状况的说法。"}], "explanations": {"可怜": "正确：「可怜」表示处境不好、令人同情，与「生活过得很」相符。", "可爱": "语义：「生活过得很可爱」说不通，与生活状况的描述不符。", "高": "搭配：「过得很高」不用于描述生活状况，搭配不当。", "快速": "搭配：「过得很快速」不符合描述生活状况的说法。"}, "sentence_index": 0, "correct_answer": "可怜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那场大火很可怜，大家都吓坏了。", "explanation": "这里应该用〈可怕〉。可怜表示令人同情，不能用来形容大火这种让人害怕的灾难。"}, {"text": "他主动把钱还给了失主，真可怜。", "explanation": "这里应该用〈可敬〉。可怜表示令人同情，主动归还财物值得敬佩，不能用「可怜」。"}, {"text": "他能坚持到最后，这份精神很可怜。", "explanation": "这里应该用〈可贵〉。可怜表示令人同情，不能用来赞扬值得珍视的精神。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90668, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可怜", "is_correct": true, "explanation": "正确：「可怜」指样子令人同情，与「让大家都很难过」相符。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大的样子」与「让大家都很难过」的语义不搭配。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：聪明的样子不会让大家难过，语义矛盾。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：漂亮的样子通常令人赞美，不会让大家难过。"}], "explanations": {"可怜": "正确：「可怜」指样子令人同情，与「让大家都很难过」相符。", "高大": "体貌：「高大的样子」与「让大家都很难过」的语义不搭配。", "聪明": "语义：聪明的样子不会让大家难过，语义矛盾。", "漂亮": "语义：漂亮的样子通常令人赞美，不会让大家难过。"}, "sentence_index": 6, "correct_answer": "可怜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个老板给员工涨了工资，真可怜。", "explanation": "这里应该用〈慷慨〉。可怜表示令人同情，老板涨工资值得称道，不能用「可怜」。"}, {"text": "这个陌生人的举动很可怜，我们要小心。", "explanation": "这里应该用〈可疑〉。可怜表示令人同情，不能形容举动可疑。"}, {"text": "这么好的机会他抓住了，真可怜。", "explanation": "这里应该用〈幸运〉。可怜表示令人同情，抓住好机会应羡慕而非同情，不能用「可怜」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小孩太可怜了了，没人管他。", "corrected_sentence": "这个小孩太可怜了，没人管他。", "error_description": "错误：「了」重复。「太可怜」后只用一个「了」，应写作「太可怜了」，不能说「太可怜了了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只狗饿得地可怜，没人喂它。", "corrected_sentence": "那只狗饿得很可怜，没人喂它。", "error_description": "错误：「饿得」之后的补语应用程度副词「很」，写作「饿得很可怜」；「地」不能用在「得」之后的补语位置。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90669, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "战前", "is_correct": true, "explanation": "正确答案。战前指战争发生之前，与战后互为反义。"}, {"text": "清晨", "is_correct": false, "explanation": "清晨指一天刚开始的时段，与战后没有反义关系。"}, {"text": "夏天", "is_correct": false, "explanation": "夏天指一年中的季节，与战后没有反义关系。"}, {"text": "饭后", "is_correct": false, "explanation": "饭后指吃完饭之后，与战后没有反义关系。"}], "correct_answer": "战前", "explanations": {"战前": "正确答案。战前指战争发生之前，与战后互为反义。", "清晨": "清晨指一天刚开始的时段，与战后没有反义关系。", "夏天": "夏天指一年中的季节，与战后没有反义关系。", "饭后": "饭后指吃完饭之后，与战后没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90669, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "战前", "is_correct": true, "explanation": "正确答案。战前指战争发生之前，与战后互为反义。"}, {"text": "中午", "is_correct": false, "explanation": "中午指一天中的时段，与战后没有反义关系。"}, {"text": "黄昏", "is_correct": false, "explanation": "黄昏指太阳快落山的时候，与战后没有反义关系。"}, {"text": "周末", "is_correct": false, "explanation": "周末指一周的最后几天，与战后没有反义关系。"}], "correct_answer": "战前", "explanations": {"战前": "正确答案。战前指战争发生之前，与战后互为反义。", "中午": "中午指一天中的时段，与战后没有反义关系。", "黄昏": "黄昏指太阳快落山的时候，与战后没有反义关系。", "周末": "周末指一周的最后几天，与战后没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90669, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "战后是打完仗以后的那段时间。", "primary_collocate": null, "pronunciation": "zhàn hòu", "ipa": "ʈʂan˥˩ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "战后，人们过着很苦的生活。", "target_word": "战后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常说战后的日子很难。", "target_word": "战后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战后，这个国家花了很多年重建。", "target_word": "战后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战后很多孩子没有学校可以上。", "target_word": "战后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战后的城市里到处是旧房子。", "target_word": "战后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书里读到战后的生活。", "target_word": "战后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战后几年，吃的东西很少。", "target_word": "战后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战后出生的人没有见过打仗。", "target_word": "战后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战后，大家都希望有和平。", "target_word": "战后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶是战后长大的。", "target_word": "战后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "戰後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "战争结束之后的一段时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52af20df-6e56-40f6-a8c1-0c1dd987e45e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90669, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "战后", "is_correct": true, "explanation": "正确答案。战后指战争结束以后的一段时间，可作句首时间状语。"}, {"text": "和平", "is_correct": false, "explanation": "语义：和平指没有战争的状态，不指时间段，与「过着很苦的生活」的语境矛盾。"}, {"text": "战争", "is_correct": false, "explanation": "搭配：战争是事件，不能单独作句首时间状语，要说「战争中」或「战后」。"}, {"text": "战场", "is_correct": false, "explanation": "搭配：战场是地点，不能作时间状语。"}], "explanations": {"战后": "正确答案。战后指战争结束以后的一段时间，可作句首时间状语。", "和平": "语义：和平指没有战争的状态，不指时间段，与「过着很苦的生活」的语境矛盾。", "战争": "搭配：战争是事件，不能单独作句首时间状语，要说「战争中」或「战后」。", "战场": "搭配：战场是地点，不能作时间状语。"}, "sentence_index": 0, "correct_answer": "战后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "战后，士兵们正在前线作战。", "explanation": "这里应该用〈战时〉。战后指战争结束之后，与「正在前线作战」这种战争进行中的情况矛盾。"}, {"text": "期末考试战后，同学们都很放心。", "explanation": "这里应该用〈考后〉。战后专指战争结束以后，期末考试之后应说〈考后〉。"}, {"text": "战后，城市里每天都有炸弹爆炸。", "explanation": "这里应该用〈战争期间〉。战后指战争结束之后，每天有炸弹爆炸说明战争还在进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90669, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战后", "is_correct": true, "explanation": "正确答案。战后几年指战争结束后的几年，与「吃的东西很少」的背景相合。"}, {"text": "丰收", "is_correct": false, "explanation": "语义：丰收指粮食多，与「吃的东西很少」矛盾。"}, {"text": "盛世", "is_correct": false, "explanation": "语义：盛世指国家繁荣，与「吃的东西很少」矛盾。"}, {"text": "饭后", "is_correct": false, "explanation": "语义：饭后指吃完饭后不久，不能说「饭后几年」，与语境不符。"}], "explanations": {"战后": "正确答案。战后几年指战争结束后的几年，与「吃的东西很少」的背景相合。", "丰收": "语义：丰收指粮食多，与「吃的东西很少」矛盾。", "盛世": "语义：盛世指国家繁荣，与「吃的东西很少」矛盾。", "饭后": "语义：饭后指吃完饭后不久，不能说「饭后几年」，与语境不符。"}, "sentence_index": 6, "correct_answer": "战后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "战后，敌人的炮火还在城市上空飞着。", "explanation": "这里应该用〈交战时〉。战后指战争结束之后，炮火仍在飞说明还在交战，应说〈交战时〉。"}, {"text": "这场足球赛战后，大家都去吃夜宵了。", "explanation": "这里应该用〈赛后〉。战后专指战争结束以后，足球赛之后应说〈赛后〉。"}, {"text": "战后，这里的孩子一听到警报就往防空洞跑。", "explanation": "这里应该用〈空袭期间〉。战后指战争结束之后，听到警报往防空洞跑是空袭中的情况，应说〈空袭期间〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90669, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "战后之后，这个村子慢慢恢复了生气。", "corrected_sentence": "战后，这个村子慢慢恢复了生气。", "error_description": "冗余错误：「战后」本身已表示战争结束以后，后面不能再加「之后」，应说「战后」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90669, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他出生战后那几年，家里很穷。", "corrected_sentence": "他出生在战后那几年，家里很穷。", "error_description": "介词缺失：表示出生的时间地点时，「战后」前需加介词「在」，应说「出生在战后那几年」，不能说「出生战后那几年」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
