INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90671, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "含是把东西放在嘴里，不吞下去。", "primary_collocate": null, "pronunciation": "hán", "ipa": "xan˧˥", "syllable_count": 1, "sentences": [{"text": "孩子嘴里含着一颗糖。", "target_word": "含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他含了一口水。", "target_word": "含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这片药含在嘴里。", "target_word": "含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把东西含在嘴里说话。", "target_word": "含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我含一会儿再咽下去。", "target_word": "含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗含着球跑过来了。", "target_word": "含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她含着糖，不想说话。", "target_word": "含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这种药要含着，不能吞。", "target_word": "含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把水含了一会儿，才吐出来。", "target_word": "含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟含着手指睡着了。", "target_word": "含", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "含着", "label": "体标"}, {"form": "含了", "label": "体标"}, {"form": "含过", "label": "体标"}], "register": "通用", "sense_fingerprint": "把东西放在嘴里不吞下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628153f8-23f4-4783-aca5-17ac6551aa7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90671, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "含", "is_correct": true, "explanation": "含 hán：把东西放在嘴里，不吞下去。"}, {"text": "喊", "is_correct": false, "explanation": "hǎn（第三声）与 hán（第二声）声调不同，意思是大声叫。"}, {"text": "汗", "is_correct": false, "explanation": "hàn（第四声）与 hán（第二声）声调不同，意思是汗水。"}, {"text": "孩", "is_correct": false, "explanation": "hái 与 hán 只有韵母不同（ai 与 an），意思是小孩。"}, {"text": "凡", "is_correct": false, "explanation": "fán 与 hán 声母不同（f 与 h），意思是凡是。"}], "explanations": {"含": "含 hán：把东西放在嘴里，不吞下去。", "喊": "hǎn（第三声）与 hán（第二声）声调不同，意思是大声叫。", "汗": "hàn（第四声）与 hán（第二声）声调不同，意思是汗水。", "孩": "hái 与 hán 只有韵母不同（ai 与 an），意思是小孩。", "凡": "fán 与 hán 声母不同（f 与 h），意思是凡是。"}, "sentence_index": null, "correct_answer": "含"}, "level_3": {"options": [{"text": "含", "is_correct": true, "explanation": "含：糖留在嘴里不吞下，与“嘴里”和“着”相合。"}, {"text": "挤", "is_correct": false, "explanation": "语义：挤是压出，与“糖留在嘴里”的状态不符。"}, {"text": "搓", "is_correct": false, "explanation": "搭配：搓是用手揉动，不能与“嘴里”搭配。"}, {"text": "摸", "is_correct": false, "explanation": "搭配：摸是用手触碰，不能与“嘴里”搭配。"}], "explanations": {"含": "含：糖留在嘴里不吞下，与“嘴里”和“着”相合。", "挤": "语义：挤是压出，与“糖留在嘴里”的状态不符。", "搓": "搭配：搓是用手揉动，不能与“嘴里”搭配。", "摸": "搭配：摸是用手触碰，不能与“嘴里”搭配。"}, "sentence_index": 0, "correct_answer": "含"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快就把苦药含了下去。", "explanation": "这里应该用〈吞〉。含是放在嘴里不吞下，药咽下去要用吞。"}, {"text": "奶奶把饭含下去，慢慢地笑了。", "explanation": "这里应该用〈咽〉。饭咽下去要用咽，含表示东西留在嘴里。"}, {"text": "小弟把嘴里的泡泡含了出来。", "explanation": "这里应该用〈吐〉。泡泡从嘴里出来要用吐，含是留在嘴里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90671, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "含", "is_correct": true, "explanation": "含 hán：把东西放在嘴里，不吞下去。"}, {"text": "航", "is_correct": false, "explanation": "háng 与 hán 韵母不同（ang 与 an），意思是航行。"}, {"text": "旱", "is_correct": false, "explanation": "hàn（第四声）与 hán（第二声）声调不同，意思是干旱。"}, {"text": "还", "is_correct": false, "explanation": "hái 与 hán 只有韵母不同（ai 与 an），意思是仍然。"}, {"text": "烦", "is_correct": false, "explanation": "fán 与 hán 声母不同（f 与 h），意思是烦恼。"}], "explanations": {"含": "含 hán：把东西放在嘴里，不吞下去。", "航": "háng 与 hán 韵母不同（ang 与 an），意思是航行。", "旱": "hàn（第四声）与 hán（第二声）声调不同，意思是干旱。", "还": "hái 与 hán 只有韵母不同（ai 与 an），意思是仍然。", "烦": "fán 与 hán 声母不同（f 与 h），意思是烦恼。"}, "sentence_index": null, "correct_answer": "含"}, "level_3": {"options": [{"text": "含", "is_correct": true, "explanation": "含：糖留在嘴里不说话，与“着”相合。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是抛出去，与“含着糖”的状态矛盾。"}, {"text": "砸", "is_correct": false, "explanation": "搭配：砸是用力击打，不能与“糖”搭配。"}, {"text": "吐", "is_correct": false, "explanation": "语义：吐是把东西排出嘴外，与“含着糖”相反。"}], "explanations": {"含": "含：糖留在嘴里不说话，与“着”相合。", "扔": "语义：扔是抛出去，与“含着糖”的状态矛盾。", "砸": "搭配：砸是用力击打，不能与“糖”搭配。", "吐": "语义：吐是把东西排出嘴外，与“含着糖”相反。"}, "sentence_index": 6, "correct_answer": "含"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟弟把饼干含碎了，才咽下去。", "explanation": "这里应该用〈嚼〉。嚼碎是用牙齿咀嚼，含只是把东西放在嘴里不嚼，不能说“含碎”。"}, {"text": "妈妈一口含了整杯牛奶。", "explanation": "这里应该用〈喝〉。含只表示嘴里放着一小口，整杯牛奶要用喝，不能用含。"}, {"text": "他把一大碗饭含进嘴里。", "explanation": "这里应该用〈扒〉。含只能放进一小口的东西，一大碗饭要用扒，不能说含进嘴里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90671, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶正含了一颗糖，没法说话。", "corrected_sentence": "奶奶正含着一颗糖，没法说话。", "error_description": "错误在动态助词：“正”表示动作状态正在持续，“含”后面应该用“着”，不能用“了”，应为“正含着一颗糖”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90671, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宝宝含了着奶嘴，睡着了。", "corrected_sentence": "宝宝含着奶嘴，睡着了。", "error_description": "错误在动态助词：“了”和“着”不能连用在同一个动词后，表示持续状态应为“含着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
