INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90673, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "扭转是把方向转过来，变成不一样。", "primary_collocate": null, "pronunciation": "niǔ zhuǎn", "ipa": "nio̯u̯˨˩˦ ʈʂuan˨˩˦", "syllable_count": 2, "sentences": [{"text": "司机扭转车头，避开了小狗。", "target_word": "扭转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他扭转车头，往回开了。", "target_word": "扭转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的局面很快扭转了。", "target_word": "扭转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想扭转自己的命运。", "target_word": "扭转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次失败扭转了他的想法。", "target_word": "扭转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想扭转学生的态度。", "target_word": "扭转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他扭转了船头的方向。", "target_word": "扭转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们必须扭转这个趋势。", "target_word": "扭转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师扭转了谈话的方向。", "target_word": "扭转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局面扭转以后，大家都笑了。", "target_word": "扭转", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扭转了", "label": "体标"}, {"form": "扭转过", "label": "体标"}, {"form": "扭轉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把原来的方向或趋势转过来，变得不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbaef05-ab62-4cb3-bccf-d75c1fe06dac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90673, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能吃“车头”。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”的宾语应是水平、效率等，不能说“提高车头”。"}, {"text": "播放", "is_correct": false, "explanation": "语义：“播放”用于音像内容，不能播放“车头”。"}, {"text": "扭转", "is_correct": true, "explanation": "“扭转车头”指把车头的方向转过来，符合句意。"}], "explanations": {"吃": "语义：“吃”的对象是食物，不能吃“车头”。", "提高": "搭配：“提高”的宾语应是水平、效率等，不能说“提高车头”。", "播放": "语义：“播放”用于音像内容，不能播放“车头”。", "扭转": "“扭转车头”指把车头的方向转过来，符合句意。"}, "sentence_index": 0, "correct_answer": "扭转"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他扭转了自己的简历。", "explanation": "这里应该用〈修改〉。扭转指把方向转过来，简历的内容要用“修改”。"}, {"text": "他扭转了一家公司的成员。", "explanation": "这里应该用〈调换〉。扭转用于方向或趋势，团体成员的调换要用“调换”。"}, {"text": "他扭转了一本书的内容。", "explanation": "这里应该用〈修改〉。扭转不能用于“内容”；书籍内容的更改要用“修改”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90673, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喂", "is_correct": false, "explanation": "语义：“喂”的对象是人或动物，不能用于“方向”。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”用于数量，不能说“增加船头的方向”。"}, {"text": "扭转", "is_correct": true, "explanation": "“扭转”指把船头的方向转过来，与“船头的方向”搭配，符合句意。"}, {"text": "缝", "is_correct": false, "explanation": "语义：“缝”指缝合布料，不能用于“方向”。"}], "explanations": {"喂": "语义：“喂”的对象是人或动物，不能用于“方向”。", "增加": "搭配：“增加”用于数量，不能说“增加船头的方向”。", "扭转": "“扭转”指把船头的方向转过来，与“船头的方向”搭配，符合句意。", "缝": "语义：“缝”指缝合布料，不能用于“方向”。"}, "sentence_index": 6, "correct_answer": "扭转"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想扭转自己的衣服款式。", "explanation": "这里应该用〈更换〉。扭转用于方向或趋势，衣服款式的变化要用“更换”。"}, {"text": "老师扭转了学生的成绩单。", "explanation": "这里应该用〈修改〉。扭转不能用于“成绩单”；成绩单的更改要用“修改”。"}, {"text": "我们扭转了一座房子的结构。", "explanation": "这里应该用〈改造〉。扭转用于方向或局势，房屋结构的改动要用“改造”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90673, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没扭转了车头。", "corrected_sentence": "他没扭转车头。", "error_description": "错误：“没扭转了”。正确：“没扭转”。“没”否定已发生的动作，后面不能再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90673, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把船头的方向扭转。", "corrected_sentence": "他把船头的方向扭转了。", "error_description": "错误：“把”字句中动作已完成，动词后漏掉“了”。正确：应说“把船头的方向扭转了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
