INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90678, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人的品行、素质；也指物品的质量。", "primary_collocate": null, "pronunciation": "pǐn zhì", "ipa": "pʰin˨˩˦ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "她的品质让大家都很尊敬她。", "target_word": "品质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这批牛奶的品质没有问题。", "target_word": "品质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好朋友要有好的品质。", "target_word": "品质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个牌子的手机品质一直很稳定。", "target_word": "品质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保证品质，工人每天都要检查产品。", "target_word": "品质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的品质要从小培养。", "target_word": "品质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块布的品质很好，穿了很多年还像新的。", "target_word": "品质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他虽然不富有，但品质高尚。", "target_word": "品质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买电脑时我最看重品质。", "target_word": "品质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司要求每件商品的品质都要合格。", "target_word": "品质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "品质管理", "label": "复合"}, {"form": "品质保证", "label": "复合"}], "register": "中性", "sense_fingerprint": "品质：人的品行素质，或物品的质量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4d7aeb-bdb3-4b50-b630-bfe4d39c60e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90678, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "品质", "is_correct": true, "explanation": "正确。“品质”指人的品行，与“让大家都很尊敬她”呼应。"}, {"text": "发型", "is_correct": false, "explanation": "体貌：“发型”指头发的样式，不能让人产生尊敬，句意不通。"}, {"text": "鞋码", "is_correct": false, "explanation": "语义：“鞋码”指鞋子的尺寸，与人的品行无关，不能成为让人尊敬的原因。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”说轻重，与令人尊敬的意思不符。"}], "explanations": {"品质": "正确。“品质”指人的品行，与“让大家都很尊敬她”呼应。", "发型": "体貌：“发型”指头发的样式，不能让人产生尊敬，句意不通。", "鞋码": "语义：“鞋码”指鞋子的尺寸，与人的品行无关，不能成为让人尊敬的原因。", "体重": "体貌：“体重”说轻重，与令人尊敬的意思不符。"}, "sentence_index": 0, "correct_answer": "品质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个牌子的手机品质一直很便宜。", "explanation": "这里应该用〈价格〉。〈品质〉说好坏，不说便宜或贵；价钱要用〈价格〉。"}, {"text": "这次考试的品质很难。", "explanation": "〈品质〉指人的品行或物的质量，这里说的是考试的〈难度〉，不能用〈品质〉来说难易。"}, {"text": "这杯茶的品质太烫了，等一会儿再喝。", "explanation": "这里应该用〈温度〉。〈品质〉说好坏，不说冷热；“烫”说的是〈温度〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "品质", "is_correct": true, "explanation": "正确。“品质”指布料的质量，与“很好，穿了很多年还像新的”呼应。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”用于人的性情，布料没有脾气，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”只用于人或生物，不能用来说布料。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”多用于人，“布的性格”不是常见搭配。"}], "explanations": {"品质": "正确。“品质”指布料的质量，与“很好，穿了很多年还像新的”呼应。", "脾气": "语义：“脾气”用于人的性情，布料没有脾气，句意不通。", "身高": "语义：“身高”只用于人或生物，不能用来说布料。", "性格": "搭配：“性格”多用于人，“布的性格”不是常见搭配。"}, "sentence_index": 6, "correct_answer": "品质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批货的品质很多，装满了三辆车。", "explanation": "这里应该用〈数量〉。〈品质〉说好坏，不说多少；“很多”说的是〈数量〉。"}, {"text": "这条路的品质很长，走了一个小时。", "explanation": "〈品质〉不能用来说长短；这里表示的是〈长度〉，与〈品质〉的好坏义无关。"}, {"text": "他把品质放进了包里。", "explanation": "〈品质〉是抽象的特点，不能像实物一样放进包里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师有一只很好的品质。", "corrected_sentence": "这位老师有一种很好的品质。", "error_description": "错误：“品质”的量词用成了“只”。“品质”是抽象名词，应用“种”，写作“一种很好的品质”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这双鞋的品质很结实。", "corrected_sentence": "这双鞋的品质很好。", "error_description": "错误：“品质”和“结实”不搭配。“结实”说的是东西本身，不能用来说“品质”。“品质”只说好坏、高低，应写作“品质很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b3437e-00b3-49dd-8c54-9732077a6547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
