INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90679, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抛是用力把东西向空中扔出去。", "primary_collocate": null, "pronunciation": "pāo", "ipa": "pʰɑʊ̯˥", "syllable_count": 1, "sentences": [{"text": "他向河里抛石头。", "target_word": "抛", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "打网球发球前要先抛球。", "target_word": "抛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他抛了一下手里的钥匙。", "target_word": "抛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用力抛绳子，船上的人接住了。", "target_word": "抛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要往窗外抛东西。", "target_word": "抛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想把书包抛到床上。", "target_word": "抛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩抛着气球玩儿。", "target_word": "抛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民把网抛向大海。", "target_word": "抛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把我抛向空中，我笑了。", "target_word": "抛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从没抛过这么重的球。", "target_word": "抛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抛了", "label": "完成体"}, {"form": "抛着", "label": "持续体"}, {"form": "抛过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "用力把东西扔向空中或远处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbaef05-ab62-4cb3-bccf-d75c1fe06dac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90679, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抛", "is_correct": true, "explanation": "正确。抛 pāo 指用力把东西向空中或远处扔出去。"}, {"text": "炮", "is_correct": false, "explanation": "pào（第四声）与 pāo（第一声）声调不同，意思是炮。"}, {"text": "刨", "is_correct": false, "explanation": "páo（第二声）与 pāo（第一声）声调不同，意思是刨子、刨。"}, {"text": "剥", "is_correct": false, "explanation": "bāo 与 pāo 声母不同（不送气的 b 与送气的 p），意思是剥。"}, {"text": "拍", "is_correct": false, "explanation": "pāi 与 pāo 韵母不同（ai 与 ao），意思是拍。"}], "explanations": {"抛": "正确。抛 pāo 指用力把东西向空中或远处扔出去。", "炮": "pào（第四声）与 pāo（第一声）声调不同，意思是炮。", "刨": "páo（第二声）与 pāo（第一声）声调不同，意思是刨子、刨。", "剥": "bāo 与 pāo 声母不同（不送气的 b 与送气的 p），意思是剥。", "拍": "pāi 与 pāo 韵母不同（ai 与 ao），意思是拍。"}, "sentence_index": null, "correct_answer": "抛"}, "level_3": {"options": [{"text": "抛", "is_correct": true, "explanation": "正确。“向河里抛石头”指把石头用力扔进河里，与语境相符。"}, {"text": "游", "is_correct": false, "explanation": "配价：“游”是不及物动词，后面不能直接带“石头”作宾语。"}, {"text": "钓", "is_correct": false, "explanation": "语义：“钓”的对象是鱼等，不能用来钓石头。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象应是食物，石头不能吃。"}], "explanations": {"抛": "正确。“向河里抛石头”指把石头用力扔进河里，与语境相符。", "游": "配价：“游”是不及物动词，后面不能直接带“石头”作宾语。", "钓": "语义：“钓”的对象是鱼等，不能用来钓石头。", "吃": "语义：“吃”的对象应是食物，石头不能吃。"}, "sentence_index": 0, "correct_answer": "抛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用力抛门，门开了。", "explanation": "这里应该用〈推〉。“抛”是把东西扔出去，门不能被抛，应该用“推”。"}, {"text": "他抛了一下脖子，转过了头。", "explanation": "这里应该用〈扭〉。“扭”指身体部位转动，“抛”是把东西扔出去，不能用于脖子的动作。"}, {"text": "他抛手告别。", "explanation": "这里应该用〈挥〉。“挥”是摆动手臂，“抛”是把东西扔出去，不能用于手的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90679, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "抛", "is_correct": true, "explanation": "正确。抛 pāo 指用力把东西向空中或远处扔出去。"}, {"text": "跑", "is_correct": false, "explanation": "pǎo（第三声）与 pāo（第一声）声调不同，意思是跑步。"}, {"text": "包", "is_correct": false, "explanation": "bāo 与 pāo 声母不同（不送气的 b 与送气的 p），意思是包。"}, {"text": "袍", "is_correct": false, "explanation": "páo（第二声）与 pāo（第一声）声调不同，意思是长袍。"}], "explanations": {"抛": "正确。抛 pāo 指用力把东西向空中或远处扔出去。", "跑": "pǎo（第三声）与 pāo（第一声）声调不同，意思是跑步。", "包": "bāo 与 pāo 声母不同（不送气的 b 与送气的 p），意思是包。", "袍": "páo（第二声）与 pāo（第一声）声调不同，意思是长袍。"}, "sentence_index": null, "correct_answer": "抛"}, "level_3": {"options": [{"text": "抛", "is_correct": true, "explanation": "正确。“小孩抛着气球玩儿”指把气球抛起来玩，与语境相符。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服、鞋袜，不能和“气球”搭配。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，后面不能直接带“气球”作宾语。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”的对象是人或动物，气球不能被喂。"}], "explanations": {"抛": "正确。“小孩抛着气球玩儿”指把气球抛起来玩，与语境相符。", "穿": "搭配：“穿”用于衣服、鞋袜，不能和“气球”搭配。", "睡": "配价：“睡”是不及物动词，后面不能直接带“气球”作宾语。", "喂": "语义：“喂”的对象是人或动物，气球不能被喂。"}, "sentence_index": 6, "correct_answer": "抛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天抛了一场感冒。", "explanation": "这里应该用〈得〉。“抛”是用力扔出的动作，感冒是疾病，不能被抛，应说“得了感冒”。"}, {"text": "这辆车抛得很快。", "explanation": "这里应该用〈开〉。“抛”是用力扔出的动作，不能用来形容车的行驶，应说“车开得很快”。"}, {"text": "他抛了一首歌给大家听。", "explanation": "这里应该用〈唱〉。“抛”是用力扔出，歌曲不能被扔，应说“唱一首歌给大家听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings 