INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90679, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把石头抛。", "corrected_sentence": "他把石头抛进河里。", "error_description": "错误：“把石头抛”。正确：“把石头抛进河里”。“把”字句中“抛”后面要有补语等成分，不能只用光杆动词结尾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90679, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟弟抛了着气球玩儿。", "corrected_sentence": "弟弟抛着气球玩儿。", "error_description": "错误：“抛了着”。正确：“抛着”。“着”表示动作正在进行或状态持续，不能和“了”同时用在动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
