INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90680, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向空中扔，投掷。", "primary_collocate": null, "pronunciation": "pāo", "ipa": "pʰɑʊ̯˥", "syllable_count": 1, "sentences": [{"text": "他用力抛球。", "target_word": "抛", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你抛一下硬币。", "target_word": "抛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她抛了一个红球。", "target_word": "抛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛前，裁判先抛硬币。", "target_word": "抛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明站在河边，向水里抛石头。", "target_word": "抛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把球抛给我。", "target_word": "抛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们把帽子抛向天空。", "target_word": "抛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抛着球走进了教室。", "target_word": "抛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你抛过硬币吗？", "target_word": "抛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把花束抛给了朋友们。", "target_word": "抛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抛了", "label": "完成体"}, {"form": "抛着", "label": "持续体"}, {"form": "抛过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把东西向空中或远处扔出，如抛球、抛硬币", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbaef05-ab62-4cb3-bccf-d75c1fe06dac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90680, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抛", "is_correct": true, "explanation": "正确。抛 pāo 指用力把东西向空中或远处扔出去。"}, {"text": "跑", "is_correct": false, "explanation": "pǎo（第三声）与 pāo（第一声）声调不同，意思是跑步。"}, {"text": "包", "is_correct": false, "explanation": "bāo 与 pāo 声母不同（不送气的 b 与送气的 p），意思是包。"}, {"text": "袍", "is_correct": false, "explanation": "páo（第二声）与 pāo（第一声）声调不同，意思是长袍。"}], "explanations": {"抛": "正确。抛 pāo 指用力把东西向空中或远处扔出去。", "跑": "pǎo（第三声）与 pāo（第一声）声调不同，意思是跑步。", "包": "bāo 与 pāo 声母不同（不送气的 b 与送气的 p），意思是包。", "袍": "páo（第二声）与 pāo（第一声）声调不同，意思是长袍。"}, "sentence_index": null, "correct_answer": "抛"}, "level_3": {"options": [{"text": "抛", "is_correct": true, "explanation": "正确。“用力抛球”指用力把球扔出去，与“用力”的动作相符。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象应是液体，球不能喝。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服、鞋袜，不能和“球”搭配。"}, {"text": "合", "is_correct": false, "explanation": "搭配：“合”多用于书本、眼睛等，“用力合球”说不通。"}], "explanations": {"抛": "正确。“用力抛球”指用力把球扔出去，与“用力”的动作相符。", "喝": "语义：“喝”的对象应是液体，球不能喝。", "穿": "搭配：“穿”用于衣服、鞋袜，不能和“球”搭配。", "合": "搭配：“合”多用于书本、眼睛等，“用力合球”说不通。"}, "sentence_index": 0, "correct_answer": "抛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在选举中抛了一票。", "explanation": "这里应该用〈投〉。“投票”要用“投”，“抛”指用力扔出，不能用于投票。"}, {"text": "他一拳抛在墙上。", "explanation": "这里应该用〈打〉。“一拳”打在墙上是击打，“抛”是扔出去，不能这样用。"}, {"text": "他抛了一下肩膀，走出了房间。", "explanation": "这里应该用〈耸〉。“耸肩”指肩膀向上抬起，“抛”是把东西扔出去，不能用于肩膀的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90680, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "抛", "is_correct": true, "explanation": "正确。抛 pāo 指用力把东西向空中或远处扔出去。"}, {"text": "炮", "is_correct": false, "explanation": "pào（第四声）与 pāo（第一声）声调不同，意思是炮。"}, {"text": "刨", "is_correct": false, "explanation": "páo（第二声）与 pāo（第一声）声调不同，意思是刨子、刨。"}, {"text": "剥", "is_correct": false, "explanation": "bāo 与 pāo 声母不同（不送气的 b 与送气的 p），意思是剥。"}, {"text": "拍", "is_correct": false, "explanation": "pāi 与 pāo 韵母不同（ai 与 ao），意思是拍。"}], "explanations": {"抛": "正确。抛 pāo 指用力把东西向空中或远处扔出去。", "炮": "pào（第四声）与 pāo（第一声）声调不同，意思是炮。", "刨": "páo（第二声）与 pāo（第一声）声调不同，意思是刨子、刨。", "剥": "bāo 与 pāo 声母不同（不送气的 b 与送气的 p），意思是剥。", "拍": "pāi 与 pāo 韵母不同（ai 与 ao），意思是拍。"}, "sentence_index": null, "correct_answer": "抛"}, "level_3": {"options": [{"text": "抛", "is_correct": true, "explanation": "正确。“把帽子抛向天空”指把帽子用力扔向空中，与语境相符。"}, {"text": "挂", "is_correct": false, "explanation": "语义：“挂”是悬挂，帽子不会被挂向天空，与“向天空”的动作不符。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”是戴在头上，不能说“戴向天空”，与“把帽子”搭配不当。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要接受者，“把帽子送向天空”缺少接受者，说不通。"}], "explanations": {"抛": "正确。“把帽子抛向天空”指把帽子用力扔向空中，与语境相符。", "挂": "语义：“挂”是悬挂，帽子不会被挂向天空，与“向天空”的动作不符。", "戴": "搭配：“戴”是戴在头上，不能说“戴向天空”，与“把帽子”搭配不当。", "送": "配价：“送”需要接受者，“把帽子送向天空”缺少接受者，说不通。"}, "sentence_index": 6, "correct_answer": "抛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天抛了一场感冒。", "explanation": "这里应该用〈得〉。“抛”是用力扔出的动作，感冒是疾病，不能被抛，应说“得了感冒”。"}, {"text": "他抛了一首歌给大家听。", "explanation": "这里应该用〈唱〉。“抛”是用力扔出，歌曲不能被扔，应说“唱一首歌给大家听”。"}, {"text": "这辆车抛得很快。", "explanation": "这里应该用〈开〉。“抛”是用力扔出的动作，不能用来形容车的行驶，应说“车开得很快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你抛了过石头吗？", "corrected_sentence": "你抛过石头吗？", "error_description": "错误：“抛了过”。正确：“抛过”。表示经历过某事只用“过”，“了”和“过”不能同时用在动词后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹抛了着彩球玩儿。", "corrected_sentence": "妹妹抛着彩球玩儿。", "error_description": "错误：“抛了着”。正确：“抛着”。“着”表示动作正在进行或状态持续，不能和“了”同时用在动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90681, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忘记", "is_correct": true, "explanation": "正确。回忆是想起过去的事，忘记是想不起来，两者意思相反。"}, {"text": "出发", "is_correct": false, "explanation": "与回忆无反义关系：出发表示离开某地去别处，与想起过去无关。"}, {"text": "唱歌", "is_correct": false, "explanation": "与回忆无反义关系：唱歌是一种行为，与想起或忘记过去的事无关。"}, {"text": "散步", "is_correct": false, "explanation": "与回忆无反义关系：散步指悠闲地走路，与记忆没有相对关系。"}], "correct_answer": "忘记", "explanations": {"忘记": "正确。回忆是想起过去的事，忘记是想不起来，两者意思相反。", "出发": "与回忆无反义关系：出发表示离开某地去别处，与想起过去无关。", "唱歌": "与回忆无反义关系：唱歌是一种行为，与想起或忘记过去的事无关。", "散步": "与回忆无反义关系：散步指悠闲地走路，与记忆没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90681, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忘记", "is_correct": true, "explanation": "正确。回忆是想起过去的事，忘记是想不起来，两者意思相反。"}, {"text": "写信", "is_correct": false, "explanation": "与回忆无反义关系：写信是一种书面交流的行为，与记忆无关。"}, {"text": "跑步", "is_correct": false, "explanation": "与回忆无反义关系：跑步是一种身体活动，与想起或忘记过去无关。"}, {"text": "种树", "is_correct": false, "explanation": "与回忆无反义关系：种树是一种劳动，与记忆没有相对关系。"}], "correct_answer": "忘记", "explanations": {"忘记": "正确。回忆是想起过去的事，忘记是想不起来，两者意思相反。", "写信": "与回忆无反义关系：写信是一种书面交流的行为，与记忆无关。", "跑步": "与回忆无反义关系：跑步是一种身体活动，与想起或忘记过去无关。", "种树": "与回忆无反义关系：种树是一种劳动，与记忆没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90681, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回忆是想起以前发生过的事。", "primary_collocate": null, "pronunciation": "huí yì", "ipa": "xweɪ˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "老人坐在椅子上，回忆着年轻时的生活。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我常常回忆小时候和奶奶在一起的日子。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他回忆了很久，还是想不起那个人的名字。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你回忆一下，昨天晚上你在哪里。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到旧照片，我开始回忆大学时代。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她回忆起那次旅行，笑了。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察让他回忆当时看到的情况。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起回忆了毕业那天的事。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他闭上眼睛，努力回忆那首歌的歌词。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢回忆打工的那几年。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回忆了", "label": "体标"}, {"form": "回忆着", "label": "体标"}, {"form": "回忆过", "label": "体标"}, {"form": "回忆录", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，想起过去发生过的具体事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b68f76f-19ce-4182-879c-f07998280520') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90681, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回忆", "is_correct": true, "explanation": "正确。回忆表示想起过去的事，与“年轻时的生活”相合。"}, {"text": "盼望", "is_correct": false, "explanation": "语义：盼望指向未来，与“年轻时的生活”这种过去的事不合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃生活”不成立，“吃”不能与“生活”这样的宾语搭配。"}, {"text": "规划", "is_correct": false, "explanation": "语义：规划指对未来的安排，与“年轻时的生活”这一过去的时间不合。"}], "explanations": {"回忆": "正确。回忆表示想起过去的事，与“年轻时的生活”相合。", "盼望": "语义：盼望指向未来，与“年轻时的生活”这种过去的事不合。", "吃": "搭配：“吃生活”不成立，“吃”不能与“生活”这样的宾语搭配。", "规划": "语义：规划指对未来的安排，与“年轻时的生活”这一过去的时间不合。"}, "sentence_index": 0, "correct_answer": "回忆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每晚回忆明天的课文。", "explanation": "这里应该用〈预习〉。回忆指想起以前发生过的事，不能用于明天的课文。"}, {"text": "我们在回忆明年的旅行。", "explanation": "这里应该用〈计划〉。回忆指想起过去的事，明年的旅行还没有发生，要说“计划”。"}, {"text": "气象台回忆下个月会降温。", "explanation": "这里应该用〈预测〉。回忆只用于过去的事，下个月的天气只能说“预测”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90681, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回忆", "is_correct": true, "explanation": "正确。警察让他说出当时看到的情况，这需要想起以前看到的事，所以用回忆。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮情况”不成立，“煮”的对象是食物，不能是情况。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：“删除情况”不成立，“删除”一般用于文件或信息，不说删除情况。"}, {"text": "下载", "is_correct": false, "explanation": "搭配：“下载”的对象是文件或软件，不说“下载情况”。"}], "explanations": {"回忆": "正确。警察让他说出当时看到的情况，这需要想起以前看到的事，所以用回忆。", "煮": "搭配：“煮情况”不成立，“煮”的对象是食物，不能是情况。", "删除": "搭配：“删除情况”不成立，“删除”一般用于文件或信息，不说删除情况。", "下载": "搭配：“下载”的对象是文件或软件，不说“下载情况”。"}, "sentence_index": 6, "correct_answer": "回忆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他正在回忆眼前的电视。", "explanation": "这里应该用〈看〉。回忆指想起过去的事，眼前正在看到的东西要用“看”。"}, {"text": "医生正在回忆病人的脸色。", "explanation": "这里应该用〈观察〉。回忆只用于想起过去的事，正在发生的情况要用“观察”。"}, {"text": "她正在回忆眼前的大海。", "explanation": "这里应该用〈注视〉。回忆不能用于眼前的景物，注视大海要用“注视”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90681, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她偶尔回忆一起童年的小镇。", "corrected_sentence": "她偶尔回忆一下童年的小镇。", "error_description": "错误：「一起」是副词，不能放在「回忆」之后作动量补语；此处应为「一下」，写作「回忆一下童年的小镇」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90681, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老兵们回忆很清楚。", "corrected_sentence": "老兵们回忆得很清楚。", "error_description": "漏掉了补语标记“得”。“回忆得很清楚”中的“得”引出补语，不能省略，“回忆很清楚”错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90682, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忘记", "is_correct": true, "explanation": "正确。回忆是想起过去的事，忘记是想不起来，两者意思相反。"}, {"text": "游泳", "is_correct": false, "explanation": "与回忆无反义关系：游泳是一种运动，与想起或忘记过去无关。"}, {"text": "建造", "is_correct": false, "explanation": "与回忆无反义关系：建造指修建东西，与记忆没有相对关系。"}, {"text": "煮饭", "is_correct": false, "explanation": "与回忆无反义关系：煮饭是一种日常劳动，与记忆无关。"}], "correct_answer": "忘记", "explanations": {"忘记": "正确。回忆是想起过去的事，忘记是想不起来，两者意思相反。", "游泳": "与回忆无反义关系：游泳是一种运动，与想起或忘记过去无关。", "建造": "与回忆无反义关系：建造指修建东西，与记忆没有相对关系。", "煮饭": "与回忆无反义关系：煮饭是一种日常劳动，与记忆无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90682, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忘记", "is_correct": true, "explanation": "正确。回忆是想起过去的事，忘记是想不起来，两者意思相反。"}, {"text": "打开", "is_correct": false, "explanation": "与回忆无反义关系：打开是动作，与想起或忘记过去的事无关。"}, {"text": "种植", "is_correct": false, "explanation": "与回忆无反义关系：种植是一种农事活动，与记忆没有相对关系。"}, {"text": "比赛", "is_correct": false, "explanation": "与回忆无反义关系：比赛是竞技活动，与想起或忘记过去无关。"}], "correct_answer": "忘记", "explanations": {"忘记": "正确。回忆是想起过去的事，忘记是想不起来，两者意思相反。", "打开": "与回忆无反义关系：打开是动作，与想起或忘记过去的事无关。", "种植": "与回忆无反义关系：种植是一种农事活动，与记忆没有相对关系。", "比赛": "与回忆无反义关系：比赛是竞技活动，与想起或忘记过去无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90682, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想起过去的事情。", "primary_collocate": null, "pronunciation": "huí yì", "ipa": "xweɪ˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "每次回到老家，我都会回忆过去。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人坐着，回忆着和朋友一起玩的日子。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈回忆起我第一次上学的样子。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们回忆一下上个星期学的课文。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢回忆，也喜欢写下来。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他回忆着当兵的那几年，心里很难受。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨的晚上，我常常回忆那段旧时光。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "让我回忆一下，钥匙放在哪儿了。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这首老歌，我又回忆起那个夏天。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在咖啡馆里回忆学生时代的故事。", "target_word": "回忆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回忆了", "label": "体标"}, {"form": "回忆着", "label": "体标"}, {"form": "回忆过", "label": "体标"}, {"form": "回忆录", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，回想过去的经历或往事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b68f76f-19ce-4182-879c-f07998280520') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90682, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回忆", "is_correct": true, "explanation": "正确。回家后想起过去，与“回忆过去”搭配一致。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫过去”不成立，“过去”不能作为打扫的对象。"}, {"text": "设计", "is_correct": false, "explanation": "语义：设计指对未来的规划，与“过去”的时间方向相反。"}, {"text": "挖", "is_correct": false, "explanation": "搭配：“挖过去”不成立，“挖”是具体的动作，不能挖掉时间。"}], "explanations": {"回忆": "正确。回家后想起过去，与“回忆过去”搭配一致。", "打扫": "搭配：“打扫过去”不成立，“过去”不能作为打扫的对象。", "设计": "语义：设计指对未来的规划，与“过去”的时间方向相反。", "挖": "搭配：“挖过去”不成立，“挖”是具体的动作，不能挖掉时间。"}, "sentence_index": 0, "correct_answer": "回忆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天回忆十年后的家。", "explanation": "这里应该用〈设想〉。回忆指想起过去的事，十年后的家还没有发生，只能说“设想”。"}, {"text": "经济学家回忆明年会增长。", "explanation": "这里应该用〈预测〉。回忆只用于过去的事，明年的经济增长要说“预测”。"}, {"text": "我正在回忆眼前的书架。", "explanation": "这里应该用〈看〉。回忆指想起过去的事，眼前的书架要用“看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回忆", "is_correct": true, "explanation": "正确。下雨的晚上怀念旧时光，这需要想起过去，所以用回忆。"}, {"text": "收拾", "is_correct": false, "explanation": "搭配：“收拾”的对象是东西或房间，不说收拾时光。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：抛弃是舍弃，与“常常”在雨夜怀念旧时光的语境不合。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是具体物体，不说擦时光。"}], "explanations": {"回忆": "正确。下雨的晚上怀念旧时光，这需要想起过去，所以用回忆。", "收拾": "搭配：“收拾”的对象是东西或房间，不说收拾时光。", "抛弃": "语义：抛弃是舍弃，与“常常”在雨夜怀念旧时光的语境不合。", "擦": "搭配：“擦”的对象是具体物体，不说擦时光。"}, "sentence_index": 6, "correct_answer": "回忆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他回忆了一杯牛奶，很开心。", "explanation": "这里应该用〈喝〉。回忆的对象是过去的事，不能回忆一杯牛奶这样的具体东西。"}, {"text": "他正在回忆下周要交的作业。", "explanation": "这里应该用〈准备〉。回忆指想起过去的事，下周要交的作业还没有发生，只能说“准备”。"}, {"text": "她正在回忆眼前的大海。", "explanation": "这里应该用〈注视〉。回忆用于想起过去的事，眼前的大海要用“注视”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈回忆一起我小时候的样子。", "corrected_sentence": "妈妈回忆一下我小时候的样子。", "error_description": "错误：「一起」是副词，不能放在「回忆」之后作动量补语；此处应为「一下」，写作「回忆一下我小时候的样子」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们回忆一起那次旅行吧。", "corrected_sentence": "我们回忆一下那次旅行吧。", "error_description": "错误：「一起」误用于「回忆」之后，应为动量补语「一下」，写作「回忆一下那次旅行吧」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
