INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90683, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "住在你家旁边的人。", "primary_collocate": null, "pronunciation": "lín jū", "ipa": "lin˧˥ tɕy˥˥", "syllable_count": 2, "sentences": [{"text": "我的邻居很好。", "target_word": "邻居", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他是我家的邻居。", "target_word": "邻居", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新邻居昨天搬来了。", "target_word": "邻居", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻居们常常一起聊天。", "target_word": "邻居", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我和邻居打过招呼。", "target_word": "邻居", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居家的小狗很可爱。", "target_word": "邻居", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "邻居正在门口等着朋友。", "target_word": "邻居", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把钥匙给了邻居。", "target_word": "邻居", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们楼上的邻居晚上常常唱歌。", "target_word": "邻居", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我请邻居来我家吃饭。", "target_word": "邻居", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "老邻居", "label": "复合"}, {"form": "新邻居", "label": "复合"}], "register": "中性", "sense_fingerprint": "住在自己家旁边的那个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a22d3499-ca45-4e80-9518-98ccdc905de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90683, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "邻居", "is_correct": true, "explanation": "“邻居”指住在附近的人，可以说“我的邻居很好”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能说“我的天气”，与“我的___很好”搭配不当。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”不能被“我的”修饰，“我的空气很好”不成立。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不能用“我的……很好”评价，只在比喻中才这样说。"}], "explanations": {"邻居": "“邻居”指住在附近的人，可以说“我的邻居很好”。", "天气": "搭配：“天气”不能说“我的天气”，与“我的___很好”搭配不当。", "空气": "搭配：“空气”不能被“我的”修饰，“我的空气很好”不成立。", "太阳": "语义：太阳是天体，不能用“我的……很好”评价，只在比喻中才这样说。"}, "sentence_index": 0, "correct_answer": "邻居"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的邻居住在三百公里以外，我们每天都见面。", "explanation": "这里应该用〈朋友〉或〈远亲〉。“邻居”指住处相邻近的人，住在三百公里以外就不能称邻居。"}, {"text": "我们楼前的邻居是一本字典，每天放在桌上。", "explanation": "“邻居”指人或人家，字典不是住户，不能作“邻居”。"}, {"text": "我的邻居是一把雨伞，下雨时我就带着它。", "explanation": "“邻居”指人或人家，雨伞不是住户，不能作“邻居”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90683, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "邻居", "is_correct": true, "explanation": "“邻居”是人，可以“正在门口等着朋友”。"}, {"text": "邻国", "is_correct": false, "explanation": "语义：邻国是国家，不能站在门口等朋友。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是无生命的物体，不会等人。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会等人。"}], "explanations": {"邻居": "“邻居”是人，可以“正在门口等着朋友”。", "邻国": "语义：邻国是国家，不能站在门口等朋友。", "窗户": "语义：窗户是无生命的物体，不会等人。", "桌子": "语义：桌子是家具，不会等人。"}, "sentence_index": 6, "correct_answer": "邻居"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的邻居都住在外地。", "explanation": "这里应该用〈亲戚〉。“邻居”指住在附近的人，不能说住在外地。"}, {"text": "我和邻居住在同一间宿舍。", "explanation": "这里应该用〈室友〉。“邻居”指住处相邻近的人，不会住在同一间宿舍里。"}, {"text": "我的邻居在北京，我在上海，我们每天一起吃早饭。", "explanation": "这里应该用〈朋友〉。“邻居”指住处相邻近的人，两人分居北京和上海，不能说是邻居。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90683, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家对面来了一只新邻居。", "corrected_sentence": "我家对面来了一位新邻居。", "error_description": "量词错误：“邻居”指人，应用量词“位”；“只”多用于动物，不能用来数人。正确说法是“一位新邻居”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90683, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "楼下搬来了一头新邻居。", "corrected_sentence": "楼下搬来了一位新邻居。", "error_description": "量词错误：“邻居”指人，应用量词“位”；“头”用于牛、猪等动物，不能用来数人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
