INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90684, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "住处相邻近的人或人家。", "primary_collocate": null, "pronunciation": "lín jū", "ipa": "lin˧˥ tɕy˥˥", "syllable_count": 2, "sentences": [{"text": "这条街上的邻居都认识我。", "target_word": "邻居", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "左右邻居都很热情。", "target_word": "邻居", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "搬家以后，我们和邻居很少见面。", "target_word": "邻居", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "隔壁的邻居是一家四口。", "target_word": "邻居", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "村里的邻居常常互相帮助。", "target_word": "邻居", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对邻居总是很客气。", "target_word": "邻居", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "前后邻居都来参加了婚礼。", "target_word": "邻居", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的邻居有三户人家。", "target_word": "邻居", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个小区的邻居关系特别好。", "target_word": "邻居", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们两家做了十年邻居，从来没吵过架。", "target_word": "邻居", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "老邻居", "label": "复合"}, {"form": "新邻居", "label": "复合"}], "register": "中性", "sense_fingerprint": "住处靠近的人或人家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a22d3499-ca45-4e80-9518-98ccdc905de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90684, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "邻居", "is_correct": true, "explanation": "“邻居”指住处相近的人或人家，“都认识我”成立。"}, {"text": "街道", "is_correct": false, "explanation": "搭配：“这条街上的街道”语义重复，街道也不会“认识我”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是无生命的自然景物，不能认识人。"}, {"text": "路灯", "is_correct": false, "explanation": "语义：路灯是无生命的物件，不会认识人。"}], "explanations": {"邻居": "“邻居”指住处相近的人或人家，“都认识我”成立。", "街道": "搭配：“这条街上的街道”语义重复，街道也不会“认识我”。", "天空": "语义：天空是无生命的自然景物，不能认识人。", "路灯": "语义：路灯是无生命的物件，不会认识人。"}, "sentence_index": 0, "correct_answer": "邻居"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的邻居都住在外地，一年也见不到几次。", "explanation": "这里应该用〈远亲〉或〈朋友〉。“邻居”指住处相邻近的人，住在外地就不能称邻居。"}, {"text": "这栋楼的邻居是一台旧冰箱，每天嗡嗡响。", "explanation": "“邻居”指人或人家，冰箱不是住户，不能作“邻居”。"}, {"text": "我和邻居在同一间屋子里住了十年。", "explanation": "这里应该用〈室友〉。“邻居”指住处相邻近的人，不会住在同一间屋子里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90684, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "邻居", "is_correct": true, "explanation": "“邻居”是有生命的人，可以“都来参加了婚礼”。"}, {"text": "树", "is_correct": false, "explanation": "语义：树是植物，不能参加婚礼。"}, {"text": "香蕉", "is_correct": false, "explanation": "语义：香蕉是水果，不会参加婚礼。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会参加婚礼。"}], "explanations": {"邻居": "“邻居”是有生命的人，可以“都来参加了婚礼”。", "树": "语义：树是植物，不能参加婚礼。", "香蕉": "语义：香蕉是水果，不会参加婚礼。", "桌子": "语义：桌子是家具，不会参加婚礼。"}, "sentence_index": 6, "correct_answer": "邻居"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的邻居住在两千公里以外，我们从来不见面。", "explanation": "这里应该用〈远亲〉或〈朋友〉。“邻居”指住处相邻近的人，不能用来形容相隔两千公里的人。"}, {"text": "我们家的邻居是一棵大树，夏天给我们遮阴。", "explanation": "“邻居”指人或人家，大树不是住户，不能作“邻居”。"}, {"text": "我们两家做了十年邻居，却住在两个不同的城市。", "explanation": "这里应该用〈朋友〉。“邻居”指住处相邻近的人，两家分居两城就不算邻居。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "隔壁来了一只新邻居。", "corrected_sentence": "隔壁来了一位新邻居。", "error_description": "量词错误：“邻居”指人，应用量词“位”，“只”多用于动物，不能用来数人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家昨天搬来了一条新邻居。", "corrected_sentence": "我家昨天搬来了一位新邻居。", "error_description": "量词错误：“邻居”指人，应用量词“位”，“条”多用于细长的物件，不能用来数人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ae80165-e6c4-48ac-aec3-363cad9d4684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
