INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90685, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "换成是把一个东西变成另一个。", "primary_collocate": null, "pronunciation": "huàn chéng", "ipa": "xwan˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我想把红色的灯换成白色的。", "target_word": "换成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子太旧了，我要换成新的。", "target_word": "换成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把旧手机换成了新手机。", "target_word": "换成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这张桌子换成大一点的。", "target_word": "换成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天冷了，妈妈把窗帘换成了厚的。", "target_word": "换成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院把旧床换成了新床。", "target_word": "换成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裤子太长，你能换成短的吗？", "target_word": "换成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不喜欢黑色的包，就换成了红色的。", "target_word": "换成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菜单上的米饭，可以换成面条吗？", "target_word": "换成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明把坏了的灯泡换成了新的。", "target_word": "换成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "换成了", "label": "体标"}, {"form": "换成过", "label": "体标"}, {"form": "換成", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把一件东西拿走，用另一件东西代替它", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f4a601-3387-46d6-8878-d4f1e5cccdbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90685, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "换成", "is_correct": true, "explanation": "换成：用白色的灯代替红色的灯，符合“把红色的灯……白色的”的替换语境。"}, {"text": "翻译成", "is_correct": false, "explanation": "语义：翻译指转换语言，灯的颜色变化不是翻译。"}, {"text": "写成", "is_correct": false, "explanation": "语义：写成指写下来或写成文字，灯不能被写成白色。"}, {"text": "摆成", "is_correct": false, "explanation": "搭配：摆成后面接的是形状或图案，不能说摆成白色的。"}], "explanations": {"换成": "换成：用白色的灯代替红色的灯，符合“把红色的灯……白色的”的替换语境。", "翻译成": "语义：翻译指转换语言，灯的颜色变化不是翻译。", "写成": "语义：写成指写下来或写成文字，灯不能被写成白色。", "摆成": "搭配：摆成后面接的是形状或图案，不能说摆成白色的。"}, "sentence_index": 0, "correct_answer": "换成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一听到这话，脸就换成了红色。", "explanation": "这里应该用〈红了〉。换成指用另一样东西替代原来的，脸色变红是身体自身的变化，不能用换成。"}, {"text": "大家把他换成了英雄。", "explanation": "这里应该用〈当成〉。换成指用另一样东西替代原来的，不能表示把某人看作某种身份，这种意思要说当成。"}, {"text": "冰遇热换成了水。", "explanation": "这里应该用〈融化〉。冰遇热变为水是物质自身的变化，换成表示用另一样东西替代，不能描写这种变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90685, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "换成", "is_correct": true, "explanation": "换成：用短的裤子代替这条太长的，符合“太长”之后要换短的语境。"}, {"text": "加长", "is_correct": false, "explanation": "语义：加长是变得更长，与前句“太长”的要求相反。"}, {"text": "延长", "is_correct": false, "explanation": "语义：延长是拉长时间或距离，与“太长”的要求相矛盾。"}, {"text": "增长", "is_correct": false, "explanation": "搭配：增长多用于数量、知识或时间，不能说裤子增长。"}], "explanations": {"换成": "换成：用短的裤子代替这条太长的，符合“太长”之后要换短的语境。", "加长": "语义：加长是变得更长，与前句“太长”的要求相反。", "延长": "语义：延长是拉长时间或距离，与“太长”的要求相矛盾。", "增长": "搭配：增长多用于数量、知识或时间，不能说裤子增长。"}, "sentence_index": 6, "correct_answer": "换成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在剧里把自己换成了医生。", "explanation": "这里应该用〈扮演〉。换成指把一样东西替换为另一样，演员表演角色要用扮演。"}, {"text": "水通电后换成了氢气和氧气。", "explanation": "这里应该用〈分解成〉。水通电后分解为两种气体是物质自身的变化，换成表示用另一样东西替代，不能用来描写这种变化。"}, {"text": "我和同桌换成了书包。", "explanation": "这里应该用〈交换〉。两人互相调换东西是交换，不是把一件东西替代为另一件，换成在这里不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90685, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把旧沙发换成了的新。", "corrected_sentence": "我把旧沙发换成了新的。", "error_description": "“的新”的语序错误。应写作新的，的必须放在新之后；的新不成词，整句应为“我把旧沙发换成了新的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90685, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把把旧车换成了电动车。", "corrected_sentence": "他把旧车换成了电动车。", "error_description": "把字重复。一个把字句只用一个把，多出的把应删去，写作他把旧车换成了电动车。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
