INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90686, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把原来的变为另一种。", "primary_collocate": null, "pronunciation": "huàn chéng", "ipa": "xwan˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "请把美元换成人民币。", "target_word": "换成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把手机的语言换成中文。", "target_word": "换成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去银行把钱换成了日元。", "target_word": "换成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个句子太长，你换成短一点的说法吧。", "target_word": "换成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上看书，请把屏幕换成夜间模式。", "target_word": "换成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想喝咖啡，请换成茶吧。", "target_word": "换成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太烫了，请把热水换成温水。", "target_word": "换成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店只收现金，我只好把卡里的钱换成现金。", "target_word": "换成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店原来卖面包，后来换成了咖啡。", "target_word": "换成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件默认是英文，我把它换成了中文。", "target_word": "换成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "换成了", "label": "体标"}, {"form": "换成过", "label": "体标"}, {"form": "換成", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把原来的种类、方式或设置改成另一种", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f4a601-3387-46d6-8878-d4f1e5cccdbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90686, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "换成", "is_correct": true, "explanation": "换成：把美元转为人民币，表示货币种类的改换，符合句意。"}, {"text": "写成", "is_correct": false, "explanation": "语义：写成指把内容写下来，美元不能被写成人民币。"}, {"text": "翻译成", "is_correct": false, "explanation": "语义：翻译指转换语言，货币之间的转换不是翻译。"}, {"text": "拆成", "is_correct": false, "explanation": "搭配：拆成指把整体分开成部分，不能拆成另一种货币。"}], "explanations": {"换成": "换成：把美元转为人民币，表示货币种类的改换，符合句意。", "写成": "语义：写成指把内容写下来，美元不能被写成人民币。", "翻译成": "语义：翻译指转换语言，货币之间的转换不是翻译。", "拆成": "搭配：拆成指把整体分开成部分，不能拆成另一种货币。"}, "sentence_index": 0, "correct_answer": "换成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水烧开后，它换成了蒸汽。", "explanation": "这里应该用〈变成〉。水受热变为蒸汽是事物自身的变化，换成表示把原来的东西改为另一种，不能描写这种变化。"}, {"text": "冬天到了，湖水换成了冰。", "explanation": "这里应该用〈冻成〉。湖水遇冷凝结成冰是事物自身的变化，换成表示用另一样东西替代，不能描写这种变化。"}, {"text": "他长大以后，声音换成了沙哑的。", "explanation": "这里应该用〈变成〉。换成指用另一样东西替代原来的，声音随年龄变化是事物自身的变化，不能用换成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90686, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "换成", "is_correct": true, "explanation": "换成：把热水替换为温水，符合“太烫了”之后要降温的语境。"}, {"text": "加热", "is_correct": false, "explanation": "语义：加热是让水变热，与“太烫了”的要求矛盾。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是加热到沸腾，只会更烫，不能煮成温水。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：烧成后面接的是灰、瓷器等，不能说烧成温水。"}], "explanations": {"换成": "换成：把热水替换为温水，符合“太烫了”之后要降温的语境。", "加热": "语义：加热是让水变热，与“太烫了”的要求矛盾。", "煮": "语义：煮是加热到沸腾，只会更烫，不能煮成温水。", "烧": "搭配：烧成后面接的是灰、瓷器等，不能说烧成温水。"}, "sentence_index": 6, "correct_answer": "换成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在剧里把自己换成了警察。", "explanation": "这里应该用〈扮演〉。换成指把一样东西替换为另一样，演员表演角色要用扮演。"}, {"text": "水通电后换成了氢气和氧气。", "explanation": "这里应该用〈分解成〉。水通电后分解为两种气体是物质自身的变化，换成表示用另一样东西替代，不能用来描写这种变化。"}, {"text": "我和同桌换成了书包。", "explanation": "这里应该用〈交换〉。两人互相调换东西是交换，不是把一件东西替代为另一件，换成在这里不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请把电脑的语言换成了英文。", "corrected_sentence": "请把电脑的语言换成英文。", "error_description": "了的用法错误。请开头的祈使句表示命令，不能在换成之后加表示完成的了，应去掉了，写作请把电脑的语言换成英文。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他还没把钱换成了美元。", "corrected_sentence": "他还没把钱换成美元。", "error_description": "了的用法错误。用“没”否定的句子表示动作还没完成，换成后面不能再加表示完成的了，应写作他还没把钱换成美元。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
