INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90687, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "在此是在这个地方，或者在这个时候。", "primary_collocate": null, "pronunciation": "zài cǐ", "ipa": "tsai˥˩ tsʰɿ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们在此等你。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家在此休息一下。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在此，我要谢谢大家。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在此停车。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在此住了三年。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在此等着大家。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议在此结束，谢谢大家。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天能在此见面，我很高兴。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾经在此学习过。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在此之前，我从没来过这里。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "在此：在这个地方，或在这个时候（书面）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '334d3bb3-d40f-4673-8ec2-5f77f12859af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90687, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在此", "is_correct": true, "explanation": "正确：“我们在此等你”中的“在此”，表示在这个地方。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然，与“等你”这种持续的等待不合。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，与“等你”这种持续的等待不合。"}, {"text": "格外", "is_correct": false, "explanation": "搭配：“格外”表示特别、分外，不用来修饰“等”这种动作。"}], "explanations": {"在此": "正确：“我们在此等你”中的“在此”，表示在这个地方。", "忽然": "语义：“忽然”表示突然，与“等你”这种持续的等待不合。", "立刻": "语义：“立刻”表示马上，与“等你”这种持续的等待不合。", "格外": "搭配：“格外”表示特别、分外，不用来修饰“等”这种动作。"}, "sentence_index": 0, "correct_answer": "在此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书在此好看。", "explanation": "这里应该用〈非常〉。“在此”表示在这个地方或这个时候，不能用来修饰形容词、表示程度。"}, {"text": "我们明天在此北京见面。", "explanation": "这里应该用〈在〉。句中已经有地点“北京”，“在此”本身就指这个地方，不能再接地点名词。"}, {"text": "我明天要在此去上海。", "explanation": "这里应该用〈从这里〉。“在此”表示位置，不能表示出发的地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90687, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在此", "is_correct": true, "explanation": "正确：“会议在此结束”中的“在此”，表示在这个地方或这个时候。"}, {"text": "反复", "is_correct": false, "explanation": "语义：“反复”表示多次重复，与一次性的“结束”不合。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时，与会议的结束这一事件不合。"}, {"text": "格外", "is_correct": false, "explanation": "搭配：“格外”修饰程度，不用来修饰“结束”这种动作。"}], "explanations": {"在此": "正确：“会议在此结束”中的“在此”，表示在这个地方或这个时候。", "反复": "语义：“反复”表示多次重复，与一次性的“结束”不合。", "偶尔": "语义：“偶尔”表示有时，与会议的结束这一事件不合。", "格外": "搭配：“格外”修饰程度，不用来修饰“结束”这种动作。"}, "sentence_index": 6, "correct_answer": "在此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜在此好吃。", "explanation": "这里应该用〈特别〉。“在此”表示在这个地方或这个时候，不能修饰形容词表示程度。"}, {"text": "下个月我们在此上海开会。", "explanation": "这里应该用〈在〉。“在此”已经指这个地方，后面不能再加“上海”这样的地点名词。"}, {"text": "我们在此去上海玩吧。", "explanation": "这里应该用〈从这里〉。“在此”表示位置，不能表示出发的地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90687, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请大家在此这里签名。", "corrected_sentence": "请大家在此签名。", "error_description": "“在此”已表示地点，后面不能再加“这里”，应说“在此签名”，错误是多出了“这里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90687, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在在此工作了三年。", "corrected_sentence": "他在此工作了三年。", "error_description": "“在”和“此”合成一个词“在此”，不能重复“在”，应说“在此工作”，错误是多出了一个“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90689, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
