INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90689, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "击中是打到了，正好碰到目标。", "primary_collocate": null, "pronunciation": "jī zhòng", "ipa": "tɕi˥ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "雪球正好击中了他的帽子。", "target_word": "击中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用弓射箭，第一箭就击中了。", "target_word": "击中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那颗球击中了门柱，没有进去。", "target_word": "击中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子扔出的纸飞机击中了老师。", "target_word": "击中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "子弹击中了树，树叶掉了下来。", "target_word": "击中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他瞄准了很久，终于击中了靶子。", "target_word": "击中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "足球击中了他的脸，他疼得叫了起来。", "target_word": "击中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老鹰飞得很快，小石头没有击中它。", "target_word": "击中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弹弓里的石子击中了树上的苹果。", "target_word": "击中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他投出的飞镖击中了红色的圆圈。", "target_word": "击中", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "击中了", "label": "体标"}, {"form": "击中过", "label": "体标"}], "register": "中性", "sense_fingerprint": "击中：打到了，正好碰到目标", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52af20df-6e56-40f6-a8c1-0c1dd987e45e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90689, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "戴上", "is_correct": false, "explanation": "搭配：“戴上”的主语要是能戴东西的人，雪球不会戴帽子。"}, {"text": "击中", "is_correct": true, "explanation": "击中：打到了，正好碰到目标，与“雪球”和“帽子”的语境相符。"}, {"text": "摘下", "is_correct": false, "explanation": "语义：摘下表示取下，与雪球打到帽子的动作不符。"}, {"text": "放下", "is_correct": false, "explanation": "语义：放下表示搁置，与雪球打中帽子的情境矛盾。"}], "explanations": {"戴上": "搭配：“戴上”的主语要是能戴东西的人，雪球不会戴帽子。", "击中": "击中：打到了，正好碰到目标，与“雪球”和“帽子”的语境相符。", "摘下": "语义：摘下表示取下，与雪球打到帽子的动作不符。", "放下": "语义：放下表示搁置，与雪球打中帽子的情境矛盾。"}, "sentence_index": 0, "correct_answer": "击中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一根火柴击中了纸堆，火很快烧了起来。", "explanation": "这里应该用〈点燃〉。火柴是把纸堆点燃，不是击中；击中指打到目标。"}, {"text": "他们的队伍击中了对手，取得了胜利。", "explanation": "这里应该用〈击败〉。击中指打到目标，战胜对手要用击败。"}, {"text": "一辆自行车击中了路边的树。", "explanation": "这里应该用〈撞上〉。自行车撞到树口语中说撞上，击中不用于这种情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90689, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "躲开", "is_correct": false, "explanation": "语义：躲开表示避让，与“疼得叫了起来”的结果矛盾。"}, {"text": "远离", "is_correct": false, "explanation": "语义：远离表示离开，与足球打到脸并造成疼痛的情境矛盾。"}, {"text": "击中", "is_correct": true, "explanation": "击中：打到了，正好碰到目标，与“足球”和“脸”的语境相符。"}, {"text": "抱住", "is_correct": false, "explanation": "语义：抱住是用手臂环绕，足球不会抱住人的脸，与「疼得叫了起来」的语境不符。"}], "explanations": {"躲开": "语义：躲开表示避让，与“疼得叫了起来”的结果矛盾。", "远离": "语义：远离表示离开，与足球打到脸并造成疼痛的情境矛盾。", "击中": "击中：打到了，正好碰到目标，与“足球”和“脸”的语境相符。", "抱住": "语义：抱住是用手臂环绕，足球不会抱住人的脸，与「疼得叫了起来」的语境不符。"}, "sentence_index": 6, "correct_answer": "击中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他爬了很久的山，终于击中了山顶。", "explanation": "这里应该用〈到达〉。击中是打中目标，人爬到山顶要说到达，不说击中。"}, {"text": "小猫不小心击中了我的手。", "explanation": "这里应该用〈碰到〉。击中强调有力地打中目标，轻轻碰到只用碰到。"}, {"text": "他一把击中了哭泣的孩子。", "explanation": "这里应该用〈抱住〉。击中是有力地打到目标，拥抱哭泣的孩子要用抱住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90689, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那颗石子击中着小狗的背。", "corrected_sentence": "那颗石子击中了小狗的背。", "error_description": "体标错误：“击中”是瞬间完成的动作，表示完成要用“了”；“着”表示持续的状态，不能用在这里，应说“击中了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90689, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我曾经用飞镖击中着靶子。", "corrected_sentence": "我曾经用飞镖击中过靶子。", "error_description": "体标错误：表示曾经有过的经历要用“过”；“着”表示持续的状态，不能用在这里，应说“击中过靶子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be4d439-7253-48f0-82fd-9f3ad089c5aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
