INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90691, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "网站打开后，最先看到的那一页。", "primary_collocate": null, "pronunciation": "shǒu yè", "ipa": "ʂoʊ˨˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "你可以从首页进入各个栏目。", "target_word": "首页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站的首页很简单，一目了然。", "target_word": "首页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天早上，我先看新闻网站的首页。", "target_word": "首页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浏览器一打开，首页就出现了。", "target_word": "首页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首页上有搜索框，可以直接查资料。", "target_word": "首页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把我们的网站设为你的首页。", "target_word": "首页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站首页的广告太多，我不喜欢。", "target_word": "首页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找不到的资料，可以回到首页再搜索。", "target_word": "首页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司首页上写着电话和地址。", "target_word": "首页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新网站的首页明天上线。", "target_word": "首页", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "网站首页", "label": "复合"}], "register": "中性", "sense_fingerprint": "打开网站后最先出现的页面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b68f76f-19ce-4182-879c-f07998280520') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90691, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "首页", "is_correct": true, "explanation": "正确：首页是打开网站后最先看到的页面，可以从这里进入各个栏目，符合句意。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：「电梯」是升降设备，不是可以进入栏目的页面。"}, {"text": "课本", "is_correct": false, "explanation": "语义：「课本」是学习用的书，没有“栏目”，不能从它进入。"}, {"text": "书页", "is_correct": false, "explanation": "搭配：「进入」后接“栏目”“页面”等，“书页”不能与“进入各个栏目”搭配。"}], "explanations": {"首页": "正确：首页是打开网站后最先看到的页面，可以从这里进入各个栏目，符合句意。", "电梯": "语义：「电梯」是升降设备，不是可以进入栏目的页面。", "课本": "语义：「课本」是学习用的书，没有“栏目”，不能从它进入。", "书页": "搭配：「进入」后接“栏目”“页面”等，“书页”不能与“进入各个栏目”搭配。"}, "sentence_index": 0, "correct_answer": "首页"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "北京是中国的首页。", "explanation": "〈首都〉。首页在这里指网站打开后的页面，不指城市；国家的政治中心应说“首都”。"}, {"text": "下班后我一般回首页休息。", "explanation": "〈家〉。首页指网站的页面，不是居所，不能说“回首页休息”。"}, {"text": "我把首页吃了。", "explanation": "〈馒头〉。首页是网页，不能吃；能吃的应说“馒头”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90691, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "首页", "is_correct": true, "explanation": "正确：首页指网站打开后最先看到的页面，“广告太多”说的正是网站页面，符合句意。"}, {"text": "名片", "is_correct": false, "explanation": "语义：「名片」是印着姓名的小卡片，不是网站的页面。"}, {"text": "书包", "is_correct": false, "explanation": "语义：「书包」是装书本的袋子，不是网站的页面，“网站书包的广告太多”说不通。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：「网站」不与“地铁”组合，“网站地铁的广告”说不通。"}], "explanations": {"首页": "正确：首页指网站打开后最先看到的页面，“广告太多”说的正是网站页面，符合句意。", "名片": "语义：「名片」是印着姓名的小卡片，不是网站的页面。", "书包": "语义：「书包」是装书本的袋子，不是网站的页面，“网站书包的广告太多”说不通。", "地铁": "搭配：「网站」不与“地铁”组合，“网站地铁的广告”说不通。"}, "sentence_index": 6, "correct_answer": "首页"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "餐厅门口放着首页。", "explanation": "〈菜单〉。首页指网站打开后最先看到的页面，不指餐馆的菜单。"}, {"text": "请把首页写在信封上。", "explanation": "〈地址〉。首页是网页，不能写在信封上，写在信封上的应该是地址。"}, {"text": "我们坐首页去公园。", "explanation": "〈地铁〉。首页不是交通工具，不能用“坐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90691, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那家公司只有一条首页。", "corrected_sentence": "那家公司只有一个首页。", "error_description": "「首页」的量词要用「个」，「条」用于河流、消息等，不能用于网页。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90691, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你首页设成中文。", "corrected_sentence": "请你把首页设成中文。", "error_description": "「设成」的对象「首页」前要用「把」引出，缺了「把」就不成句；应说「请你把首页设成中文」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90693, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "窄", "is_correct": true, "explanation": "窄：与“宽”反义，指从一边到另一边的距离小。"}, {"text": "深", "is_correct": false, "explanation": "“深”说纵向的深浅，不与“宽”构成横向距离的反义。"}, {"text": "厚", "is_correct": false, "explanation": "“厚”说上下的厚薄，不与“宽”构成反义。"}, {"text": "高", "is_correct": false, "explanation": "“高”说纵向的高低，不与“宽”构成横向距离的反义。"}], "correct_answer": "窄", "explanations": {"窄": "窄：与“宽”反义，指从一边到另一边的距离小。", "深": "“深”说纵向的深浅，不与“宽”构成横向距离的反义。", "厚": "“厚”说上下的厚薄，不与“宽”构成反义。", "高": "“高”说纵向的高低，不与“宽”构成横向距离的反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90693, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "窄", "is_correct": true, "explanation": "窄：与“宽”反义，指从一边到另一边的距离小。"}, {"text": "浅", "is_correct": false, "explanation": "“浅”说深浅，不与“宽”构成横向距离的反义。"}, {"text": "薄", "is_correct": false, "explanation": "“薄”说厚薄，不与“宽”构成反义。"}, {"text": "短", "is_correct": false, "explanation": "“短”说长短，不与“宽”构成横向距离的反义。"}], "correct_answer": "窄", "explanations": {"窄": "窄：与“宽”反义，指从一边到另一边的距离小。", "浅": "“浅”说深浅，不与“宽”构成横向距离的反义。", "薄": "“薄”说厚薄，不与“宽”构成反义。", "短": "“短”说长短，不与“宽”构成横向距离的反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90693, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "宽是从这一边到那一边很远。路很宽，车就好走。", "primary_collocate": null, "pronunciation": "kuān", "ipa": "kʰuan˥", "syllable_count": 1, "sentences": [{"text": "这条路很宽。", "target_word": "宽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河面很宽，对岸看不清。", "target_word": "宽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "路很宽，两辆车可以一起走。", "target_word": "宽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张桌子太宽，放不进小房间。", "target_word": "宽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的肩膀很宽，背着大包也不累。", "target_word": "宽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门不够宽，大沙发搬不进来。", "target_word": "宽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条街比那条街宽多了。", "target_word": "宽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们走过了一条很宽的大街。", "target_word": "宽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的床有多宽？", "target_word": "宽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座桥又宽又平，车可以并排开。", "target_word": "宽", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "宽宽的", "label": "重叠"}, {"form": "宽大", "label": "复合"}, {"form": "宽度", "label": "复合"}, {"form": "寬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体或地方从一边到另一边的距离大，如路宽、河宽", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79e60a67-5d39-493a-b9c5-106ceed17226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90693, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宽", "is_correct": true, "explanation": "宽：从一边到另一边的距离大，用来形容路，句子通顺。"}, {"text": "深", "is_correct": false, "explanation": "语义：“深”说纵向的深浅，路面不说深，句子不通。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”说物体上下的厚度，不用于说路的横向距离。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”只用于人或动物的身形，不能用来形容路。"}], "explanations": {"宽": "宽：从一边到另一边的距离大，用来形容路，句子通顺。", "深": "语义：“深”说纵向的深浅，路面不说深，句子不通。", "厚": "语义：“厚”说物体上下的厚度，不用于说路的横向距离。", "胖": "体貌：“胖”只用于人或动物的身形，不能用来形容路。"}, "sentence_index": 0, "correct_answer": "宽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个假期很宽，我们可以去很多地方。", "explanation": "这里应该用〈长〉。宽说横向距离，时间的长短要用“长”。"}, {"text": "这杯咖啡很宽，小心别喝太快。", "explanation": "这里应该用〈烫〉。宽只用于物体或地方的横向距离，饮料的温度高要用“烫”。"}, {"text": "这件衣服的价格很宽。", "explanation": "这里应该用〈高〉。宽不用于价格，价格的高低要用“高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90693, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宽", "is_correct": true, "explanation": "宽：这里比较两条街的横向距离，填入后句子通顺。"}, {"text": "轻", "is_correct": false, "explanation": "语义：“轻”说重量，街道不用轻重来比较，句子不通。"}, {"text": "矮", "is_correct": false, "explanation": "语义：“矮”说高度，街道的横向距离不用“矮”来形容。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”只用于人或动物的身形，不能用来比较街道。"}], "explanations": {"宽": "宽：这里比较两条街的横向距离，填入后句子通顺。", "轻": "语义：“轻”说重量，街道不用轻重来比较，句子不通。", "矮": "语义：“矮”说高度，街道的横向距离不用“矮”来形容。", "瘦": "体貌：“瘦”只用于人或动物的身形，不能用来比较街道。"}, "sentence_index": 6, "correct_answer": "宽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的节奏很宽。", "explanation": "这里应该用〈慢〉。宽说横向距离，节奏的快慢要用“慢”或“快”。"}, {"text": "他的病情很宽。", "explanation": "这里应该用〈好〉。宽不用于病情，病情的好坏要用“好”。"}, {"text": "今天的天气很宽。", "explanation": "这里应该用〈热〉。宽不用于天气，天气的冷热要用“热”或“冷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90693, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这扇门宽很，大车能开进去。", "corrected_sentence": "这扇门很宽，大车能开进去。", "error_description": "语序错误：程度副词“很”要放在形容词前面，“宽很”错误，应为“很宽”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90693, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个广场很宽度，可以放很多桌子。", "corrected_sentence": "这个广场很宽，可以放很多桌子。", "error_description": "用词错误：“宽度”是名词，形容词“宽”后不能直接加“度”，这里应说“很宽”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
