INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90695, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改组是把一个团体里的人重新安排。", "primary_collocate": null, "pronunciation": "gǎi zǔ", "ipa": "kai̯˨˩˦ tsu˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司去年改组了销售部。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校决定改组学生会。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队换了教练后又改组了。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理想把这个小组改组一下。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的乐队改组过两次。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说下个月要改组团队。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个委员会已经改组了。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改组以后，大家的工作都变了。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了提高效率，公司改组了管理层。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家医院改组过自己的科室。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改组了", "label": "体标"}, {"form": "改组过", "label": "体标"}, {"form": "改組", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把团体、小组里的成员重新安排和组合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbaef05-ab62-4cb3-bccf-d75c1fe06dac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90695, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象应是食物，不能说“吃了销售部”。"}, {"text": "改组", "is_correct": true, "explanation": "“改组”指重新调整部门的人员和组合，与“销售部”搭配，符合句意。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”的宾语应是水平、效率等，不能说“提高销售部”。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象应是饮料，“销售部”不能被喝。"}], "explanations": {"吃": "语义：“吃”的对象应是食物，不能说“吃了销售部”。", "改组": "“改组”指重新调整部门的人员和组合，与“销售部”搭配，符合句意。", "提高": "搭配：“提高”的宾语应是水平、效率等，不能说“提高销售部”。", "喝": "语义：“喝”的对象应是饮料，“销售部”不能被喝。"}, "sentence_index": 0, "correct_answer": "改组"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "经理想改组这个小组的工作方式。", "explanation": "这里应该用〈改革〉。改组指调整团体的人员或机构，不能用于“工作方式”；改变做事方法要用“改革”。"}, {"text": "公司把这笔资金改组了。", "explanation": "这里应该用〈调配〉。改组针对团体或机构的成员，资金的调度要用“调配”。"}, {"text": "这次考试的时间要改组一下。", "explanation": "这里应该用〈调整〉。改组指重新组合团体或机构，不能用于“时间”；安排时间要用“调整”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90695, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”只用于人与人之间的婚姻，委员会不能结婚。"}, {"text": "下降", "is_correct": false, "explanation": "搭配：“下降”多指数量、价格减少，说委员会本身“下降了”不合适。"}, {"text": "改组", "is_correct": true, "explanation": "“改组”作不及物用法，指委员会自身重新调整组合，与“已经……了”的句意相符。"}, {"text": "怀孕", "is_correct": false, "explanation": "语义：“怀孕”只用于人或动物的身体状态，不能用于委员会。"}], "explanations": {"结婚": "语义：“结婚”只用于人与人之间的婚姻，委员会不能结婚。", "下降": "搭配：“下降”多指数量、价格减少，说委员会本身“下降了”不合适。", "改组": "“改组”作不及物用法，指委员会自身重新调整组合，与“已经……了”的句意相符。", "怀孕": "语义：“怀孕”只用于人或动物的身体状态，不能用于委员会。"}, "sentence_index": 6, "correct_answer": "改组"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家医院要改组服务态度。", "explanation": "这里应该用〈改善〉。改组用于团体或机构的人员调整，“服务态度”要用“改善”。"}, {"text": "市场需要改组一下秩序。", "explanation": "这里应该用〈整顿〉。改组不能用于“秩序”；整理混乱的秩序要用“整顿”。"}, {"text": "他改组了合同的条款。", "explanation": "这里应该用〈修改〉。改组针对团体或机构，合同的条款要用“修改”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90695, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上个月，他们改组着财务部。", "corrected_sentence": "上个月，他们改组了财务部。", "error_description": "错误：“改组着”。正确：“改组了”。“上个月”表示动作已经完成，应该用“了”，不能用表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90695, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那所学校去年改组两次。", "corrected_sentence": "那所学校去年改组了两次。", "error_description": "错误：表示已完成的动作，“改组”后漏掉“了”。正确：应说“去年改组了两次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
