INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90696, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "重新调整、组合机构或人员。", "primary_collocate": null, "pronunciation": "gǎi zǔ", "ipa": "kai̯˨˩˦ tsu˨˩˦", "syllable_count": 2, "sentences": [{"text": "政府改组了教育部门。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里的旅游局明年要改组。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司改组后，部门少了两个。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总经理把董事会改组了。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行改组过好几次。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在改组研究所。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新老板上任后马上改组了机构。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改组机构是为了减少浪费。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院改组了，护士也换了岗位。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家决定改组这个机构。", "target_word": "改组", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改组了", "label": "体标"}, {"form": "改组过", "label": "体标"}, {"form": "改組", "label": "繁体"}], "register": "书面", "sense_fingerprint": "对机构或人员配置进行重新调整和组合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbaef05-ab62-4cb3-bccf-d75c1fe06dac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90696, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "种植", "is_correct": false, "explanation": "语义：“种植”的对象是植物，“教育部门”不能被种植。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”的宾语应是水平、质量等，不能说“提高教育部门”。"}, {"text": "改组", "is_correct": true, "explanation": "“改组”指重新调整机构的组合，与“教育部门”搭配，符合句意。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”的对象应是人或动物，不能用于“教育部门”。"}], "explanations": {"种植": "语义：“种植”的对象是植物，“教育部门”不能被种植。", "提高": "搭配：“提高”的宾语应是水平、质量等，不能说“提高教育部门”。", "改组": "“改组”指重新调整机构的组合，与“教育部门”搭配，符合句意。", "喂": "语义：“喂”的对象应是人或动物，不能用于“教育部门”。"}, "sentence_index": 0, "correct_answer": "改组"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "总经理改组了董事会的纪律。", "explanation": "这里应该用〈整顿〉。改组针对团体的成员，不能用于“纪律”；整顿纪律要用“整顿”。"}, {"text": "公司改组了一名员工去外地。", "explanation": "这里应该用〈调动〉。改组针对团体或机构，单个员工的岗位变动要用“调动”。"}, {"text": "他改组了行程安排。", "explanation": "这里应该用〈调整〉。改组不能用于“行程安排”；安排的变化要用“调整”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90696, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开除", "is_correct": false, "explanation": "语义：“开除”针对人员，不能说“开除机构”。"}, {"text": "发放", "is_correct": false, "explanation": "搭配：“发放”的对象是工资、补贴等，不能说“发放机构”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，“机构”不能被吃。"}, {"text": "改组", "is_correct": true, "explanation": "“改组”指重新调整机构的人员和组合，与“新老板上任后”的句意相符。"}], "explanations": {"开除": "语义：“开除”针对人员，不能说“开除机构”。", "发放": "搭配：“发放”的对象是工资、补贴等，不能说“发放机构”。", "吃": "语义：“吃”的对象是食物，“机构”不能被吃。", "改组": "“改组”指重新调整机构的人员和组合，与“新老板上任后”的句意相符。"}, "sentence_index": 6, "correct_answer": "改组"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国家决定改组这个机构的服务。", "explanation": "这里应该用〈改善〉。改组是调整机构的人员或组织，不能用于“服务”；提升服务质量要用“改善”。"}, {"text": "国家改组了法律条款。", "explanation": "这里应该用〈修改〉。改组针对团体、机构，“法律条款”要用“修改”。"}, {"text": "国家需要改组这项法规。", "explanation": "这里应该用〈完善〉。改组用于团体或机构，法规的内容要用“完善”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90696, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个政府上个月改组着内阁。", "corrected_sentence": "这个政府上个月改组了内阁。", "error_description": "错误：“改组着”。正确：“改组了”。“上个月”表示动作已完成，应该用“了”，不能用表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90696, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司今年改组了过两次。", "corrected_sentence": "这家公司今年改组过两次。", "error_description": "错误：“改组了过”。正确：“改组过两次”。表示经历只用“过”，“了过”这样连用是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
