INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90697, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "非常聪明、本领很大的人。", "primary_collocate": null, "pronunciation": "gāo cái", "ipa": "kɑʊ˥ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "他是我们公司里有名的高才。", "target_word": "高才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位高才三十岁就当了教授。", "target_word": "高才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请来了一位高才给大家上课。", "target_word": "高才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班出了一位数学高才。", "target_word": "高才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说他是个高才。", "target_word": "高才", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司里有很多高才。", "target_word": "高才", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一位年轻的高才解决了这个难题。", "target_word": "高才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家需要更多的高才。", "target_word": "高才", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他真是个高才，什么问题都难不倒他。", "target_word": "高才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位高才在报纸上写了一篇文章。", "target_word": "高才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高才生", "label": "复合词"}], "register": "书面", "sense_fingerprint": "指聪明而本领大的人，可数，前面常有“一位”“个”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '741a067b-35ee-42ee-a9a5-e70920a0d4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90697, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大楼", "is_correct": false, "explanation": "语义：“他是”后面不能接建筑，大楼不指人。"}, {"text": "高才", "is_correct": true, "explanation": "高才：指聪明、本领大的人，与“他是我们公司里有名的”相符，是唯一能填入的词。"}, {"text": "产品", "is_correct": false, "explanation": "语义：“产品”指商品，不能用来指人。"}, {"text": "食堂", "is_correct": false, "explanation": "搭配：“他是”后面接人时才说“有名的”，“食堂”作为表语与句意不符。"}], "explanations": {"大楼": "语义：“他是”后面不能接建筑，大楼不指人。", "高才": "高才：指聪明、本领大的人，与“他是我们公司里有名的”相符，是唯一能填入的词。", "产品": "语义：“产品”指商品，不能用来指人。", "食堂": "搭配：“他是”后面接人时才说“有名的”，“食堂”作为表语与句意不符。"}, "sentence_index": 0, "correct_answer": "高才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中拿了高才。", "explanation": "这里应该用〈高分〉。“高才”指聪明、本领大的人，不能用来说比赛成绩，成绩高应说“高分”。"}, {"text": "这件衣服卖了高才。", "explanation": "这里应该用〈高价〉。“高才”指聪明、本领大的人，不能用来说价钱，价钱高应说“高价”。"}, {"text": "这台电脑的高才很好用。", "explanation": "这里应该用〈性能〉。“高才”指聪明、本领大的人，不能说机器好不好用，应说“性能”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90697, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老人", "is_correct": false, "explanation": "语义：“年轻的”与“老人”矛盾，句意不通。"}, {"text": "高才", "is_correct": true, "explanation": "高才：指聪明、本领大的人，与“一位年轻的”和“解决了这个难题”相符，是唯一能填入的词。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不能解决难题，与句意不符。"}, {"text": "机器", "is_correct": false, "explanation": "搭配：“一位”用于人，机器应用“台”计量，且机器一般不说“年轻”。"}], "explanations": {"老人": "语义：“年轻的”与“老人”矛盾，句意不通。", "高才": "高才：指聪明、本领大的人，与“一位年轻的”和“解决了这个难题”相符，是唯一能填入的词。", "猫": "语义：猫不能解决难题，与句意不符。", "机器": "搭配：“一位”用于人，机器应用“台”计量，且机器一般不说“年轻”。"}, "sentence_index": 6, "correct_answer": "高才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月的高才都很多。", "explanation": "这里应该用〈工资〉。“高才”指聪明、本领大的人，不能指收入，收入多应说“工资”多。"}, {"text": "他跑步的高才很快。", "explanation": "这里应该用〈速度〉。“高才”指聪明、本领大的人，不能指快慢，跑得快应说“速度”快。"}, {"text": "他在部门里升到了高才。", "explanation": "这里应该用〈高位〉。“高才”指聪明、本领大的人，不能指职位，职位高应说“高位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90697, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校里来了一辆物理高才。", "corrected_sentence": "学校里来了一位物理高才。", "error_description": "错误在量词：“辆”用于车辆，人不能用“辆”计量，指人的“高才”应说“一位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90697, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那把高才昨天到了学校。", "corrected_sentence": "那位高才昨天到了学校。", "error_description": "错误在量词：“把”多用于有柄的器物，“那把”修饰指人的“高才”不通，应说“那位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
