INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90698, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "（书面）出众的才能。", "primary_collocate": null, "pronunciation": "gāo cái", "ipa": "kɑʊ˥ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "他年轻时就有高才，大家都很佩服。", "target_word": "高才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，他的高才表现在写文章上。", "target_word": "高才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有高才，却从不骄傲。", "target_word": "高才", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家的高才，人人都知道。", "target_word": "高才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠自己的高才进了大学。", "target_word": "高才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年纪虽小，他的高才已经让人吃惊。", "target_word": "高才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有高才的人，也要不停地学习。", "target_word": "高才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都夸他有高才，他只是笑笑。", "target_word": "高才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者凭借高才，在二十岁时就发表了重要论文。", "target_word": "高才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老校长很看重他的高才。", "target_word": "高才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "指出众的才能、才华，常作“有高才”的宾语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '741a067b-35ee-42ee-a9a5-e70920a0d4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90698, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毛病", "is_correct": false, "explanation": "语义：“佩服”的对象是才能或品格，“毛病”是缺点，不值得佩服。"}, {"text": "高才", "is_correct": true, "explanation": "高才：指出众的才能，与“大家都很佩服”相符，是唯一能填入的词。"}, {"text": "烦恼", "is_correct": false, "explanation": "语义：烦恼令人同情，不会让人佩服。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“佩服”不搭配“脾气”，“有脾气”与后半句的评价语义冲突。"}], "explanations": {"毛病": "语义：“佩服”的对象是才能或品格，“毛病”是缺点，不值得佩服。", "高才": "高才：指出众的才能，与“大家都很佩服”相符，是唯一能填入的词。", "烦恼": "语义：烦恼令人同情，不会让人佩服。", "脾气": "搭配：“佩服”不搭配“脾气”，“有脾气”与后半句的评价语义冲突。"}, "sentence_index": 0, "correct_answer": "高才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次考试拿了高才。", "explanation": "这里应该用〈高分〉。“高才”指出众的才能，不能用来说考试成绩，成绩高应说“高分”。"}, {"text": "他在比赛中取得了很大的高才。", "explanation": "这里应该用〈成就〉。“取得”搭配成绩、成就等结果；“高才”是人本身具有的才能，不能“取得”。"}, {"text": "这棵树的高才有十米。", "explanation": "这里应该用〈高度〉。“高才”指才能出众，不能指高矮，树的高矮应说“高度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尾巴", "is_correct": false, "explanation": "语义：人没有尾巴，“有尾巴的人”不成立，与句意不符。"}, {"text": "高才", "is_correct": true, "explanation": "高才：指出众的才能，“有高才的人”与后半句“也要不停地学习”相符，是唯一能填入的词。"}, {"text": "翅膀", "is_correct": false, "explanation": "语义：人没有翅膀，“有翅膀的人”不合句意。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“寿命”一般说“寿命长”，不说“有寿命的人”。"}], "explanations": {"尾巴": "语义：人没有尾巴，“有尾巴的人”不成立，与句意不符。", "高才": "高才：指出众的才能，“有高才的人”与后半句“也要不停地学习”相符，是唯一能填入的词。", "翅膀": "语义：人没有翅膀，“有翅膀的人”不合句意。", "寿命": "搭配：“寿命”一般说“寿命长”，不说“有寿命的人”。"}, "sentence_index": 6, "correct_answer": "高才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司给他发了很多高才。", "explanation": "这里应该用〈奖金〉。“发”的对象是钱或实物；“高才”是人本身具有的才能，不能由别人“发”给。"}, {"text": "他在公司里升到了高才。", "explanation": "这里应该用〈高位〉。“高才”指出众的才能，不能指职位，职位高应说“高位”。"}, {"text": "老校长很看重他，因为他出身于高才。", "explanation": "这里应该用〈家庭〉。“高才”指才能出众，不能指出身背景，应说“出身于……家庭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她从小就高才，老师很佩服。", "corrected_sentence": "她从小就有高才，老师很佩服。", "error_description": "错误在动词“有”：“高才”是名词，表示“才能出众”，不能直接作谓语，应说“有高才”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从小就有一把高才，父母很骄傲。", "corrected_sentence": "他从小就有高才，父母很骄傲。", "error_description": "错误在量词：“把”多用于有把手的器物，不能修饰“高才”；这里直接说“有高才”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6f1ef3-c904-4026-9405-deef1fc6ef07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
