INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90699, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "专是只做一件事，不去做别的事。", "primary_collocate": null, "pronunciation": "zhuān", "ipa": "ʈʂwan˥", "syllable_count": 1, "sentences": [{"text": "这家小店专做牛肉面，别的都不卖。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电台专放老歌，没有新歌。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生专治小孩的病。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班专收小学生，大人不能报名。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个窗口专收现金，不收卡。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她专给孩子们写故事，从不写别的。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老师专教小孩画画，不教大人。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子专给客人用，我们自己不用。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目专讲历史故事，不讲别的。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他专挑便宜的东西买，贵的都不要。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，用在动词前，表示只做某一件事、不做别的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b68f76f-19ce-4182-879c-f07998280520') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90699, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "专", "is_correct": true, "explanation": "正确答案。专（zhuān，第一声）表示只做某一件事，不做别的。"}, {"text": "转", "is_correct": false, "explanation": "zhuǎn（第三声）与 zhuān（第一声）声调不同，意思是转动。"}, {"text": "站", "is_correct": false, "explanation": "zhàn（第四声）与 zhuān（第一声）不仅声调不同，韵母还少了介音 u，意思是站立。"}, {"text": "穿", "is_correct": false, "explanation": "chuān 与 zhuān 声母不同（ch 与 zh），意思是穿上。"}, {"text": "装", "is_correct": false, "explanation": "zhuāng 与 zhuān 韵母不同（ang 与 an），意思是装上、装饰。"}], "explanations": {"专": "正确答案。专（zhuān，第一声）表示只做某一件事，不做别的。", "转": "zhuǎn（第三声）与 zhuān（第一声）声调不同，意思是转动。", "站": "zhàn（第四声）与 zhuān（第一声）不仅声调不同，韵母还少了介音 u，意思是站立。", "穿": "chuān 与 zhuān 声母不同（ch 与 zh），意思是穿上。", "装": "zhuāng 与 zhuān 韵母不同（ang 与 an），意思是装上、装饰。"}, "sentence_index": null, "correct_answer": "专"}, "level_3": {"options": [{"text": "专", "is_correct": true, "explanation": "正确。专表示只做牛肉面，这与“别的都不卖”一致。"}, {"text": "刚", "is_correct": false, "explanation": "语义：刚表示时间上刚发生不久，不能描述长期只做一种面的经营方式。"}, {"text": "又", "is_correct": false, "explanation": "语义：又表示动作重复出现，这里说的是经营范围，不是重复。"}, {"text": "正", "is_correct": false, "explanation": "体貌：正表示动作正在进行，不能表示长期的经营方式。"}], "explanations": {"专": "正确。专表示只做牛肉面，这与“别的都不卖”一致。", "刚": "语义：刚表示时间上刚发生不久，不能描述长期只做一种面的经营方式。", "又": "语义：又表示动作重复出现，这里说的是经营范围，不是重复。", "正": "体貌：正表示动作正在进行，不能表示长期的经营方式。"}, "sentence_index": 0, "correct_answer": "专"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我专吃饭，也在打电话。", "explanation": "这里不能用〈专〉。专表示只做一件事、不做别的，与“也在打电话”相矛盾。"}, {"text": "他专看书，却在玩手机。", "explanation": "这里不能用〈专〉。专表示只做一件事、不做别的，与“却在玩手机”相矛盾。"}, {"text": "这家店专卖牛肉面，另外还卖饺子和汤。", "explanation": "这里表达的是〈兼营〉，不能用〈专〉。专表示只做一件事，与“另外还卖饺子和汤”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90699, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "专", "is_correct": true, "explanation": "正确答案。专（zhuān，第一声）表示只做某一件事，不做别的。"}, {"text": "赚", "is_correct": false, "explanation": "zhuàn（第四声）与 zhuān（第一声）声调不同，意思是赚钱。"}, {"text": "占", "is_correct": false, "explanation": "zhàn（第四声）与 zhuān（第一声）不仅声调不同，韵母还少了介音 u，意思是占据。"}, {"text": "庄", "is_correct": false, "explanation": "zhuāng 与 zhuān 韵母不同（ang 与 an），意思是村庄。"}, {"text": "沾", "is_correct": false, "explanation": "zhān 与 zhuān 少了介音 u，意思是沾上。"}], "explanations": {"专": "正确答案。专（zhuān，第一声）表示只做某一件事，不做别的。", "赚": "zhuàn（第四声）与 zhuān（第一声）声调不同，意思是赚钱。", "占": "zhàn（第四声）与 zhuān（第一声）不仅声调不同，韵母还少了介音 u，意思是占据。", "庄": "zhuāng 与 zhuān 韵母不同（ang 与 an），意思是村庄。", "沾": "zhān 与 zhuān 少了介音 u，意思是沾上。"}, "sentence_index": null, "correct_answer": "专"}, "level_3": {"options": [{"text": "专", "is_correct": true, "explanation": "正确。专表示只教小孩画画，这与“不教大人”一致。"}, {"text": "互相", "is_correct": false, "explanation": "语法：互相要求主语是两个以上的人彼此做某事，“这个老师”只有一个人，不能用。"}, {"text": "一起", "is_correct": false, "explanation": "语法：一起要求两个以上的人共同做事，单个主语“这个老师”不能这样说。"}, {"text": "渐渐", "is_correct": false, "explanation": "语义：渐渐表示慢慢变化，不能说明固定只教小孩、不教大人的安排。"}], "explanations": {"专": "正确。专表示只教小孩画画，这与“不教大人”一致。", "互相": "语法：互相要求主语是两个以上的人彼此做某事，“这个老师”只有一个人，不能用。", "一起": "语法：一起要求两个以上的人共同做事，单个主语“这个老师”不能这样说。", "渐渐": "语义：渐渐表示慢慢变化，不能说明固定只教小孩、不教大人的安排。"}, "sentence_index": 6, "correct_answer": "专"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他专挑便宜的东西买，贵的也买。", "explanation": "这里不能用〈专〉。专表示只挑某一类东西，与“贵的也买”相矛盾。"}, {"text": "他专挑便宜的东西，也挑贵的东西买。", "explanation": "这里不能用〈专〉。专表示只挑某一类东西，与“也挑贵的东西买”相矛盾。"}, {"text": "他专挑所有的东西买。", "explanation": "这里表达的是〈全部〉，不能用〈专〉。专表示只做某件事、不做别的，与“挑所有的东西买”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, a