INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90700, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "用心专一，不分散。", "primary_collocate": null, "pronunciation": "zhuān", "ipa": "ʈʂwan˥", "syllable_count": 1, "sentences": [{"text": "他对感情很专，从不三心二意。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他干起活来很专，不会一会儿干这个，一会儿干那个。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她爱得很专，心里只有他一个人。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子做事很专，一做就是一下午。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对妻子很专，心里从没有过别人。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做研究，心要专，不能分神。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画画画得很专，连饭都忘了吃。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个人用情很专，结婚三十年了。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读书很专，一本书能看上一整天。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学习很专，写作业时从不看手机。", "target_word": "专", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容词，指用心专一、不分散", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b68f76f-19ce-4182-879c-f07998280520') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90700, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "专", "is_correct": true, "explanation": "正确答案。专（zhuān，第一声）形容用心专一、不分散。"}, {"text": "转", "is_correct": false, "explanation": "zhuǎn（第三声）与 zhuān（第一声）声调不同，意思是转动。"}, {"text": "站", "is_correct": false, "explanation": "zhàn（第四声）与 zhuān（第一声）不仅声调不同，韵母还少了介音 u，意思是站立。"}, {"text": "穿", "is_correct": false, "explanation": "chuān 与 zhuān 声母不同（ch 与 zh），意思是穿上。"}, {"text": "装", "is_correct": false, "explanation": "zhuāng 与 zhuān 韵母不同（ang 与 an），意思是装上、装饰。"}], "explanations": {"专": "正确答案。专（zhuān，第一声）形容用心专一、不分散。", "转": "zhuǎn（第三声）与 zhuān（第一声）声调不同，意思是转动。", "站": "zhàn（第四声）与 zhuān（第一声）不仅声调不同，韵母还少了介音 u，意思是站立。", "穿": "chuān 与 zhuān 声母不同（ch 与 zh），意思是穿上。", "装": "zhuāng 与 zhuān 韵母不同（ang 与 an），意思是装上、装饰。"}, "sentence_index": null, "correct_answer": "专"}, "level_3": {"options": [{"text": "专", "is_correct": true, "explanation": "正确。专表示感情上用心专一，与“从不三心二意”一致。"}, {"text": "薄", "is_correct": false, "explanation": "语义：薄表示感情淡薄，与“从不三心二意”所说的忠诚相反。"}, {"text": "散", "is_correct": false, "explanation": "搭配：“散”指分散，不能用来说感情“很散”。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”不用来形容感情，“感情很硬”不成立。"}], "explanations": {"专": "正确。专表示感情上用心专一，与“从不三心二意”一致。", "薄": "语义：薄表示感情淡薄，与“从不三心二意”所说的忠诚相反。", "散": "搭配：“散”指分散，不能用来说感情“很散”。", "硬": "搭配：“硬”不用来形容感情，“感情很硬”不成立。"}, "sentence_index": 0, "correct_answer": "专"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子做事很专，一会儿画画，一会儿跳舞。", "explanation": "这里应该用〈浮躁〉。专表示用心专一，与“一会儿画画，一会儿跳舞”相矛盾。"}, {"text": "他学习很专，常常东想西想。", "explanation": "这里应该用〈散漫〉。专表示用心专一，与“东想西想”矛盾。"}, {"text": "他对工作很专，常常在上班时间打游戏。", "explanation": "这里应该用〈心不在焉〉。专表示用心专一，与“常常在上班时间打游戏”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90700, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "专", "is_correct": true, "explanation": "正确答案。专（zhuān，第一声）形容用心专一、不分散。"}, {"text": "赚", "is_correct": false, "explanation": "zhuàn（第四声）与 zhuān（第一声）声调不同，意思是赚钱。"}, {"text": "占", "is_correct": false, "explanation": "zhàn（第四声）与 zhuān（第一声）不仅声调不同，韵母还少了介音 u，意思是占据。"}, {"text": "庄", "is_correct": false, "explanation": "zhuāng 与 zhuān 韵母不同（ang 与 an），意思是村庄。"}, {"text": "沾", "is_correct": false, "explanation": "zhān 与 zhuān 少了介音 u，意思是沾上。"}], "explanations": {"专": "正确答案。专（zhuān，第一声）形容用心专一、不分散。", "赚": "zhuàn（第四声）与 zhuān（第一声）声调不同，意思是赚钱。", "占": "zhàn（第四声）与 zhuān（第一声）不仅声调不同，韵母还少了介音 u，意思是占据。", "庄": "zhuāng 与 zhuān 韵母不同（ang 与 an），意思是村庄。", "沾": "zhān 与 zhuān 少了介音 u，意思是沾上。"}, "sentence_index": null, "correct_answer": "专"}, "level_3": {"options": [{"text": "专", "is_correct": true, "explanation": "正确。专表示用心专一，与“画得很专，连饭都忘了吃”一致。"}, {"text": "亮", "is_correct": false, "explanation": "语义：亮形容光线或颜色，与“连饭都忘了吃”所说的投入程度无关。"}, {"text": "懒", "is_correct": false, "explanation": "语义：懒与“连饭都忘了吃”所描述的投入状态相反。"}, {"text": "凉", "is_correct": false, "explanation": "搭配：“凉”不用来形容画画，“画得很凉”不成立。"}], "explanations": {"专": "正确。专表示用心专一，与“画得很专，连饭都忘了吃”一致。", "亮": "语义：亮形容光线或颜色，与“连饭都忘了吃”所说的投入程度无关。", "懒": "语义：懒与“连饭都忘了吃”所描述的投入状态相反。", "凉": "搭配：“凉”不用来形容画画，“画得很凉”不成立。"}, "sentence_index": 6, "correct_answer": "专"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他学习很专，写作业时一直看手机。", "explanation": "这里不能用〈专〉。专表示用心专一，与“写作业时一直看手机”相矛盾。"}, {"text": "他学习很专，上课总是东张西望。", "explanation": "这里应该用〈不专心〉。专表示用心专一，与“上课总是东张西望”相矛盾。"}, {"text": "他学习很专，写一会儿作业就去玩游戏。", "explanation": "这里不能用〈专〉。专表示用心专一，与“写一会儿就去玩游戏”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404695b5-d5d1-43a0-ad79-48073ddffab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, mod