INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90701, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "晚餐是晚上吃的饭。", "primary_collocate": null, "pronunciation": "wǎn cān", "ipa": "wan˨˩˦ tsʰan˥", "syllable_count": 2, "sentences": [{"text": "我家的晚餐总是七点开始。", "target_word": "晚餐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今晚的晚餐有汤，也有青菜。", "target_word": "晚餐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们坐在桌子旁边等着晚餐。", "target_word": "晚餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳下山了，大家开始准备晚餐。", "target_word": "晚餐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我很饿，晚餐什么时候能吃？", "target_word": "晚餐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一个人在家吃了简单的晚餐。", "target_word": "晚餐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友晚上来家里，我要准备晚餐。", "target_word": "晚餐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃完晚餐，他洗了碗就去睡觉。", "target_word": "晚餐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个周末的晚餐，我想吃火锅。", "target_word": "晚餐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她喜欢在晚餐时听音乐。", "target_word": "晚餐", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "一顿晚餐", "label": "量词"}, {"form": "烛光晚餐", "label": "复合"}], "register": "中性", "sense_fingerprint": "晚上吃的饭菜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f4a601-3387-46d6-8878-d4f1e5cccdbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90701, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晚餐", "is_correct": true, "explanation": "正确：“晚餐”是晚上吃的饭，与“我家的……总是七点开始”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是有固定开始时间的活动，“总是七点开始”不成立。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不是活动，不能在七点“开始”。"}, {"text": "房门", "is_correct": false, "explanation": "语义：“房门”是建筑部件，不能“开始”。"}], "explanations": {"晚餐": "正确：“晚餐”是晚上吃的饭，与“我家的……总是七点开始”相符。", "天气": "语义：“天气”不是有固定开始时间的活动，“总是七点开始”不成立。", "窗户": "语义：“窗户”不是活动，不能在七点“开始”。", "房门": "语义：“房门”是建筑部件，不能“开始”。"}, "sentence_index": 0, "correct_answer": "晚餐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中午，我们在食堂吃了一顿晚餐。", "explanation": "这里应该用〈午餐〉。晚餐指晚上吃的饭，中午吃的饭要说〈午餐〉。"}, {"text": "早上八点，我在去学校的路上吃了晚餐。", "explanation": "这里应该用〈早餐〉。晚餐指晚上吃的饭，早上八点吃的饭要说〈早餐〉。"}, {"text": "清晨六点，爸爸在厨房吃晚餐。", "explanation": "这里应该用〈早餐〉。晚餐指晚上吃的饭，清晨吃的饭要说〈早餐〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90701, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晚餐", "is_correct": true, "explanation": "正确：“晚餐”与“朋友晚上来家里，我要准备……”相符。"}, {"text": "皱纹", "is_correct": false, "explanation": "语义：“皱纹”是皮肤上的纹路，不能被准备。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”不是可以事先准备的东西。"}, {"text": "身材", "is_correct": false, "explanation": "搭配：“准备”不与“身材”搭配，身材不能像待客物品那样事先准备。"}], "explanations": {"晚餐": "正确：“晚餐”与“朋友晚上来家里，我要准备……”相符。", "皱纹": "语义：“皱纹”是皮肤上的纹路，不能被准备。", "年龄": "语义：“年龄”不是可以事先准备的东西。", "身材": "搭配：“准备”不与“身材”搭配，身材不能像待客物品那样事先准备。"}, "sentence_index": 6, "correct_answer": "晚餐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "深夜三点，他饿得睡不着，爬起来吃了一顿晚餐。", "explanation": "这里应该用〈夜宵〉。晚餐指晚上的正餐，饿得睡不着后爬起来吃的小吃要说〈夜宵〉。"}, {"text": "下午两点，她在茶馆吃了点心，喝了茶，当作晚餐。", "explanation": "这里应该用〈下午茶〉。晚餐指晚上吃的正餐，下午两点吃的点心和茶要说〈下午茶〉。"}, {"text": "上午九点，爸爸在街边吃了一顿晚餐。", "explanation": "这里应该用〈早点〉。晚餐指晚上吃的饭，上午吃的小吃要说〈早点〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90701, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们吃了一顿丰盛地晚餐。", "corrected_sentence": "我们吃了一顿丰盛的晚餐。", "error_description": "错误形式：“丰盛地晚餐”；正确形式：“丰盛的晚餐”。修饰名词要用结构助词“的”，“地”用于修饰动词，不能修饰名词“晚餐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90701, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈在晚餐做好了。", "corrected_sentence": "妈妈把晚餐做好了。", "error_description": "错误形式：“在晚餐做好了”；正确形式：“把晚餐做好了”。处置式要用“把”引出被处置的宾语“晚餐”，“在”不能引出这一宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
