INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90702, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "晚上吃的一顿饭。", "primary_collocate": null, "pronunciation": "wǎn cān", "ipa": "wan˨˩˦ tsʰan˥", "syllable_count": 2, "sentences": [{"text": "今天的晚餐是鱼和米饭。", "target_word": "晚餐", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们晚上六点吃晚餐。", "target_word": "晚餐", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天快黑了，妈妈在厨房做晚餐。", "target_word": "晚餐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天的晚餐很丰盛，我吃了很多。", "target_word": "晚餐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天下班回家，先做晚餐，再看电视。", "target_word": "晚餐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚餐后，我们一起去公园散步。", "target_word": "晚餐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想在家吃晚餐，还是去饭店吃？", "target_word": "晚餐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭店的晚餐只供应到九点。", "target_word": "晚餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在海边吃过一次浪漫的晚餐。", "target_word": "晚餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，晚餐不能吃得太晚。", "target_word": "晚餐", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一顿晚餐", "label": "量词"}, {"form": "烛光晚餐", "label": "复合"}], "register": "中性", "sense_fingerprint": "晚上吃的那一顿饭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f4a601-3387-46d6-8878-d4f1e5cccdbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90702, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晚餐", "is_correct": true, "explanation": "正确：“晚餐”指晚上吃的饭，与“今天的……是鱼和米饭”相符。"}, {"text": "房间", "is_correct": false, "explanation": "语义：“房间”是空间，不是食物，不能与“鱼和米饭”构成“是”的关系。"}, {"text": "晚报", "is_correct": false, "explanation": "语义：“晚报”是报纸，不是食物，不能与“鱼和米饭”构成“是”的关系。"}, {"text": "晚会", "is_correct": false, "explanation": "搭配：“晚会”指聚会或演出，不能说“今天的晚会是鱼和米饭”。"}], "explanations": {"晚餐": "正确：“晚餐”指晚上吃的饭，与“今天的……是鱼和米饭”相符。", "房间": "语义：“房间”是空间，不是食物，不能与“鱼和米饭”构成“是”的关系。", "晚报": "语义：“晚报”是报纸，不是食物，不能与“鱼和米饭”构成“是”的关系。", "晚会": "搭配：“晚会”指聚会或演出，不能说“今天的晚会是鱼和米饭”。"}, "sentence_index": 0, "correct_answer": "晚餐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们十二点在公司附近吃了一顿晚餐。", "explanation": "这里应该用〈午餐〉。晚餐指晚上吃的正餐，十二点吃的饭要说〈午餐〉。"}, {"text": "我昨天吃了一只晚餐。", "explanation": "这里量词用错。吃晚餐的量词是〈顿〉，应说“一顿晚餐”；〈只〉用于动物或成对物品中的一个，不能用于晚餐。"}, {"text": "我们每天早上七点在家吃晚餐。", "explanation": "这里应该用〈早餐〉。晚餐指晚上吃的饭，早上吃的饭要说〈早餐〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90702, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晚餐", "is_correct": true, "explanation": "正确：“晚餐”是晚上吃的饭，与“在家吃……还是去饭店吃”相符。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”不是可以吃的东西，与“吃”的对象不合。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学习任务，不能被“吃”。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：“吃”不与“电影”搭配，“在家吃电影”不成立。"}], "explanations": {"晚餐": "正确：“晚餐”是晚上吃的饭，与“在家吃……还是去饭店吃”相符。", "钥匙": "语义：“钥匙”不是可以吃的东西，与“吃”的对象不合。", "作业": "语义：“作业”是学习任务，不能被“吃”。", "电影": "搭配：“吃”不与“电影”搭配，“在家吃电影”不成立。"}, "sentence_index": 6, "correct_answer": "晚餐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "半夜两点，他饿醒了，起来吃了一顿晚餐。", "explanation": "这里应该用〈夜宵〉。晚餐指晚上的正餐，睡觉后饿醒了再吃的小吃要说〈夜宵〉。"}, {"text": "下午三点，我们在咖啡店吃了一顿晚餐。", "explanation": "这里应该用〈下午茶〉。晚餐指晚上吃的正餐，下午的点心要说〈下午茶〉。"}, {"text": "上午十点，我们在街边吃了一顿晚餐。", "explanation": "这里应该用〈早点〉。晚餐指晚上吃的饭，上午吃的小吃要说〈早点〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们吃了完晚餐就去散步了。", "corrected_sentence": "我们吃完晚餐就去散步了。", "error_description": "错误形式：“吃了完晚餐”；正确形式：“吃完晚餐”。结果补语“完”紧跟动词“吃”，中间不能插入“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去年在日本吃了过一顿晚餐。", "corrected_sentence": "我去年在日本吃过一顿晚餐。", "error_description": "错误形式：“吃了过一顿晚餐”；正确形式：“吃过一顿晚餐”。经历标记“过”紧跟动词“吃”，不能与“了”叠用在同一动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
