INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90704, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "像成熟的香蕉皮、向日葵花那样的颜色。", "primary_collocate": null, "pronunciation": "huáng sè", "ipa": "xwaŋ˧˥ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "向日葵开花了，花瓣是黄色的。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "熟透的香蕉皮变成了黄色。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片向日葵田，一眼看去全是黄色。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "青香蕉放几天，就会变成黄色。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花瓶里插着黄色的向日葵。", "target_word": "黄色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成熟的香蕉是漂亮的黄色。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "向日葵的花盘四周是明亮的黄色。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用黄色的颜料画向日葵。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根香蕉的皮是黄色的，已经熟了。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天的田野里，黄色的向日葵开得很美。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "黃色", "label": "繁体"}, {"form": "淡黄色", "label": "复合"}], "register": "中性", "sense_fingerprint": "黄色-像成熟香蕉皮、向日葵花的颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '10b74abb-82e7-47f8-a7df-97bad8dedd21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90704, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黄色", "is_correct": true, "explanation": "向日葵的花瓣呈黄色，与句意相符。"}, {"text": "蓝色", "is_correct": false, "explanation": "语义：向日葵的花瓣不是蓝色，与“向日葵开花”的常见颜色不符。"}, {"text": "紫色", "is_correct": false, "explanation": "语义：向日葵的花瓣不是紫色，与句中的“向日葵”不相符。"}, {"text": "绛色", "is_correct": false, "explanation": "语域：绛色是书面色名，口语描述向日葵花瓣不用；且绛为深红，与向日葵不符。"}], "explanations": {"黄色": "向日葵的花瓣呈黄色，与句意相符。", "蓝色": "语义：向日葵的花瓣不是蓝色，与“向日葵开花”的常见颜色不符。", "紫色": "语义：向日葵的花瓣不是紫色，与句中的“向日葵”不相符。", "绛色": "语域：绛色是书面色名，口语描述向日葵花瓣不用；且绛为深红，与向日葵不符。"}, "sentence_index": 0, "correct_answer": "黄色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次面试的结果很黄色，大家都没想到。", "explanation": "这里“黄色”只表示颜色，不能形容结果。应说〈意外〉或〈出人意料〉。"}, {"text": "他跑得很黄色，第一个到了终点。", "explanation": "这里“黄色”只表示颜色，不能形容跑步。应说〈快〉。"}, {"text": "这个箱子很黄色，我一个人搬不动。", "explanation": "这里“黄色”只表示颜色，不能形容重量。应说〈重〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90704, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黄色", "is_correct": true, "explanation": "向日葵的花盘呈明亮的黄色，与句意相符。"}, {"text": "红色", "is_correct": false, "explanation": "语义：向日葵的花盘四周不是红色，与“向日葵”的颜色不符。"}, {"text": "墨绿色", "is_correct": false, "explanation": "语义：墨绿色偏暗沉，与“明亮”的描述相矛盾。"}, {"text": "赭色", "is_correct": false, "explanation": "语域：赭色是书面色名，口语描述花盘颜色不用；且赭色暗褐，与“明亮”不符。"}], "explanations": {"黄色": "向日葵的花盘呈明亮的黄色，与句意相符。", "红色": "语义：向日葵的花盘四周不是红色，与“向日葵”的颜色不符。", "墨绿色": "语义：墨绿色偏暗沉，与“明亮”的描述相矛盾。", "赭色": "语域：赭色是书面色名，口语描述花盘颜色不用；且赭色暗褐，与“明亮”不符。"}, "sentence_index": 6, "correct_answer": "黄色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中国经济迎来了黄色时代。", "explanation": "这里应该用〈黄金〉，表示最好的时期。〈黄色〉只表示颜色，不能用来指一个时代。"}, {"text": "裁判向他拿出了黄色。", "explanation": "这里应该用〈黄牌〉，指足球比赛中的警告牌。〈黄色〉只表示颜色，不能指比赛中的牌子。"}, {"text": "这次考试的黄色很好，大家都很高兴。", "explanation": "这里应该用〈成绩〉。〈黄色〉只表示颜色，不能指考试结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈的围裙很黄色的，上面绣着花。", "corrected_sentence": "妈妈的围裙是黄色的，上面绣着花。", "error_description": "“黄色”作表语要用“是……的”，不能直接受“很”修饰。应说“是黄色的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这串香蕉全熟了，皮很黄色的。", "corrected_sentence": "这串香蕉全熟了，皮是黄色的。", "error_description": "“黄色”作表语要用“是……的”，不能直接受“很”修饰。应说“是黄色的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '199bcd13-0765-45cd-a211-d7508a709a8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
