INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90705, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "后跟是鞋子后面，脚后跟踩的地方。", "primary_collocate": null, "pronunciation": "hòu gēn", "ipa": "xoʊ̯˥˩ kən˥", "syllable_count": 2, "sentences": [{"text": "他每天踩着鞋的后跟走路，鞋很快就坏了。", "target_word": "后跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋的后跟很厚，走路不累。", "target_word": "后跟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说后跟低一点的鞋对脚好。", "target_word": "后跟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我买了一双后跟很矮的黑鞋。", "target_word": "后跟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鞋后跟掉了，我只好走回家。", "target_word": "后跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把鞋的后跟擦干净。", "target_word": "后跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的红鞋后跟很细，走得很慢。", "target_word": "后跟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗咬坏了我的拖鞋后跟。", "target_word": "后跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步时，鞋后跟要结实。", "target_word": "后跟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双运动鞋的后跟上有一个小标志。", "target_word": "后跟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "鞋后跟", "label": "复合"}, {"form": "後跟", "label": "繁体"}], "register": "中性", "sense_fingerprint": "鞋子后面脚跟踩着的那一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f17da28-59f8-418f-b207-d6e528bd9ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90705, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后跟", "is_correct": true, "explanation": "正确：「后跟」是鞋子后面脚跟踩的部分，与“踩着……走路”相符。"}, {"text": "鞋面", "is_correct": false, "explanation": "语义：「鞋面」在鞋的上部，脚不踩在那里，与“踩着走路”不符。"}, {"text": "鞋舌", "is_correct": false, "explanation": "语义：「鞋舌」在鞋面前部，脚不踩在那里，与“踩着……走路”不符。"}, {"text": "袖口", "is_correct": false, "explanation": "语义：「袖口」属于衣服，不是鞋子的部分。"}], "explanations": {"后跟": "正确：「后跟」是鞋子后面脚跟踩的部分，与“踩着……走路”相符。", "鞋面": "语义：「鞋面」在鞋的上部，脚不踩在那里，与“踩着走路”不符。", "鞋舌": "语义：「鞋舌」在鞋面前部，脚不踩在那里，与“踩着……走路”不符。", "袖口": "语义：「袖口」属于衣服，不是鞋子的部分。"}, "sentence_index": 0, "correct_answer": "后跟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈的帽子后跟破了，要缝一下。", "explanation": "这里应该用〈后面〉。后跟只指鞋袜后部，帽子的后部要说后面。"}, {"text": "这把椅子的后跟断了，要换一个。", "explanation": "这里应该用〈椅腿〉。后跟只指鞋袜后部，椅子的支撑部分要说椅腿。"}, {"text": "沙发的后跟坏了，要找人修一下。", "explanation": "这里应该用〈沙发腿〉。后跟只指鞋袜后部，沙发的支撑部分要说沙发腿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90705, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后跟", "is_correct": true, "explanation": "正确：「后跟」指鞋子后部，句中说“很细”，与此相符。"}, {"text": "领带", "is_correct": false, "explanation": "语义：「领带」属于衣服，不是鞋的部分，句中的“红鞋”不能对应领带。"}, {"text": "帽檐", "is_correct": false, "explanation": "语义：「帽檐」是帽子的边，与鞋无关。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：「红鞋」后面接的部件要属于鞋，「手套」不能作为鞋的部位来“很细”。"}], "explanations": {"后跟": "正确：「后跟」指鞋子后部，句中说“很细”，与此相符。", "领带": "语义：「领带」属于衣服，不是鞋的部分，句中的“红鞋”不能对应领带。", "帽檐": "语义：「帽檐」是帽子的边，与鞋无关。", "手套": "搭配：「红鞋」后面接的部件要属于鞋，「手套」不能作为鞋的部位来“很细”。"}, "sentence_index": 6, "correct_answer": "后跟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的书包后跟破了，要缝一下。", "explanation": "这里应该用〈背面〉。后跟只指鞋袜后部，书包的后部要说背面。"}, {"text": "小狗咬坏了我的玩具后跟。", "explanation": "这里应该用〈后半部〉。后跟只指鞋袜后部，玩具的后部要说后半部。"}, {"text": "这辆自行车的后跟断了，要去修车店。", "explanation": "这里应该用〈车架〉。后跟只指鞋袜后部，自行车的框架要说车架。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90705, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她总是踩了鞋后跟走路，鞋很快就坏了。", "corrected_sentence": "她总是踩着鞋后跟走路，鞋很快就坏了。", "error_description": "错误：表示“踩”的动作持续进行，应用助词“着”，不能用“了”。应说“踩着鞋后跟走路”，不能说“踩了鞋后跟走路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90705, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "跑步时，鞋后跟磨很快。", "corrected_sentence": "跑步时，鞋后跟磨得很快。", "error_description": "动词“磨”后面表示程度要用助词“得”，正确的说法是“磨得很快”，不能说“磨很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
