INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90706, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "鞋袜后部包着脚跟的部分。", "primary_collocate": null, "pronunciation": "hòu gēn", "ipa": "xoʊ̯˥˩ kən˥", "syllable_count": 2, "sentences": [{"text": "这双鞋的后跟太高，走路很累。", "target_word": "后跟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的鞋后跟坏了，要去修一下。", "target_word": "后跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的袜子后跟破了一个洞。", "target_word": "后跟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双新鞋后跟很软，穿着很舒服。", "target_word": "后跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，后跟高的鞋不好走路。", "target_word": "后跟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把鞋的后跟踩坏了。", "target_word": "后跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子跑得太快，一只鞋的后跟掉了。", "target_word": "后跟", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋前面是黑的，后跟是红色的。", "target_word": "后跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鞋店的人说，后跟太细容易坏。", "target_word": "后跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双袜子的后跟很厚，冬天穿很暖和。", "target_word": "后跟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "鞋后跟", "label": "复合"}, {"form": "後跟", "label": "繁体"}], "register": "中性", "sense_fingerprint": "鞋或袜子后部包着脚跟的那一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f17da28-59f8-418f-b207-d6e528bd9ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90706, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后跟", "is_correct": true, "explanation": "正确：「后跟」指鞋子后部包着脚跟的部分，与“这双鞋的……太高”相符。"}, {"text": "袖口", "is_correct": false, "explanation": "语义：「袖口」是衣袖的末端，不是鞋子的部分。"}, {"text": "鞋带", "is_correct": false, "explanation": "搭配：「太高」一般用于鞋跟、鞋子的高度，不说鞋带的高低。"}, {"text": "领口", "is_correct": false, "explanation": "语义：「领口」是衣服领子的开口，与鞋无关。"}], "explanations": {"后跟": "正确：「后跟」指鞋子后部包着脚跟的部分，与“这双鞋的……太高”相符。", "袖口": "语义：「袖口」是衣袖的末端，不是鞋子的部分。", "鞋带": "搭配：「太高」一般用于鞋跟、鞋子的高度，不说鞋带的高低。", "领口": "语义：「领口」是衣服领子的开口，与鞋无关。"}, "sentence_index": 0, "correct_answer": "后跟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的裙子后跟坏了，要去修一下。", "explanation": "这里应该说〈裙摆〉。后跟只指鞋袜后部包脚跟的地方，裙子上没有后跟。"}, {"text": "这个书包的后跟破了，要换一个。", "explanation": "这里应该用〈底部〉。后跟只指鞋袜后部包着脚跟的部分，书包下面的部分要说底部。"}, {"text": "桌子的后跟松了，要找人修一下。", "explanation": "这里应该用〈桌腿〉。后跟只指鞋袜后部，桌子的支撑部分要说桌腿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后跟", "is_correct": true, "explanation": "正确：「后跟」是鞋的部件，“一只鞋的……掉了”说的正是鞋的部分，相符。"}, {"text": "帽子", "is_correct": false, "explanation": "语义：「帽子」不是鞋的部分，“一只鞋的……掉了”不成立。"}, {"text": "手套", "is_correct": false, "explanation": "语义：「手套」不是鞋的部分，“一只鞋的……”后面不能接手套。"}, {"text": "裤腿", "is_correct": false, "explanation": "搭配：「一只鞋的」后面要接鞋的部件，「裤腿」属于裤子，不能这样说。"}], "explanations": {"后跟": "正确：「后跟」是鞋的部件，“一只鞋的……掉了”说的正是鞋的部分，相符。", "帽子": "语义：「帽子」不是鞋的部分，“一只鞋的……掉了”不成立。", "手套": "语义：「手套」不是鞋的部分，“一只鞋的……”后面不能接手套。", "裤腿": "搭配：「一只鞋的」后面要接鞋的部件，「裤腿」属于裤子，不能这样说。"}, "sentence_index": 6, "correct_answer": "后跟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衬衫的后跟破了，要缝一下。", "explanation": "这里应该用〈后背〉。后跟只指鞋袜的后部，衬衫背后的部分要说后背。"}, {"text": "窗帘的后跟很长，挡住了阳光。", "explanation": "这里应该用〈下摆〉。后跟只指鞋袜后部，窗帘底边要说下摆。"}, {"text": "汽车的后跟上贴着一张贴纸。", "explanation": "这里应该用〈车尾〉。后跟只指鞋袜后部，汽车的后部要说车尾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的鞋后跟磨很厉害，要换一双了。", "corrected_sentence": "我的鞋后跟磨得很厉害，要换一双了。", "error_description": "动词“磨”后面表示程度要用助词“得”，正确的说法是“磨得很厉害”，不能说“磨很厉害”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的鞋后跟掉起来了，要去修一下。", "corrected_sentence": "我的鞋后跟掉了，要去修一下。", "error_description": "错误：“掉”表示脱落，后面不能加趋向补语“起来”，应说“鞋后跟掉了”，多加“起来”不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90707, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "成年", "is_correct": true, "explanation": "正确：成年与未成年互为反义词，指已经长大、达到成年年龄。"}, {"text": "健壮", "is_correct": false, "explanation": "健壮形容身体状况，不是“未成年”的反义词。"}, {"text": "温柔", "is_correct": false, "explanation": "温柔形容性情，与“未成年”的年龄概念无关，不构成反义。"}, {"text": "认真", "is_correct": false, "explanation": "认真形容做事的态度，与“未成年”没有反义关系。"}], "correct_answer": "成年", "explanations": {"成年": "正确：成年与未成年互为反义词，指已经长大、达到成年年龄。", "健壮": "健壮形容身体状况，不是“未成年”的反义词。", "温柔": "温柔形容性情，与“未成年”的年龄概念无关，不构成反义。", "认真": "认真形容做事的态度，与“未成年”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90707, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "成年", "is_correct": true, "explanation": "正确：成年与未成年互为反义词，指已经长大、达到成年年龄。"}, {"text": "乐观", "is_correct": false, "explanation": "乐观形容对待生活的态度，不是“未成年”的反义词。"}, {"text": "稳重", "is_correct": false, "explanation": "稳重形容性格沉稳，与“未成年”没有反义关系。"}, {"text": "富有", "is_correct": false, "explanation": "富有形容拥有财富或某种丰富的品质，与“未成年”无关，不构成反义。"}], "correct_answer": "成年", "explanations": {"成年": "正确：成年与未成年互为反义词，指已经长大、达到成年年龄。", "乐观": "乐观形容对待生活的态度，不是“未成年”的反义词。", "稳重": "稳重形容性格沉稳，与“未成年”没有反义关系。", "富有": "富有形容拥有财富或某种丰富的品质，与“未成年”无关，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90707, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "未成年是说年纪还小，还没有长成大人。", "primary_collocate": null, "pronunciation": "wèi chéng nián", "ipa": "wei˥˩ ʈʂʰəŋ˧˥ njɛn˧˥", "syllable_count": 3, "sentences": [{"text": "他们还未成年，需要大人照顾。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些孩子都未成年，别让他们喝酒。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他未成年，所以没有工作。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子未成年，还不懂很多事。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她未成年的时候就一个人出国了。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未成年的弟弟很喜欢踢球。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我侄子还未成年，平时只在家里玩。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小男孩未成年，家里人都很爱他。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未成年的孩子要多睡觉。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妹妹还未成年，不能一个人去远处。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "未成年人", "label": "复合"}, {"form": "未成年的", "label": "复合"}], "register": "中性", "sense_fingerprint": "未成年：年纪还小，还没长成大人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0a5c81-35f2-4930-926c-6a53b5a7efb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90707, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未成年", "is_correct": true, "explanation": "正确：“未成年”说年纪还小，需要大人照顾，与句意相符。"}, {"text": "成年", "is_correct": false, "explanation": "语义：成年后一般不需要大人照顾，与后句“需要大人照顾”矛盾。"}, {"text": "独立", "is_correct": false, "explanation": "语义：独立的人不需要大人照顾，与后句“需要大人照顾”矛盾。"}, {"text": "健壮", "is_correct": false, "explanation": "体貌：“健壮”描写体格，不说“还健壮”，与“需要大人照顾”也不相符。"}], "explanations": {"未成年": "正确：“未成年”说年纪还小，需要大人照顾，与句意相符。", "成年": "语义：成年后一般不需要大人照顾，与后句“需要大人照顾”矛盾。", "独立": "语义：独立的人不需要大人照顾，与后句“需要大人照顾”矛盾。", "健壮": "体貌：“健壮”描写体格，不说“还健壮”，与“需要大人照顾”也不相符。"}, "sentence_index": 0, "correct_answer": "未成年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的未成年很快乐，常和朋友玩。", "explanation": "这里应该用〈童年〉。未成年指还没长大的状态，不指一段时期，那段时光要说“童年”。"}, {"text": "这台机器还未成年，所以总是出故障。", "explanation": "这里应该用〈调试〉。未成年只用于指人，机器应说“还没调试好”。"}, {"text": "这座新房子还未成年，还不能住人。", "explanation": "这里应该用〈竣工〉。未成年只用于指人，房子应说“还未竣工”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90707, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未成年", "is_correct": true, "explanation": "正确：“未成年”说年纪小，与“平时只在家里玩”相符。"}, {"text": "外向", "is_correct": false, "explanation": "语义：外向的人爱外出活动，与“平时只在家里玩”矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”说身材，与“平时只在家里玩”没有关系，且不说“还高大”。"}, {"text": "精明", "is_correct": false, "explanation": "语义：精明的人懂得谋生和外出办事，与“平时只在家里玩”不相符。"}], "explanations": {"未成年": "正确：“未成年”说年纪小，与“平时只在家里玩”相符。", "外向": "语义：外向的人爱外出活动，与“平时只在家里玩”矛盾。", "高大": "体貌：“高大”说身材，与“平时只在家里玩”没有关系，且不说“还高大”。", "精明": "语义：精明的人懂得谋生和外出办事，与“平时只在家里玩”不相符。"}, "sentence_index": 6, "correct_answer": "未成年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门语言还未成年，很多词还在变。", "explanation": "这里应该用〈发展〉。未成年只用于指人，语言应说“还在发展”。"}, {"text": "这座桥还未成年，还不能通车。", "explanation": "这里应该用〈建成〉。未成年只用于指人，桥应说“还没建成”。"}, {"text": "这家餐厅还未成年，还在试营业。", "explanation": "这里应该用〈开业〉。未成年只用于指人，餐厅应说“还没开业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90707, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个未成年地男孩需要大人照顾。", "corrected_sentence": "那个未成年的男孩需要大人照顾。", "error_description": "错误：修饰名词要用“的”，不用“地”。应说“未成年的男孩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90707, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子很未成年，所以还不懂事。", "corrected_sentence": "这个孩子未成年，所以还不懂事。", "error_description": "错误：“未成年”前不能加程度副词“很”。应说“这个孩子未成年”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90708, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "成年", "is_correct": true, "explanation": "正确：成年与未成年互为反义词，指已达到法定成年年龄。"}, {"text": "健康", "is_correct": false, "explanation": "健康形容身体状况，不是“未成年”的反义词。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明形容头脑，与“未成年”的年龄概念无关，不构成反义。"}, {"text": "勇敢", "is_correct": false, "explanation": "勇敢形容性格，与“未成年”没有反义关系。"}], "correct_answer": "成年", "explanations": {"成年": "正确：成年与未成年互为反义词，指已达到法定成年年龄。", "健康": "健康形容身体状况，不是“未成年”的反义词。", "聪明": "聪明形容头脑，与“未成年”的年龄概念无关，不构成反义。", "勇敢": "勇敢形容性格，与“未成年”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90708, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "成年", "is_correct": true, "explanation": "正确：成年与未成年互为反义词，指已达到法定成年年龄。"}, {"text": "严肃", "is_correct": false, "explanation": "严肃形容态度或神情，不是“未成年”的反义词。"}, {"text": "热情", "is_correct": false, "explanation": "热情形容待人的态度，与“未成年”没有反义关系。"}, {"text": "诚实", "is_correct": false, "explanation": "诚实形容品德，与“未成年”的年龄概念无关，不构成反义。"}], "correct_answer": "成年", "explanations": {"成年": "正确：成年与未成年互为反义词，指已达到法定成年年龄。", "严肃": "严肃形容态度或神情，不是“未成年”的反义词。", "热情": "热情形容待人的态度，与“未成年”没有反义关系。", "诚实": "诚实形容品德，与“未成年”的年龄概念无关，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90708, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "还没有达到成年的法定年龄。", "primary_collocate": null, "pronunciation": "wèi chéng nián", "ipa": "wei˥˩ ʈʂʰəŋ˧˥ njɛn˧˥", "syllable_count": 3, "sentences": [{"text": "他还未成年，不能自己开车。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未成年的孩子不能进网吧。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今年才十六岁，还未成年。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律上，未成年的学生不能结婚。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为未成年，他不能买酒。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏不让未成年的孩子玩。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未成年的他不能签合同。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们都未成年，不能一个人住酒店。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十七岁的哥哥还未成年。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未成年的客人请家长陪同。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "未成年人", "label": "复合"}, {"form": "未成年的", "label": "复合"}], "register": "中性", "sense_fingerprint": "未成年：尚未达到法定成年年龄", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0a5c81-35f2-4930-926c-6a53b5a7efb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90708, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未成年", "is_correct": true, "explanation": "正确：“未成年”说明没到法定年龄，与“不能自己开车”相符。"}, {"text": "成年", "is_correct": false, "explanation": "语义：成年人可以自己开车，与后句“不能自己开车”矛盾。"}, {"text": "熟练", "is_correct": false, "explanation": "语义：“熟练”说明驾驶能力强，与“不能自己开车”矛盾。"}, {"text": "完整", "is_correct": false, "explanation": "搭配：“完整”不用来形容人的年龄或资格，“他还完整”不通。"}], "explanations": {"未成年": "正确：“未成年”说明没到法定年龄，与“不能自己开车”相符。", "成年": "语义：成年人可以自己开车，与后句“不能自己开车”矛盾。", "熟练": "语义：“熟练”说明驾驶能力强，与“不能自己开车”矛盾。", "完整": "搭配：“完整”不用来形容人的年龄或资格，“他还完整”不通。"}, "sentence_index": 0, "correct_answer": "未成年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个计划还未成年，需要再讨论。", "explanation": "这里应该用〈成熟〉。未成年只用于指人，指没到法定年龄；计划应说“还未成熟”。"}, {"text": "这家公司还未成年，不能参加招标。", "explanation": "这里应该用〈成立〉。未成年只用于指人，公司应说“还未成立”。"}, {"text": "树上的苹果还未成年，现在还不能摘。", "explanation": "这里应该用〈成熟〉。未成年只用于指人，水果应说“还未成熟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90708, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未成年", "is_correct": true, "explanation": "正确：“未成年”说明没到法定年龄，与“不能签合同”相符。"}, {"text": "老练", "is_correct": false, "explanation": "语义：“老练”说明能力强，与“不能签合同”矛盾。"}, {"text": "成功", "is_correct": false, "explanation": "语义：“成功”说明事情办成了，“成功的他不能签合同”说不通，也与年龄资格无关。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”说身材，与签合同的资格无关，句子不通。"}], "explanations": {"未成年": "正确：“未成年”说明没到法定年龄，与“不能签合同”相符。", "老练": "语义：“老练”说明能力强，与“不能签合同”矛盾。", "成功": "语义：“成功”说明事情办成了，“成功的他不能签合同”说不通，也与年龄资格无关。", "高大": "体貌：“高大”说身材，与签合同的资格无关，句子不通。"}, "sentence_index": 6, "correct_answer": "未成年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盆花还未成年，还不能开花。", "explanation": "这里应该用〈长大〉。未成年只用于指人，植物应说“还没长大”。"}, {"text": "这次项目还未成年，还要等审批。", "explanation": "这里应该用〈启动〉。未成年只用于指人，项目应说“还未启动”。"}, {"text": "这套制度还未成年，还需要磨合。", "explanation": "这里应该用〈成熟〉。未成年只用于指人，制度应说“还不成熟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90708, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹还未成年了，不能喝酒。", "corrected_sentence": "我妹妹还未成年，不能喝酒。", "error_description": "错误：“还未成年”表示状态还没有改变，不能再加表示变化完成的“了”。应说“我妹妹还未成年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位未成年地顾客需要家长陪同。", "corrected_sentence": "那位未成年的顾客需要家长陪同。", "error_description": "错误：修饰名词要用“的”，不用“地”。“地”用于修饰动词，应说“未成年的顾客”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
