INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90710, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "成双的两个；量词，用于成双的人或物。", "primary_collocate": null, "pronunciation": "yí duì", "ipa": "i˧˥ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "她买了一对红色的耳环。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着一对花瓶。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口有一对石狮子。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟有一对漂亮的翅膀。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送了朋友一对杯子。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一对枕头很软。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗边挂着一对红灯笼。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有一对大眼睛。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶戴着一对玉镯。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里摆着一对旧椅子。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "两对", "label": "数量"}, {"form": "几对", "label": "数量"}], "register": "中性", "sense_fingerprint": "用于成双成套的物品，如耳环、花瓶、灯笼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: 镯 (Zipf 2.13)']::text[], '624b5296-b316-469e-b898-2490f7fe2795') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90710, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一对", "is_correct": true, "explanation": "正确：“一对”指成双的物件，耳环成对佩戴。"}, {"text": "一条", "is_correct": false, "explanation": "搭配：“条”用于细长的物件，耳环不用“条”计量。"}, {"text": "一根", "is_correct": false, "explanation": "搭配：“根”用于细长的棍状物，不用于计量耳环。"}, {"text": "一张", "is_correct": false, "explanation": "语义：“张”指平面的物品，耳环是小件首饰，与句意不合。"}], "explanations": {"一对": "正确：“一对”指成双的物件，耳环成对佩戴。", "一条": "搭配：“条”用于细长的物件，耳环不用“条”计量。", "一根": "搭配：“根”用于细长的棍状物，不用于计量耳环。", "一张": "语义：“张”指平面的物品，耳环是小件首饰，与句意不合。"}, "sentence_index": 0, "correct_answer": "一对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌上放着一对课本。", "explanation": "这里应该用〈一本〉。课本是单个的，不成对，不能用“一对”计量。"}, {"text": "他戴着一对眼镜。", "explanation": "这里应该用〈一副〉。眼镜是成套的物件，用“副”计量；“一对”多用于成双的物件。"}, {"text": "院子里晾着一对被子。", "explanation": "这里应该用〈一床〉。被子用“床”计量，单件被子不能用“一对”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一对", "is_correct": true, "explanation": "正确：“一对”指成双的物件，灯笼成对悬挂。"}, {"text": "一朵", "is_correct": false, "explanation": "搭配：“朵”用于花朵或云朵，不用于灯笼。"}, {"text": "一座", "is_correct": false, "explanation": "语义：“座”指大型的建筑或固定物体，灯笼太小，与句意不合。"}, {"text": "一扇", "is_correct": false, "explanation": "搭配：“扇”用于门窗，不用于计量灯笼。"}], "explanations": {"一对": "正确：“一对”指成双的物件，灯笼成对悬挂。", "一朵": "搭配：“朵”用于花朵或云朵，不用于灯笼。", "一座": "语义：“座”指大型的建筑或固定物体，灯笼太小，与句意不合。", "一扇": "搭配：“扇”用于门窗，不用于计量灯笼。"}, "sentence_index": 6, "correct_answer": "一对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一对裤子。", "explanation": "这里应该用〈一条〉。裤子是一件物品，用“条”计量，不能用“一对”。"}, {"text": "信箱里有一对信。", "explanation": "这里应该用〈一封〉。信是单个的，用“封”计量，不能用“一对”。"}, {"text": "他买了一对牙膏。", "explanation": "这里应该用〈一管〉。牙膏用“管”计量，单管牙膏不能用“一对”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗台上摆着一对的小花瓶。", "corrected_sentence": "窗台上摆着一对小花瓶。", "error_description": "错误形式「一对的小花瓶」；正确形式「一对小花瓶」。量词「一对」后面不能直接加「的」，应直接修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "床头摆着一对的小铜镜。", "corrected_sentence": "床头摆着一对小铜镜。", "error_description": "错误形式「一对的小铜镜」；正确形式「一对小铜镜」。量词「一对」后面不能直接加「的」，应直接修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
