INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90711, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "凭是靠着一样东西来做事。", "primary_collocate": null, "pronunciation": "píng", "ipa": "pʰiŋ˧˥", "syllable_count": 1, "sentences": [{"text": "他凭本事吃饭，不靠别人。", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她凭努力考上了大学。", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们凭自己的双手过上了好日子。", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王凭一副好嗓子当上了歌手。", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他凭着一股热情做完了这件事。", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民凭力气和汗水养活一家人。", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想赢就得凭实力，不能靠运气。", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老人凭记忆画出了老家的样子。", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我凭这点钱做不了大生意。", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他凭一张嘴说服了所有人。", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "凭着", "label": "体标"}], "register": "中性", "sense_fingerprint": "凭·靠着自身本领或条件做成事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '752a5636-7271-49eb-b21b-15ae1b5105ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90711, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "凭", "is_correct": true, "explanation": "正确：读 píng（第二声），意思是靠着自身的本领或条件。"}, {"text": "频", "is_correct": false, "explanation": "pín（第二声）与 píng 韵母不同（-n 与 -ng），意思是频率。"}, {"text": "捧", "is_correct": false, "explanation": "pěng（第三声）与 píng 韵母（eng 与 ing）与声调都不同，意思是双手托着。"}, {"text": "拼", "is_correct": false, "explanation": "pīn（第一声）与 píng 韵母不同（-n 与 -ng），声调也不同，意思是拼合。"}, {"text": "聘", "is_correct": false, "explanation": "pìn（第四声）与 píng 韵母不同（-n 与 -ng），声调也不同，意思是聘请。"}], "explanations": {"凭": "正确：读 píng（第二声），意思是靠着自身的本领或条件。", "频": "pín（第二声）与 píng 韵母不同（-n 与 -ng），意思是频率。", "捧": "pěng（第三声）与 píng 韵母（eng 与 ing）与声调都不同，意思是双手托着。", "拼": "pīn（第一声）与 píng 韵母不同（-n 与 -ng），声调也不同，意思是拼合。", "聘": "pìn（第四声）与 píng 韵母不同（-n 与 -ng），声调也不同，意思是聘请。"}, "sentence_index": null, "correct_answer": "凭"}, "level_3": {"options": [{"text": "凭", "is_correct": true, "explanation": "正确：“凭”表示靠着本事，“凭本事吃饭”句意通顺。"}, {"text": "为", "is_correct": false, "explanation": "语义：“为”表示为了某个目的，本事不能成为吃饭的目的，句意不通。"}, {"text": "对", "is_correct": false, "explanation": "搭配：“对”后接对象，“对本事吃饭”不成搭配。"}, {"text": "向", "is_correct": false, "explanation": "搭配：“向”引出对象或方向，不能用来说明靠什么吃饭。"}], "explanations": {"凭": "正确：“凭”表示靠着本事，“凭本事吃饭”句意通顺。", "为": "语义：“为”表示为了某个目的，本事不能成为吃饭的目的，句意不通。", "对": "搭配：“对”后接对象，“对本事吃饭”不成搭配。", "向": "搭配：“向”引出对象或方向，不能用来说明靠什么吃饭。"}, "sentence_index": 0, "correct_answer": "凭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我凭这件事很生气，所以走了。", "explanation": "这里应该用〈因为〉（“我因为这件事很生气，所以走了”）。凭表示依据或凭借，不表示原因，与本义“靠自身本领做成事”不同。"}, {"text": "这批货凭上海运到了北京。", "explanation": "这里应该用〈从〉。凭表示依据，不表示起点，说明货物的起点要用“从”，与本义“靠自身本领做成事”不同。"}, {"text": "他凭妹妹一起去了上海。", "explanation": "这里应该用〈和〉。凭表示依据或凭借，不表示伴随，与人一起去要说“和”，与本义“靠自身本领做成事”不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90711, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "凭", "is_correct": true, "explanation": "正确：读 píng（第二声），意思是靠着自身的本领或条件。"}, {"text": "贫", "is_correct": false, "explanation": "pín（第二声）与 píng 韵母不同（-n 与 -ng），意思是贫穷。"}, {"text": "碰", "is_correct": false, "explanation": "pèng（第四声）与 píng 韵母（eng 与 ing）与声调都不同，意思是碰撞。"}, {"text": "砰", "is_correct": false, "explanation": "pēng（第一声）与 píng 声调不同，是象声词，表示撞击的声音。"}, {"text": "拼", "is_correct": false, "explanation": "pīn（第一声）与 píng 韵母不同（-n 与 -ng），声调也不同，意思是拼合。"}], "explanations": {"凭": "正确：读 píng（第二声），意思是靠着自身的本领或条件。", "贫": "pín（第二声）与 píng 韵母不同（-n 与 -ng），意思是贫穷。", "碰": "pèng（第四声）与 píng 韵母（eng 与 ing）与声调都不同，意思是碰撞。", "砰": "pēng（第一声）与 píng 声调不同，是象声词，表示撞击的声音。", "拼": "pīn（第一声）与 píng 韵母不同（-n 与 -ng），声调也不同，意思是拼合。"}, "sentence_index": null, "correct_answer": "凭"}, "level_3": {"options": [{"text": "凭", "is_correct": true, "explanation": "正确：“凭”表示依靠实力，“凭实力”与“不能靠运气”形成对比，句意通顺。"}, {"text": "跟", "is_correct": false, "explanation": "搭配：“跟”引出共同行动的对象，“跟实力”不成搭配。"}, {"text": "和", "is_correct": false, "explanation": "搭配：“和”连接并列的事物，不能说“想赢就得和实力”。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替他人，实力不能被代替，句意不通。"}], "explanations": {"凭": "正确：“凭”表示依靠实力，“凭实力”与“不能靠运气”形成对比，句意通顺。", "跟": "搭配：“跟”引出共同行动的对象，“跟实力”不成搭配。", "和": "搭配：“和”连接并列的事物，不能说“想赢就得和实力”。", "替": "语义：“替”表示代替他人，实力不能被代替，句意不通。"}, "sentence_index": 6, "correct_answer": "凭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我凭三天时间就做完了作业。", "explanation": "这里应该用〈花〉。凭表示依据，不表示花费时间，说“花三天时间”才对，与本义“靠自身本领做成事”不同。"}, {"text": "他凭下午来了学校。", "explanation": "这里应该用〈在〉（“他在下午来了学校”）。凭表示依据或凭借，不表示时间，与本义“靠自身本领做成事”不同。"}, {"text": "凭天气好，我们去了郊外。", "explanation": "这里应该用〈因为〉。凭不表示原因，说明原因要用“因为”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90711, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他凭了自己的双手赚钱养家。", "corrected_sentence": "他凭自己的双手赚钱养家。", "error_description": "“凭”是介词，后面不能加体标“了”。应说“他凭自己的双手赚钱养家”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90711, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她凭的一手好厨艺开了一家饭馆。", "corrected_sentence": "她凭一手好厨艺开了一家饭馆。", "error_description": "“凭”是介词，不能用“的”来修饰。应说“她凭一手好厨艺”，去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
