INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90712, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "根据某种凭证或依据。", "primary_collocate": null, "pronunciation": "píng", "ipa": "pʰiŋ˧˥", "syllable_count": 1, "sentences": [{"text": "进场要凭票，没有票不能进。", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你凭什么说他没有来过？", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生凭经验就能看出问题。", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "取包裹时，要凭取件码。", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师凭声音就认出了我。", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住店要凭身份证登记。", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察凭指纹找到了那个人。", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他凭着护照顺利过了海关。", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凭这张卡，你可以免费喝咖啡。", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官不能凭感觉，要凭证据判案。", "target_word": "凭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "凭着", "label": "体标"}], "register": "中性", "sense_fingerprint": "凭·根据某种凭证或依据", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '752a5636-7271-49eb-b21b-15ae1b5105ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90712, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "凭", "is_correct": true, "explanation": "正确：读 píng（第二声），意思是依据、凭借。"}, {"text": "贫", "is_correct": false, "explanation": "pín（第二声）与 píng 韵母不同（-n 与 -ng），意思是贫穷。"}, {"text": "碰", "is_correct": false, "explanation": "pèng（第四声）与 píng 韵母（eng 与 ing）与声调都不同，意思是碰撞。"}, {"text": "捧", "is_correct": false, "explanation": "pěng（第三声）与 píng 韵母（eng 与 ing）与声调都不同，意思是双手托着。"}, {"text": "停", "is_correct": false, "explanation": "tíng 与 píng 声母不同（t 与 p），意思是停止。"}, {"text": "冰", "is_correct": false, "explanation": "bīng（第一声）与 píng 声母不同（b 与 p），声调也不同，意思是冰。"}], "explanations": {"凭": "正确：读 píng（第二声），意思是依据、凭借。", "贫": "pín（第二声）与 píng 韵母不同（-n 与 -ng），意思是贫穷。", "碰": "pèng（第四声）与 píng 韵母（eng 与 ing）与声调都不同，意思是碰撞。", "捧": "pěng（第三声）与 píng 韵母（eng 与 ing）与声调都不同，意思是双手托着。", "停": "tíng 与 píng 声母不同（t 与 p），意思是停止。", "冰": "bīng（第一声）与 píng 声母不同（b 与 p），声调也不同，意思是冰。"}, "sentence_index": null, "correct_answer": "凭"}, "level_3": {"options": [{"text": "凭", "is_correct": true, "explanation": "正确：“凭”是介词，表示以票为依据，句意通顺。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替他人做事，票无法代替人，“要替票”句意不通。"}, {"text": "向", "is_correct": false, "explanation": "搭配：“向”后要接人或方向，不能接“票”。"}, {"text": "对", "is_correct": false, "explanation": "搭配：“对”后接对象，“对票”不成搭配，句意不通。"}], "explanations": {"凭": "正确：“凭”是介词，表示以票为依据，句意通顺。", "替": "语义：“替”表示代替他人做事，票无法代替人，“要替票”句意不通。", "向": "搭配：“向”后要接人或方向，不能接“票”。", "对": "搭配：“对”后接对象，“对票”不成搭配，句意不通。"}, "sentence_index": 0, "correct_answer": "凭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他凭一辆自行车去了学校。", "explanation": "这里应该用〈骑〉。凭表示依据凭证或条件，骑车出行要说“骑”，与本义“根据凭证或依据”不同。"}, {"text": "我凭两小时就学会了游泳。", "explanation": "这里应该用〈花〉。凭表示依据凭证或条件，不表示花费时间，说“花两小时”才对，与本义“根据凭证或依据”不同。"}, {"text": "他凭朋友一起去了北京。", "explanation": "这里应该用〈和〉。凭表示依据或凭借，不表示伴随，与朋友一起去要说“和”，与本义“根据凭证或依据”不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90712, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "凭", "is_correct": true, "explanation": "正确：读 píng（第二声），意思是依据、凭借。"}, {"text": "频", "is_correct": false, "explanation": "pín（第二声）与 píng 韵母不同（-n 与 -ng），意思是频率、频繁。"}, {"text": "砰", "is_correct": false, "explanation": "pēng（第一声）与 píng 声调不同，是象声词，表示撞击或爆炸的声音。"}, {"text": "亭", "is_correct": false, "explanation": "tíng（第二声）与 píng 声母不同（t 与 p），意思是亭子。"}, {"text": "拼", "is_correct": false, "explanation": "pīn（第一声）与 píng 韵母不同（-n 与 -ng），声调也不同，意思是拼合。"}, {"text": "兵", "is_correct": false, "explanation": "bīng（第一声）与 píng 声母不同（b 与 p），声调也不同，意思是士兵。"}], "explanations": {"凭": "正确：读 píng（第二声），意思是依据、凭借。", "频": "pín（第二声）与 píng 韵母不同（-n 与 -ng），意思是频率、频繁。", "砰": "pēng（第一声）与 píng 声调不同，是象声词，表示撞击或爆炸的声音。", "亭": "tíng（第二声）与 píng 声母不同（t 与 p），意思是亭子。", "拼": "pīn（第一声）与 píng 韵母不同（-n 与 -ng），声调也不同，意思是拼合。", "兵": "bīng（第一声）与 píng 声母不同（b 与 p），声调也不同，意思是士兵。"}, "sentence_index": null, "correct_answer": "凭"}, "level_3": {"options": [{"text": "凭", "is_correct": true, "explanation": "正确：“凭”表示依据，指纹是找到人的依据，句意通顺。"}, {"text": "跟", "is_correct": false, "explanation": "搭配：“跟”引出共同行动的对象，“跟指纹”不成搭配。"}, {"text": "为", "is_correct": false, "explanation": "语义：“为”表示为了某个目的，指纹不能成为找人的目的，句意不通。"}, {"text": "和", "is_correct": false, "explanation": "搭配：“和”连接并列的人或事物，不能与“指纹”构成状语。"}], "explanations": {"凭": "正确：“凭”表示依据，指纹是找到人的依据，句意通顺。", "跟": "搭配：“跟”引出共同行动的对象，“跟指纹”不成搭配。", "为": "语义：“为”表示为了某个目的，指纹不能成为找人的目的，句意不通。", "和": "搭配：“和”连接并列的人或事物，不能与“指纹”构成状语。"}, "sentence_index": 6, "correct_answer": "凭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他凭父母养活，自己从不工作。", "explanation": "这里应该用〈靠〉。凭指依据凭证或自身条件，依赖他人养活要说“靠”，与本义“根据凭证或依据”不同。"}, {"text": "他凭一根绳子把箱子拉上了楼。", "explanation": "这里应该用〈用〉。凭表示依据凭证或条件，用绳子拉箱子是具体动作，要说“用”，与本义“根据凭证或依据”不同。"}, {"text": "凭天气好，我们去了郊外。", "explanation": "这里应该用〈因为〉。凭不表示原因，说明原因要用“因为”，与“根据凭证或依据”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "坐飞机要凭办理登机。", "corrected_sentence": "坐飞机要凭身份证办理登机。", "error_description": "“凭”是介词，后面必须带上依据的东西（如“身份证”），不能直接接动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他凭了一张照片认出了那个小偷。", "corrected_sentence": "他凭一张照片认出了那个小偷。", "error_description": "“凭”是介词，后面不能加体标“了”。应说“他凭一张照片认出了那个小偷”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
