INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90713, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "本性是一个人天生就有的性格。", "primary_collocate": null, "pronunciation": "běn xìng", "ipa": "pən˨˩˦ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他本性善良，总是帮助别人。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "江山易改，本性难移。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这孩子本性很活泼。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她本性不坏，只是脾气急。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的本性很害羞，不爱说话。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境会变，可是人的本性不容易变。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他终于露出了自己的本性。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，每个孩子的本性都不一样。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他本性爱玩，不喜欢坐着学习。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她本性乐观，遇到难事也不哭。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人天生的性格，不容易改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0120cb63-e99a-4427-ab15-5932136b311c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90713, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本性", "is_correct": true, "explanation": "本性指人天生的性格，“善良”是其内在品性。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用“善良”来形容。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是身体特征，不能用“善良”来形容。"}, {"text": "动作", "is_correct": false, "explanation": "搭配：“善良”一般修饰人的品性，不用来修饰“动作”。"}], "explanations": {"本性": "本性指人天生的性格，“善良”是其内在品性。", "颜色": "语义：颜色不能用“善良”来形容。", "身高": "语义：身高是身体特征，不能用“善良”来形容。", "动作": "搭配：“善良”一般修饰人的品性，不用来修饰“动作”。"}, "sentence_index": 0, "correct_answer": "本性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从小养成了早睡的本性。", "explanation": "这里应该用〈习惯〉。习惯是后天养成的，本性是天生的，不能说“养成本性”。"}, {"text": "他的本性是老师，教我们数学。", "explanation": "这里应该用〈身份〉。身份指社会角色，本性指天生的性格，不能说“本性是老师”。"}, {"text": "他的本性是钓鱼。", "explanation": "这里应该用〈爱好〉。爱好是后天培养的兴趣，本性指天生的性格，不能说“本性是钓鱼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90713, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本性", "is_correct": true, "explanation": "本性指人天生的性格，“终于露出”指内在的真实一面显现出来。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是岁数，不是性格，不能“露出”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的数值，不能用“露出”来表达。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“露出”一般不接“名字”，这里要表达内在性格。"}], "explanations": {"本性": "本性指人天生的性格，“终于露出”指内在的真实一面显现出来。", "年龄": "语义：年龄是岁数，不是性格，不能“露出”。", "体重": "语义：体重是身体的数值，不能用“露出”来表达。", "名字": "搭配：“露出”一般不接“名字”，这里要表达内在性格。"}, "sentence_index": 6, "correct_answer": "本性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今天本性很好，大家都很开心。", "explanation": "这里应该用〈心情〉。心情是一时的，本性是天生稳定的性格，不能说“今天本性很好”。"}, {"text": "他的本性很白，医生说要多晒太阳。", "explanation": "这里应该用〈脸色〉。脸色是外表，本性指天生的性格，不能说“本性很白”。"}, {"text": "他的本性很大，隔壁都听见了。", "explanation": "这里应该用〈声音〉。声音有大小，本性是性格，不能用“很大”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90713, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她很本性善良，从不骗人。", "corrected_sentence": "她本性善良，从不骗人。", "error_description": "程度副词错误：“很”不能放在“本性”前面，应删去“很”。正确说法是“她本性善良”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90713, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他喝醉以后，露出了很本性。", "corrected_sentence": "他喝醉以后，露出了本性。", "error_description": "程度副词错误：“本性”是名词，不能用“很”修饰，应删去“很”，说“露出了本性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
