INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90714, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90714, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "天生的性格或习性。", "primary_collocate": null, "pronunciation": "běn xìng", "ipa": "pən˨˩˦ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "鸟爱唱歌是它们的本性。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫爱干净是它的本性。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狼的本性很凶。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兔子胆小是它的本性。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗爱跑爱跳，这是它的本性。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼离不开水，这是它的本性。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要改变孩子爱问问题的本性。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎本性凶猛，不能当宠物养。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂爱花，这是它们的本性。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的本性就是爱笑，大家都喜欢他。", "target_word": "本性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人或动物天生的性格和习性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0120cb63-e99a-4427-ab15-5932136b311c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90714, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本性", "is_correct": true, "explanation": "本性指动物天生的习性，“鸟爱唱歌”正是它们的习性。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是外貌，不是习性，“爱唱歌”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“是它们的体重”与“爱唱歌”搭配不成立。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指岁数，不是习性，不能说“爱唱歌是年龄”。"}], "explanations": {"本性": "本性指动物天生的习性，“鸟爱唱歌”正是它们的习性。", "颜色": "语义：颜色是外貌，不是习性，“爱唱歌”说不通。", "体重": "搭配：“是它们的体重”与“爱唱歌”搭配不成立。", "年龄": "语义：年龄指岁数，不是习性，不能说“爱唱歌是年龄”。"}, "sentence_index": 0, "correct_answer": "本性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小猫养成了每天洗脸的本性。", "explanation": "这里应该用〈习惯〉。习惯是后天养成的，本性是天生的，不能说“养成本性”。"}, {"text": "这只猫的本性是黑色的。", "explanation": "这里应该用〈颜色〉。颜色是外貌特征，本性指天生的习性，不能说“本性是黑色的”。"}, {"text": "这只老虎的本性是三岁。", "explanation": "这里应该用〈年龄〉。年龄指岁数，不是天生的习性，不能说“本性是三岁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90714, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本性", "is_correct": true, "explanation": "本性指天生的性格，“改变孩子爱问问题的本性”指不要改掉这一天性。"}, {"text": "长相", "is_correct": false, "explanation": "语义：长相是外貌，不能说“改变爱问问题的长相”。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是身体特征，与“爱问问题”无关。"}, {"text": "脸色", "is_correct": false, "explanation": "搭配：“脸色”不说“爱问问题的脸色”，搭配不通。"}], "explanations": {"本性": "本性指天生的性格，“改变孩子爱问问题的本性”指不要改掉这一天性。", "长相": "语义：长相是外貌，不能说“改变爱问问题的长相”。", "身高": "语义：身高是身体特征，与“爱问问题”无关。", "脸色": "搭配：“脸色”不说“爱问问题的脸色”，搭配不通。"}, "sentence_index": 6, "correct_answer": "本性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "猫今天的本性很好，一直在玩。", "explanation": "这里应该用〈心情〉。心情是一时的，本性是天生的习性，不能说“今天的本性很好”。"}, {"text": "小鸟的本性很好听，每天都唱。", "explanation": "这里应该用〈叫声〉。叫声是发出的声音，本性指天生的习性，不能说“本性很好听”。"}, {"text": "这头牛本性很大，能拉好几吨。", "explanation": "这里应该用〈力气〉。力气是体力，本性不能用来描述力气大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "熊冬天冬眠，这是它很本性。", "corrected_sentence": "熊冬天冬眠，这是它的本性。", "error_description": "程度副词错误：“很”不能修饰名词“本性”，应去掉“很”，用领属结构“它的本性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小狗爱咬拖鞋，这是它很本性。", "corrected_sentence": "小狗爱咬拖鞋，这是它的本性。", "error_description": "程度副词错误：“本性”是名词，不能用“很”修饰，应把“很”改成“的”，说“它的本性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
