INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90715, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用电脑或手机连到网络上，看里面的东西。", "primary_collocate": null, "pronunciation": "shàng wǎng", "ipa": "ʂɑŋ˥˩ wɑŋ˨˩", "syllable_count": 2, "sentences": [{"text": "我每天晚上都上网看新闻。", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手机上网查地图。", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的电脑今天不能上网。", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会上网买东西吗？", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在家上网看电视剧。", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家咖啡店可以免费上网。", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟喜欢上网看动画片。", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在图书馆上网找资料。", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天上网两个小时。", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子上网时，爸爸坐在旁边。", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上过网", "label": "体标"}, {"form": "上了网", "label": "体标"}, {"form": "上網", "label": "繁体"}], "register": "口语", "sense_fingerprint": "用电脑或手机连到网络上看东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20866e08-b43e-403c-ad2b-6b6e0b8a5d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90715, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上网", "is_correct": true, "explanation": "正确：“上网”指用电脑或手机连到网络，与“每天晚上看新闻”相符。"}, {"text": "上台", "is_correct": false, "explanation": "语义：“上台”指走到台子上，与“看新闻”的场景不符。"}, {"text": "上传", "is_correct": false, "explanation": "配价：“上传”要带受事宾语（如文件），这里没有宾语，不能说“上传看新闻”。"}, {"text": "上街", "is_correct": false, "explanation": "语义：“上街”指走到街上去，不能与“看新闻”构成动作和目的的关系。"}], "explanations": {"上网": "正确：“上网”指用电脑或手机连到网络，与“每天晚上看新闻”相符。", "上台": "语义：“上台”指走到台子上，与“看新闻”的场景不符。", "上传": "配价：“上传”要带受事宾语（如文件），这里没有宾语，不能说“上传看新闻”。", "上街": "语义：“上街”指走到街上去，不能与“看新闻”构成动作和目的的关系。"}, "sentence_index": 0, "correct_answer": "上网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他饿了，马上去饭馆上网。", "explanation": "这里应该用〈吃饭〉。上网只表示连接网络，饿了去饭馆要说“吃饭”。"}, {"text": "周末他上网拜访客户。", "explanation": "这里应该用〈上门〉。上门指亲自到对方所在的地方去，上网只表示连接网络，不能表示亲身前往。"}, {"text": "他每天早上八点去公司上网，下午五点下班。", "explanation": "这里应该用〈上班〉。上网只表示连接网络，去公司工作、与“下班”相对的是“上班”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90715, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上网", "is_correct": true, "explanation": "正确：“上网”指用电脑或手机连到网络，与“看动画片”相符。"}, {"text": "上课", "is_correct": false, "explanation": "语义：“上课”指在教室里学习，不能与“看动画片”并列。"}, {"text": "上班", "is_correct": false, "explanation": "语义：“上班”指去单位工作，与“看动画片”不相容。"}, {"text": "上学", "is_correct": false, "explanation": "搭配：“喜欢上学看动画片”不成立，“上学”不能作为“看动画片”的方式或目的。"}], "explanations": {"上网": "正确：“上网”指用电脑或手机连到网络，与“看动画片”相符。", "上课": "语义：“上课”指在教室里学习，不能与“看动画片”并列。", "上班": "语义：“上班”指去单位工作，与“看动画片”不相容。", "上学": "搭配：“喜欢上学看动画片”不成立，“上学”不能作为“看动画片”的方式或目的。"}, "sentence_index": 6, "correct_answer": "上网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一看见公交车，马上跑过去上网。", "explanation": "这里应该用〈上车〉。上网只表示连接网络，不能表示登上交通工具。"}, {"text": "他给妈妈上网，告诉她自己到家了。", "explanation": "这里应该用〈打电话〉。上网不能表示与人通话，也不能把“妈妈”作为接收者。"}, {"text": "妈妈下班后上网洗衣服。", "explanation": "这里的“上网”只表示连接网络，不能表示洗衣服这类家务活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90715, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天晚上网查天气。", "corrected_sentence": "我每天晚上上网查天气。", "error_description": "“上网”是动宾式离合词，不能去掉“上”而只用“网”作动词。错误形式：“网查天气”；正确形式：“上网查天气”；原因：“上”是动词的组成部分，不可省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90715, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹的平板很上网，也能看书。", "corrected_sentence": "妹妹的平板能上网，也能看书。", "error_description": "错误：程度副词「很」不能修饰动作动词「上网」。正确：表示可能的「能」应放在「上网」前，说「能上网」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
