INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90716, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90716, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "连接互联网浏览或使用网络。", "primary_collocate": null, "pronunciation": "shàng wǎng", "ipa": "ʂɑŋ˥˩ wɑŋ˨˩", "syllable_count": 2, "sentences": [{"text": "山里没有信号，没法上网。", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问这里的上网密码是多少？", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我上网回复了朋友的邮件。", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在宿舍上网聊天。", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国旅行时，我先买一张电话卡，好上网。", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她上网学习英语。", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机忘了交钱，不能上网了。", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在地铁里用流量上网看书。", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷也学会了上网。", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让学生上网查资料。", "target_word": "上网", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上过网", "label": "体标"}, {"form": "上了网", "label": "体标"}, {"form": "上網", "label": "繁体"}], "register": "口语", "sense_fingerprint": "连接互联网浏览或使用网络", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20866e08-b43e-403c-ad2b-6b6e0b8a5d75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90716, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上网", "is_correct": true, "explanation": "正确：“上网”指连接网络，与“山里没有信号，没法”相符。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”指去学校读书，与“没有信号”之间没有因果关系，句意不通。"}, {"text": "上台", "is_correct": false, "explanation": "语义：“上台”指走上台子，与信号的有无毫无关系，句意不通。"}, {"text": "上楼", "is_correct": false, "explanation": "语义：“上楼”指走到楼上去，与“山里没有信号”之间没有关系，句意不通。"}], "explanations": {"上网": "正确：“上网”指连接网络，与“山里没有信号，没法”相符。", "上学": "语义：“上学”指去学校读书，与“没有信号”之间没有因果关系，句意不通。", "上台": "语义：“上台”指走上台子，与信号的有无毫无关系，句意不通。", "上楼": "语义：“上楼”指走到楼上去，与“山里没有信号”之间没有关系，句意不通。"}, "sentence_index": 0, "correct_answer": "上网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一看见公交车来了，就赶紧上网。", "explanation": "这里应该用〈上车〉。上网只表示连接网络，不能表示登上交通工具。"}, {"text": "他跟朋友在广场上网，跳得很好。", "explanation": "这里的“上网”只表示连接网络，不能表示舞蹈这类身体活动。"}, {"text": "他每天晚上都上网洗澡。", "explanation": "这里的“上网”只表示连接网络，不能表示身体清洁这类个人护理活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上网", "is_correct": true, "explanation": "正确：“上网”指连接网络，与“手机欠费”造成的结果相符。"}, {"text": "上课", "is_correct": false, "explanation": "语义：“上课”指在教室学习，手机欠费不影响去上课，句意不通。"}, {"text": "上班", "is_correct": false, "explanation": "语义：“上班”指去单位工作，与手机欠费没有直接的因果关系。"}, {"text": "上街", "is_correct": false, "explanation": "搭配：“上街”指走到街上，与“不能……了”的因果搭配不上。"}], "explanations": {"上网": "正确：“上网”指连接网络，与“手机欠费”造成的结果相符。", "上课": "语义：“上课”指在教室学习，手机欠费不影响去上课，句意不通。", "上班": "语义：“上班”指去单位工作，与手机欠费没有直接的因果关系。", "上街": "搭配：“上街”指走到街上，与“不能……了”的因果搭配不上。"}, "sentence_index": 6, "correct_answer": "上网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给妈妈上网，告诉她自己到家了。", "explanation": "这里应该用〈打电话〉。上网不能表示与人通话，也不能把“妈妈”作为接收者。"}, {"text": "周末他在海边上网，收获了很多螃蟹。", "explanation": "这里应该用〈赶海〉。上网只表示连接网络，不能表示在海边捉螃蟹这类活动。"}, {"text": "我饭后去菜市场上网，买了一条鱼。", "explanation": "这里的“上网”只表示连接网络，不能表示买东西这类交易行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宿舍的网线修好了，我的电脑很上网了。", "corrected_sentence": "宿舍的网线修好了，我的电脑能上网了。", "error_description": "错误：程度副词「很」不能修饰动作动词「上网」。正确：表示可能的「能」应放在「上网」前，说「能上网了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟弟用手机很上网听歌。", "corrected_sentence": "弟弟用手机上网听歌。", "error_description": "错误形式：很上网；正确形式：上网（去掉“很”）。程度副词“很”修饰形容词或心理动词，不能修饰“上网”这类动作性的动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa96f0d6-b19b-4b34-bbb3-50e94e67c254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
