INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90718, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "植物生长在土里的部分，起固定和吸收养分的作用。", "primary_collocate": null, "pronunciation": "gēn", "ipa": "kən˥", "syllable_count": 1, "sentences": [{"text": "这棵树的根很深。", "target_word": "根", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "根在土里，我们看不见。", "target_word": "根", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大树的根能吸收水和养分。", "target_word": "根", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风很大，但是树的根抓得很紧。", "target_word": "根", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "草的根很细，却很长。", "target_word": "根", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这盆花的根烂了，叶子都黄了。", "target_word": "根", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用手把小树的根轻轻埋进土里。", "target_word": "根", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看见路边的大树露着根。", "target_word": "根", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根有固定树的作用，树才不会倒。", "target_word": "根", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天来了，树的根开始吸水。", "target_word": "根", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "树根", "label": "复合"}, {"form": "草根", "label": "复合"}, {"form": "根部", "label": "复合"}], "register": "中性", "sense_fingerprint": "植物长在土里、固定植株并吸收水分养分的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79e60a67-5d39-493a-b9c5-106ceed17226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90718, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "根", "is_correct": true, "explanation": "根：读 gēn（第一声），指植物长在土里的部分。"}, {"text": "干", "is_correct": false, "explanation": "gān（第一声）与 gēn 韵母不同（a 与 e），意思是干燥。"}, {"text": "耕", "is_correct": false, "explanation": "「gēng（第一声）与 gēn 韵母不同（eng 与 en），意思是耕种」。"}, {"text": "奔", "is_correct": false, "explanation": "「bēn（第一声）与 gēn 声母不同（b 与 g），意思是跑」。"}], "explanations": {"根": "根：读 gēn（第一声），指植物长在土里的部分。", "干": "gān（第一声）与 gēn 韵母不同（a 与 e），意思是干燥。", "耕": "「gēng（第一声）与 gēn 韵母不同（eng 与 en），意思是耕种」。", "奔": "「bēn（第一声）与 gēn 声母不同（b 与 g），意思是跑」。"}, "sentence_index": null, "correct_answer": "根"}, "level_3": {"options": [{"text": "根", "is_correct": true, "explanation": "根：指树在土里的部分，与「很深」搭配，符合句意。"}, {"text": "叶", "is_correct": false, "explanation": "语义：「叶」长在枝上，不能用「深」来形容。"}, {"text": "花", "is_correct": false, "explanation": "搭配：「花」与「很深」不能搭配。"}, {"text": "果", "is_correct": false, "explanation": "语义：「果」长在枝头，不能用「深」来形容。"}], "explanations": {"根": "根：指树在土里的部分，与「很深」搭配，符合句意。", "叶": "语义：「叶」长在枝上，不能用「深」来形容。", "花": "搭配：「花」与「很深」不能搭配。", "果": "语义：「果」长在枝头，不能用「深」来形容。"}, "sentence_index": 0, "correct_answer": "根"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵树有一只根很深。", "explanation": "这里应该用〈条〉。根是细长的东西，量词用条；只有动物才用只。"}, {"text": "这把椅子的根很结实。", "explanation": "这里应该用〈腿〉。椅子下面支撑座面的部分叫腿，根只指植物长在土里的部分。"}, {"text": "我把书放在桌子的根下。", "explanation": "这里应该用〈底下〉。说桌子下面的位置要用底下，根不能指物体的下方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90718, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "根", "is_correct": true, "explanation": "根：读 gēn（第一声），指植物长在土里的部分。"}, {"text": "奔", "is_correct": false, "explanation": "「bēn（第一声）与 gēn 声母不同（b 与 g），意思是跑」。"}, {"text": "羹", "is_correct": false, "explanation": "「gēng（第一声）与 gēn 韵母不同（eng 与 en），意思是汤羹」。"}, {"text": "甘", "is_correct": false, "explanation": "「gān（第一声）与 gēn 韵母不同（a 与 e），意思是甘甜」。"}], "explanations": {"根": "根：读 gēn（第一声），指植物长在土里的部分。", "奔": "「bēn（第一声）与 gēn 声母不同（b 与 g），意思是跑」。", "羹": "「gēng（第一声）与 gēn 韵母不同（eng 与 en），意思是汤羹」。", "甘": "「gān（第一声）与 gēn 韵母不同（a 与 e），意思是甘甜」。"}, "sentence_index": null, "correct_answer": "根"}, "level_3": {"options": [{"text": "根", "is_correct": true, "explanation": "根：树在土里的部分，「埋进土里」的是根，符合句意。"}, {"text": "花瓣", "is_correct": false, "explanation": "语义：「花瓣」是花的部分，不是小树的部分，不能埋进土里当作树根。"}, {"text": "石头", "is_correct": false, "explanation": "语义：小树没有「石头」这一部分，句中说的是树的部分。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：「玻璃」不能说成「小树的玻璃」。"}], "explanations": {"根": "根：树在土里的部分，「埋进土里」的是根，符合句意。", "花瓣": "语义：「花瓣」是花的部分，不是小树的部分，不能埋进土里当作树根。", "石头": "语义：小树没有「石头」这一部分，句中说的是树的部分。", "玻璃": "搭配：「玻璃」不能说成「小树的玻璃」。"}, "sentence_index": 6, "correct_answer": "根"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要找到根的解决办法。", "explanation": "这里应该用〈根本〉。修饰「解决办法」表示彻底要用根本，根只指植物的部分。"}, {"text": "这座雕像的根很稳。", "explanation": "这里应该用〈底座〉。雕像的底部要用底座，根只指植物长在土里的部分。"}, {"text": "这块地的根很肥。", "explanation": "这里应该用〈土壤〉。说土地的肥力要用土壤，根不能指土地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这棵小草有一只很短的根。", "corrected_sentence": "这棵小草有一条很短的根。", "error_description": "错误：量词「只」。正确：量词「条」。根是细长的东西，量词用「条」，「只」一般用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这棵大树的根树很粗。", "corrected_sentence": "这棵大树的树根很粗。", "error_description": "错误：「根树」。正确：「树根」。表示树的根时要用复合词「树根」，语序不能颠倒。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
