INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90719, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "本月是现在这个月。", "primary_collocate": null, "pronunciation": "běn yuè", "ipa": "pən˨˩ ɥœ˥˩", "syllable_count": 2, "sentences": [{"text": "本月我很忙，每天都加班。", "target_word": "本月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在是十一月，本月的工作快做完了。", "target_word": "本月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本月天气很冷，我常常穿厚衣服。", "target_word": "本月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店本月有很多便宜的东西。", "target_word": "本月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我本月的房租已经交了。", "target_word": "本月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本月十五号是妈妈的生日。", "target_word": "本月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他本月工资不多，只有四千块。", "target_word": "本月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校本月会开一次家长会。", "target_word": "本月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本月我看了五本书，比上月多。", "target_word": "本月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你本月把这些表格交给我。", "target_word": "本月", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本月初", "label": "复合"}, {"form": "本月底", "label": "复合"}], "register": "中性", "sense_fingerprint": "指现在所在的这个月份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbce584a-af1d-4384-840f-ffa4055c1833') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90719, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "本月", "is_correct": true, "explanation": "正确答案：本月（běn yuè），指现在所在的这个月。"}, {"text": "半月", "is_correct": false, "explanation": "bàn yuè 与 běn yuè 的第一音节韵母 en/an 不同，声调也不同（去声/上声），意思是半个月。"}, {"text": "本院", "is_correct": false, "explanation": "běn yuàn 与 běn yuè 的第二音节韵母不同（üe/uan），意思是本院，即这个机构。"}, {"text": "奔月", "is_correct": false, "explanation": "bēn yuè 与 běn yuè 只有第一音节声调不同（阴平/上声），意思是飞向月亮，如“嫦娥奔月”。"}], "explanations": {"本月": "正确答案：本月（běn yuè），指现在所在的这个月。", "半月": "bàn yuè 与 běn yuè 的第一音节韵母 en/an 不同，声调也不同（去声/上声），意思是半个月。", "本院": "běn yuàn 与 běn yuè 的第二音节韵母不同（üe/uan），意思是本院，即这个机构。", "奔月": "bēn yuè 与 běn yuè 只有第一音节声调不同（阴平/上声），意思是飞向月亮，如“嫦娥奔月”。"}, "sentence_index": null, "correct_answer": "本月"}, "level_3": {"options": [{"text": "本月", "is_correct": true, "explanation": "正确答案：本月。句子说的是这个月的忙碌状态。"}, {"text": "今天", "is_correct": false, "explanation": "语义：“今天”只指一天，与“每天都加班”的持续周期冲突。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”指过去的一天，与现在的忙碌状态以及“每天”不相容。"}, {"text": "本期", "is_correct": false, "explanation": "语域：“本期”是书面的刊期用语，口语叙述“我很忙”时不这样说。"}], "explanations": {"本月": "正确答案：本月。句子说的是这个月的忙碌状态。", "今天": "语义：“今天”只指一天，与“每天都加班”的持续周期冲突。", "昨天": "语义：“昨天”指过去的一天，与现在的忙碌状态以及“每天”不相容。", "本期": "语域：“本期”是书面的刊期用语，口语叙述“我很忙”时不这样说。"}, "sentence_index": 0, "correct_answer": "本月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一九九八年本月出生在上海。", "explanation": "本月指现在所在的月份，不能指过去某一年的月份。这里应该用〈那一年〉，或写出具体的年份和月份。"}, {"text": "这门课本月学了两年。", "explanation": "本月只指一个月之内，不能与“学了两年”这样的长时段搭配。这里应该说〈学了两年〉，不用本月。"}, {"text": "我们本月的第一次见面是去年十月。", "explanation": "这里把“本月”误用为指去年的某个月。应直接用〈去年十月〉，不能与“本月”同用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90719, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本月", "is_correct": true, "explanation": "正确答案：本月。句子说的是这个月的工资数额。"}, {"text": "每天", "is_correct": false, "explanation": "语义：工资按月计算，“每天”与“只有四千块”的月薪周期冲突。"}, {"text": "当天", "is_correct": false, "explanation": "语义：“当天”指单日，不能说明一个月的工资情况。"}, {"text": "本日", "is_correct": false, "explanation": "语域：“本日”偏书面，口语叙述工资时不这样说。"}], "explanations": {"本月": "正确答案：本月。句子说的是这个月的工资数额。", "每天": "语义：工资按月计算，“每天”与“只有四千块”的月薪周期冲突。", "当天": "语义：“当天”指单日，不能说明一个月的工资情况。", "本日": "语域：“本日”偏书面，口语叙述工资时不这样说。"}, "sentence_index": 6, "correct_answer": "本月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的奶奶是在我出生那一年的本月去世的。", "explanation": "这里把“本月”误用为指过去某一年的某个月。本月只指现在所在的月份，应改用具体的月份，如〈三月〉。"}, {"text": "这所学校在本月的一百年前就建成了。", "explanation": "这里把“本月”误用为指一百年前的某个时间。应直接说〈一百年前〉，不用“本月的”。"}, {"text": "这件事本月已经发生在我出生之前。", "explanation": "这里把“本月”误用为指过去的某个时间。这件事的时间应由具体的过去时间表达，不能用“本月”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90719, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我本月的去了北京。", "corrected_sentence": "我本月去了北京。", "error_description": "时间词“本月”作状语后不能加结构助词“的”，应直接放在动词前。错误形式：“我本月的去了北京”；正确形式：“我本月去了北京”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90719, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本月我要去上海出差。", "corrected_sentence": "本月我要去上海出差。", "error_description": "“本”本身已经表示“这一个”，前面不能再加指示词“这”。错误形式：“这本月”；正确形式：“本月”或“这个月”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e2d4187-6139-4efd-86fc-95b01e03f44e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
