INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90722, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "（书面）是；就是。", "primary_collocate": null, "pronunciation": "nǎi", "ipa": "nai˨˩˦", "syllable_count": 1, "sentences": [{"text": "长城乃中国古代的伟大工程。", "target_word": "乃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此乃我国传统文化的重要部分。", "target_word": "乃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京乃中国的首都。", "target_word": "乃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这乃大家共同努力的结果。", "target_word": "乃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孔子乃中国古代著名的思想家。", "target_word": "乃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失败乃成功之母。", "target_word": "乃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此地乃兵家必争之地。", "target_word": "乃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他所说的乃是事实。", "target_word": "乃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄河乃中华民族的母亲河。", "target_word": "乃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱国乃每个公民应尽的责任。", "target_word": "乃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "书面判断词，相当于“是”，连接主语和名词性成分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '752a5636-7271-49eb-b21b-15ae1b5105ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90722, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "乃", "is_correct": true, "explanation": "乃（nǎi）是书面语，表示“是”，是本题的目标词。"}, {"text": "耐", "is_correct": false, "explanation": "nǎi（第三声）与 nài（第四声）声调不同，“耐”的意思是忍受。"}, {"text": "内", "is_correct": false, "explanation": "nǎi 与 nèi 韵母与声调都不同，“内”的意思是里面。"}, {"text": "哪", "is_correct": false, "explanation": "nǎi 与 nǎ 韵母不同（ai 与 a），“哪”的意思是哪里或哪个。"}, {"text": "男", "is_correct": false, "explanation": "nǎi 与 nán 韵母与声调都不同，“男”的意思是男性。"}], "explanations": {"乃": "乃（nǎi）是书面语，表示“是”，是本题的目标词。", "耐": "nǎi（第三声）与 nài（第四声）声调不同，“耐”的意思是忍受。", "内": "nǎi 与 nèi 韵母与声调都不同，“内”的意思是里面。", "哪": "nǎi 与 nǎ 韵母不同（ai 与 a），“哪”的意思是哪里或哪个。", "男": "nǎi 与 nán 韵母与声调都不同，“男”的意思是男性。"}, "sentence_index": null, "correct_answer": "乃"}, "level_3": {"options": [{"text": "乃", "is_correct": true, "explanation": "“乃”表示“是”，构成判断句，符合句意。"}, {"text": "叫", "is_correct": false, "explanation": "配价：“叫”要求名字或称呼作宾语，“中国古代的伟大工程”不是名称。"}, {"text": "说", "is_correct": false, "explanation": "语义：“说”是说话的动作，长城不能“说”一项工程。"}, {"text": "修", "is_correct": false, "explanation": "语义：长城是已经建成的工程，不能说“修”一项工程。"}], "explanations": {"乃": "“乃”表示“是”，构成判断句，符合句意。", "叫": "配价：“叫”要求名字或称呼作宾语，“中国古代的伟大工程”不是名称。", "说": "语义：“说”是说话的动作，长城不能“说”一项工程。", "修": "语义：长城是已经建成的工程，不能说“修”一项工程。"}, "sentence_index": 0, "correct_answer": "乃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这乃什么？", "explanation": "这里应该用〈是〉（“这是什么？”）。“乃”是书面判断词，不用于这类疑问句。"}, {"text": "这里乃很多人。", "explanation": "这里应该用〈有〉（“这里有很多人”）。“乃”是判断词，不用于存在句。"}, {"text": "你乃学生吗？", "explanation": "这里应该用〈是〉。“乃”是书面语，不用于“……吗”的疑问句，口语疑问要用“是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90722, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "乃", "is_correct": true, "explanation": "乃（nǎi）是书面语，表示“是”，是本题的目标词。"}, {"text": "那", "is_correct": false, "explanation": "nǎi（第三声）与 nà（第四声）韵母与声调都不同，“那”的意思是那个。"}, {"text": "奈", "is_correct": false, "explanation": "nǎi（第三声）与 nài（第四声）声调不同，“奈”的意思是怎样、如何（如“无奈”）。"}, {"text": "南", "is_correct": false, "explanation": "nǎi 与 nán 韵母与声调都不同，“南”的意思是南方。"}, {"text": "纳", "is_correct": false, "explanation": "nǎi 与 nà 韵母与声调都不同，“纳”的意思是接受或收取。"}], "explanations": {"乃": "乃（nǎi）是书面语，表示“是”，是本题的目标词。", "那": "nǎi（第三声）与 nà（第四声）韵母与声调都不同，“那”的意思是那个。", "奈": "nǎi（第三声）与 nài（第四声）声调不同，“奈”的意思是怎样、如何（如“无奈”）。", "南": "nǎi 与 nán 韵母与声调都不同，“南”的意思是南方。", "纳": "nǎi 与 nà 韵母与声调都不同，“纳”的意思是接受或收取。"}, "sentence_index": null, "correct_answer": "乃"}, "level_3": {"options": [{"text": "乃", "is_correct": true, "explanation": "“乃”表示“是”，构成判断句，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，“此地吃兵家必争之地”无法说通。"}, {"text": "去", "is_correct": false, "explanation": "配价：“去”需要处所作宾语，不能直接接“兵家必争之地”作判断。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”指穿戴衣物，“此地穿兵家必争之地”与语境不符。"}], "explanations": {"乃": "“乃”表示“是”，构成判断句，符合句意。", "吃": "语义：“吃”指进食，“此地吃兵家必争之地”无法说通。", "去": "配价：“去”需要处所作宾语，不能直接接“兵家必争之地”作判断。", "穿": "语义：“穿”指穿戴衣物，“此地穿兵家必争之地”与语境不符。"}, "sentence_index": 6, "correct_answer": "乃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他乃打篮球。", "explanation": "这里应该用〈喜欢〉（“他喜欢打篮球”）。“乃”是判断词，不能直接接动词短语。"}, {"text": "这次出差我们乃很辛苦。", "explanation": "这里应去掉〈乃〉（“这次出差我们很辛苦”）。“乃”是判断词，后面要接名词性成分，不能直接接形容词“很辛苦”作谓语。"}, {"text": "他乃快乐地工作。", "explanation": "这里应去掉〈乃〉（“他快乐地工作”）。“乃”是判断词，不能接形容词性的状语短语“快乐地工作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是乃我的老师。", "corrected_sentence": "他乃是我的老师。", "error_description": "“乃”作判断动词，应放在判断对象之前，正确为“乃是”。“是乃”的顺序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "乃这是我的家乡。", "corrected_sentence": "这乃是我的家乡。", "error_description": "“乃”应位于判断主语之后，正确为“这乃是我的家乡”。“乃这”的顺序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
