INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90725, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "柴油机是一种用柴油来开动的机器。", "primary_collocate": null, "pronunciation": "chái yóu jī", "ipa": "ʈʂʰai˧˥ iou˧˥ tɕi˥", "syllable_count": 3, "sentences": [{"text": "爸爸买了一台新柴油机。", "target_word": "柴油机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "柴油机比汽油机更省油。", "target_word": "柴油机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "拖拉机里装着柴油机。", "target_word": "柴油机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "柴油机一开，整个院子都在响。", "target_word": "柴油机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种机器是柴油机，要加柴油。", "target_word": "柴油机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的水泵用柴油机带动。", "target_word": "柴油机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给柴油机加了油。", "target_word": "柴油机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那台柴油机已经用了十年。", "target_word": "柴油机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "柴油机的声音比电动机大。", "target_word": "柴油机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把柴油机关掉。", "target_word": "柴油机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一台柴油机", "label": "量词"}, {"form": "柴油机油", "label": "复合"}], "register": "中性", "sense_fingerprint": "用柴油开动的机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbaef05-ab62-4cb3-bccf-d75c1fe06dac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90725, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "柴油机", "is_correct": true, "explanation": "正确：“买了一台新柴油机”符合语境，量词“台”也正确。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：量词“台”用于机器，不能说“一台新书包”。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“台”不用于食品，不能说“一台新蛋糕”。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能被买，句子不通。"}], "explanations": {"柴油机": "正确：“买了一台新柴油机”符合语境，量词“台”也正确。", "书包": "搭配：量词“台”用于机器，不能说“一台新书包”。", "蛋糕": "搭配：“台”不用于食品，不能说“一台新蛋糕”。", "月亮": "语义：月亮不能被买，句子不通。"}, "sentence_index": 0, "correct_answer": "柴油机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种机器是柴油机，要加汽油。", "explanation": "这里应该用〈汽油机〉。这种机器靠汽油工作，应说“是汽油机，要加汽油”；柴油机要加柴油。"}, {"text": "我们家有一张柴油机。", "explanation": "这里应该用〈台〉。量词〈张〉用于纸、桌子等平面的东西，机器应说“一台柴油机”。"}, {"text": "这台柴油机要定期充电，不能加油。", "explanation": "这里应该用〈电动机〉。充电的是电动机，柴油机要靠柴油开动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90725, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "柴油机", "is_correct": true, "explanation": "正确：“他给柴油机加了油”指给机器加燃料，符合语境。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“加油”若是鼓励，对象应是人；作业不能被“加油”。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“加油”搭配机器或车辆，不搭配课本。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是需要加油的器械，句子不通。"}], "explanations": {"柴油机": "正确：“他给柴油机加了油”指给机器加燃料，符合语境。", "作业": "语义：“加油”若是鼓励，对象应是人；作业不能被“加油”。", "课本": "搭配：“加油”搭配机器或车辆，不搭配课本。", "天空": "语义：天空不是需要加油的器械，句子不通。"}, "sentence_index": 6, "correct_answer": "柴油机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了两桶柴油机。", "explanation": "这里应该用〈柴油〉。柴油机是机器，不是燃料，桶里装的应是柴油。"}, {"text": "他家有一颗柴油机。", "explanation": "这里应该用〈台〉。量词〈颗〉用于粒状或球形的东西，机器应说“一台柴油机”。"}, {"text": "柴油机不用柴油，要充电。", "explanation": "这里应该用〈电动车〉。柴油机要靠柴油开动，不用充电；不用柴油、要充电的是电动车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90725, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家有一把柴油机。", "corrected_sentence": "我家有一台柴油机。", "error_description": "量词错误：“柴油机”应搭配“台”，“把”用于有柄的器具，不能用来数柴油机。正确应为“一台柴油机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90725, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把柴油机擦很亮。", "corrected_sentence": "他把柴油机擦得很亮。", "error_description": "补语错误：“擦”后接程度补语时要用“得”，应为“擦得很亮”；少了“得”，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
