INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90726, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以柴油为燃料的内燃发动机。", "primary_collocate": null, "pronunciation": "chái yóu jī", "ipa": "ʈʂʰai˧˥ iou˧˥ tɕi˥", "syllable_count": 3, "sentences": [{"text": "他会修柴油机。", "target_word": "柴油机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "卡车上有一台柴油机。", "target_word": "柴油机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "柴油机用的是柴油，不是汽油。", "target_word": "柴油机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民用柴油机抽水。", "target_word": "柴油机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台柴油机坏了，需要修。", "target_word": "柴油机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船上的柴油机声音很大。", "target_word": "柴油机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人正在检查柴油机。", "target_word": "柴油机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新柴油机比旧的更省油。", "target_word": "柴油机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，柴油机有时不容易启动。", "target_word": "柴油机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台柴油机很有力。", "target_word": "柴油机", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一台柴油机", "label": "量词"}, {"form": "柴油机油", "label": "复合"}], "register": "中性", "sense_fingerprint": "以柴油为燃料的内燃发动机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dbaef05-ab62-4cb3-bccf-d75c1fe06dac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90726, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "柴油机", "is_correct": true, "explanation": "正确：柴油机是可以修理的机器，“他会修柴油机”通顺。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是机器，不能修理。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海是自然景观，不能修理。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“修”搭配机器或设施，不搭配空气。"}], "explanations": {"柴油机": "正确：柴油机是可以修理的机器，“他会修柴油机”通顺。", "月亮": "语义：月亮不是机器，不能修理。", "大海": "语义：大海是自然景观，不能修理。", "空气": "搭配：“修”搭配机器或设施，不搭配空气。"}, "sentence_index": 0, "correct_answer": "柴油机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆摩托车的柴油机每天都要加汽油。", "explanation": "这里应该用〈汽油机〉。柴油机以柴油为燃料，摩托车加汽油的应是汽油机。"}, {"text": "他买了一块柴油机。", "explanation": "这里应该用〈台〉。量词〈块〉用于块状或片状的东西，机器应说“一台柴油机”。"}, {"text": "这台柴油机不用加油，只要插上电就能转。", "explanation": "这里应该用〈电动机〉。柴油机要靠柴油开动，插电就能转的是电动机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "柴油机", "is_correct": true, "explanation": "正确：“工人正在检查柴油机”是常见说法，符合语境。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹是天气现象，工人不会去检查它。"}, {"text": "春风", "is_correct": false, "explanation": "语义：春风不是可以检查的物件。"}, {"text": "相貌", "is_correct": false, "explanation": "体貌：相貌是人的外表，不能作为检查对象。"}], "explanations": {"柴油机": "正确：“工人正在检查柴油机”是常见说法，符合语境。", "彩虹": "语义：彩虹是天气现象，工人不会去检查它。", "春风": "语义：春风不是可以检查的物件。", "相貌": "体貌：相貌是人的外表，不能作为检查对象。"}, "sentence_index": 6, "correct_answer": "柴油机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台车的油箱里装的是柴油机。", "explanation": "这里应该用〈柴油〉。柴油机是发动机，不是燃料，油箱里装的是柴油。"}, {"text": "他家有一座柴油机。", "explanation": "这里应该用〈台〉。量词〈座〉用于山、楼等大型物体，机器应说“一台柴油机”。"}, {"text": "这台柴油机是一辆卡车，很有力。", "explanation": "这里应该用〈柴油车〉。柴油机是发动机，不是整车，不能说它是一辆卡车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一只柴油机。", "corrected_sentence": "他买了一台柴油机。", "error_description": "量词错误：“柴油机”应搭配“台”，“只”多用于动物等，不能用来数机器。正确应为“一台柴油机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把柴油机修很快。", "corrected_sentence": "工人把柴油机修得很快。", "error_description": "补语错误：“修”后接程度补语时要用“得”，应为“修得很快”；少了“得”，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e528c8-54f7-4af2-964b-e559ca43505a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90727, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收", "is_correct": true, "explanation": "收与付相对：付是把钱给出去，收是接过钱来。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”是进食的动作，与“付”的给钱之义没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”指发声演唱，与“付”没有反义关系。"}, {"text": "睡", "is_correct": false, "explanation": "“睡”指闭眼休息，与“付”没有反义关系。"}], "correct_answer": "收", "explanations": {"收": "收与付相对：付是把钱给出去，收是接过钱来。", "吃": "“吃”是进食的动作，与“付”的给钱之义没有反义关系。", "唱": "“唱”指发声演唱，与“付”没有反义关系。", "睡": "“睡”指闭眼休息，与“付”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
