INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90727, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把钱给别人，买东西或请人做事。", "primary_collocate": null, "pronunciation": "fù", "ipa": "fu˥˩", "syllable_count": 1, "sentences": [{"text": "今天吃饭我来付。", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想用现金付，还是用手机付？", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅修好车，我就付了钱。", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你付了钱，老板才会给你东西。", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请了一位老师，每个月付她工资。", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这家店可以用手机付钱。", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁付钱，谁就可以选餐厅。", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出租车到了，我付钱下了车。", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友帮我搬家，我想付他一点钱。", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她付了钱，拿着买好的书走了。", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "付了", "label": "体标"}, {"form": "付过", "label": "体标"}, {"form": "付费", "label": "复合"}], "register": "中性", "sense_fingerprint": "为买东西或请人做事而把钱给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5695439c-db40-4c72-952c-6632c53558c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90727, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "付", "is_correct": true, "explanation": "付是正确答案，指把钱给别人以买东西或请人做事。"}, {"text": "夫", "is_correct": false, "explanation": "fū（第一声）与 fù（第四声）声调不同，意思是丈夫。"}, {"text": "府", "is_correct": false, "explanation": "fǔ（第三声）与 fù（第四声）声调不同，意思是政府、府第。"}, {"text": "户", "is_correct": false, "explanation": "h 与 f 声母不同，两者都是第四声，意思是户口、家庭。"}, {"text": "物", "is_correct": false, "explanation": "w 与 f 声母不同，两者都是第四声，意思是东西、物品。"}], "explanations": {"付": "付是正确答案，指把钱给别人以买东西或请人做事。", "夫": "fū（第一声）与 fù（第四声）声调不同，意思是丈夫。", "府": "fǔ（第三声）与 fù（第四声）声调不同，意思是政府、府第。", "户": "h 与 f 声母不同，两者都是第四声，意思是户口、家庭。", "物": "w 与 f 声母不同，两者都是第四声，意思是东西、物品。"}, "sentence_index": null, "correct_answer": "付"}, "level_3": {"options": [{"text": "付", "is_correct": true, "explanation": "正确：付指把钱给别人，与“吃饭”“我来”的付钱场合相合。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”指用脚击打，与饭局付钱无关。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”指跌落，与付钱的意思不合。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿夹住东西，与请客付钱无关。"}], "explanations": {"付": "正确：付指把钱给别人，与“吃饭”“我来”的付钱场合相合。", "踢": "语义：“踢”指用脚击打，与饭局付钱无关。", "摔": "语义：“摔”指跌落，与付钱的意思不合。", "咬": "语义：“咬”指用牙齿夹住东西，与请客付钱无关。"}, "sentence_index": 0, "correct_answer": "付"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我付大家一个好消息。", "explanation": "这里应该用〈告诉〉。付只表示把钱交出去，传递消息要说告诉，不能说付。"}, {"text": "老师付我们英语。", "explanation": "这里应该用〈教〉。付不能用于传授知识。"}, {"text": "妈妈付我逛了一下午街。", "explanation": "这里应该用〈陪〉。付只能指付钱，不能表示陪伴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90727, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "付", "is_correct": true, "explanation": "付是正确答案，指把钱给别人以买东西或请人做事。"}, {"text": "服", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）声调不同，意思是服从、衣服。"}, {"text": "护", "is_correct": false, "explanation": "h 与 f 声母不同，两者都是第四声，意思是保护。"}, {"text": "务", "is_correct": false, "explanation": "w 与 f 声母不同，两者都是第四声，意思是事务、任务。"}, {"text": "辅", "is_correct": false, "explanation": "fǔ（第三声）与 fù（第四声）声调不同，意思是辅助。"}], "explanations": {"付": "付是正确答案，指把钱给别人以买东西或请人做事。", "服": "fú（第二声）与 fù（第四声）声调不同，意思是服从、衣服。", "护": "h 与 f 声母不同，两者都是第四声，意思是保护。", "务": "w 与 f 声母不同，两者都是第四声，意思是事务、任务。", "辅": "fǔ（第三声）与 fù（第四声）声调不同，意思是辅助。"}, "sentence_index": null, "correct_answer": "付"}, "level_3": {"options": [{"text": "付", "is_correct": true, "explanation": "正确：付指把钱给别人，与“谁”“钱”“选餐厅”的付钱语境相合。"}, {"text": "吐", "is_correct": false, "explanation": "语义：“吐”指从嘴里吐出东西，与付钱请客无关。"}, {"text": "掐", "is_correct": false, "explanation": "语义：“掐”指用指甲夹住，与付钱无关。"}, {"text": "踩", "is_correct": false, "explanation": "语义：“踩”指用脚压住，与付钱无关。"}], "explanations": {"付": "正确：付指把钱给别人，与“谁”“钱”“选餐厅”的付钱语境相合。", "吐": "语义：“吐”指从嘴里吐出东西，与付钱请客无关。", "掐": "语义：“掐”指用指甲夹住，与付钱无关。", "踩": "语义：“踩”指用脚压住，与付钱无关。"}, "sentence_index": 6, "correct_answer": "付"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她付了一首歌。", "explanation": "这里应该用〈唱〉。付只表示把钱交出去，唱歌要说唱，不能说付。"}, {"text": "她付了我一个问题。", "explanation": "这里应该用〈问〉。付只用于钱款，提问题要说问，不能说付。"}, {"text": "她付了一个电话。", "explanation": "这里应该用〈打〉。付只表示把钱交出去，打电话要说打，不能说付。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90727, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前付了过房租。", "corrected_sentence": "我以前付过房租。", "error_description": "错误在“过”前多加了“了”。“付过”表示曾经有过的经历，中间不能插入“了”，应说“以前付过房租”，不能说“付了过房租”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90727, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把车费付了司机。", "corrected_sentence": "我把车费付给了司机。", "error_description": "错误在于漏掉了“给”。付钱给某人时要说“付给”，应说“付给了司机”，不能说“付了司机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931ecebe-b86c-4db3-88b2-20f1f6e216e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
