INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90729, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "港是海边可以让船停下来的地方。", "primary_collocate": null, "pronunciation": "gǎng", "ipa": "kɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "船进港了，大家都下了船。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个港很大，有很多船。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔船晚上都回港了。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天风很大，船不能出港。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "港里停着十几条小船。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条大船要在港里停三天。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小港很安静，没有什么人。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家旁边有一个港。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以前，船必须靠港。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐船到了一个小港。", "target_word": "港", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "港口", "label": "复合"}, {"form": "港湾", "label": "复合"}], "register": "中性", "sense_fingerprint": "港：海边让船停靠的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0a5c81-35f2-4930-926c-6a53b5a7efb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90729, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "港", "is_correct": true, "explanation": "正确：港（gǎng，第三声）指海边供船停靠的地方。"}, {"text": "钢", "is_correct": false, "explanation": "声调不同：钢读 gāng（第一声），意思是钢铁，与 gǎng（第三声）的港不同。"}, {"text": "赶", "is_correct": false, "explanation": "韵母不同：赶读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是追赶。"}, {"text": "杠", "is_correct": false, "explanation": "声调不同：杠读 gàng（第四声），意思是杠杆，与 gǎng（第三声）不同。"}, {"text": "感", "is_correct": false, "explanation": "韵母不同：感读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是感觉。"}], "explanations": {"港": "正确：港（gǎng，第三声）指海边供船停靠的地方。", "钢": "声调不同：钢读 gāng（第一声），意思是钢铁，与 gǎng（第三声）的港不同。", "赶": "韵母不同：赶读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是追赶。", "杠": "声调不同：杠读 gàng（第四声），意思是杠杆，与 gǎng（第三声）不同。", "感": "韵母不同：感读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是感觉。"}, "sentence_index": null, "correct_answer": "港"}, "level_3": {"options": [{"text": "港", "is_correct": true, "explanation": "正确：港是地方名词，船可以驶入港，之后大家下船。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，船不会进教室，“船进教室了”不通。"}, {"text": "车站", "is_correct": false, "explanation": "语义：车站供车辆停靠，船不会进车站。"}, {"text": "机场", "is_correct": false, "explanation": "语义：机场供飞机起降，船不会进机场。"}], "explanations": {"港": "正确：港是地方名词，船可以驶入港，之后大家下船。", "教室": "语义：教室是上课的地方，船不会进教室，“船进教室了”不通。", "车站": "语义：车站供车辆停靠，船不会进车站。", "机场": "语义：机场供飞机起降，船不会进机场。"}, "sentence_index": 0, "correct_answer": "港"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火车准点进港了。", "explanation": "这里应该用〈车站〉。火车进车站，港是供船只靠泊的地方，火车不能进港。"}, {"text": "这架飞机准时靠港了。", "explanation": "这里应该用〈机场〉。飞机在机场降落，港供船只靠泊，飞机不能靠港。"}, {"text": "工人们在港里生产汽车零件。", "explanation": "这里应该用〈工厂〉。工厂里生产零件，港是供船只靠泊的地方，不能用来生产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90729, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "港", "is_correct": true, "explanation": "正确：港（gǎng，第三声）指海边供船停靠的地方。"}, {"text": "刚", "is_correct": false, "explanation": "声调不同：刚读 gāng（第一声），意思是刚才，与 gǎng（第三声）不同。"}, {"text": "缸", "is_correct": false, "explanation": "声调不同：缸读 gāng（第一声），意思是盛水的器皿，与港不同。"}, {"text": "敢", "is_correct": false, "explanation": "韵母不同：敢读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是勇敢。"}, {"text": "杆", "is_correct": false, "explanation": "韵母不同：杆读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是杆子。"}], "explanations": {"港": "正确：港（gǎng，第三声）指海边供船停靠的地方。", "刚": "声调不同：刚读 gāng（第一声），意思是刚才，与 gǎng（第三声）不同。", "缸": "声调不同：缸读 gāng（第一声），意思是盛水的器皿，与港不同。", "敢": "韵母不同：敢读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是勇敢。", "杆": "韵母不同：杆读 gǎn，以 -n 结尾，与 gǎng 的 -ng 不同，意思是杆子。"}, "sentence_index": null, "correct_answer": "港"}, "level_3": {"options": [{"text": "港", "is_correct": true, "explanation": "正确：港是地方名词，可以用“安静”描述，也可以“没有什么人”。"}, {"text": "演唱会", "is_correct": false, "explanation": "语义：演唱会是人多、声音大的活动，与“安静”“没有什么人”矛盾。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音本身不能说“很安静”，也不能说“没有什么人”，句子不通。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“小”修饰的是具体的地方，不说“小天空”，句子不通。"}], "explanations": {"港": "正确：港是地方名词，可以用“安静”描述，也可以“没有什么人”。", "演唱会": "语义：演唱会是人多、声音大的活动，与“安静”“没有什么人”矛盾。", "声音": "语义：声音本身不能说“很安静”，也不能说“没有什么人”，句子不通。", "天空": "搭配：“小”修饰的是具体的地方，不说“小天空”，句子不通。"}, "sentence_index": 6, "correct_answer": "港"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们在港里借书。", "explanation": "这里应该用〈图书馆〉。借书要去图书馆，港是供船只靠泊的地方，不能在港里借书。"}, {"text": "汽车在港上飞快地行驶。", "explanation": "这里应该用〈马路〉。汽车在马路上行驶，港是供船只靠泊的地方，不能用来行车。"}, {"text": "农民在港里插秧。", "explanation": "这里应该用〈稻田〉。插秧要在稻田里，港是供船只靠泊的地方，不能用来插秧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90729, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只港很大，停着许多大船。", "corrected_sentence": "那个港很大，停着许多大船。", "error_description": "错误：“港”是地方，量词应用“个”，不能用“只”。应说“那个港”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90729, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我哥把船开进了一条港。", "corrected_sentence": "我哥把船开进了一个港。", "error_description": "错误：量词用错。“港”是地方，应用“个”，不用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb7fc0c-ddaa-466c-b702-db87b56f0124') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
