INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90731, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "桌子是放东西、吃饭、写字的家具。", "primary_collocate": null, "pronunciation": "zhuō zi", "ipa": "ʈʂwo˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "桌子上有一本书。", "target_word": "桌子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请把书放在桌子上。", "target_word": "桌子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们家的桌子是木头做的。", "target_word": "桌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把饭菜放到桌子上。", "target_word": "桌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在桌子前写作业。", "target_word": "桌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里有三十张桌子。", "target_word": "桌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子太小，坐不下六个人。", "target_word": "桌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫跳上了桌子。", "target_word": "桌子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用布擦了擦桌子。", "target_word": "桌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子下面有一只小狗。", "target_word": "桌子", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "书桌", "label": "复合"}, {"form": "饭桌", "label": "复合"}], "register": "中性", "sense_fingerprint": "放东西、吃饭、写字用的家具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f4a601-3387-46d6-8878-d4f1e5cccdbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90731, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桌子", "is_correct": true, "explanation": "正确：“桌子”是有平面可以放东西的家具，与“……上有一本书”相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能承托书，书不能放在天空上。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“上”后要接能承托东西的平面，空气不能承托书，不说空气上有书。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵是水汽凝结的云，不能承托一本书。"}], "explanations": {"桌子": "正确：“桌子”是有平面可以放东西的家具，与“……上有一本书”相符。", "天空": "语义：天空不能承托书，书不能放在天空上。", "空气": "搭配：“上”后要接能承托东西的平面，空气不能承托书，不说空气上有书。", "云朵": "语义：云朵是水汽凝结的云，不能承托一本书。"}, "sentence_index": 0, "correct_answer": "桌子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他喝了一口桌子，觉得很甜。", "explanation": "这里应该用〈茶〉。桌子是家具，不能喝，能喝的是茶之类的饮料。"}, {"text": "他关上了桌子，走进了房间。", "explanation": "这里应该用〈门〉。桌子不能关上，关上的是门。"}, {"text": "他把画挂在桌子上。", "explanation": "这里应该用〈墙〉。挂画要挂在竖直的墙面上，桌子是平面，不能挂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90731, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": true, "explanation": "正确：“桌子”可供人围坐，句中说“这张……太小，坐不下六个人”，与句意相符。"}, {"text": "脸", "is_correct": false, "explanation": "语义：脸不能用来坐人，句中说的是坐不下六个人。"}, {"text": "画", "is_correct": false, "explanation": "配价：“坐”要求有座位的人或物，画不能坐人，不能说坐不下六个人。"}, {"text": "纸", "is_correct": false, "explanation": "语义：一张纸不能坐人，说它太小、坐不下六个人与事实不符。"}], "explanations": {"桌子": "正确：“桌子”可供人围坐，句中说“这张……太小，坐不下六个人”，与句意相符。", "脸": "语义：脸不能用来坐人，句中说的是坐不下六个人。", "画": "配价：“坐”要求有座位的人或物，画不能坐人，不能说坐不下六个人。", "纸": "语义：一张纸不能坐人，说它太小、坐不下六个人与事实不符。"}, "sentence_index": 6, "correct_answer": "桌子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "船在桌子上航行。", "explanation": "这里应该用〈海〉。船在水面上航行，桌子不是水域，不能航行。"}, {"text": "鸟在桌子中飞翔。", "explanation": "这里应该用〈天空〉。鸟在空中飞翔，桌子中间没有空间可以飞。"}, {"text": "桌子从山上流下来。", "explanation": "这里应该用〈河流〉。河流才会从山上流下来，桌子不会流动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90731, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教室里摆着四只桌子。", "corrected_sentence": "教室里摆着四张桌子。", "error_description": "量词错误：“桌子”应用量词“张”计量，说“只桌子”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90731, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把桌子擦很干净。", "corrected_sentence": "我把桌子擦得很干净。", "error_description": "补语错误：“擦”后带程度补语要用“得”连接，应说“擦得很干净”，漏掉“得”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
