INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90732, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有平面和支柱，供放物、写字、吃饭用的家具。", "primary_collocate": null, "pronunciation": "zhuō zi", "ipa": "ʈʂwo˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "这张桌子有四条腿。", "target_word": "桌子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子的面很平，很适合写字。", "target_word": "桌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一张新桌子放在房间里。", "target_word": "桌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把桌子搬到了窗边。", "target_word": "桌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老桌子的腿已经不稳了。", "target_word": "桌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张圆桌子可以坐八个人。", "target_word": "桌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上的东西太多，要收拾。", "target_word": "桌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子躲在桌子下面。", "target_word": "桌子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这张桌子是爷爷自己做的。", "target_word": "桌子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子坏了，要请人来修。", "target_word": "桌子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "书桌", "label": "复合"}, {"form": "圆桌", "label": "复合"}], "register": "中性", "sense_fingerprint": "有平面和腿、供放物写字吃饭的家具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f4a601-3387-46d6-8878-d4f1e5cccdbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90732, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桌子", "is_correct": true, "explanation": "正确：“桌子”有四条腿，与“这张……有四条腿”相符。"}, {"text": "纸", "is_correct": false, "explanation": "语义：一张纸没有腿，不能说有四条腿。"}, {"text": "脸", "is_correct": false, "explanation": "搭配：“有四条腿”说有腿的家具或动物，脸上没有腿，搭配不当。"}, {"text": "照片", "is_correct": false, "explanation": "语义：照片是图像，没有腿，不能说有四条腿。"}], "explanations": {"桌子": "正确：“桌子”有四条腿，与“这张……有四条腿”相符。", "纸": "语义：一张纸没有腿，不能说有四条腿。", "脸": "搭配：“有四条腿”说有腿的家具或动物，脸上没有腿，搭配不当。", "照片": "语义：照片是图像，没有腿，不能说有四条腿。"}, "sentence_index": 0, "correct_answer": "桌子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他穿上了桌子，出门去了。", "explanation": "这里应该用〈衣服〉。穿的是衣服，桌子不能穿。"}, {"text": "他把桌子挂在墙上。", "explanation": "这里应该用〈画〉。挂在墙上的是画，桌子不能挂。"}, {"text": "桌子长在山坡上。", "explanation": "这里应该用〈树〉。树才会长在山坡上，桌子不会生长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90732, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": true, "explanation": "正确：“桌子”上可以放东西，与“桌子上的东西太多，要收拾”相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空上不能放东西，句中说的是要收拾的东西。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“上”后不接房间，要说“房间里”，不能说房间上的东西。"}, {"text": "云", "is_correct": false, "explanation": "语义：云上不能堆放东西，也不需要收拾。"}], "explanations": {"桌子": "正确：“桌子”上可以放东西，与“桌子上的东西太多，要收拾”相符。", "天空": "语义：天空上不能放东西，句中说的是要收拾的东西。", "房间": "搭配：“上”后不接房间，要说“房间里”，不能说房间上的东西。", "云": "语义：云上不能堆放东西，也不需要收拾。"}, "sentence_index": 6, "correct_answer": "桌子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌子漏水了，要请人来修。", "explanation": "这里应该用〈房子〉。桌子不会漏水，漏水要用“房子”之类的建筑。"}, {"text": "桌子煮熟了，可以吃了。", "explanation": "这里应该用〈鸡蛋〉。桌子不能煮熟，也不能吃，煮熟的是鸡蛋之类的食物。"}, {"text": "桌子摇着尾巴跑过来。", "explanation": "这里应该用〈小狗〉。摇尾巴、跑过来是动物的动作，桌子不能这样做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90732, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只桌子是新买的。", "corrected_sentence": "这张桌子是新买的。", "error_description": "量词错误：“桌子”应用量词“张”计量，说“这只桌子”是错误的，应说“这张桌子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90732, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条桌子太重了，我搬不动。", "corrected_sentence": "那张桌子太重了，我搬不动。", "error_description": "量词错误：“桌子”应用量词“张”，不能说“那条桌子”，应说“那张桌子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
