INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90733, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "有空的时候，顺便。", "primary_collocate": null, "pronunciation": "biàn zhōng", "ipa": "pʰjɛn˥˩ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "请便中帮我买瓶水。", "target_word": "便中", "complexity_tier": "T3", "furigana": "qǐng biàn zhōng bāng wǒ mǎi píng shuǐ", "sentence_source": "generated"}, {"text": "请你便中把这封信带给他。", "target_word": "便中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请便中去趟银行，帮我取点钱。", "target_word": "便中", "complexity_tier": "T3", "furigana": "qǐng biàn zhōng qù tàng yín háng bāng wǒ qǔ diǎn qián", "sentence_source": "generated"}, {"text": "他让我便中来看看老人。", "target_word": "便中", "complexity_tier": "T3", "furigana": "tā ràng wǒ biàn zhōng lái kàn kan lǎo rén", "sentence_source": "generated"}, {"text": "请便中把门口的信拿上来。", "target_word": "便中", "complexity_tier": "T3", "furigana": "qǐng biàn zhōng bǎ mén kǒu de xìn ná shàng lái", "sentence_source": "generated"}, {"text": "请便中告诉他，会议改到明天。", "target_word": "便中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我们便中把作业交上来。", "target_word": "便中", "complexity_tier": "T3", "furigana": "lǎo shī qǐng wǒ men biàn zhōng bǎ zuò yè jiāo shàng lái", "sentence_source": "generated"}, {"text": "请便中到超市买点水果。", "target_word": "便中", "complexity_tier": "T3", "furigana": "qǐng biàn zhōng dào chāo shì mǎi diǎn shuǐ guǒ", "sentence_source": "generated"}, {"text": "请便中去邮局寄一下那个包裹。", "target_word": "便中", "complexity_tier": "T3", "furigana": "qǐng biàn zhōng qù yóu jú jì yí xià nà ge bāo guǒ", "sentence_source": "generated"}, {"text": "请便中给我回个电话。", "target_word": "便中", "complexity_tier": "T3", "furigana": "qǐng biàn zhōng gěi wǒ huí gè diàn huà", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "便中·有空时顺便做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '752a5636-7271-49eb-b21b-15ae1b5105ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90733, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "便中", "is_correct": true, "explanation": "正确：“便中”表示有空时顺便，符合“请……帮我买”的语境。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一贯如此，与请对方有空时顺便办的事矛盾。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：“已经”表示已经发生，不能用在“请”后面表示请求。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，与礼貌请求的语境不合。"}], "explanations": {"便中": "正确：“便中”表示有空时顺便，符合“请……帮我买”的语境。", "从来": "语义：“从来”表示一贯如此，与请对方有空时顺便办的事矛盾。", "已经": "搭配：“已经”表示已经发生，不能用在“请”后面表示请求。", "竟然": "语义：“竟然”表示出乎意料，与礼貌请求的语境不合。"}, "sentence_index": 0, "correct_answer": "便中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我为了你的事便中专门去了一趟银行。", "explanation": "这里应该用〈特意〉。便中表示有空时顺便，不能用于专门为某事而做。"}, {"text": "孩子快哭了，请便中把奶瓶递给我。", "explanation": "这里应该用〈马上〉。便中表示不急、有空时顺便，不能用于紧急情况。"}, {"text": "我每天便中都练钢琴。", "explanation": "这里不能用“便中”。便中表示有空时偶然顺便，不能表示天天坚持。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90733, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便中", "is_correct": true, "explanation": "正确：“便中”表示有空时顺便，符合“老师请我们……把作业交上来”的语境。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与老师请大家做的事矛盾。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”一般修饰形容词，不能放在“请我们”后面修饰动作。"}, {"text": "早已", "is_correct": false, "explanation": "语义：“早已”表示很久以前就已完成，与请求对方去做的语境矛盾。"}], "explanations": {"便中": "正确：“便中”表示有空时顺便，符合“老师请我们……把作业交上来”的语境。", "从不": "语义：“从不”表示从来没有，与老师请大家做的事矛盾。", "十分": "搭配：“十分”一般修饰形容词，不能放在“请我们”后面修饰动作。", "早已": "语义：“早已”表示很久以前就已完成，与请求对方去做的语境矛盾。"}, "sentence_index": 6, "correct_answer": "便中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你必须便中把这件事办完。", "explanation": "这里不能用“便中”。便中表示有空时顺便，不能表示必须完成的义务。"}, {"text": "这份文件请便中在今天下午五点前交给我。", "explanation": "这里应去掉“便中”（“这份文件请在今天下午五点前交给我”）。便中表示不急、有空时顺便，不能用于有明确期限的要求。"}, {"text": "王先生病得很重，请便中去探望。", "explanation": "这里应该用〈尽快〉。便中表示不急，不能用于病重需要尽快探望的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90733, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请便中了替我把快递取回来。", "corrected_sentence": "请便中替我把快递取回来。", "error_description": "“便中”是副词，后面不能直接加“了”。删去“了”即可，应说“请便中替我把快递取回来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90733, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请便中的给我带一份报纸。", "corrected_sentence": "请便中给我带一份报纸。", "error_description": "“便中”是副词，不能加“的”。应说“请便中给我带一份报纸”，去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
