INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90734, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "（书面）在方便的时候。", "primary_collocate": null, "pronunciation": "biàn zhōng", "ipa": "pʰjɛn˥˩ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "如有消息，请便中告知。", "target_word": "便中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先生若来京，请便中来访。", "target_word": "便中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来信收悉，容便中回复。", "target_word": "便中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请便中将此物转交王先生。", "target_word": "便中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贵校如有新书，请便中寄来。", "target_word": "便中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您的书稿，我便中再细读。", "target_word": "便中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若有机会，请便中向李教授问好。", "target_word": "便中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此事不急，请便中回话。", "target_word": "便中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家父近况，容便中详告。", "target_word": "便中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告请便中交到办公室。", "target_word": "便中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "便中·书面语，在方便之时", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '752a5636-7271-49eb-b21b-15ae1b5105ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90734, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "便中", "is_correct": true, "explanation": "正确：“便中”表示在方便的时候，书面语，符合“如有消息，请……告知”的语境。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一贯如此，与“如有消息”的将来情况不合。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，不能用于礼貌的请求。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：“已经”表示已经完成，不能用在“请”后面。"}], "explanations": {"便中": "正确：“便中”表示在方便的时候，书面语，符合“如有消息，请……告知”的语境。", "从来": "语义：“从来”表示一贯如此，与“如有消息”的将来情况不合。", "竟然": "语义：“竟然”表示出乎意料，不能用于礼貌的请求。", "已经": "搭配：“已经”表示已经完成，不能用在“请”后面。"}, "sentence_index": 0, "correct_answer": "便中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事关紧急，请便中将此物转交王先生。", "explanation": "这里应该用〈立即〉。便中表示在方便的时候，不适用于紧急事务。"}, {"text": "这是规定，您必须便中将此物转交王先生。", "explanation": "这里不能用“便中”。便中表示方便时再办，不能用于必须履行的规定。"}, {"text": "为了这件事，我便中专门跑了一趟王先生家。", "explanation": "这里不能用“便中”。便中表示方便时顺便去做，不能表示特意为某事而去，与这里的专程之意矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90734, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便中", "is_correct": true, "explanation": "正确：“便中”表示方便时，书面语，符合“若有机会，请……问好”的语境。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与请对方问好的语境矛盾。"}, {"text": "刚刚", "is_correct": false, "explanation": "搭配：“刚刚”表示时间刚过不久，不能用在“请”后面。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示经常如此，与“若有机会”的偶然语境不合。"}], "explanations": {"便中": "正确：“便中”表示方便时，书面语，符合“若有机会，请……问好”的语境。", "从不": "语义：“从不”表示从来没有，与请对方问好的语境矛盾。", "刚刚": "搭配：“刚刚”表示时间刚过不久，不能用在“请”后面。", "总是": "语义：“总是”表示经常如此，与“若有机会”的偶然语境不合。"}, "sentence_index": 6, "correct_answer": "便中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报告需在周五前交到办公室，请便中提交。", "explanation": "这里应该用〈按时〉。便中表示方便时再办，不急；句中已有“周五前”的明确期限，不能用“便中”。"}, {"text": "每次开会，我总是便中做好笔记。", "explanation": "这里不能用“便中”。便中表示方便时偶然顺便，不能表示次次如此的规律性做法。"}, {"text": "王先生有急事，请便中马上回电。", "explanation": "这里不能用“便中”。便中表示不急、有空时顺便，与“有急事”的紧急情况矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请便中了将样品寄来。", "corrected_sentence": "请便中将样品寄来。", "error_description": "“便中”是副词，不能带“了”。应说“请便中将样品寄来”，“了”不能跟在“便中”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "烦请便中的将报告寄来。", "corrected_sentence": "烦请便中将报告寄来。", "error_description": "“便中”是副词，不能带“的”。应说“烦请便中将报告寄来”，去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
