INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90735, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "楼梯是房子里供人一级一级走上走下的台阶。", "primary_collocate": null, "pronunciation": "lóu tī", "ipa": "lou̯˧˥ tʰi˥", "syllable_count": 2, "sentences": [{"text": "我家的楼梯很窄。", "target_word": "楼梯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天走楼梯上楼。", "target_word": "楼梯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼梯口放着一把伞。", "target_word": "楼梯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩在楼梯上玩，很危险。", "target_word": "楼梯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座楼的楼梯有三十级。", "target_word": "楼梯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不坐电梯，我爬楼梯。", "target_word": "楼梯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼梯太滑，请小心。", "target_word": "楼梯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人上楼梯很慢。", "target_word": "楼梯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站在楼梯下面等我。", "target_word": "楼梯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道楼梯通向二楼。", "target_word": "楼梯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "量词"}, {"form": "段", "label": "量词"}, {"form": "樓梯", "label": "繁体"}], "register": "中性", "sense_fingerprint": "房子里供人上下楼的一级一级台阶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3040b130-1c83-4aba-a0d1-f87d0f162c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90735, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是房屋中的空间，不能说“我家的歌曲很窄”。"}, {"text": "楼梯", "is_correct": true, "explanation": "正确。楼梯是房子里供人上下的台阶，可以用“窄”形容它的宽度。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空指自然界的天空，不是房屋的组成部分，“我家的天空很窄”不成立。"}, {"text": "月光", "is_correct": false, "explanation": "搭配：“窄”用于空间或通道，不能用来形容月光。"}], "explanations": {"歌曲": "语义：歌曲不是房屋中的空间，不能说“我家的歌曲很窄”。", "楼梯": "正确。楼梯是房子里供人上下的台阶，可以用“窄”形容它的宽度。", "天空": "语义：天空指自然界的天空，不是房屋的组成部分，“我家的天空很窄”不成立。", "月光": "搭配：“窄”用于空间或通道，不能用来形容月光。"}, "sentence_index": 0, "correct_answer": "楼梯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "饭馆门口有三个楼梯，进门时小心别摔倒。", "explanation": "这里应该用〈台阶〉。台阶可以指门口几级矮矮的石阶；楼梯是楼房里连接上下楼层的台阶，不能说门口有“三个楼梯”。"}, {"text": "这间楼梯教室可以坐三百人。", "explanation": "这里应该用〈阶梯〉。阶梯还可指一级一级升高的座位，如阶梯教室；楼梯只指楼房里供人上下的台阶，不能用来修饰教室。"}, {"text": "我每天坐楼梯上班。", "explanation": "这里应该用〈电梯〉。“坐”用于电梯这类可乘坐的交通工具，楼梯要走或爬，不能说“坐楼梯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90735, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不会“滑”，不能说“天气太滑”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字没有光滑或湿滑的属性，不能说“名字太滑”。"}, {"text": "楼梯", "is_correct": true, "explanation": "正确。楼梯台阶湿滑时可以说“太滑”，与“请小心”的语境相合。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“滑”形容物体表面，不能用来形容考试。"}], "explanations": {"天气": "语义：天气不会“滑”，不能说“天气太滑”。", "名字": "语义：名字没有光滑或湿滑的属性，不能说“名字太滑”。", "楼梯": "正确。楼梯台阶湿滑时可以说“太滑”，与“请小心”的语境相合。", "考试": "搭配：“滑”形容物体表面，不能用来形容考试。"}, "sentence_index": 6, "correct_answer": "楼梯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用楼梯爬到树上摘果子。", "explanation": "这里应该用〈梯子〉。梯子可以靠在树上或墙上，供人登高；楼梯固定在楼房里，不能用来爬到树上。"}, {"text": "轮椅可以沿着楼梯上楼。", "explanation": "这里应该用〈坡道〉。坡道是平缓的斜面，轮椅可以推上去；楼梯是一级一级的台阶，轮椅上不去。"}, {"text": "这座楼的楼梯很快，几分钟就到顶层了。", "explanation": "这里应该用〈电梯〉。电梯可以快速升降，能说“很快”；楼梯要一级一级地走，不能说楼梯“很快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90735, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把楼梯很窄，只能一个人上。", "corrected_sentence": "这道楼梯很窄，只能一个人上。", "error_description": "量词错误：楼梯应用“道”或“段”计量，“把”用于有柄的器具，不能用来数楼梯。正确应为“这道楼梯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90735, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这栋楼梯很长，我们走了很久。", "corrected_sentence": "这段楼梯很长，我们走了很久。", "error_description": "量词错误：楼梯应用“段”或“道”计量，“栋”用于房屋，不能说“这栋楼梯”。正确应为“这段楼梯”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
