INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90737, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "火车是在铁路上跑的长长的车，里面可以坐很多人。", "primary_collocate": null, "pronunciation": "huǒ chē", "ipa": "xuo˨˩˦ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "火车来了。", "target_word": "火车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我坐火车去上海。", "target_word": "火车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这列火车很长。", "target_word": "火车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车几点到北京？", "target_word": "火车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们坐了三个小时的火车。", "target_word": "火车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车里坐满了人，我没有座位。", "target_word": "火车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在窗边看着火车。", "target_word": "火车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前坐过一次火车。", "target_word": "火车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在火车上睡了一觉。", "target_word": "火车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车在铁路上跑得很快。", "target_word": "火车", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "列", "label": "量词"}, {"form": "趟", "label": "量词"}, {"form": "火車", "label": "繁体"}], "register": "中性", "sense_fingerprint": "火车：在铁路上跑的长长的车，可以坐很多人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4256b07-2d2b-4db1-830f-e6bafd30f388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90737, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "火车", "is_correct": true, "explanation": "正确：「火车来了」指火车到达车站，符合句意。"}, {"text": "道理", "is_correct": false, "explanation": "语义：「道理」是抽象概念，不会「来」。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：「眼睛」是身体器官，不能「来」。"}, {"text": "数学", "is_correct": false, "explanation": "语义：「数学」是学科名称，不会「来」。"}], "explanations": {"火车": "正确：「火车来了」指火车到达车站，符合句意。", "道理": "语义：「道理」是抽象概念，不会「来」。", "眼睛": "语义：「眼睛」是身体器官，不能「来」。", "数学": "语义：「数学」是学科名称，不会「来」。"}, "sentence_index": 0, "correct_answer": "火车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我坐了一只火车去北京。", "explanation": "量词：火车用「列」或「趟」，不用「只」（「只」多用于动物），这里应说〈一列火车〉。"}, {"text": "这列火车在马路上开得很快。", "explanation": "这里应该用〈汽车〉。火车只能在铁路上行驶，不能在马路上开。"}, {"text": "我们乘火车飞过了大海。", "explanation": "这里应该用〈飞机〉。火车在铁路上行驶，不能用来「飞」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90737, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火车", "is_correct": true, "explanation": "正确：「看着火车」指看火车经过，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：「空气」看不见，不能「看着」。"}, {"text": "歌声", "is_correct": false, "explanation": "搭配：「看」搭配的是可见的事物，「歌声」是用耳朵听的。"}, {"text": "道理", "is_correct": false, "explanation": "语义：「道理」是抽象概念，不能用眼睛看。"}], "explanations": {"火车": "正确：「看着火车」指看火车经过，符合句意。", "空气": "语义：「空气」看不见，不能「看着」。", "歌声": "搭配：「看」搭配的是可见的事物，「歌声」是用耳朵听的。", "道理": "语义：「道理」是抽象概念，不能用眼睛看。"}, "sentence_index": 6, "correct_answer": "火车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这列火车在河里航行。", "explanation": "这里应该用〈轮船〉。火车只能在铁路上行驶，不能在河里航行。"}, {"text": "我看见一个火车从桥上开过去。", "explanation": "量词：火车用「列」或「趟」，不用「个」，这里应说〈一列火车〉。"}, {"text": "这列火车在大楼里上下。", "explanation": "这里应该用〈电梯〉。火车只在铁路上行驶，不能在大楼里上下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90737, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们坐了一列的火车去上海。", "corrected_sentence": "我们坐了一列火车去上海。", "error_description": "「一列」修饰名词时直接接在名词前，中间不加「的」，应说「一列火车」，不说「一列的火车」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90737, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在站台上看见了一只火车。", "corrected_sentence": "我在站台上看见了一列火车。", "error_description": "量词：火车用「列」，不用「只」，应说「一列火车」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
