INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90740, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b08207e-ba0d-47c1-91ac-7fbdd82699f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90740, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示进一层，并且。", "primary_collocate": null, "pronunciation": "zài zé", "ipa": "tsai̯˥˩ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这件衣服太贵，再则颜色也不适合我。", "target_word": "再则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他身体不好，再则工作也很忙，不能去了。", "target_word": "再则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天太晚了，再则外面在下雨，你别回去了。", "target_word": "再则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想搬家，房租太高，再则离公司也远。", "target_word": "再则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法省钱，再则又简单，我们就用它吧。", "target_word": "再则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很聪明，再则肯努力，所以进步很快。", "target_word": "再则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的东西质量好，再则价格便宜，顾客总是很多。", "target_word": "再则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不会同意的，再则我也不想麻烦他。", "target_word": "再则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路太远，再则天气不好，我们改天再去吧。", "target_word": "再则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书内容有意思，再则语言简单，适合学生看。", "target_word": "再则", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "连接分句，在前面理由的基础上再补充更进一层的理由或情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3664d668-2958-407a-84af-382c04e663fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90740, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再则", "is_correct": true, "explanation": "正确：再则表示进一层，补充理由，与前句并列。"}, {"text": "所以", "is_correct": false, "explanation": "语义：所以表示因果，“太贵”与“颜色不适合”之间不是因果关系。"}, {"text": "因此", "is_correct": false, "explanation": "语义：因此表示结果，与这里的并列补充不符。"}, {"text": "于是", "is_correct": false, "explanation": "搭配：“于是”承接前面的动作，不接并列的理由。"}], "explanations": {"再则": "正确：再则表示进一层，补充理由，与前句并列。", "所以": "语义：所以表示因果，“太贵”与“颜色不适合”之间不是因果关系。", "因此": "语义：因此表示结果，与这里的并列补充不符。", "于是": "搭配：“于是”承接前面的动作，不接并列的理由。"}, "sentence_index": 0, "correct_answer": "再则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很努力，再则成绩很差。", "explanation": "这里应该用〈但是〉。再则只表示递进，补充同方向的理由，不表示转折。"}, {"text": "再则下雨，我们也要去。", "explanation": "这里应该用〈即使〉。再则表示补充或递进，不表示让步，不能引出“即使下雨也要去”的意思。"}, {"text": "这个菜看起来不好吃，再则味道很好。", "explanation": "这里应该用〈可是〉。再则只补充同方向的理由，不表示转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b08207e-ba0d-47c1-91ac-7fbdd82699f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90740, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再则", "is_correct": true, "explanation": "正确：再则用于补充同方向的评价，与“东西好”“价格便宜”相符。"}, {"text": "不然", "is_correct": false, "explanation": "语义：不然表示假设不成立时的后果，此处并非假设。"}, {"text": "而是", "is_correct": false, "explanation": "语义：而是表示对比否定，此处并不否定前句。"}, {"text": "因而", "is_correct": false, "explanation": "语义：因而表示结果，“东西好”并不导致“价格便宜”。"}], "explanations": {"再则": "正确：再则用于补充同方向的评价，与“东西好”“价格便宜”相符。", "不然": "语义：不然表示假设不成立时的后果，此处并非假设。", "而是": "语义：而是表示对比否定，此处并不否定前句。", "因而": "语义：因而表示结果，“东西好”并不导致“价格便宜”。"}, "sentence_index": 6, "correct_answer": "再则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不是老师，再则是医生。", "explanation": "这里应该用〈而是〉。再则只表示并列或递进，不表示“不是……而是……”的对比。"}, {"text": "天气很热，再则我们去游泳。", "explanation": "这里应该用〈因此〉。再则表示补充，不表示由前面导致的结果。"}, {"text": "我先洗澡，再则吃饭。", "explanation": "这里应该用〈然后〉。再则表示补充，不表示动作的先后顺序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b08207e-ba0d-47c1-91ac-7fbdd82699f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90740, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间太小，又再则光线也不好。", "corrected_sentence": "这个房间太小，再则光线也不好。", "error_description": "语序错误：“又”不能放在“再则”之前（可以说“再则又……”，不能说“又再则……”）。去掉“又”，正确说法是“这个房间太小，再则光线也不好。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b08207e-ba0d-47c1-91ac-7fbdd82699f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90740, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家饭店的菜好吃，再则了服务也好。", "corrected_sentence": "这家饭店的菜好吃，再则服务也好。", "error_description": "误加“了”：“再则”是连词，后面不能加“了”，应说“再则服务也好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b08207e-ba0d-47c1-91ac-7fbdd82699f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
