INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90741, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机票是坐飞机要买的票。", "primary_collocate": null, "pronunciation": "jī piào", "ipa": "tɕi˥ pʰiɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我在网上买了两张机票。", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去北京的机票太贵了。", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天早上的机票已经卖完了。", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想订一张去上海的机票。", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张机票是打折的，很便宜。", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暑假的机票比平时贵很多。", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我买了回家的机票。", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们买的是去程和回程的机票。", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买机票花了三千块钱。", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节前的机票很难买。", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "往返机票", "label": "复合"}, {"form": "機票", "label": "繁体"}], "register": "中性", "sense_fingerprint": "买来坐飞机的票，强调购买的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0120cb63-e99a-4427-ab15-5932136b311c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90741, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "机票", "is_correct": true, "explanation": "机票（jī piào）指乘坐飞机的票，是正确答案。"}, {"text": "计票", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，计票指计算选票，意思不同。"}, {"text": "几票", "is_correct": false, "explanation": "jǐ（第三声）与 jī（第一声）声调不同，几票指几张票。"}, {"text": "七票", "is_correct": false, "explanation": "qī（七）与 jī（机）声母不同，七票指七张票。"}], "explanations": {"机票": "机票（jī piào）指乘坐飞机的票，是正确答案。", "计票": "jì（第四声）与 jī（第一声）声调不同，计票指计算选票，意思不同。", "几票": "jǐ（第三声）与 jī（第一声）声调不同，几票指几张票。", "七票": "qī（七）与 jī（机）声母不同，七票指七张票。"}, "sentence_index": null, "correct_answer": "机票"}, "level_3": {"options": [{"text": "机票", "is_correct": true, "explanation": "机票是乘坐飞机的凭证，可以在网上购买，量词用“张”。"}, {"text": "书", "is_correct": false, "explanation": "搭配：量词“张”不用于书，书的量词是“本”。"}, {"text": "信", "is_correct": false, "explanation": "语义：信是写给别人的，不是在网上买的，量词也不用“张”。"}, {"text": "水", "is_correct": false, "explanation": "搭配：量词“张”不能用于水，水要用“瓶”或“杯”计量。"}], "explanations": {"机票": "机票是乘坐飞机的凭证，可以在网上购买，量词用“张”。", "书": "搭配：量词“张”不用于书，书的量词是“本”。", "信": "语义：信是写给别人的，不是在网上买的，量词也不用“张”。", "水": "搭配：量词“张”不能用于水，水要用“瓶”或“杯”计量。"}, "sentence_index": 0, "correct_answer": "机票"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我坐火车去北京，在车站买了一张机票。", "explanation": "这里应该用〈车票〉。坐火车要买车票，机票是乘坐飞机的票。"}, {"text": "周末我去动物园，在门口买了一张机票。", "explanation": "这里应该用〈门票〉。进动物园要买门票，机票是乘坐飞机的票。"}, {"text": "周末我去电影院，在售票处买了一张机票。", "explanation": "这里应该用〈电影票〉。看电影要买电影票，机票是乘坐飞机的票。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90741, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机票", "is_correct": true, "explanation": "机票是乘坐飞机的票，“回家的机票”指回家乘机用的票。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是老师布置的，不是买来的，“买回家的作业”说不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能买，也不是可以带回家的东西。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“买”的对象不能是名字，名字要用“取”或“起”。"}], "explanations": {"机票": "机票是乘坐飞机的票，“回家的机票”指回家乘机用的票。", "作业": "语义：作业是老师布置的，不是买来的，“买回家的作业”说不通。", "空气": "语义：空气不能买，也不是可以带回家的东西。", "名字": "搭配：“买”的对象不能是名字，名字要用“取”或“起”。"}, "sentence_index": 6, "correct_answer": "机票"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公园的机票要五十块。", "explanation": "这里应该用〈门票〉。进公园要买门票，机票是乘坐飞机的票。"}, {"text": "上班路上，我坐机票去公司。", "explanation": "这里应该用〈飞机〉。坐的是飞机，机票只是乘机的凭证，不能当交通工具。"}, {"text": "船要开了，我还没买机票。", "explanation": "这里应该用〈船票〉。坐船要买船票，机票只用于飞机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
