INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90741, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他订了两本去成都的机票。", "corrected_sentence": "他订了两张去成都的机票。", "error_description": "量词错误：“机票”应用量词“张”，不能用“本”（“本”用于书刊等）。正确说法是“两张去成都的机票”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
