INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90742, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "乘坐飞机的凭证。", "primary_collocate": null, "pronunciation": "jī piào", "ipa": "tɕi˥ pʰiɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "上飞机前，请给我看一下你的机票。", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他找不到机票，很着急。", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机票上写着你的名字和座位号。", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的机票丢了，怎么办？", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请带好护照和机票。", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机票上的日期是十月八号。", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张机票不能改签。", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着机票走进了机场。", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机票要和身份证一起给工作人员看。", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把机票打印出来了。", "target_word": "机票", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "機票", "label": "繁体"}], "register": "中性", "sense_fingerprint": "登机时要出示的凭证，强调票上的信息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0120cb63-e99a-4427-ab15-5932136b311c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90742, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "机票", "is_correct": true, "explanation": "机票（jī piào）指乘坐飞机的凭证，是正确答案。"}, {"text": "计票", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，计票指计算选票，意思不同。"}, {"text": "几票", "is_correct": false, "explanation": "jǐ（第三声）与 jī（第一声）声调不同，几票指几张票。"}, {"text": "七票", "is_correct": false, "explanation": "qī（七）与 jī（机）声母不同，七票指七张票。"}], "explanations": {"机票": "机票（jī piào）指乘坐飞机的凭证，是正确答案。", "计票": "jì（第四声）与 jī（第一声）声调不同，计票指计算选票，意思不同。", "几票": "jǐ（第三声）与 jī（第一声）声调不同，几票指几张票。", "七票": "qī（七）与 jī（机）声母不同，七票指七张票。"}, "sentence_index": null, "correct_answer": "机票"}, "level_3": {"options": [{"text": "机票", "is_correct": true, "explanation": "机票是登机时要出示的凭证，上飞机前要给工作人员看。"}, {"text": "车票", "is_correct": false, "explanation": "语义：车票是坐火车用的，上飞机前不用出示。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是登机时要出示的东西。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“看一下你的名字”不是常见说法，这里要看的是凭证。"}], "explanations": {"机票": "机票是登机时要出示的凭证，上飞机前要给工作人员看。", "车票": "语义：车票是坐火车用的，上飞机前不用出示。", "作业": "语义：作业不是登机时要出示的东西。", "名字": "搭配：“看一下你的名字”不是常见说法，这里要看的是凭证。"}, "sentence_index": 0, "correct_answer": "机票"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去火车站，给自己买了一张机票去南京。", "explanation": "这里应该用〈车票〉。去火车站买的是车票，机票是乘坐飞机的票。"}, {"text": "我坐地铁去学校，买了一张机票。", "explanation": "这里应该用〈地铁票〉。坐地铁要买地铁票，机票是乘坐飞机的票。"}, {"text": "周末我去看演唱会，在售票处买了一张机票。", "explanation": "这里应该用〈演出票〉。看演出要买演出票，机票是乘坐飞机的凭证。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机票", "is_correct": true, "explanation": "机票是乘坐飞机的凭证，可以办理改签。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：量词“张”不用于饭，饭要用“份”或“顿”。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：量词“张”不用于电视，电视用“台”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能改签，也不是可以预订的凭证。"}], "explanations": {"机票": "机票是乘坐飞机的凭证，可以办理改签。", "饭": "搭配：量词“张”不用于饭，饭要用“份”或“顿”。", "电视": "搭配：量词“张”不用于电视，电视用“台”。", "空气": "语义：空气不能改签，也不是可以预订的凭证。"}, "sentence_index": 6, "correct_answer": "机票"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公园的机票要五十块。", "explanation": "这里应该用〈门票〉。进公园要买门票，机票是乘坐飞机的票。"}, {"text": "上班路上，我坐机票去公司。", "explanation": "这里应该用〈飞机〉。坐的是飞机，机票只是乘机的凭证，不能当交通工具。"}, {"text": "船要开了，我还没买机票。", "explanation": "这里应该用〈船票〉。坐船要买船票，机票只用于飞机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她拿着一个机票找到了登机口。", "corrected_sentence": "她拿着一张机票找到了登机口。", "error_description": "量词错误：“机票”用量词“张”计量，不能用“个”。正确说法是“一张机票”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于找了到机票。", "corrected_sentence": "他终于找到了机票。", "error_description": "补语错误：结果补语“到”应紧跟动词，说“找到了机票”，不能说“找了到机票”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e811a05-3358-4792-9d62-fdb1a7433492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
