INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90746, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "实地观看（工厂、展览等）。", "primary_collocate": null, "pronunciation": "cān guān", "ipa": "tsʰan˥ kuan˥", "syllable_count": 2, "sentences": [{"text": "我们明天去参观汽车工厂。", "target_word": "参观", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师带学生参观了科技展览。", "target_word": "参观", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "参观工厂时，大家都要戴安全帽。", "target_word": "参观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们参观了这家公司的生产线。", "target_word": "参观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来参观画展的人排了很长的队。", "target_word": "参观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员带客人参观新建的实验室。", "target_word": "参观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想先参观一下农场，再回家。", "target_word": "参观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你参观过那家造纸厂吗？", "target_word": "参观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参观展览要先在门口买票。", "target_word": "参观", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者受邀参观了这座新建的工厂。", "target_word": "参观", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "参观了", "label": "体标"}, {"form": "参观过", "label": "体标"}, {"form": "参观参观", "label": "重叠"}, {"form": "參觀", "label": "繁体"}], "register": "中性", "sense_fingerprint": "亲自到工厂、展览等地方实地观看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2de67917-7f36-4640-ba0a-be9730ecd119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90746, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参观", "is_correct": true, "explanation": "正确：参观是实地看工厂，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“去吃汽车工厂”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，与去工厂看看的意思不符。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“汽车工厂”作宾语。"}], "explanations": {"参观": "正确：参观是实地看工厂，符合句意。", "吃": "搭配：“吃”的对象是食物，不能说“去吃汽车工厂”。", "唱": "语义：“唱”指唱歌，与去工厂看看的意思不符。", "睡": "配价：“睡”是不及物动词，不能带“汽车工厂”作宾语。"}, "sentence_index": 0, "correct_answer": "参观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们去参观朋友。", "explanation": "这里应该用〈拜访〉。参观用于工厂、展览等地方，去看人要用拜访。"}, {"text": "医生仔细参观病人的变化。", "explanation": "这里应该用〈观察〉。参观是亲自到某地实地看，不用于仔细看事物的变化。"}, {"text": "很多人参观那起车祸。", "explanation": "这里应该用〈围观〉。参观是有目的地到展览、工厂等地方看，车祸这类突发事件要用围观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90746, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参观", "is_correct": true, "explanation": "正确：参观是实地看农场，符合句意。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物、身体等，不能说“洗农场”。"}, {"text": "念", "is_correct": false, "explanation": "语义：“念”指出声读出，与去农场看看的意思不符。"}, {"text": "跳", "is_correct": false, "explanation": "配价：“跳”是不及物动词，不能带“农场”作宾语。"}], "explanations": {"参观": "正确：参观是实地看农场，符合句意。", "洗": "搭配：“洗”的对象是衣物、身体等，不能说“洗农场”。", "念": "语义：“念”指出声读出，与去农场看看的意思不符。", "跳": "配价：“跳”是不及物动词，不能带“农场”作宾语。"}, "sentence_index": 6, "correct_answer": "参观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们正在参观这道数学题。", "explanation": "这里应该用〈研究〉。参观针对可以实地看的地方或展览，数学题要用研究。"}, {"text": "我们在礼堂参观了一场讲座。", "explanation": "这里应该用〈听〉。参观是到地方去看展品或设施，听讲座要用听。"}, {"text": "我每天参观一小时英语。", "explanation": "这里应该用〈学〉。参观是到地方实地看，学习英语要用学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3964c9e1-47a6-4c43-b89b-858c5dc24afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
