INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90747, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "正生是中国戏里扮演主要男角色的人。", "primary_collocate": null, "pronunciation": "zhèng shēng", "ipa": "ʈʂɤŋ˥˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这位正生唱得非常好。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在戏里演正生。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正生是戏里的主要男角色。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这出戏的正生是一位老演员。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥从小就想当正生。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上的正生穿着红衣服。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看过很多位正生的表演。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剧团正在找一位年轻的正生。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个正生的声音很好听。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，正生要站得很直。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位正生", "label": "量词"}, {"form": "一个正生", "label": "量词"}], "register": "专业", "sense_fingerprint": "戏曲演员：扮演主要男角色的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7a2fbd5-9221-419f-9b73-a6b85fe461a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90747, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正生", "is_correct": true, "explanation": "正生：扮演主要男角色的人，能唱戏，符合句意。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“唱得非常好”的主语要能唱，钢琴是乐器，不能唱歌。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装书的袋子，不是能唱戏的人。"}, {"text": "河水", "is_correct": false, "explanation": "语义：河水是流动的水，不能唱歌，也不能用“这位”来称呼。"}], "explanations": {"正生": "正生：扮演主要男角色的人，能唱戏，符合句意。", "钢琴": "搭配：“唱得非常好”的主语要能唱，钢琴是乐器，不能唱歌。", "书包": "语义：书包是装书的袋子，不是能唱戏的人。", "河水": "语义：河水是流动的水，不能唱歌，也不能用“这位”来称呼。"}, "sentence_index": 0, "correct_answer": "正生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这出戏的正生只有两句台词，戏份很少。", "explanation": "这里应该用〈配角〉。正生扮演主要男角色，戏份很少、只有两句台词的只能是配角，不能叫正生。"}, {"text": "这出戏的正生是一位白发老奶奶。", "explanation": "这里应该用〈老旦〉。老旦扮演老年女性，正生扮演主要男角色，性别不符。"}, {"text": "这出戏的正生是一个爱讲笑话的小丑。", "explanation": "这里应该用〈丑角〉。丑角是负责逗笑的角色，正生扮演主要男角色，不演小丑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90747, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正生", "is_correct": true, "explanation": "正生：扮演主要男角色的人，可以用“位”来数，表演是戏曲演出，句意通顺。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是人，不能表演，句中说的是“表演”。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“表演”的主体应是演员或角色，雨伞不能表演。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有表演，与“很多位……的表演”的句意不符。"}], "explanations": {"正生": "正生：扮演主要男角色的人，可以用“位”来数，表演是戏曲演出，句意通顺。", "窗户": "语义：窗户不是人，不能表演，句中说的是“表演”。", "雨伞": "搭配：“表演”的主体应是演员或角色，雨伞不能表演。", "石头": "语义：石头没有表演，与“很多位……的表演”的句意不符。"}, "sentence_index": 6, "correct_answer": "正生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师说，正生要演好戏里的老奶奶。", "explanation": "这里应该用〈老旦〉。老旦扮演老年女性，正生扮演主要男角色，性别和年龄都不符。"}, {"text": "老师说，正生要在台上专门逗大家笑。", "explanation": "这里应该用〈丑角〉。丑角负责逗笑，正生扮演主要男角色，不专门逗笑。"}, {"text": "老师说，正生要在脸上画大花脸。", "explanation": "这里应该用〈净〉。画大花脸的是净角，正生不勾脸谱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90747, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我弟弟想当一只正生。", "corrected_sentence": "我弟弟想当一位正生。", "error_description": "量词错误：“正生”指演员，应说“一位正生”。“只”多用于动物或成对的东西，不用于指人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90747, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "剧团里来了一位新的正生们。", "corrected_sentence": "剧团里来了一位新的正生。", "error_description": "数量错误：前面有“一位”，表示一个人，后面的“正生”不能再加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
