INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90748, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90748, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "传统戏曲中生行的一种，扮演主要的男性角色。", "primary_collocate": null, "pronunciation": "zhèng shēng", "ipa": "ʈʂɤŋ˥˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "京剧里的正生常常演好人。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学了十年，终于成了正生。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个戏团的正生叫李明。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正生在台上唱着一首老歌。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很喜欢那位演正生的演员。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演正生的人要有好嗓子。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这场戏里不演小丑，演正生。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "观众都在看台上的正生。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位正生刚过三十岁。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正生和丑角都在台上。", "target_word": "正生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位正生", "label": "量词"}, {"form": "一个正生", "label": "量词"}], "register": "专业", "sense_fingerprint": "传统戏曲生行：主要男性角色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7a2fbd5-9221-419f-9b73-a6b85fe461a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90748, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正生", "is_correct": true, "explanation": "正生：生行中扮演主要男性角色的人，能演好人，符合句意。"}, {"text": "观众", "is_correct": false, "explanation": "搭配：“演好人”的主体应是演员，观众不演戏。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是演员，不能在戏里演好人。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶不会演戏，与句意不符。"}], "explanations": {"正生": "正生：生行中扮演主要男性角色的人，能演好人，符合句意。", "观众": "搭配：“演好人”的主体应是演员，观众不演戏。", "冰箱": "语义：冰箱不是演员，不能在戏里演好人。", "花瓶": "语义：花瓶不会演戏，与句意不符。"}, "sentence_index": 0, "correct_answer": "正生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这出戏的正生只站在后面，没有一句台词。", "explanation": "这里应该用〈配角〉。正生扮演主要男性角色，不能指没有台词、只站在后面的人，这类角色是配角。"}, {"text": "这出戏的正生专门负责逗观众笑。", "explanation": "这里应该用〈丑角〉。丑角负责逗笑，正生扮演主要男性角色，不负责逗笑。"}, {"text": "正生在台上演着一位年轻的小姐。", "explanation": "这里应该用〈旦角〉。扮演女性的是旦角，正生扮演主要男性角色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90748, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正生", "is_correct": true, "explanation": "正生：扮演主要男性角色的人，与“不演小丑，演……”的对比相符。"}, {"text": "小丑", "is_correct": false, "explanation": "语义：句中已说“不演小丑”，再填“小丑”就前后矛盾。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“演”的对象应是角色，窗帘不能被扮演。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是角色，不能被扮演，与句意不符。"}], "explanations": {"正生": "正生：扮演主要男性角色的人，与“不演小丑，演……”的对比相符。", "小丑": "语义：句中已说“不演小丑”，再填“小丑”就前后矛盾。", "窗帘": "搭配：“演”的对象应是角色，窗帘不能被扮演。", "河流": "语义：河流不是角色，不能被扮演，与句意不符。"}, "sentence_index": 6, "correct_answer": "正生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这出戏的正生在台上勾着大花脸，很有气势。", "explanation": "这里应该用〈净〉。正生扮演主要男性角色，不勾脸谱；勾大花脸的是净角，不是正生。"}, {"text": "这出戏的正生是一位年迈的老太太。", "explanation": "这里应该用〈老旦〉。老旦扮演老年女性，正生扮演主要男性角色，性别不符。"}, {"text": "这出戏的正生只在最后上台说了一句话。", "explanation": "这里应该用〈配角〉。正生是主要男性角色，戏份很少的是配角。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只正生是剧团的台柱子。", "corrected_sentence": "这位正生是剧团的台柱子。", "error_description": "量词错误：指人的正生应用“位”或“个”，“只”不能用于指人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "观众都在看台上的一位正生们。", "corrected_sentence": "观众都在看台上的一位正生。", "error_description": "数量错误：有了“一位”，“正生”后面不能再加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
