INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90749, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "男女是男的和女的。", "primary_collocate": null, "pronunciation": "nán nǚ", "ipa": "nan˧˥ ny˨˩˦", "syllable_count": 2, "sentences": [{"text": "运动会上男女都要跑一百米。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的队伍里男女一样多。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服男女都能穿。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来看电影的男女很多。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的厕所要分男女。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛分男女两组，我在女组。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里男女宿舍是分开的。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来跳舞的男女都穿得很漂亮。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司男女各占一半。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鞋男女都可以穿。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "男的和女的（区分性别时用）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628153f8-23f4-4783-aca5-17ac6551aa7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90749, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "男女", "is_correct": true, "explanation": "男女：男的和女的，与“运动会上……都要跑一百米”相合。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能参加跑步，与“跑一百米”不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能跑步，放在运动会的语境里不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能作跑步的主体，与“跑一百米”搭配不当。"}], "explanations": {"男女": "男女：男的和女的，与“运动会上……都要跑一百米”相合。", "桌子": "语义：桌子不能参加跑步，与“跑一百米”不符。", "冰箱": "语义：冰箱不能跑步，放在运动会的语境里不通。", "天气": "搭配：“天气”不能作跑步的主体，与“跑一百米”搭配不当。"}, "sentence_index": 0, "correct_answer": "男女"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在电影院认识了一个男女。", "explanation": "“男女”指男的和女的两类人，不能用“一个”指单个的人，这里应改用〈人〉或〈朋友〉。"}, {"text": "请在表格上填写男女。", "explanation": "这里应该用〈性别〉。表格上要填的是性别，男女指两性的人群，不能说填写男女。"}, {"text": "那位男女是我的同学。", "explanation": "“男女”指两种性别，不能指单个的人，这里应改用〈他〉或〈她〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90749, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "男女", "is_correct": true, "explanation": "男女：男的和女的，与“学校里……宿舍是分开的”相合。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”是心情，不能修饰“宿舍”，句子不通。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”是时间，“明天宿舍是分开的”说不通。"}, {"text": "跑步", "is_correct": false, "explanation": "搭配：“跑步”是动作，不能修饰“宿舍”。"}], "explanations": {"男女": "男女：男的和女的，与“学校里……宿舍是分开的”相合。", "高兴": "语义：“高兴”是心情，不能修饰“宿舍”，句子不通。", "明天": "语义：“明天”是时间，“明天宿舍是分开的”说不通。", "跑步": "搭配：“跑步”是动作，不能修饰“宿舍”。"}, "sentence_index": 6, "correct_answer": "男女"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种鞋一个男女都可以穿。", "explanation": "这里应该用〈对〉或说“一男一女”。男女指两种性别，不能用“个”计数。"}, {"text": "这张表格要你写出你的男女。", "explanation": "这里应该用〈性别〉。表格要求填写的是性别，男女指两性的人群，不能这样说。"}, {"text": "那位男女是我的老师。", "explanation": "“男女”指两种性别，不能指单个的人，这里应改用〈他〉或〈她〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90749, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "比赛时男女们都要穿统一的队服。", "corrected_sentence": "比赛时男女都要穿统一的队服。", "error_description": "错误在“男女”后面加了“们”：“男女”本身已指两种性别，后面不能再加复数词尾“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90749, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师让一个男女分开排队。", "corrected_sentence": "老师让男女分开排队。", "error_description": "错误在“男女”前面多加了“一个”：“男女”指两种性别的人群，不能用量词“个”计数，应直接说“男女”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
