INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90750, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "男人和女人。", "primary_collocate": null, "pronunciation": "nán nǚ", "ipa": "nan˧˥ ny˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家公司里男女都有。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男女都可以参加这个比赛。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里的男女学生一样多。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管男女，大家都要排队。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说男女应该得到一样的机会。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律上男女是平等的。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动不分男女，谁都可以来。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加会议的男女一共有五十人。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司男女的工资一样高。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里跳舞的男女都很开心。", "target_word": "男女", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "男人和女人（泛指两种性别的人）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628153f8-23f4-4783-aca5-17ac6551aa7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90750, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "男女", "is_correct": true, "explanation": "男女：泛指男人和女人，与“这家公司里……都有”相合。"}, {"text": "非常", "is_correct": false, "explanation": "词性：“非常”是副词，不能作“都有”的主语。"}, {"text": "已经", "is_correct": false, "explanation": "词性：“已经”是副词，不能指公司里的人。"}, {"text": "因为", "is_correct": false, "explanation": "词性：“因为”是连词，放在这里句子不通。"}], "explanations": {"男女": "男女：泛指男人和女人，与“这家公司里……都有”相合。", "非常": "词性：“非常”是副词，不能作“都有”的主语。", "已经": "词性：“已经”是副词，不能指公司里的人。", "因为": "词性：“因为”是连词，放在这里句子不通。"}, "sentence_index": 0, "correct_answer": "男女"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和妹妹是男女，长得很像。", "explanation": "这里应该用〈兄妹〉。男女泛指两种性别的人，不表示亲属关系。"}, {"text": "他是个真正的男女。", "explanation": "这里应该用〈男子汉〉。男女指两性，不能用来形容一个人有男子气概。"}, {"text": "这位男女是我的同学。", "explanation": "“男女”泛指两性，不能指单个的人，这里应改用〈他〉或〈她〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90750, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "男女", "is_correct": true, "explanation": "男女：泛指两种性别的人，与“不分……，谁都可以来”相合。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“不分”后接“汽车”不成立，活动不以汽车为分类。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头不是可以用来区分参加者的类别。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典与参加活动的人无关，不能作“不分”的对象。"}], "explanations": {"男女": "男女：泛指两种性别的人，与“不分……，谁都可以来”相合。", "汽车": "搭配：“不分”后接“汽车”不成立，活动不以汽车为分类。", "木头": "语义：木头不是可以用来区分参加者的类别。", "字典": "语义：字典与参加活动的人无关，不能作“不分”的对象。"}, "sentence_index": 6, "correct_answer": "男女"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们是男女，已经结婚十年了。", "explanation": "这里应该用〈夫妻〉。男女泛指两种性别的人，不表示婚姻关系。"}, {"text": "他很有男女气概，做事干脆利落。", "explanation": "这里应该用〈男子〉。男子气概指男人的气质，男女指两性，不能这样用。"}, {"text": "那位男女是医生。", "explanation": "“男女”泛指两性，不能指单个的人，这里应改用〈他〉或〈她〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "舞台上走来了一个男女。", "corrected_sentence": "舞台上走来了一对男女。", "error_description": "错误在量词：一男一女成对出现时用“对”计量，说“一对男女”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路边走过一位男女，手牵着手。", "corrected_sentence": "路边走过一对男女，手牵着手。", "error_description": "错误在量词：“位”只计一个人。一男一女成对出现时用“对”，应为“一对男女”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
