INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90751, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很多人参加、规模很大的比赛。", "primary_collocate": null, "pronunciation": "dà sài", "ipa": "ta˥˩ saɪ˥˩", "syllable_count": 2, "sentences": [{"text": "全国的学生都来参加这次大赛。", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大赛有一千多人报名。", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校要举办唱歌大赛。", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大赛中得了第一名。", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天有一场足球大赛，我们去看吧。", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次大赛的奖品很多。", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说画画大赛下个月开始。", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你准备好参加汉语大赛了吗？", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年的大赛都有几万人报名。", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了大赛，每天练习三个小时。", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "届", "label": "量词"}], "register": "中性", "sense_fingerprint": "很多人参加、规模很大的比赛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628153f8-23f4-4783-aca5-17ac6551aa7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90751, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大赛", "is_correct": true, "explanation": "大赛：很多人参加、规模很大的比赛，符合“全国的学生都来参加这次”的句意。"}, {"text": "大厦", "is_correct": false, "explanation": "搭配：“参加”需要比赛、活动之类的宾语，大厦不能被参加。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“参加”不能带“花园”作宾语，学生不会去参加花园。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不是活动，学生不会“参加”它。"}], "explanations": {"大赛": "大赛：很多人参加、规模很大的比赛，符合“全国的学生都来参加这次”的句意。", "大厦": "搭配：“参加”需要比赛、活动之类的宾语，大厦不能被参加。", "花园": "搭配：“参加”不能带“花园”作宾语，学生不会去参加花园。", "钢琴": "语义：钢琴是乐器，不是活动，学生不会“参加”它。"}, "sentence_index": 0, "correct_answer": "大赛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "期末的大赛我考了九十分。", "explanation": "这里应该用〈考试〉。大赛指很多人参加的大型比赛，个人的期末测验要用考试。"}, {"text": "我每天早上一个人在公园里做大赛。", "explanation": "这里应该用〈运动〉。大赛要有很多人参加，个人的日常锻炼要说做运动。"}, {"text": "学校礼堂今晚有一场大赛，校长讲了开学的注意事项。", "explanation": "这里应该用〈大会〉。大赛是比赛，校长讲话、布置事项属于大会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90751, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大赛", "is_correct": true, "explanation": "大赛：比赛活动，符合“听说画画……下个月开始”的句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“画画”是绘画活动，后面不能接“冰箱”，这样搭配不通。"}, {"text": "手术", "is_correct": false, "explanation": "语义：手术是医疗操作，与绘画活动无关，句子语境说不通。"}, {"text": "红绿灯", "is_correct": false, "explanation": "搭配：“画画”不能带“红绿灯”作宾语，这样搭配不通。"}], "explanations": {"大赛": "大赛：比赛活动，符合“听说画画……下个月开始”的句意。", "冰箱": "搭配：“画画”是绘画活动，后面不能接“冰箱”，这样搭配不通。", "手术": "语义：手术是医疗操作，与绘画活动无关，句子语境说不通。", "红绿灯": "搭配：“画画”不能带“红绿灯”作宾语，这样搭配不通。"}, "sentence_index": 6, "correct_answer": "大赛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天放学后在家做大赛。", "explanation": "这里应该用〈作业〉。大赛是很多人参加的比赛，做作业不能说大赛。"}, {"text": "这次大赛我们去了很多地方，玩得很开心。", "explanation": "这里应该用〈旅行〉。大赛是竞赛，外出游玩、到各地看看要用旅行。"}, {"text": "春节是中国的大赛，全家人一起吃饭。", "explanation": "这里应该用〈节日〉。大赛指比赛活动，春节是传统节日，要用节日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90751, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校下个月要举办一只大赛。", "corrected_sentence": "学校下个月要举办一场大赛。", "error_description": "量词错误：“大赛”是比赛活动，应用“场”或“届”，不能用“只”。应说“学校下个月要举办一场大赛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90751, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校吃掉了一场唱歌大赛。", "corrected_sentence": "学校举办了一场唱歌大赛。", "error_description": "动词搭配错误：“大赛”是活动，不能“吃掉”，应用“举办”。应说“学校举办了一场唱歌大赛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
