INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90752, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "规模较大的比赛。", "primary_collocate": null, "pronunciation": "dà sài", "ipa": "ta˥˩ saɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这次大赛在北京举行。", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校举办了一场作文大赛。", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们队赢了这场篮球大赛。", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大赛的第一天，天气很好。", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她参加了市里的歌唱大赛。", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的游泳大赛在海边进行。", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了这场大赛，他们准备了半年。", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大赛开始前，大家都很紧张。", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带学生去参加大赛。", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在这次大赛里认识了很多朋友。", "target_word": "大赛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "届", "label": "量词"}], "register": "中性", "sense_fingerprint": "规模较大的比赛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628153f8-23f4-4783-aca5-17ac6551aa7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90752, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大赛", "is_correct": true, "explanation": "大赛：规模较大的比赛，符合“这次……在北京举行”的句意。"}, {"text": "公寓", "is_correct": false, "explanation": "搭配：“举行”用于活动，公寓不能被举行，这样搭配不通。"}, {"text": "草原", "is_correct": false, "explanation": "搭配：“举行”不能用于草原，这样搭配不通。"}, {"text": "合同", "is_correct": false, "explanation": "语义：合同是文件，不是活动，不能在北京举行。"}], "explanations": {"大赛": "大赛：规模较大的比赛，符合“这次……在北京举行”的句意。", "公寓": "搭配：“举行”用于活动，公寓不能被举行，这样搭配不通。", "草原": "搭配：“举行”不能用于草原，这样搭配不通。", "合同": "语义：合同是文件，不是活动，不能在北京举行。"}, "sentence_index": 0, "correct_answer": "大赛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的大赛医生给很多人检查身体。", "explanation": "这里应该用〈体检〉。大赛是规模较大的比赛，医生给很多人检查身体要用体检。"}, {"text": "今天的大赛讨论了下个月的工作计划。", "explanation": "这里应该用〈会议〉。大赛是比赛，讨论工作计划要用会议。"}, {"text": "今晚的大赛大家一起唱歌跳舞，很热闹。", "explanation": "这里应该用〈晚会〉。大赛要比出名次，随意唱歌跳舞不是比赛，要用晚会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大赛", "is_correct": true, "explanation": "大赛：规模较大的比赛，符合“为了这场……准备了半年”的句意。"}, {"text": "晚霞", "is_correct": false, "explanation": "搭配：不能为“晚霞”准备半年，这样搭配不通。"}, {"text": "雪花", "is_correct": false, "explanation": "搭配：不能为“雪花”准备半年，这样搭配不通。"}, {"text": "名片", "is_correct": false, "explanation": "语义：名片是小卡片，不是活动，不需要为它准备半年。"}], "explanations": {"大赛": "大赛：规模较大的比赛，符合“为了这场……准备了半年”的句意。", "晚霞": "搭配：不能为“晚霞”准备半年，这样搭配不通。", "雪花": "搭配：不能为“雪花”准备半年，这样搭配不通。", "名片": "语义：名片是小卡片，不是活动，不需要为它准备半年。"}, "sentence_index": 6, "correct_answer": "大赛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本大赛很厚，我看了一个月。", "explanation": "这里应该用〈书〉。大赛是比赛活动，不能用来读。"}, {"text": "这个大赛的水果很便宜。", "explanation": "这里应该用〈市场〉。大赛是比赛活动，卖水果的地方要用市场。"}, {"text": "这家大赛的床很舒服，我们住了一晚。", "explanation": "这里应该用〈宾馆〉。大赛是比赛，供人住宿、床位舒适的地方要用宾馆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年有一只大赛在北京举行。", "corrected_sentence": "今年有一场大赛在北京举行。", "error_description": "量词错误：“大赛”是比赛活动，应用“场”或“届”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "为了这场大赛们，我们练习了很久。", "corrected_sentence": "为了这场大赛，我们练习了很久。", "error_description": "“大赛”是比赛活动，不指人，不能加复数词尾“们”。应说“为了这场大赛”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35e2a32e-37dc-49d0-81a3-3d3291b7cd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
