INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90753, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "气息是呼出来或闻到的气味。", "primary_collocate": null, "pronunciation": "qì xī", "ipa": "tɕʰi˥˩ ɕi˥", "syllable_count": 2, "sentences": [{"text": "他刚吃过蒜，嘴里有一股难闻的气息。", "target_word": "气息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开窗户，就能闻到花草的气息。", "target_word": "气息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的空气里有泥土的气息。", "target_word": "气息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里有一股清新的气息。", "target_word": "气息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她身上有淡淡的香皂气息。", "target_word": "气息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗闻着地上的气息找到了主人。", "target_word": "气息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里飘出面包的气息。", "target_word": "气息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，空气里满是青草的气息。", "target_word": "气息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间旧屋子有一股发霉的气息。", "target_word": "气息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠近我，我闻到了酒的气息。", "target_word": "气息", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股气息", "label": "量词"}, {"form": "一丝气息", "label": "量词"}], "register": "中性", "sense_fingerprint": "呼出或闻到的气味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99f4a601-3387-46d6-8878-d4f1e5cccdbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90753, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "气息", "is_correct": true, "explanation": "正确：“气息”指闻到的气味，与“嘴里有一股难闻的……”相符。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”是听到的，不是嘴里能闻到的难闻东西。"}, {"text": "牙齿", "is_correct": false, "explanation": "语义：“牙齿”是器官，不能是“难闻”的气味来源的描述对象。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“难闻”形容气味，不能修饰“颜色”。"}], "explanations": {"气息": "正确：“气息”指闻到的气味，与“嘴里有一股难闻的……”相符。", "声音": "语义：“声音”是听到的，不是嘴里能闻到的难闻东西。", "牙齿": "语义：“牙齿”是器官，不能是“难闻”的气味来源的描述对象。", "颜色": "搭配：“难闻”形容气味，不能修饰“颜色”。"}, "sentence_index": 0, "correct_answer": "气息"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的气息很咸，我多喝了几口汤。", "explanation": "这里应该用〈味道〉。气息指呼出或闻到的气味，“咸”形容味觉，要说〈味道〉。"}, {"text": "森林里有一只清新的气息。", "explanation": "这里量词用错。“气息”前一般用〈股〉或〈丝〉，不说〈只〉。"}, {"text": "他用手摸了摸森林里的气息。", "explanation": "这里应该用〈闻〉。气息要用鼻子去〈闻〉，不能用手去〈摸〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90753, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "气息", "is_correct": true, "explanation": "正确：“气息”指飘散的气味，与“厨房里飘出面包的……”相符。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”是走路的动作，不会“飘出”。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是金属工具，不能“飘出”。"}, {"text": "形状", "is_correct": false, "explanation": "搭配：“飘出”不与“形状”搭配。"}], "explanations": {"气息": "正确：“气息”指飘散的气味，与“厨房里飘出面包的……”相符。", "脚步": "语义：“脚步”是走路的动作，不会“飘出”。", "钥匙": "语义：“钥匙”是金属工具，不能“飘出”。", "形状": "搭配：“飘出”不与“形状”搭配。"}, "sentence_index": 6, "correct_answer": "气息"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个苹果的气息很硬，咬一口很脆。", "explanation": "这里应该用〈口感〉。气息指呼出或闻到的气味，“硬”“脆”形容的是口感，不能用来形容气味。"}, {"text": "我看见了他身上的酒的气息。", "explanation": "这里动词用错。气息要用鼻子〈闻〉到，不能用眼睛〈看见〉。"}, {"text": "他的气息关上了门，转身离开了。", "explanation": "主语用错。关门的应该是人，〈气息〉不能做“关上”的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90753, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨房里飘出来一块香香的气息。", "corrected_sentence": "厨房里飘出来一股香香的气息。", "error_description": "错误形式：“一块香香的气息”；正确形式：“一股香香的气息”。“块”用于块状物，不能搭配“气息”，应改用“股”（或“丝”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90753, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在厨房里闻到一块酒的气息。", "corrected_sentence": "我在厨房里闻到一股酒的气息。", "error_description": "错误形式：“一块酒的气息”；正确形式：“一股酒的气息”。“块”用于块状物，不能搭配“气息”，应改用“股”（或“丝”）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51775b1b-94e7-4748-b602-c5d56bf5490b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
