INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90755, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "当初是最开始那个时候。", "primary_collocate": null, "pronunciation": "dāng chū", "ipa": "taŋ˥ tʂʰu˥", "syllable_count": 2, "sentences": [{"text": "当初我们住在一个小村子里。", "target_word": "当初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当初为什么离开家，没人知道。", "target_word": "当初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当初说好一起去，你怎么不来了？", "target_word": "当初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我当初很喜欢这份工作。", "target_word": "当初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当初那家店很小，现在很大了。", "target_word": "当初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当初她哭着说再见，我还记得。", "target_word": "当初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你当初为什么选这个专业？", "target_word": "当初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当初是他先找的我。", "target_word": "当初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们当初的约定，你还记得吗？", "target_word": "当初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当初这个城市没有地铁。", "target_word": "当初", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "当初：指过去最开始的那个时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf72999-cc70-48ab-a55f-436b9cac05ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90755, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当初", "is_correct": true, "explanation": "“当初”指过去最早的那段时间，与“住在一个小村子里”相合。"}, {"text": "大都市", "is_correct": false, "explanation": "语义：“大都市”与“小村子”矛盾，句子说的是小村子。"}, {"text": "城市", "is_correct": false, "explanation": "语法：“城市”是地点名词，不能放在句首表示时间，句子不通。"}, {"text": "年代", "is_correct": false, "explanation": "搭配：“年代”单独作主语不成立，需说“那个年代”。"}], "explanations": {"当初": "“当初”指过去最早的那段时间，与“住在一个小村子里”相合。", "大都市": "语义：“大都市”与“小村子”矛盾，句子说的是小村子。", "城市": "语法：“城市”是地点名词，不能放在句首表示时间，句子不通。", "年代": "搭配：“年代”单独作主语不成立，需说“那个年代”。"}, "sentence_index": 0, "correct_answer": "当初"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我当初下个月就要毕业了。", "explanation": "这里说的是将来的事。“当初”只指过去最早的时候，不能和“下个月”一起用，应去掉“当初”。"}, {"text": "当初我们在开会，电话响了。", "explanation": "这里应该用〈当时〉。“当初”指最早的时候，描述正在进行的事情要用“当时”。"}, {"text": "刚才当初她哭着走了。", "explanation": "这里说的是不久前发生的事。“当初”指最早的时候，不能用来说不久前的事，应去掉“当初”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90755, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当初", "is_correct": true, "explanation": "“当初”指做决定的最早时候，与“为什么选这个专业”的问题相合。"}, {"text": "年头", "is_correct": false, "explanation": "搭配：“年头”不能直接放在句首作时间，需说“那年头”或“这年头”。"}, {"text": "时代", "is_correct": false, "explanation": "语义：“时代”指大的历史阶段，不能用来问个人选专业的时间。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”指一周的时间，选专业不是一周之内的事，句子不通。"}], "explanations": {"当初": "“当初”指做决定的最早时候，与“为什么选这个专业”的问题相合。", "年头": "搭配：“年头”不能直接放在句首作时间，需说“那年头”或“这年头”。", "时代": "语义：“时代”指大的历史阶段，不能用来问个人选专业的时间。", "星期": "语义：“星期”指一周的时间，选专业不是一周之内的事，句子不通。"}, "sentence_index": 6, "correct_answer": "当初"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "当初你明天就会来吗？", "explanation": "这是对将来的问话，“当初”只指过去，这里应该用〈以后〉。"}, {"text": "我每次回家，当初都会看见他。", "explanation": "这里表示经常发生的事，应该用〈经常〉。“当初”只指最早的那一次，不能用来说反复发生的事。"}, {"text": "我当初今天吃了两碗饭。", "explanation": "这里说的是当天发生的事。“当初”指最早的时候，不能用来说当天的事，应去掉“当初”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90755, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们当初了住在一个大院子里。", "corrected_sentence": "他们当初住在一个大院子里。", "error_description": "错误：“当初”是时间词，后面不能加助词“了”。正确：“他们当初住在一个大院子里。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90755, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他当初了没有带钥匙。", "corrected_sentence": "他当初没有带钥匙。", "error_description": "错误：“当初”是时间词，后面不能加助词“了”。正确：“他当初没有带钥匙。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
