INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90756, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "起初；事情发生的最初时候。", "primary_collocate": null, "pronunciation": "dāng chū", "ipa": "taŋ˥ tʂʰu˥", "syllable_count": 2, "sentences": [{"text": "当初我们都不认识，后来才成了朋友。", "target_word": "当初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当初这里只有一条小路。", "target_word": "当初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当初来北京的时候，一个人也不认识。", "target_word": "当初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我当初不该说那句话。", "target_word": "当初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当初大家都不同意，现在都说好。", "target_word": "当初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司当初只有五个人。", "target_word": "当初", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当初你要是听我的就好了。", "target_word": "当初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当初买这房子，只花了二十万。", "target_word": "当初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当初学汉语，一天只学十个字。", "target_word": "当初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当初的想法，现在看来太简单了。", "target_word": "当初", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "当初：回指事情刚开始、最初的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf72999-cc70-48ab-a55f-436b9cac05ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90756, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当初", "is_correct": true, "explanation": "“当初”指事情最开始的时候，与后面的“后来”相呼应。"}, {"text": "时代", "is_correct": false, "explanation": "语义：“时代”指一个历史阶段，不能作“我们都不认识”的时间起点。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”指一周的时间，与“后来才成了朋友”所说的较长变化不合。"}, {"text": "年代", "is_correct": false, "explanation": "搭配：“年代”单独作时间状语不成立，需说“那个年代”。"}], "explanations": {"当初": "“当初”指事情最开始的时候，与后面的“后来”相呼应。", "时代": "语义：“时代”指一个历史阶段，不能作“我们都不认识”的时间起点。", "星期": "语义：“星期”指一周的时间，与“后来才成了朋友”所说的较长变化不合。", "年代": "搭配：“年代”单独作时间状语不成立，需说“那个年代”。"}, "sentence_index": 0, "correct_answer": "当初"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "当初我正在上课，没接你的电话。", "explanation": "这里应该用〈当时〉。“当初”指事情最开始的时候，描述正在进行的某个时刻要用“当时”。"}, {"text": "当初你明天再来吧，我现在没空。", "explanation": "这里说的是明天，应该用〈以后〉。“当初”只指过去的最初时间，不能用来指将来。"}, {"text": "当初我们现在就出发吧。", "explanation": "这里说的是现在要做的事。“当初”只指过去最早的时候，不能和“现在”一起用，应去掉“当初”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90756, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当初", "is_correct": true, "explanation": "“当初”指过去的最初时候，与“要是……就好了”表示对过去的遗憾相合。"}, {"text": "季节", "is_correct": false, "explanation": "语义：“季节”指一年中的时段，不能作表示遗憾的假设句的时间起点。"}, {"text": "世纪", "is_correct": false, "explanation": "语义：“世纪”跨度太大，不符合“听我的就好了”这种具体的遗憾。"}, {"text": "年头", "is_correct": false, "explanation": "搭配：“年头”单用不能作时间状语，需说“那年头”或“这年头”。"}], "explanations": {"当初": "“当初”指过去的最初时候，与“要是……就好了”表示对过去的遗憾相合。", "季节": "语义：“季节”指一年中的时段，不能作表示遗憾的假设句的时间起点。", "世纪": "语义：“世纪”跨度太大，不符合“听我的就好了”这种具体的遗憾。", "年头": "搭配：“年头”单用不能作时间状语，需说“那年头”或“这年头”。"}, "sentence_index": 6, "correct_answer": "当初"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每次去那家店，当初都会买一杯咖啡。", "explanation": "这里表示经常发生的事，应该用〈经常〉。“当初”只指事情最开始的那一次，不能用来说反复发生的事。"}, {"text": "刚才当初有人来过这里。", "explanation": "这里说的是不久前发生的事。“当初”指最早的时候，不能用来说不久前的事，应去掉“当初”。"}, {"text": "我当初今天没来上课。", "explanation": "这里说的是当天发生的事。“当初”指最早的时候，不能用来说当天的事，应去掉“当初”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90756, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他当初了没有结婚。", "corrected_sentence": "他当初没有结婚。", "error_description": "错误：“当初”是时间词，后面不能加助词“了”。正确：“他当初没有结婚。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90756, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们当初了约好每周见一次。", "corrected_sentence": "我们当初约好每周见一次。", "error_description": "错误：“当初”是时间词，后面不能加助词“了”。正确：“我们当初约好每周见一次。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
