INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90758, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "工资以外按规定发给的补助费用。", "primary_collocate": null, "pronunciation": "jīn tiē", "ipa": "tɕin˥ tʰiɛ˥", "syllable_count": 2, "sentences": [{"text": "按规定，出差的人每天有津贴。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校按规定给老师发津贴。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家规定，医生上夜班可以拿津贴。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出差的时候，公司每天发一百元津贴。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份津贴是国家给学生的补助。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他申请了津贴，可是没有通过。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高温天气，按规定要给工人发津贴。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔津贴是按规定算出来的。", "target_word": "津贴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究生每月可以领到学校的津贴。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "领津贴的人要先填一张表。", "target_word": "津贴", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份津贴", "label": "量词"}, {"form": "一笔津贴", "label": "量词"}, {"form": "住房津贴", "label": "复合"}], "register": "中性", "sense_fingerprint": "按规定发给的补助费用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2c25b5f-321c-4d4e-a8d4-6527f919495c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90758, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "津贴", "is_correct": true, "explanation": "津贴是按规定发给的补助费用，与“按规定”“出差”相合。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是要交给学校的钱，出差的人不会“有”这笔钱作为每天的补助。"}, {"text": "假期", "is_correct": false, "explanation": "搭配：“每天”计量的是钱款或补助，“每天有假期”不成立。"}, {"text": "学位", "is_correct": false, "explanation": "语义：学位是学业的认定，与按规定每天发放的补助无关。"}], "explanations": {"津贴": "津贴是按规定发给的补助费用，与“按规定”“出差”相合。", "学费": "语义：学费是要交给学校的钱，出差的人不会“有”这笔钱作为每天的补助。", "假期": "搭配：“每天”计量的是钱款或补助，“每天有假期”不成立。", "学位": "语义：学位是学业的认定，与按规定每天发放的补助无关。"}, "sentence_index": 0, "correct_answer": "津贴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他因为成绩好，拿到了一笔津贴。", "explanation": "这里应该用〈奖学金〉。津贴是按规定发给的补助，因成绩好而颁发的钱要用奖学金。"}, {"text": "工厂因为事故，给工人一大笔津贴。", "explanation": "这里应该用〈赔偿金〉。津贴是按规定发给的补助，不是对事故损失的赔偿。"}, {"text": "他把钱存进银行，每年能拿到一笔津贴。", "explanation": "这里应该用〈利息〉。银行存款的收益叫利息，津贴是按规定发给的补助，不由银行发放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "津贴", "is_correct": true, "explanation": "津贴是按规定发给工人的补助，与高温天气的语境相合。"}, {"text": "罚单", "is_correct": false, "explanation": "语义：罚单是发给违章者的，与发给工人的补助不合。"}, {"text": "奖状", "is_correct": false, "explanation": "语义：奖状是表彰成绩的，与高温天气下按规定的补助不符。"}, {"text": "病历", "is_correct": false, "explanation": "搭配：“发”不接“病历”，病历由医院开具，不能由单位发给工人当补助。"}], "explanations": {"津贴": "津贴是按规定发给工人的补助，与高温天气的语境相合。", "罚单": "语义：罚单是发给违章者的，与发给工人的补助不合。", "奖状": "语义：奖状是表彰成绩的，与高温天气下按规定的补助不符。", "病历": "搭配：“发”不接“病历”，病历由医院开具，不能由单位发给工人当补助。"}, "sentence_index": 6, "correct_answer": "津贴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他替邻居照看了一周孩子，邻居给了他一笔津贴。", "explanation": "这里应该用〈报酬〉。津贴是按规定发给的补助，邻里之间临时的酬劳不叫津贴。"}, {"text": "租房时，他交了一笔津贴。", "explanation": "这里应该用〈押金〉。押金是交给房东的钱，津贴是发给人的补助，方向不合。"}, {"text": "春节那天，叔叔给我一笔津贴。", "explanation": "这里应该用〈压岁钱〉。津贴是按规定发给的补助，春节时长辈给晚辈的礼钱不叫津贴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂每月给工人发一条津贴。", "corrected_sentence": "工厂每月给工人发一份津贴。", "error_description": "量词错误：津贴应说“份”或“笔”，“条”用于细长的东西，不能用来计量津贴。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每月按规定领一只津贴。", "corrected_sentence": "他每月按规定领一笔津贴。", "error_description": "量词错误：津贴应说“笔”或“份”，“只”不能用来计量津贴。应说“领一笔津贴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc03b1c-cf4d-4937-8b7a-40cd3077c746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
