INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90759, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90759, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "当天是发生这件事的那一天。", "primary_collocate": null, "pronunciation": "dāng tiān", "ipa": "taŋ˥ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "这张票只在当天有用。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早上寄信，当天就到了。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当天的作业要当天写完。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们当天去，当天回来。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买的新鲜鱼要当天吃。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨的话，比赛当天会改时间。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生日当天收到很多礼物。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到北京的当天，我们就去了长城。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上买的书，当天就能送到家。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试当天，他起得很早。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "当天：正在说的这件事发生的那一天，常指同一天内完成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53db9dd3-8e45-4d0b-b8b6-d4711d195280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90759, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小猫", "is_correct": false, "explanation": "语义：票只能在“小猫”身上有用，不合常理，也不能限定时间。"}, {"text": "当天", "is_correct": true, "explanation": "正确：“当天”指那一天，与“只在……有用”的时间限定相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：票在厨房里有用不合常理，与票务的使用语境不符。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：票只在黑板上有用不合常理，与票务的使用语境不符。"}], "explanations": {"小猫": "语义：票只能在“小猫”身上有用，不合常理，也不能限定时间。", "当天": "正确：“当天”指那一天，与“只在……有用”的时间限定相符。", "厨房": "语义：票在厨房里有用不合常理，与票务的使用语境不符。", "黑板": "语义：票只在黑板上有用不合常理，与票务的使用语境不符。"}, "sentence_index": 0, "correct_answer": "当天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他正在吃饭，当天朋友来了。", "explanation": "这里应该用〈当时〉。“吃饭”的瞬间用〈当时〉指那个时候；〈当天〉指整整一天，不能表示某一时刻。"}, {"text": "他当天在这家公司工作了十年。", "explanation": "这里应该用〈当年〉。“工作了十年”是很长的一段时间，〈当天〉只指一天，不能和“十年”这样的时长搭配。"}, {"text": "他一说完，大家当天鼓起掌来。", "explanation": "这里应该用〈当即〉。紧接着发生的动作要用〈当即〉表示马上做出；〈当天〉指整天，不能表示即时反应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90759, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作", "is_correct": false, "explanation": "语义：“工作”不是时间词，不能限定“收到礼物”的时点。"}, {"text": "当天", "is_correct": true, "explanation": "正确：“当天”指生日这一天，与句中的时间背景相符。"}, {"text": "眼睛", "is_correct": false, "explanation": "配价：“收到”的主语必须是人，“眼睛”不能收到礼物。"}, {"text": "片刻", "is_correct": false, "explanation": "语域：“片刻”偏书面，指极短的时间，与整个生日的语境不合。"}], "explanations": {"工作": "语义：“工作”不是时间词，不能限定“收到礼物”的时点。", "当天": "正确：“当天”指生日这一天，与句中的时间背景相符。", "眼睛": "配价：“收到”的主语必须是人，“眼睛”不能收到礼物。", "片刻": "语域：“片刻”偏书面，指极短的时间，与整个生日的语境不合。"}, "sentence_index": 6, "correct_answer": "当天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们当天经常见面。", "explanation": "这里〈当天〉被误用为“每天、反复”的意思，但〈当天〉只指事情发生的那一天，不能表示反复出现。"}, {"text": "这个学期当天结束。", "explanation": "这里〈当天〉被误用为“较长时段结束”的意思，但〈当天〉只指事情发生的那一天，不能用来说一段时期的结束。"}, {"text": "他每周当天去游泳。", "explanation": "这里〈当天〉被误用为“按周重复”的意思，但〈当天〉只指事情发生的那一天，不表示周期性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90759, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张车票只能对当天使用。", "corrected_sentence": "这张车票只能在当天使用。", "error_description": "错误：“对当天使用”，应为“在当天使用”。“对”引出的是对象，不能引出时间范围；表示限定在某一天内要用“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90759, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比赛很当天，我们都去现场加油了。", "corrected_sentence": "比赛当天，我们都去现场加油了。", "error_description": "错误：“很当天”，应为“比赛当天”。“当天”是时间名词，不能受副词“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
