INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90760, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事情发生的那一天；同一天。", "primary_collocate": null, "pronunciation": "dāng tiān", "ipa": "taŋ˥ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "婚礼当天，天气特别好。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事故当天，路上没有什么人。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报名当天，我就交了钱。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出发当天，大家都到得很早。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说药要当天用完。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛当天，我紧张得睡不着。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试当天，他穿了一件白衬衫。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天买的面包，当天吃最好吃。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家当天，朋友都来帮忙了。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当天写好信，当天就寄出去了。", "target_word": "当天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "当天：某件事情发生的那一天，常放在事件名称之后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53db9dd3-8e45-4d0b-b8b6-d4711d195280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90760, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "午夜", "is_correct": false, "explanation": "语义：婚礼很少在午夜举行，与“天气特别好”所描述的白天场景不合。"}, {"text": "当天", "is_correct": true, "explanation": "正确：“当天”指婚礼那一天，与句中的时间背景相符。"}, {"text": "刹那", "is_correct": false, "explanation": "语域：“刹那”是书面语，指瞬间，不能用来指婚礼的日子。"}, {"text": "凌晨", "is_correct": false, "explanation": "语义：婚礼一般不在凌晨进行，与“天气特别好”的白天语境不合。"}], "explanations": {"午夜": "语义：婚礼很少在午夜举行，与“天气特别好”所描述的白天场景不合。", "当天": "正确：“当天”指婚礼那一天，与句中的时间背景相符。", "刹那": "语域：“刹那”是书面语，指瞬间，不能用来指婚礼的日子。", "凌晨": "语义：婚礼一般不在凌晨进行，与“天气特别好”的白天语境不合。"}, "sentence_index": 0, "correct_answer": "当天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他正在看书，当天有人敲门。", "explanation": "这里应该用〈当时〉。敲门是看书时的一个瞬间，用〈当时〉；〈当天〉指整天，不表示某一时刻。"}, {"text": "他话音刚落，当天站了起来。", "explanation": "这里应该用〈随即〉。紧接着发生的动作要用〈随即〉表示立即进行；〈当天〉指整天，不能表示紧接着的动作。"}, {"text": "一听到这个消息，大家当天顿时哭了起来。", "explanation": "这里〈当天〉指整天，与句中表示即时反应的〈顿时〉相冲突；〈当天〉不能表示马上发生的反应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深夜", "is_correct": false, "explanation": "语义：面试很少在深夜进行，且穿白衬衫的正式场合与深夜不合。"}, {"text": "当天", "is_correct": true, "explanation": "正确：“当天”指面试那一天，与句中的时间背景相符。"}, {"text": "片刻", "is_correct": false, "explanation": "语域：“片刻”偏书面，指极短的时间，不能用来指面试的日子。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“面试”后不能接身体器官名词，此处搭配不通。"}], "explanations": {"深夜": "语义：面试很少在深夜进行，且穿白衬衫的正式场合与深夜不合。", "当天": "正确：“当天”指面试那一天，与句中的时间背景相符。", "片刻": "语域：“片刻”偏书面，指极短的时间，不能用来指面试的日子。", "眼睛": "搭配：“面试”后不能接身体器官名词，此处搭配不通。"}, "sentence_index": 6, "correct_answer": "当天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店当天开了三年。", "explanation": "这里〈当天〉被误用为“持续多年”的意思，但〈当天〉只指事情发生的那一天，不能表示持续多年。"}, {"text": "她每个月当天交房租。", "explanation": "这里〈当天〉被误用为“每月重复”的意思，但〈当天〉只指一天，不能表示周期性。"}, {"text": "这个假期当天结束。", "explanation": "这里〈当天〉被误用为“整段时间结束”的意思，但〈当天〉只指事情发生的那一天，不能用来表示整段时间的结束。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "典礼很当天，场地里挤满了人。", "corrected_sentence": "典礼当天，场地里挤满了人。", "error_description": "错误：“很当天”，应为“当天”。“当天”是时间名词，不能受副词“很”修饰；“很”修饰的是形容词等，不能加在这个词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "搬家当天，我们一起吃了午饭当天。", "corrected_sentence": "搬家当天，我们一起吃了午饭。", "error_description": "错误：句末多出的“当天”，应删去。“当天”是时间名词，句首的“搬家当天”已经交代了时间，句末的“午饭当天”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
