INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90761, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "和一个人住在一起的家里人。", "primary_collocate": null, "pronunciation": "jiā shǔ", "ipa": "tɕja˥ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "他和家属住在公司附近的小区里。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和家属住在一起，生活很温馨。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家时，家属一起帮他收拾东西。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天下班回家陪家属吃晚饭。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套房子很大，够他和家属住。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带着家属搬到了新城市。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末他常和家属一起去公园散步。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家属都在家等他回来吃饭。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把家属接到了身边一起生活。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家属都很喜欢这个新家。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "家屬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "与某人同住的家人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '752a5636-7271-49eb-b21b-15ae1b5105ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90761, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家属", "is_correct": true, "explanation": "正确答案。家属指与他同住的家人，符合“住在小区里”的语境。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是外地来旅游的人，不会和他一起住在小区里。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是乘坐交通工具的人，与“住在小区里”的语境不符。"}, {"text": "宾客", "is_correct": false, "explanation": "语域：宾客是较正式的书面用语，且指来做客的人，不会长住在小区里。"}], "explanations": {"家属": "正确答案。家属指与他同住的家人，符合“住在小区里”的语境。", "游客": "语义：游客是外地来旅游的人，不会和他一起住在小区里。", "乘客": "语义：乘客是乘坐交通工具的人，与“住在小区里”的语境不符。", "宾客": "语域：宾客是较正式的书面用语，且指来做客的人，不会长住在小区里。"}, "sentence_index": 0, "correct_answer": "家属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们一家人都很爱学习，是一个很温馨的家属。", "explanation": "这里应该用〈家庭〉。家属指家里的某一位成员，说整个家这个集体要用“家庭”。"}, {"text": "球队的家属都在场上比赛。", "explanation": "这里应该用〈队员〉。队员是上场比赛的人；家属指与某人同住的家里人，不会上场比赛。"}, {"text": "他是这所大学的家属，去年被学校开除了学籍。", "explanation": "这里应该用〈学生〉。学籍只属于学生；家属是与某人同住的家里人，没有学籍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90761, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家属", "is_correct": true, "explanation": "正确答案。家属指与他同住的家人，符合“一起去公园散步”的语境。"}, {"text": "顾客", "is_correct": false, "explanation": "语义：顾客是来买东西的人，不会常和他一起去公园散步。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众是看演出或比赛的人，与他常一起散步的关系不符。"}, {"text": "来宾", "is_correct": false, "explanation": "语域：来宾是正式场合的用语，口语叙述中一般不用，且指出席活动的客人。"}], "explanations": {"家属": "正确答案。家属指与他同住的家人，符合“一起去公园散步”的语境。", "顾客": "语义：顾客是来买东西的人，不会常和他一起去公园散步。", "观众": "语义：观众是看演出或比赛的人，与他常一起散步的关系不符。", "来宾": "语域：来宾是正式场合的用语，口语叙述中一般不用，且指出席活动的客人。"}, "sentence_index": 6, "correct_answer": "家属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个家属很大，有三层楼。", "explanation": "这里应该用〈房子〉。房子是有楼层的建筑；家属指人，不能用来形容房屋的大小和楼层。"}, {"text": "王家的家属延续了三百年，人人都姓王。", "explanation": "这里应该用〈家族〉。家族指同一宗族、可延续多代的人；家属只指与某人同住的家里人。"}, {"text": "他被关在家属里，连门都出不去。", "explanation": "这里应该用〈家〉。家是住的地方，可以说“在家里”；家属指人，不能说“在家属里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90761, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的家属有三只，都住在这个小区。", "corrected_sentence": "他的家属有三位，都住在这个小区。", "error_description": "量词错误：“家属”指人，应该用“位”计数，不能用“只”（“只”用于动物或成对物品中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90761, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末他带着两条家属去了郊外。", "corrected_sentence": "周末他带着两位家属去了郊外。", "error_description": "量词错误：“家属”指人，应该用“位”计数，“条”用于细长的东西，不能用来数人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
