INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90762, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "户主或某人的家庭成员。", "primary_collocate": null, "pronunciation": "jiā shǔ", "ipa": "tɕja˥ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "医生把病情告诉了病人家属。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给职工家属发了节日礼物。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请病人家属在门外等一下。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动欢迎员工和家属参加。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院规定，家属可以在下午探视。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事故发生后，警方通知了遇难者家属。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烈士家属受到了社会的尊敬。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校邀请学生家属来看演出。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术前，家属需要在同意书上签字。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂为职工家属建了一所幼儿园。", "target_word": "家属", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "家屬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "病人、职工、遇难者等人的家庭成员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '752a5636-7271-49eb-b21b-15ae1b5105ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90762, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家属", "is_correct": true, "explanation": "正确答案。家属指病人的家庭成员，符合“把病情告诉病人家属”的语境。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众是看演出或比赛的人，不会接受医生对病情的告知。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是来旅游的人，与病人的病情和医生的告知无关。"}, {"text": "来宾", "is_correct": false, "explanation": "语域：来宾是正式场合的用语，且指出席活动的客人，与病情告知的语境不合。"}], "explanations": {"家属": "正确答案。家属指病人的家庭成员，符合“把病情告诉病人家属”的语境。", "观众": "语义：观众是看演出或比赛的人，不会接受医生对病情的告知。", "游客": "语义：游客是来旅游的人，与病人的病情和医生的告知无关。", "来宾": "语域：来宾是正式场合的用语，且指出席活动的客人，与病情告知的语境不合。"}, "sentence_index": 0, "correct_answer": "家属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小区里一个家属有三口人。", "explanation": "这里应该用〈家庭〉。家属是家庭中的个人，说一家有几口人要用“家庭”。"}, {"text": "这家养殖场的家属都在院子里吃草。", "explanation": "这里应该用〈家畜〉。家畜是养在家中的牲畜，会在院子里吃草；家属指人，不能指动物。"}, {"text": "这台电脑的家属都很旧了，需要换掉。", "explanation": "这里应该用〈部件〉。部件是电脑的组成零件，用久了会旧、需要更换；家属指人，不能指电脑的零件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90762, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家属", "is_correct": true, "explanation": "正确答案。家属指烈士的家庭成员，符合“受到社会尊敬”的语境。"}, {"text": "顾客", "is_correct": false, "explanation": "语义：顾客是来买东西的人，“烈士顾客”搭配不通，且与烈士的亲属无关。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是乘坐交通工具的人，与烈士的身份和社会尊敬的语境无关。"}, {"text": "宾客", "is_correct": false, "explanation": "语域：宾客是较正式的书面用语，且指来做客的人，与烈士的身份不相关。"}], "explanations": {"家属": "正确答案。家属指烈士的家庭成员，符合“受到社会尊敬”的语境。", "顾客": "语义：顾客是来买东西的人，“烈士顾客”搭配不通，且与烈士的亲属无关。", "乘客": "语义：乘客是乘坐交通工具的人，与烈士的身份和社会尊敬的语境无关。", "宾客": "语域：宾客是较正式的书面用语，且指来做客的人，与烈士的身份不相关。"}, "sentence_index": 6, "correct_answer": "家属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房的桌子上放着家属，准备今晚做饭。", "explanation": "这里应该用〈食材〉。食材是用来做饭的原料；家属指人，不能当作食材。"}, {"text": "这栋家属很旧，已经有一百多年了。", "explanation": "这里应该用〈楼房〉。楼房是建筑，可以说“这栋楼房很旧”；家属指人，不能用“栋”，也不能形容建筑的新旧。"}, {"text": "事故现场，警方收集了遇难者的家属，装进了证物袋。", "explanation": "这里应该用〈遗物〉。遗物是死者留下的物品，可以装进证物袋；家属指遇难者的亲属，不是物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "病人的两只家属在门外等了很久。", "corrected_sentence": "病人的两位家属在门外等了很久。", "error_description": "量词错误：“家属”指人，应该用“位”计数，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次事故中，遇难者的两条家属都来了现场。", "corrected_sentence": "这次事故中，遇难者的两位家属都来了现场。", "error_description": "量词错误：“家属”指人，应该用“位”计数，“条”用于细长的东西，不能用来数人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
