INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90763, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "火焰是火烧起来时，向上跳动的亮光。", "primary_collocate": null, "pronunciation": "huǒ yàn", "ipa": "xuo˨˩˦ jɛn˥˩", "syllable_count": 2, "sentences": [{"text": "火焰在夜里跳动着。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红红的火焰往上冒。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的火焰很远就能看见。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们围着火焰唱歌。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火焰越来越高，大家都往后退。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大火把木头烧成了黑色，火焰冲得很高。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "炉子里有一团火焰。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看见窗外有火焰，马上打电话。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火焰的光照在她脸上。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火很小的时候，火焰也在动。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一团火焰", "label": "量词"}, {"form": "一道火焰", "label": "量词"}], "register": "中性", "sense_fingerprint": "火烧起来时向上跳动的亮光", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7a2fbd5-9221-419f-9b73-a6b85fe461a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90763, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "火焰", "is_correct": true, "explanation": "火焰指火烧起来时向上跳动的亮光，是这里要选的词。"}, {"text": "火眼", "is_correct": false, "explanation": "yàn（第四声）与 yǎn（第三声）声调不同，火眼指眼病或明亮的眼睛，不是火焰。"}, {"text": "火烟", "is_correct": false, "explanation": "yàn（第四声）与 yān（第一声）声调不同，火烟指烧火时冒出的烟。"}, {"text": "火药", "is_correct": false, "explanation": "yàn 与 yào 韵母不同（an/ao），火药是易燃易爆的东西。"}], "explanations": {"火焰": "火焰指火烧起来时向上跳动的亮光，是这里要选的词。", "火眼": "yàn（第四声）与 yǎn（第三声）声调不同，火眼指眼病或明亮的眼睛，不是火焰。", "火烟": "yàn（第四声）与 yān（第一声）声调不同，火烟指烧火时冒出的烟。", "火药": "yàn 与 yào 韵母不同（an/ao），火药是易燃易爆的东西。"}, "sentence_index": null, "correct_answer": "火焰"}, "level_3": {"options": [{"text": "火焰", "is_correct": true, "explanation": "火焰是火烧起来时向上跳动的亮光，正好能在夜里跳动。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是静止的物体，不会跳动。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会自己跳动，句子说不通。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：月亮只说升起、落下，不说“跳动”。"}], "explanations": {"火焰": "火焰是火烧起来时向上跳动的亮光，正好能在夜里跳动。", "石头": "语义：石头是静止的物体，不会跳动。", "桌子": "语义：桌子不会自己跳动，句子说不通。", "月亮": "搭配：月亮只说升起、落下，不说“跳动”。"}, "sentence_index": 0, "correct_answer": "火焰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜里的街上火焰通明，像白天一样。", "explanation": "这里应该用〈灯火〉。“灯火通明”指灯光照得很亮，火焰指向上跳动的亮光，不用来形容街道的灯光。"}, {"text": "铁匠锤打烧红的铁块，迸出许多火焰。", "explanation": "这里应该用〈火星〉。锤打铁块迸出的是细小炽热的火点，即火星；“火焰”指向上跳动的亮光，不用来形容四散的火点。"}, {"text": "他使劲一擦，把火焰擦亮了。", "explanation": "这里应该用〈火柴〉。“擦亮”用于火柴，火焰是向上跳动的亮光，擦不亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90763, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火焰", "is_correct": true, "explanation": "火焰是火烧起来时向上跳动的亮光，可以说“一团火焰”，正好填入。"}, {"text": "冰", "is_correct": false, "explanation": "语义：冰是冷的固体，放在有火的炉子里不会成团。"}, {"text": "雪", "is_correct": false, "explanation": "语义：雪遇热就化，不会在炉子里成团。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜是水果，不会放在炉子里，也不说“一团西瓜”。"}], "explanations": {"火焰": "火焰是火烧起来时向上跳动的亮光，可以说“一团火焰”，正好填入。", "冰": "语义：冰是冷的固体，放在有火的炉子里不会成团。", "雪": "语义：雪遇热就化，不会在炉子里成团。", "西瓜": "语义：西瓜是水果，不会放在炉子里，也不说“一团西瓜”。"}, "sentence_index": 6, "correct_answer": "火焰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一生气就火焰很大，谁都不敢劝他。", "explanation": "这里应该用〈火气〉。“火气大”指脾气急躁，火焰指向上跳动的亮光，不用来形容人的脾气。"}, {"text": "屋里飘着呛人的火焰。", "explanation": "这里应该用〈烟〉。“呛人”说的是烟，火焰会发光发热，不会呛人。"}, {"text": "消防车射出一道火焰。", "explanation": "这里应该用〈水柱〉。消防车射出的是水，不是燃烧的火焰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90763, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "远处的山顶上有一只火焰。", "corrected_sentence": "远处的山顶上有一团火焰。", "error_description": "量词错误：火焰应用量词“团”，“只”用于动物等，错误在“一只”，应改为“一团火焰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90763, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我看见火焰屋顶上蹿起来。", "corrected_sentence": "我看见火焰从屋顶上蹿起来。", "error_description": "介词遗漏：表示起点的“屋顶上”前要用介词“从”，应说“火焰从屋顶上蹿起来”。去掉“从”后，“屋顶上”无法表示起点，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
