INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90764, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "燃烧时发光发热的气体部分。", "primary_collocate": null, "pronunciation": "huǒ yàn", "ipa": "xuo˨˩˦ jɛn˥˩", "syllable_count": 2, "sentences": [{"text": "蜡烛的火焰很小。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火焰的外面比中间更热。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，火焰就晃了起来。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蓝色的火焰最热。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手挡着火焰。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火焰照亮了黑黑的房间。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看着火焰，觉得很暖和。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火焰碰到纸就烧起来了。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒精灯的火焰是淡蓝色的。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火焰太大，快把火关小一点。", "target_word": "火焰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一团火焰", "label": "量词"}, {"form": "一道火焰", "label": "量词"}], "register": "中性", "sense_fingerprint": "燃烧时发光发热的气体部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7a2fbd5-9221-419f-9b73-a6b85fe461a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90764, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "火焰", "is_correct": true, "explanation": "火焰指燃烧时发光发热的气体部分，是这里要选的词。"}, {"text": "火眼", "is_correct": false, "explanation": "yàn（第四声）与 yǎn（第三声）声调不同，火眼指眼病或明亮的眼睛，不是火焰。"}, {"text": "火烟", "is_correct": false, "explanation": "yàn（第四声）与 yān（第一声）声调不同，火烟指烧火时冒出的烟。"}, {"text": "火药", "is_correct": false, "explanation": "yàn 与 yào 的韵母不同（an/ao），火药是一种易燃易爆的混合物。"}], "explanations": {"火焰": "火焰指燃烧时发光发热的气体部分，是这里要选的词。", "火眼": "yàn（第四声）与 yǎn（第三声）声调不同，火眼指眼病或明亮的眼睛，不是火焰。", "火烟": "yàn（第四声）与 yān（第一声）声调不同，火烟指烧火时冒出的烟。", "火药": "yàn 与 yào 的韵母不同（an/ao），火药是一种易燃易爆的混合物。"}, "sentence_index": null, "correct_answer": "火焰"}, "level_3": {"options": [{"text": "火焰", "is_correct": true, "explanation": "火焰是蜡烛燃烧时发光发热的部分，正好填入这里。"}, {"text": "灯泡", "is_correct": false, "explanation": "搭配：蜡烛靠燃烧发光，不说“蜡烛的灯泡”。"}, {"text": "烟囱", "is_correct": false, "explanation": "语义：烟囱是排烟的管道，蜡烛上没有烟囱。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：手机与蜡烛无关，“蜡烛的手机”不通。"}], "explanations": {"火焰": "火焰是蜡烛燃烧时发光发热的部分，正好填入这里。", "灯泡": "搭配：蜡烛靠燃烧发光，不说“蜡烛的灯泡”。", "烟囱": "语义：烟囱是排烟的管道，蜡烛上没有烟囱。", "手机": "搭配：手机与蜡烛无关，“蜡烛的手机”不通。"}, "sentence_index": 0, "correct_answer": "火焰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他使劲一擦，把火焰擦亮了。", "explanation": "这里应该用〈火柴〉。“擦亮”用于火柴，火焰是燃烧时发光发热的气体部分，擦不亮。"}, {"text": "两块石头一碰，就迸出了火焰。", "explanation": "这里应该用〈火花〉。石头相碰迸出的是细小的火星，即火花；火焰是燃烧时发光发热的大片气体。"}, {"text": "夜里的街上火焰通明，像白天一样。", "explanation": "这里应该用〈灯火〉。“灯火通明”指灯光照得很亮，火焰是燃烧的气体，不用来形容街道的灯光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火焰", "is_correct": true, "explanation": "火焰是看着就觉得暖和的东西，正好填入这里。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块是冷的，与“觉得很暖和”矛盾。"}, {"text": "雪花", "is_correct": false, "explanation": "体貌：雪花白而冷，外形和感觉都与“暖和”相反。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：冰箱用来保冷，“看着冰箱”后接“觉得很暖和”说不通。"}], "explanations": {"火焰": "火焰是看着就觉得暖和的东西，正好填入这里。", "冰块": "语义：冰块是冷的，与“觉得很暖和”矛盾。", "雪花": "体貌：雪花白而冷，外形和感觉都与“暖和”相反。", "冰箱": "搭配：冰箱用来保冷，“看着冰箱”后接“觉得很暖和”说不通。"}, "sentence_index": 6, "correct_answer": "火焰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一说话就火焰很大，大家都不敢靠近。", "explanation": "这里应该用〈火气〉。“火气大”指脾气急躁，火焰指燃烧时发光发热的气体部分，不用来形容人的脾气。"}, {"text": "厨房里冒出很多火焰，呛得人直咳嗽。", "explanation": "这里应该用〈烟〉。火焰会发光发热，不会呛人，让人咳嗽的是烟。"}, {"text": "探照灯射出一道火焰。", "explanation": "这里应该用〈光束〉。探照灯发出的是电光，不是燃烧的火焰，应说“射出一道光束”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里升起一只火焰。", "corrected_sentence": "院子里升起一团火焰。", "error_description": "量词错误：火焰应用量词“团”，“只”用于动物等，错误在“一只”，应改为“一团火焰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "远处的山坡上，火焰慢慢烧起去了。", "corrected_sentence": "远处的山坡上，火焰慢慢烧起来了。", "error_description": "补语错误：“烧起去”不成立，表示开始并持续的说法是“烧起来”，应把“去”改为“来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90765, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相同", "is_correct": true, "explanation": "相同：与「相反」构成反义，表示口味或爱好一致，正是句中所说的反面。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：形容光线或颜色，与「相反」的意思没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软：形容质地，与「相反」没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "干净：形容清洁程度，与「相反」没有反义关系。"}], "correct_answer": "相同", "explanations": {"相同": "相同：与「相反」构成反义，表示口味或爱好一致，正是句中所说的反面。", "明亮": "明亮：形容光线或颜色，与「相反」的意思没有反义关系。", "柔软": "柔软：形容质地，与「相反」没有反义关系。", "干净": "干净：形容清洁程度，与「相反」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90765, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相同", "is_correct": true, "explanation": "相同：与「相反」构成反义，表示爱好与哥哥一样，正是句中所说的反面。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹：形容场面或气氛，与「相反」没有反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙：形容表面质地，与「相反」没有反义关系。"}, {"text": "甜美", "is_correct": false, "explanation": "甜美：形容味道或声音，与「相反」没有反义关系。"}], "correct_answer": "相同", "explanations": {"相同": "相同：与「相反」构成反义，表示爱好与哥哥一样，正是句中所说的反面。", "热闹": "热闹：形容场面或气氛，与「相反」没有反义关系。", "粗糙": "粗糙：形容表面质地，与「相反」没有反义关系。", "甜美": "甜美：形容味道或声音，与「相反」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90765, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "相反是和这个正好不一样。", "primary_collocate": null, "pronunciation": "xiāng fǎn", "ipa": "ɕi̯ɑŋ˥ fan˨˩", "syllable_count": 2, "sentences": [{"text": "我和他的想法正好相反。", "target_word": "相反", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "结果和我想的相反。", "target_word": "相反", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你说的和他说的完全相反。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥爱吃甜的，我和他相反。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他以为我会哭，我的反应却正好相反。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们两个人的性格正好相反。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都说好，只有他的看法相反。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想去海边，妹妹想去山上，我们的想法相反。", "target_word": "相反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的结果和大家的预测正好相反。", "target_word": "相反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢安静，弟弟和我正好相反。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "相反地", "label": "副词形式"}], "register": "中性", "sense_fingerprint": "两个人或事的想法、结果、性格正好不一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79e60a67-5d39-493a-b9c5-106ceed17226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90765, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相反", "is_correct": true, "explanation": "相反：与「我」的想法正好对立，与句中「正好」搭配。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：「明亮」形容光线或颜色，不能用来形容想法。"}, {"text": "咸", "is_correct": false, "explanation": "语义：「咸」说的是味道，想法没有咸淡之分。"}, {"text": "热", "is_correct": false, "explanation": "搭配：「热」不能修饰「想法」，「我和他的想法正好热」不成立。"}], "explanations": {"相反": "相反：与「我」的想法正好对立，与句中「正好」搭配。", "明亮": "语义：「明亮」形容光线或颜色，不能用来形容想法。", "咸": "语义：「咸」说的是味道，想法没有咸淡之分。", "热": "搭配：「热」不能修饰「想法」，「我和他的想法正好热」不成立。"}, "sentence_index": 0, "correct_answer": "相反"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两根绳子的长度相反。", "explanation": "这里应该用〈相同〉。相反表示方向、立场或作用完全对立，说长度要用相同或不同，不能说相反。"}, {"text": "他和哥哥的年龄相反。", "explanation": "这里应该用〈相差〉（如「相差三岁」）或〈差不多〉。年龄只有大小差距，相反表示对立，不能用来说年龄。"}, {"text": "这对双胞胎长得很相反。", "explanation": "这里应该用〈相似〉。说外貌像不像要用相似，相反只表示两者对立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90765, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相反", "is_correct": true, "explanation": "相反：与「大家都说好」形成对立，只有他的看法与众人相反。"}, {"text": "陡", "is_correct": false, "explanation": "语义：「陡」形容坡度，不能用来形容看法。"}, {"text": "甜", "is_correct": false, "explanation": "语义：「甜」说的是味道，看法没有甜不甜之分。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：「烫」说的是温度，不能修饰「看法」。"}], "explanations": {"相反": "相反：与「大家都说好」形成对立，只有他的看法与众人相反。", "陡": "语义：「陡」形容坡度，不能用来形容看法。", "甜": "语义：「甜」说的是味道，看法没有甜不甜之分。", "烫": "搭配：「烫」说的是温度，不能修饰「看法」。"}, "sentence_index": 6, "correct_answer": "相反"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两张纸的面积相反。", "explanation": "这里应该用〈相等〉。比较面积的大小是否一样要用相等，相反表示对立，不能用来说面积。"}, {"text": "这两座山的高度相反。", "explanation": "这里应该用〈相同〉或〈相近〉。说高度一样或接近要用相同、相近，相反表示对立，不能用来比较高度。"}, {"text": "这些书排得很相反。", "explanation": "这里应该用〈整齐〉。说摆放得整洁要用整齐，相反不能描述摆放的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90765, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的兴趣从妹妹正好相反。", "corrected_sentence": "我的兴趣和妹妹正好相反。", "error_description": "介词用错：“相反”前应用“和”（或“与”“跟”）引出对比对象，“从”不能用来引出相反的对象。应把“从”改为“和”，写作“我的兴趣和妹妹正好相反”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90765, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的爱好和哥哥正好相反地。", "corrected_sentence": "我的爱好和哥哥正好相反。", "error_description": "错误：「相反地」。正确：「相反」。「相反地」是副词，要修饰后面的动词，作谓语时应说「相反」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
