INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90766, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "事物的两个方面互相对立；方向、位置等完全不同。", "primary_collocate": null, "pronunciation": "xiāng fǎn", "ipa": "ɕi̯ɑŋ˥ fan˨˩", "syllable_count": 2, "sentences": [{"text": "两辆车往相反的方向开。", "target_word": "相反", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们的意见完全相反。", "target_word": "相反", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "出了门，我们俩往相反的方向走。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风是从相反的方向吹来的。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两种药的作用正好相反。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他朝着和我相反的方向走了。", "target_word": "相反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的看法相反，所以吵了起来。", "target_word": "相反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好和坏是相反的两个词。", "target_word": "相反", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校和家在相反的方向，我每天要走很远。", "target_word": "相反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的路线相反，所以在路上没有遇到。", "target_word": "相反", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相反地", "label": "副词形式"}], "register": "中性", "sense_fingerprint": "方向、位置完全不同，或意见、作用互相对立", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79e60a67-5d39-493a-b9c5-106ceed17226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90766, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相反", "is_correct": true, "explanation": "相反：指两个方向完全对立，修饰「方向」，符合句意。"}, {"text": "厚", "is_correct": false, "explanation": "语义：「厚」说的是物体的厚薄，不能用来指方向。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：「辣」说的是味道，不能修饰「方向」。"}, {"text": "圆", "is_correct": false, "explanation": "语义：「圆」说的是形状，不能用来指方向。"}], "explanations": {"相反": "相反：指两个方向完全对立，修饰「方向」，符合句意。", "厚": "语义：「厚」说的是物体的厚薄，不能用来指方向。", "辣": "搭配：「辣」说的是味道，不能修饰「方向」。", "圆": "语义：「圆」说的是形状，不能用来指方向。"}, "sentence_index": 0, "correct_answer": "相反"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两张桌子的高度相反。", "explanation": "这里应该用〈相同〉。说高度是否一样要用相同或不同，相反表示对立，不能用来说高度。"}, {"text": "这两个人的体重相反。", "explanation": "这里应该用〈相差〉（如「相差五公斤」）或〈差不多〉。体重只有轻重差距，相反表示对立，不能用来说体重。"}, {"text": "这对双胞胎长得很相反。", "explanation": "这里应该用〈相似〉。说外貌像不像要用相似，相反只表示两者对立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相反", "is_correct": true, "explanation": "相反：两人的看法对立，所以才吵了起来，符合句意。"}, {"text": "脆", "is_correct": false, "explanation": "语义：「脆」形容食物或东西的质地，不能用来形容看法。"}, {"text": "咸", "is_correct": false, "explanation": "语义：「咸」说的是味道，看法没有咸淡之分。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：「烫」说的是温度，不能修饰「看法」。"}], "explanations": {"相反": "相反：两人的看法对立，所以才吵了起来，符合句意。", "脆": "语义：「脆」形容食物或东西的质地，不能用来形容看法。", "咸": "语义：「咸」说的是味道，看法没有咸淡之分。", "烫": "搭配：「烫」说的是温度，不能修饰「看法」。"}, "sentence_index": 6, "correct_answer": "相反"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两个杯子的容量相反。", "explanation": "这里应该用〈相等〉。比较容量是否一样要用相等，相反表示对立，不能用来说容量。"}, {"text": "这两座山的高度相反。", "explanation": "这里应该用〈相同〉或〈相近〉。说高度一样或接近要用相同、相近，相反表示对立，不能用来比较高度。"}, {"text": "这些书排得很相反。", "explanation": "这里应该用〈整齐〉。说摆放得整洁要用整齐，相反不能描述摆放的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个人朝着相反地方向跑去。", "corrected_sentence": "两个人朝着相反的方向跑去。", "error_description": "错误：「相反地方向」，「地」用错了。「相反地」是副词形式，「地」用于修饰动词，这里修饰名词「方向」，应该用「的」。正确：「相反的方向」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们的看法正好被相反。", "corrected_sentence": "他们的看法正好相反。", "error_description": "错误：「被」字句。正确：去掉「被」，说「正好相反」。「相反」是形容词，不能用在「被」字句中。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7229e18-8ea4-49e4-bc7f-85d3a891aaf3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
