INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90767, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "关系很近，常常在一起。", "primary_collocate": null, "pronunciation": "mì qiè", "ipa": "mi˥˩ tɕʰjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他们两家的关系很密切。", "target_word": "密切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和邻居来往很密切。", "target_word": "密切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个孩子从小关系密切。", "target_word": "密切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和学生之间接触很密切。", "target_word": "密切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和同事天天在一起，关系很密切。", "target_word": "密切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位老朋友来往密切，常常一起吃饭。", "target_word": "密切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们俩的关系越来越密切了。", "target_word": "密切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是同学，平时接触很密切。", "target_word": "密切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐妹俩关系密切，每天都见面。", "target_word": "密切", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两家人常常串门，往来密切。", "target_word": "密切", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "密切关系", "label": "复合"}], "register": "中性", "sense_fingerprint": "人与人之间关系近、来往多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '752a5636-7271-49eb-b21b-15ae1b5105ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90767, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "密切", "is_correct": true, "explanation": "正确答案。密切形容两家的关系近，符合句意。"}, {"text": "锋利", "is_correct": false, "explanation": "语义：锋利形容刀刃等物体，不能用来形容两家的关系。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：清脆形容声音，与“关系”搭配不通。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：高大形容人或物的外形，不用于描述两家的关系。"}], "explanations": {"密切": "正确答案。密切形容两家的关系近，符合句意。", "锋利": "语义：锋利形容刀刃等物体，不能用来形容两家的关系。", "清脆": "语义：清脆形容声音，与“关系”搭配不通。", "高大": "体貌：高大形容人或物的外形，不用于描述两家的关系。"}, "sentence_index": 0, "correct_answer": "密切"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "城市里的建筑很密切。", "explanation": "这里应该用〈密集〉。密集形容排列紧、数量多；“密切”形容关系或联系近，不用于建筑。"}, {"text": "两块木板连接得很密切。", "explanation": "这里应该用〈紧密〉。紧密形容结合牢固、没有空隙；“密切”只用于人与人、事与事之间的关系。"}, {"text": "两个车站的距离很密切。", "explanation": "这里应该用〈接近〉。接近形容距离相近；“密切”形容关系或联系，不说距离很密切。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90767, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密切", "is_correct": true, "explanation": "正确答案。密切形容两人的关系越来越近，符合句意。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：响亮形容声音大，不能用来形容两人的关系。"}, {"text": "漆黑", "is_correct": false, "explanation": "语义：漆黑形容颜色或光线暗，与“关系”搭配不通。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：潮湿形容空气或物体含水多，不能用来形容两人的关系。"}], "explanations": {"密切": "正确答案。密切形容两人的关系越来越近，符合句意。", "响亮": "语义：响亮形容声音大，不能用来形容两人的关系。", "漆黑": "语义：漆黑形容颜色或光线暗，与“关系”搭配不通。", "潮湿": "语义：潮湿形容空气或物体含水多，不能用来形容两人的关系。"}, "sentence_index": 6, "correct_answer": "密切"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个地区的人口很密切。", "explanation": "这里应该用〈稠密〉。稠密形容人口或物体分布的密度；“密切”不用于描述人口。"}, {"text": "这个方案的步骤安排得很密切。", "explanation": "这里应该用〈紧凑〉。紧凑形容安排得满、没有空隙；“密切”不用于描述步骤安排。"}, {"text": "这台仪器的结构很密切。", "explanation": "这里应该用〈精密〉。精密形容做工细致、准确；“密切”形容关系近，不能用来形容结构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640d2302-ec7c-48da-abb3-66b005f97511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
