INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90769, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "无形是说看不见，也摸不着。", "primary_collocate": null, "pronunciation": "wú xíng", "ipa": "u˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "思想是无形的，看不见也摸不着。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信任是无形的，却比金钱更重要。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压力是无形的，我们摸不着它。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络信号是无形的，眼睛看不到。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文化是一种无形的财富。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话给了我很多无形的帮助。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一条无形的线把两颗心连在一起。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷空气是无形的，却让人发抖。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种无形的东西，没法用手去摸。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名声是无形的，失去后很难找回。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无形的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "看不见也摸不着的抽象事物（思想、信任、文化、名声等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5a0525c-6c30-4575-ae39-cf48177bb3a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90769, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无形", "is_correct": true, "explanation": "无形：看不见，也摸不着。"}, {"text": "五行", "is_correct": false, "explanation": "wǔ xíng（第三声）与 wú xíng（第二声）声调不同，意思是金、木、水、火、土五种元素，不是看不见的。"}, {"text": "无性", "is_correct": false, "explanation": "xìng（第四声）与 xíng（第二声）声调不同，意思是没有性别。"}, {"text": "无情", "is_correct": false, "explanation": "qíng 与 xíng 声母不同（q 与 x），意思是没有感情。"}], "explanations": {"无形": "无形：看不见，也摸不着。", "五行": "wǔ xíng（第三声）与 wú xíng（第二声）声调不同，意思是金、木、水、火、土五种元素，不是看不见的。", "无性": "xìng（第四声）与 xíng（第二声）声调不同，意思是没有性别。", "无情": "qíng 与 xíng 声母不同（q 与 x），意思是没有感情。"}, "sentence_index": null, "correct_answer": "无形"}, "level_3": {"options": [{"text": "无形", "is_correct": true, "explanation": "无形：看不见也摸不着，与后半句相合。"}, {"text": "鲜红", "is_correct": false, "explanation": "语义：“鲜红”说颜色，思想看不见，没有颜色可言。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不用来形容思想。"}, {"text": "黝黑", "is_correct": false, "explanation": "体貌：“黝黑”形容颜色深，与看不见也摸不着的思想不搭。"}], "explanations": {"无形": "无形：看不见也摸不着，与后半句相合。", "鲜红": "语义：“鲜红”说颜色，思想看不见，没有颜色可言。", "清脆": "搭配：“清脆”形容声音，不用来形容思想。", "黝黑": "体貌：“黝黑”形容颜色深，与看不见也摸不着的思想不搭。"}, "sentence_index": 0, "correct_answer": "无形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇论文的观点很无形，读者很难理解。", "explanation": "这里应该用〈抽象〉。抽象指概念不具体，可以用来形容观点；无形指看不见，不能用来形容观点的概括程度。"}, {"text": "这次投票结果无形了，需要重新投票。", "explanation": "这里应该用〈无效〉。无效指不算数、不起作用，如投票结果无效；无形指看不见，不能用来说结果作废。"}, {"text": "他说的那些大道理很无形，没有实际内容。", "explanation": "这里应该用〈空洞〉。“空洞”指话语没有实际内容；“无形”指看不见，不能用来说道理没有内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90769, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "无形", "is_correct": true, "explanation": "无形：看不见也摸不着。"}, {"text": "无名", "is_correct": false, "explanation": "míng（第二声）与 xíng 声母不同（m 与 x），意思是没有名气、不知名。"}, {"text": "无性", "is_correct": false, "explanation": "xìng（第四声）与 xíng（第二声）声调不同，意思是没有性别或性质。"}, {"text": "无星", "is_correct": false, "explanation": "xīng（第一声）与 xíng（第二声）声调不同，意思是没有星星。"}], "explanations": {"无形": "无形：看不见也摸不着。", "无名": "míng（第二声）与 xíng 声母不同（m 与 x），意思是没有名气、不知名。", "无性": "xìng（第四声）与 xíng（第二声）声调不同，意思是没有性别或性质。", "无星": "xīng（第一声）与 xíng（第二声）声调不同，意思是没有星星。"}, "sentence_index": null, "correct_answer": "无形"}, "level_3": {"options": [{"text": "无形", "is_correct": true, "explanation": "无形：看不见也摸不着，比喻无形的情感联系，与“把两颗心连在一起”相合。"}, {"text": "锋利", "is_correct": false, "explanation": "语义：“锋利”说切割能力，与“把两颗心连在一起”的意思相反。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不用来形容线。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容有形体的人或物，线没有这种体貌。"}], "explanations": {"无形": "无形：看不见也摸不着，比喻无形的情感联系，与“把两颗心连在一起”相合。", "锋利": "语义：“锋利”说切割能力，与“把两颗心连在一起”的意思相反。", "响亮": "搭配：“响亮”形容声音，不用来形容线。", "高大": "体貌：“高大”形容有形体的人或物，线没有这种体貌。"}, "sentence_index": 6, "correct_answer": "无形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这层玻璃很无形，大家都能看见它。", "explanation": "这里应该用〈透明〉。玻璃有具体形状，能看透，应说透明；无形指看不见，不能用来形容玻璃。"}, {"text": "这座大楼是无形的，站在远处就能看见。", "explanation": "这里应该用〈高大〉。大楼有具体形状，应说高大；无形指看不见，不能用来形容大楼。"}, {"text": "他的眼镜是无形的，戴上后别人看不出来。", "explanation": "这里应该用〈隐形〉。隐形指戴在身上不易被看出，如隐形眼镜；眼镜有具体形状，不能说无形的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90769, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一种无形地力量。", "corrected_sentence": "这是一种无形的力量。", "error_description": "错误：“无形”修饰名词“力量”时应用“的”，写作“无形的力量”。“地”用来修饰动词或形容词，不能修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
