INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90770, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有具体形状，看不到的。", "primary_collocate": null, "pronunciation": "wú xíng", "ipa": "u˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "空气是无形的，我们看不见它。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风是无形的，但我们能感觉到它。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他感到一种无形的压力。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱是无形的，却能让人觉得温暖。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "声音也是无形的，我们只能听到。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "友情是一种无形的力量。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一堵无形的墙挡在他们中间。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "香味是无形的，却飘满了屋子。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水有形状，但空气是无形的。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灵魂是无形的，没有人见过它。", "target_word": "无形", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无形的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "没有具体形状、看不到的（空气、风、压力等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5a0525c-6c30-4575-ae39-cf48177bb3a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90770, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无形", "is_correct": true, "explanation": "无形：没有具体形状，看不见的。"}, {"text": "五行", "is_correct": false, "explanation": "wǔ xíng（第三声）与 wú xíng（第二声）声调不同，意思是金、木、水、火、土五种元素，不是看不见的。"}, {"text": "无性", "is_correct": false, "explanation": "xìng（第四声）与 xíng（第二声）声调不同，意思是没有性别。"}, {"text": "无情", "is_correct": false, "explanation": "qíng 与 xíng 声母不同（q 与 x），意思是没有感情。"}], "explanations": {"无形": "无形：没有具体形状，看不见的。", "五行": "wǔ xíng（第三声）与 wú xíng（第二声）声调不同，意思是金、木、水、火、土五种元素，不是看不见的。", "无性": "xìng（第四声）与 xíng（第二声）声调不同，意思是没有性别。", "无情": "qíng 与 xíng 声母不同（q 与 x），意思是没有感情。"}, "sentence_index": null, "correct_answer": "无形"}, "level_3": {"options": [{"text": "无形", "is_correct": true, "explanation": "无形：没有具体形状、看不见，与后半句“看不见它”相合。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”指光线充足、看得清楚，与“看不见它”矛盾。"}, {"text": "显眼", "is_correct": false, "explanation": "语义：“显眼”指容易被看见，与“我们看不见它”矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容有形的人或物的身形，空气没有体态可言。"}], "explanations": {"无形": "无形：没有具体形状、看不见，与后半句“看不见它”相合。", "明亮": "语义：“明亮”指光线充足、看得清楚，与“看不见它”矛盾。", "显眼": "语义：“显眼”指容易被看见，与“我们看不见它”矛盾。", "高大": "体貌：“高大”形容有形的人或物的身形，空气没有体态可言。"}, "sentence_index": 0, "correct_answer": "无形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他戴着无形的眼镜，别人都看不出来。", "explanation": "这里应该用〈隐形〉。隐形指戴在身上不易被看出，如隐形眼镜；眼镜有具体形状，不能说无形的眼镜。"}, {"text": "这张优惠券已经无形了，不能再用。", "explanation": "这里应该用〈无效〉。无效指不起作用、不能再用，如优惠券无效；无形指看不见、没有具体形状，不能用来说优惠券。"}, {"text": "这幅油画很无形，我看不懂它想表达什么。", "explanation": "这里应该用〈抽象〉。抽象指不具体、不写实，可以用来形容画的风格；无形指看不见，不能用来形容画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90770, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "无形", "is_correct": true, "explanation": "无形：没有具体形状，看不见的。"}, {"text": "无名", "is_correct": false, "explanation": "míng（第二声）与 xíng 声母不同（m 与 x），意思是没有名气、不知名。"}, {"text": "无性", "is_correct": false, "explanation": "xìng（第四声）与 xíng（第二声）声调不同，意思是没有性别或性质。"}, {"text": "无星", "is_correct": false, "explanation": "xīng（第一声）与 xíng（第二声）声调不同，意思是没有星星。"}], "explanations": {"无形": "无形：没有具体形状，看不见的。", "无名": "míng（第二声）与 xíng 声母不同（m 与 x），意思是没有名气、不知名。", "无性": "xìng（第四声）与 xíng（第二声）声调不同，意思是没有性别或性质。", "无星": "xīng（第一声）与 xíng（第二声）声调不同，意思是没有星星。"}, "sentence_index": null, "correct_answer": "无形"}, "level_3": {"options": [{"text": "无形", "is_correct": true, "explanation": "无形：此处比喻看不见的隔阂，与“挡在他们中间”相合。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不用来修饰墙。"}, {"text": "轻盈", "is_correct": false, "explanation": "搭配：“轻盈”多形容身姿、步伐，不用来形容墙。"}, {"text": "芬芳", "is_correct": false, "explanation": "搭配：“芬芳”形容气味，墙不能用来形容。"}], "explanations": {"无形": "无形：此处比喻看不见的隔阂，与“挡在他们中间”相合。", "清脆": "搭配：“清脆”形容声音，不用来修饰墙。", "轻盈": "搭配：“轻盈”多形容身姿、步伐，不用来形容墙。", "芬芳": "搭配：“芬芳”形容气味，墙不能用来形容。"}, "sentence_index": 6, "correct_answer": "无形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座高塔是无形的，远远就能望见。", "explanation": "这里应该用〈高大〉。高塔有具体形状，应说高大；无形指看不见，不能用来形容高塔。"}, {"text": "这扇窗户很无形，大家都能看见。", "explanation": "这里应该用〈透明〉。窗户有具体形状，能看透，应说透明；无形指看不见、没有具体形状，不能用来形容窗户。"}, {"text": "这番话很无形，没有实际内容。", "explanation": "这里应该用〈空洞〉。“空洞”指话语没有实际内容；“无形”指看不见，不能用来说话语没有内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她心里有一种无形地压力。", "corrected_sentence": "她心里有一种无形的压力。", "error_description": "错误：“无形”修饰名词“压力”时应用“的”，写作“无形的压力”。“地”用来修饰动词或形容词，不能修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们之间有一堵很无形的墙。", "corrected_sentence": "他们之间有一堵无形的墙。", "error_description": "错误：“无形”是非程度形容词，不能受“很”修饰，应去掉“很”，写作“一堵无形的墙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
