INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90771, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大家坐在一起，认真看一看，讨论能不能这样做。", "primary_collocate": null, "pronunciation": "shěn yì", "ipa": "ʂən˨˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "委员们正在审议这个计划。", "target_word": "审议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议审议了新的学校规则。", "target_word": "审议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家要先审议，再决定做不做。", "target_word": "审议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个方案明天开会审议。", "target_word": "审议", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "代表们认真审议了今年的预算。", "target_word": "审议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家长委员会审议了学校的旅行安排。", "target_word": "审议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份报告还没有审议，不能马上用。", "target_word": "审议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司经理们审议了三个新计划。", "target_word": "审议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小组审议后，同意了这个办法。", "target_word": "审议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会上大家审议得很认真，谁也没有说笑。", "target_word": "审议", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "审议了", "label": "体标"}, {"form": "審議", "label": "繁体"}], "register": "书面", "sense_fingerprint": "众人聚在一起认真审看并讨论某计划、方案能否实行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab11b7c9-d5a8-4a17-9c0b-0279c3fa91db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90771, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "审议", "is_correct": true, "explanation": "审议（shěn yì）指大家坐在一起认真审查、讨论计划或方案能否实行，是听到的正确词。"}, {"text": "生意", "is_correct": false, "explanation": "shēng（第一声）与 shěn（第三声）韵母与声调都不同，意思是买卖、生计。"}, {"text": "深意", "is_correct": false, "explanation": "shēn（第一声）与 shěn（第三声）声调不同，意思是深刻的含义。"}, {"text": "神意", "is_correct": false, "explanation": "shén（第二声）与 shěn（第三声）声调不同，意思是神的旨意，较书面。"}, {"text": "神异", "is_correct": false, "explanation": "shén（第二声）与 shěn（第三声）声调不同，意思是神奇怪异，较书面。"}], "explanations": {"审议": "审议（shěn yì）指大家坐在一起认真审查、讨论计划或方案能否实行，是听到的正确词。", "生意": "shēng（第一声）与 shěn（第三声）韵母与声调都不同，意思是买卖、生计。", "深意": "shēn（第一声）与 shěn（第三声）声调不同，意思是深刻的含义。", "神意": "shén（第二声）与 shěn（第三声）声调不同，意思是神的旨意，较书面。", "神异": "shén（第二声）与 shěn（第三声）声调不同，意思是神奇怪异，较书面。"}, "sentence_index": null, "correct_answer": "审议"}, "level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“计划”作宾语，“委员们正在吃这个计划”说不通。"}, {"text": "审议", "is_correct": true, "explanation": "正确：审议指委员对计划的集体审查讨论，与“委员们”“计划”相合。"}, {"text": "免疫", "is_correct": false, "explanation": "语义：免疫指身体抵抗病菌，不能用来形容对计划的审查。"}, {"text": "挖", "is_correct": false, "explanation": "搭配：“挖”不能带“计划”作宾语，“挖这个计划”说不通。"}], "explanations": {"吃": "搭配：“吃”不能带“计划”作宾语，“委员们正在吃这个计划”说不通。", "审议": "正确：审议指委员对计划的集体审查讨论，与“委员们”“计划”相合。", "免疫": "语义：免疫指身体抵抗病菌，不能用来形容对计划的审查。", "挖": "搭配：“挖”不能带“计划”作宾语，“挖这个计划”说不通。"}, "sentence_index": 0, "correct_answer": "审议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海关审议了他的行李。", "explanation": "这里应该用〈审查〉。审议多指大家讨论议案、方案，检查个人行李要用“审查”或“检查”。"}, {"text": "医生审议了病人的心跳。", "explanation": "这里应该用〈检查〉。审议是对议案、方案的集体审查讨论，检查心跳要用“检查”。"}, {"text": "科学家审议了这种病毒。", "explanation": "这里应该用〈研究〉。审议是对议案的集体审查讨论，探究病毒的性质要用“研究”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90771, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "语义：“喝”不能用于报告这类文件，“还没有喝”句子不通。"}, {"text": "审议", "is_correct": true, "explanation": "正确：审议指对报告进行审查，与“还没有”“不能马上用”的语境相合。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”不能带“报告”作宾语，“咬报告”搭配不通。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”针对可以咽下的东西，不能用于报告。"}], "explanations": {"喝": "语义：“喝”不能用于报告这类文件，“还没有喝”句子不通。", "审议": "正确：审议指对报告进行审查，与“还没有”“不能马上用”的语境相合。", "咬": "搭配：“咬”不能带“报告”作宾语，“咬报告”搭配不通。", "吞": "语义：“吞”针对可以咽下的东西，不能用于报告。"}, "sentence_index": 6, "correct_answer": "审议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师审议了我的作文。", "explanation": "这里应该用〈评价〉。审议用于对议案、方案的集体审查，评改个人作品要用“评价”。"}, {"text": "记者审议了这家公司的账目。", "explanation": "这里应该用〈调查〉。审议不指对账目的调查，揭露问题要用“调查”。"}, {"text": "学校审议了学生的身高。", "explanation": "这里应该用〈测量〉。审议用于议案、方案的讨论决定，量身高要用“测量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90771, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "代表们正在审议了这项提案。", "corrected_sentence": "代表们正在审议这项提案。", "error_description": "错误：“正在”表示动作进行，又在“审议”后加“了”表示完成，体标冲突。正确形式是“正在审议这项提案”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90771, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生会正在审议过这个活动方案。", "corrected_sentence": "学生会正在审议这个活动方案。", "error_description": "错误：“正在”表示动作进行，与表示经历的“过”冲突。正确形式是“正在审议这个活动方案”，去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
