INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90772, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "审查并讨论。", "primary_collocate": null, "pronunciation": "shěn yì", "ipa": "ʂən˨˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "市民代表审议了这条新路的方案。", "target_word": "审议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律草案明天提交大会审议。", "target_word": "审议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事需要专门的小组审议。", "target_word": "审议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们把预算交给委员会审议。", "target_word": "审议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议会正在审议新的税收办法。", "target_word": "审议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "草案经过三次审议才通过。", "target_word": "审议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校今天审议老师们提出的意见。", "target_word": "审议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请各位代表认真审议这份报告。", "target_word": "审议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份文件还在审议中。", "target_word": "审议", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "董事会审议后，决定不买那块地。", "target_word": "审议", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "审议了", "label": "体标"}, {"form": "審議", "label": "繁体"}], "register": "书面", "sense_fingerprint": "对草案、预算、报告等先审查再讨论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab11b7c9-d5a8-4a17-9c0b-0279c3fa91db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90772, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "审议", "is_correct": true, "explanation": "审议（shěn yì）指审查并讨论草案、预算等，是听到的正确词。"}, {"text": "生意", "is_correct": false, "explanation": "shēng（第一声）与 shěn（第三声）韵母与声调都不同，意思是买卖、生计。"}, {"text": "深意", "is_correct": false, "explanation": "shēn（第一声）与 shěn（第三声）声调不同，意思是深刻的含义。"}, {"text": "神意", "is_correct": false, "explanation": "shén（第二声）与 shěn（第三声）声调不同，意思是神的旨意，较书面。"}, {"text": "神异", "is_correct": false, "explanation": "shén（第二声）与 shěn（第三声）声调不同，意思是神奇怪异，较书面。"}], "explanations": {"审议": "审议（shěn yì）指审查并讨论草案、预算等，是听到的正确词。", "生意": "shēng（第一声）与 shěn（第三声）韵母与声调都不同，意思是买卖、生计。", "深意": "shēn（第一声）与 shěn（第三声）声调不同，意思是深刻的含义。", "神意": "shén（第二声）与 shěn（第三声）声调不同，意思是神的旨意，较书面。", "神异": "shén（第二声）与 shěn（第三声）声调不同，意思是神奇怪异，较书面。"}, "sentence_index": null, "correct_answer": "审议"}, "level_3": {"options": [{"text": "烧", "is_correct": false, "explanation": "语义：“烧”指焚毁，句意变成烧掉方案，与“审议”不符。"}, {"text": "审议", "is_correct": true, "explanation": "正确：审议指市民代表对方案的审查讨论，与句中语境相合。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”不能带“方案”作宾语，“煮了方案”搭配不通。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”的对象是人或动物，不能用于方案。"}], "explanations": {"烧": "语义：“烧”指焚毁，句意变成烧掉方案，与“审议”不符。", "审议": "正确：审议指市民代表对方案的审查讨论，与句中语境相合。", "煮": "搭配：“煮”不能带“方案”作宾语，“煮了方案”搭配不通。", "喂": "语义：“喂”的对象是人或动物，不能用于方案。"}, "sentence_index": 0, "correct_answer": "审议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "安检员审议了乘客的护照。", "explanation": "这里应该用〈审查〉。审议用于议案的集体讨论，核验护照要用“审查”。"}, {"text": "老师审议了学生的作业。", "explanation": "这里应该用〈检查〉。审议偏重大家对议案的讨论决定，批改作业要用“检查”。"}, {"text": "游客审议了这座桥的承重。", "explanation": "这里应该用〈检测〉。审议是对议案的审查讨论，检测桥梁承重要用“检测”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挖", "is_correct": false, "explanation": "搭配：“挖”不能带“意见”作宾语，“挖意见”说不通。"}, {"text": "审议", "is_correct": true, "explanation": "正确：审议指对老师们提出的意见进行审查讨论，与句中语境相合。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”针对实物，不能用于意见。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”不能带“意见”作宾语，“拍意见”搭配不通。"}], "explanations": {"挖": "搭配：“挖”不能带“意见”作宾语，“挖意见”说不通。", "审议": "正确：审议指对老师们提出的意见进行审查讨论，与句中语境相合。", "切": "语义：“切”针对实物，不能用于意见。", "拍": "搭配：“拍”不能带“意见”作宾语，“拍意见”搭配不通。"}, "sentence_index": 6, "correct_answer": "审议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学者审议了古代的文字。", "explanation": "这里应该用〈研究〉。审议用于对议案的审查讨论，探究古代文字要用“研究”。"}, {"text": "妈妈审议了我的画。", "explanation": "这里应该用〈评价〉。审议不用于评价个人作品，此处要说“评价”。"}, {"text": "警察审议了这起案件。", "explanation": "这里应该用〈调查〉。审议不指侦查案件，警方查案要用“调查”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "董事会正在审议了这份合同。", "corrected_sentence": "董事会正在审议这份合同。", "error_description": "错误：“正在”表示动作进行中，与表示完成的“了”不能同时用于“审议”。正确形式是“正在审议这份合同”，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "财务部门正在被审议这笔支出。", "corrected_sentence": "财务部门正在审议这笔支出。", "error_description": "错误：“被”使“财务部门”成为受事，但“财务部门”是审议的主体，应改用主动句。正确形式是“财务部门正在审议这笔支出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
