INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90773, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看情况是等到那时候，再看是怎么样，再决定。", "primary_collocate": null, "pronunciation": "kàn qíng kuàng", "ipa": "kʰan˥˩ tɕʰiŋ˧˥ kʰuaŋ˥˩", "syllable_count": 3, "sentences": [{"text": "我现在不知道去不去，到时候看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天会不会下雨还不知道，那天再看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在先不买票，等出发前看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他问我去不去，我说到时候看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先不用决定，到了那里再看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明年要不要换工作，明年再看情况吧。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的计划还没定，到时候看情况吧。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想现在说，等他回来了再看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭后要不要出去走走，吃完了看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先走着，到了路口再看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看情況", "label": "繁体"}, {"form": "看情况而定", "label": "复合"}], "register": "口语", "sense_fingerprint": "先不决定，等到那时候再看再定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '388a63b1-0373-4e8f-9a4b-1f114645e9ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90773, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看情况", "is_correct": true, "explanation": "“看情况”指到时候再看具体情形再决定，与“不知道去不去”相符。"}, {"text": "出发", "is_correct": false, "explanation": "语义：“到时候出发”预设已经决定去，与“不知道去不去”矛盾。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示不同意，与“不知道去不去”的未定状态不符。"}, {"text": "答应", "is_correct": false, "explanation": "语义：“答应”表示同意，与“不知道去不去”的未定状态不符。"}], "explanations": {"看情况": "“看情况”指到时候再看具体情形再决定，与“不知道去不去”相符。", "出发": "语义：“到时候出发”预设已经决定去，与“不知道去不去”矛盾。", "拒绝": "语义：“拒绝”表示不同意，与“不知道去不去”的未定状态不符。", "答应": "语义：“答应”表示同意，与“不知道去不去”的未定状态不符。"}, "sentence_index": 0, "correct_answer": "看情况"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "合同规定下周一必须交货，我们现在还要看情况。", "explanation": "这里应该用〈确定〉。“看情况”表示还没定，与“规定下周一必须交货”的既定安排矛盾。"}, {"text": "太阳每天从东边升起，我们还要看情况。", "explanation": "这里应该用〈确定〉。“看情况”表示还没定，而太阳东升是确定的规律，不能这样说。"}, {"text": "他已经付了钱，还在看情况。", "explanation": "这里应该用〈已经决定〉。“看情况”表示还没定，与“已经付了钱”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90773, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看情况", "is_correct": true, "explanation": "“看情况”指到时候再根据情形决定，与“计划还没定”相符。"}, {"text": "完成", "is_correct": false, "explanation": "语义：计划还没定，谈不上“完成”。"}, {"text": "结束", "is_correct": false, "explanation": "语义：计划还没开始，不能说“结束”。"}, {"text": "失败", "is_correct": false, "explanation": "语义：计划还没定，不会“失败”。"}], "explanations": {"看情况": "“看情况”指到时候再根据情形决定，与“计划还没定”相符。", "完成": "语义：计划还没定，谈不上“完成”。", "结束": "语义：计划还没开始，不能说“结束”。", "失败": "语义：计划还没定，不会“失败”。"}, "sentence_index": 6, "correct_answer": "看情况"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个方案只有一个正确选项，我们看情况选吧。", "explanation": "这里应该用〈确定〉。“看情况”表示还没定，只有一个正确选项时不能再看情况选。"}, {"text": "这份合同签了字，我们看情况再签。", "explanation": "这里应该用〈已经签好〉。“看情况”表示还没定，合同已签字时不能再说看情况。"}, {"text": "这道题我已经算出答案，还要看情况。", "explanation": "这里应该用〈已经确定〉。“看情况”表示还没定，答案已经算出，就不该再看情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90773, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事我们暂时不谈，等结果出来再看情况了。", "corrected_sentence": "这件事我们暂时不谈，等结果出来再看情况。", "error_description": "助词错误：“再看情况了”；正确：“再看情况”。“再”表示以后要做的动作，句中还没发生，不能加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90773, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个问题先放着，等下周开会再看情况的。", "corrected_sentence": "这个问题先放着，等下周开会再看情况。", "error_description": "助词错误：句末多出“的”；“再看情况”已是完整谓语，应说“等下周开会再看情况”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
