INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90774, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "根据具体情况再作决定。", "primary_collocate": null, "pronunciation": "kàn qíng kuàng", "ipa": "kʰan˥˩ tɕʰiŋ˧˥ kʰuaŋ˥˩", "syllable_count": 3, "sentences": [{"text": "要不要带伞，得看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一天学多少个字，看情况，不一定。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "给不给孩子零花钱，要看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "什么时候吃药，医生说要看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐地铁还是打车，看情况再决定。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每周见几次面，要看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买多大的房子，得看情况，钱够不够。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去不去参加比赛，我要看情况再决定。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价钱可以便宜多少，老板说看情况。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要不要请假，看情况，小病就不用了。", "target_word": "看情况", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看情況", "label": "繁体"}, {"form": "看情况而定", "label": "复合"}], "register": "口语", "sense_fingerprint": "根据具体情况来决定，没有固定做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '388a63b1-0373-4e8f-9a4b-1f114645e9ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看情况", "is_correct": true, "explanation": "“看情况”指根据具体情形再决定，与“要不要带伞”相符。"}, {"text": "看见", "is_correct": false, "explanation": "语义：要不要带伞是决定问题，“看见”与之不符。"}, {"text": "答应", "is_correct": false, "explanation": "配价：“答应”需要承诺的内容，“得答应”没有所指。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“得高兴”与要不要带伞的决定无关，句意不通。"}], "explanations": {"看情况": "“看情况”指根据具体情形再决定，与“要不要带伞”相符。", "看见": "语义：要不要带伞是决定问题，“看见”与之不符。", "答应": "配价：“答应”需要承诺的内容，“得答应”没有所指。", "高兴": "语义：“得高兴”与要不要带伞的决定无关，句意不通。"}, "sentence_index": 0, "correct_answer": "看情况"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条规定很明确：每天八点准时开会，要看情况。", "explanation": "这里应该用〈必须〉。“看情况”表示没有固定做法，与“规定很明确”的既定安排矛盾。"}, {"text": "地铁票价是固定的，要看情况。", "explanation": "这里应该用〈一律〉。“看情况”表示要根据具体情形决定，票价统一时不能这样说。"}, {"text": "他每天六点起床，这是一贯的习惯，看情况。", "explanation": "这里应该用〈一直〉。“看情况”表示要根据情形决定，习惯已经固定时不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看情况", "is_correct": true, "explanation": "“看情况”指要根据具体条件再决定，与“钱够不够”的判断相符。"}, {"text": "看中", "is_correct": false, "explanation": "语义：“看中”指喜欢，与“钱够不够”的判断不符。"}, {"text": "出租", "is_correct": false, "explanation": "语义：买房子不是出租房子，句意不通。"}, {"text": "说话", "is_correct": false, "explanation": "配价：“说话”不能带“多大的房子”作宾语，句子不通。"}], "explanations": {"看情况": "“看情况”指要根据具体条件再决定，与“钱够不够”的判断相符。", "看中": "语义：“看中”指喜欢，与“钱够不够”的判断不符。", "出租": "语义：买房子不是出租房子，句意不通。", "说话": "配价：“说话”不能带“多大的房子”作宾语，句子不通。"}, "sentence_index": 6, "correct_answer": "看情况"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题的答案只有一个，要看情况。", "explanation": "这里应该用〈唯一〉。“看情况”表示没有固定答案，题目答案唯一时不能用。"}, {"text": "一周有七天，我们要看情况。", "explanation": "这里应该用〈客观事实〉。“看情况”表示要根据具体情形决定，一周七天这类事实不能这样说。"}, {"text": "会议时间早就定好了，要看情况。", "explanation": "这里应该用〈已定〉。“看情况”表示还没有固定做法，会议时间已定时不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天去不去爬山，要看情况的再决定。", "corrected_sentence": "明天去不去爬山，要看情况再决定。", "error_description": "助词错误：“看情况”后面不能加“的”，应直接说“看情况再决定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个周末去不去，还得看情况着。", "corrected_sentence": "这个周末去不去，还得看情况。", "error_description": "助词错误：“看情况”表示视情形而定，后面不能加“着”，应说“还得看情况”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5f9d30a-5d78-4cbb-9677-e0bf01625f72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90775, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有情", "is_correct": true, "explanation": "正确。“有情”与“无情”互为反义，指有感情、有情义。"}, {"text": "潮湿", "is_correct": false, "explanation": "“潮湿”形容含水分多，与人的感情无关，不是“无情”的反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”指明白、不模糊，与“无情”不构成反义关系。"}, {"text": "宽阔", "is_correct": false, "explanation": "“宽阔”形容空间面积大，与“无情”没有反义关系。"}], "correct_answer": "有情", "explanations": {"有情": "正确。“有情”与“无情”互为反义，指有感情、有情义。", "潮湿": "“潮湿”形容含水分多，与人的感情无关，不是“无情”的反义词。", "清楚": "“清楚”指明白、不模糊，与“无情”不构成反义关系。", "宽阔": "“宽阔”形容空间面积大，与“无情”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90775, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有情", "is_correct": true, "explanation": "正确。“有情”与“无情”互为反义，指有感情、有情义。"}, {"text": "高大", "is_correct": false, "explanation": "“高大”形容身材或体积，与“无情”不构成反义关系。"}, {"text": "响亮", "is_correct": false, "explanation": "“响亮”形容声音大，与人的感情无关，不是“无情”的反义词。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”指质地松软，与“无情”没有反义关系。"}], "correct_answer": "有情", "explanations": {"有情": "正确。“有情”与“无情”互为反义，指有感情、有情义。", "高大": "“高大”形容身材或体积，与“无情”不构成反义关系。", "响亮": "“响亮”形容声音大，与人的感情无关，不是“无情”的反义词。", "柔软": "“柔软”指质地松软，与“无情”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90775, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "无情是说没有感情，心很硬。", "primary_collocate": null, "pronunciation": "wú qíng", "ipa": "u˧˥ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他对家人太无情了。", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么能这么无情？", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说他是个无情的人。", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看见朋友摔倒，却转身走了，真无情。", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了她的话，我觉得她很无情。", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的心像石头一样无情。", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们怎么对孩子这样无情？", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无情的人不会想别人。", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭了，可是他一点也不难过，真无情。", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人那么难过，他却笑着，太无情了。", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "無情", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人没有感情，心肠很硬", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3040b130-1c83-4aba-a0d1-f87d0f162c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90775, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明亮", "is_correct": false, "explanation": "体貌：“明亮”形容光线或外观，不用来说对家人的态度。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：“干净”用于环境或物品，不说对家人“太干净了”。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“便宜”指价格低，与对家人的态度无关。"}, {"text": "无情", "is_correct": true, "explanation": "正确。“无情”指对家人没有感情、心很硬，与“太……了”相合。"}], "explanations": {"明亮": "体貌：“明亮”形容光线或外观，不用来说对家人的态度。", "干净": "搭配：“干净”用于环境或物品，不说对家人“太干净了”。", "便宜": "语义：“便宜”指价格低，与对家人的态度无关。", "无情": "正确。“无情”指对家人没有感情、心很硬，与“太……了”相合。"}, "sentence_index": 0, "correct_answer": "无情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他无情地把积蓄全捐给了孤儿院。", "explanation": "这里应该用〈无私〉。无私指不为自己考虑，修饰捐助的行为；无情指没有感情、心很硬，不能用来形容捐款的态度。"}, {"text": "妈妈无情地抱着孩子，轻轻拍着他的背。", "explanation": "这里应该用〈温柔〉。温柔指态度柔和，修饰抱孩子的动作；无情指没有感情，不能形容这样的亲昵动作。"}, {"text": "他无情地给花浇水，每天早上都去。", "explanation": "这里应该用〈细心〉。细心指做事周到、留神，修饰浇花；无情指没有感情，不能形容浇水的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90775, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整齐", "is_correct": false, "explanation": "体貌：“整齐”说外表或排列，不用来说对待孩子的方式。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”指环境或状态，不指对待孩子的感情。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外貌，不说对待孩子的方式“这样漂亮”。"}, {"text": "无情", "is_correct": true, "explanation": "正确。“无情”指对孩子没有感情，与“怎么……这样”的语境相合。"}], "explanations": {"整齐": "体貌：“整齐”说外表或排列，不用来说对待孩子的方式。", "安静": "语义：“安静”指环境或状态，不指对待孩子的感情。", "漂亮": "搭配：“漂亮”形容外貌，不说对待孩子的方式“这样漂亮”。", "无情": "正确。“无情”指对孩子没有感情，与“怎么……这样”的语境相合。"}, "sentence_index": 6, "correct_answer": "无情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师对学生很无情，但很关心他们。", "explanation": "这里应该用〈严厉〉。严厉指要求严格，无情指没有感情，与“很关心他们”的语境矛盾。"}, {"text": "他遇到危险时很无情，救了三个人。", "explanation": "这里应该用〈冷静〉。冷静指头脑清楚、不慌乱，无情指没有感情，与“救了三个人”的语境矛盾。"}, {"text": "老板对员工很无情，每次都帮他们加薪。", "explanation": "这里应该用〈体贴〉。体贴指关心照顾他人，无情指没有感情，与“帮他们加薪”的语境矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90775, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对孩子无情很，从不关心他们。", "corrected_sentence": "他对孩子无情得很，从不关心他们。", "error_description": "程度补语的“得”缺失。形容词“无情”后要用“得”引出“很”，应说“无情得很”，不能说“无情很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90775, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个人无情得拒绝了朋友的请求。", "corrected_sentence": "这个人无情地拒绝了朋友的请求。", "error_description": "状语标记用错。“无情”修饰动词“拒绝”，作状语，中间应用“地”；“得”引出补语，不能用在动词前。应说“无情地拒绝”，不能说“无情得拒绝”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
