INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90776, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有感情，不讲情面。", "primary_collocate": null, "pronunciation": "wú qíng", "ipa": "u˧˥ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "法律是无情的，错了就要受罚。", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板很无情，把他开除了。", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争无情，夺走了很多人的家。", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水无情，冲走了河边的房子。", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "寒风无情，吹得路人直发抖。", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间无情，一天天过去了。", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理对迟到的人很无情，一次也不原谅。", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老师太无情，学生哭着求情也不松口。", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大火无情，一晚上烧了三间房。", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商场如战场，对手很无情。", "target_word": "无情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "無情", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不讲情面，对人或事毫不留情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3040b130-1c83-4aba-a0d1-f87d0f162c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90776, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”形容说话风趣，不用来描述法律的性质。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外貌或外观，不用来形容法律。"}, {"text": "无情", "is_correct": true, "explanation": "正确。“法律是无情的”说法律不讲情面，与“错了就要受罚”相合。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：“甜蜜”指感情或味道，与法律的性质无关。"}], "explanations": {"幽默": "语义：“幽默”形容说话风趣，不用来描述法律的性质。", "漂亮": "搭配：“漂亮”形容外貌或外观，不用来形容法律。", "无情": "正确。“法律是无情的”说法律不讲情面，与“错了就要受罚”相合。", "甜蜜": "语义：“甜蜜”指感情或味道，与法律的性质无关。"}, "sentence_index": 0, "correct_answer": "无情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他无情地洗了碗，又把灶台擦得很干净。", "explanation": "这里应该用〈仔细〉。仔细指做事认真周到，修饰洗碗；无情指不讲情面，不能用来形容洗碗的态度。"}, {"text": "她无情地安慰着哭泣的孩子，轻轻地拍着他的肩膀。", "explanation": "这里应该用〈温柔〉。温柔指态度柔和，修饰安慰的动作；无情指不讲情面，与“轻轻拍着他的肩膀”的安慰语境矛盾。"}, {"text": "他无情地拿着那只碗，生怕它掉下来。", "explanation": "这里应该用〈小心〉。小心指留神、谨慎，修饰拿碗的动作；无情指不讲情面，与“生怕它掉下来”的谨慎态度矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bb85020-5dbd-412f-a076-97e87ec4ad03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
